window.PYQ_CHEMISTRY = {"version":1,"subject":"Chemistry","class":12,"chapters":[{"n":1,"t":"Solutions","unit":"I","unitName":"Solutions","unitMarks":7,"count":83},{"n":2,"t":"Electrochemistry","unit":"II","unitName":"Electrochemistry","unitMarks":9,"count":81},{"n":3,"t":"Chemical Kinetics","unit":"III","unitName":"Chemical Kinetics","unitMarks":7,"count":89},{"n":4,"t":"The d- and f-Block Elements","unit":"IV","unitName":"The d- and f-Block Elements","unitMarks":7,"count":102},{"n":5,"t":"Coordination Compounds","unit":"V","unitName":"Coordination Compounds","unitMarks":7,"count":85},{"n":6,"t":"Haloalkanes and Haloarenes","unit":"VI","unitName":"Haloalkanes and Haloarenes","unitMarks":6,"count":73},{"n":7,"t":"Alcohols, Phenols and Ethers","unit":"VII","unitName":"Alcohols, Phenols and Ethers","unitMarks":6,"count":92},{"n":8,"t":"Aldehydes, Ketones and Carboxylic Acids","unit":"VIII","unitName":"Aldehydes, Ketones and Carboxylic Acids","unitMarks":8,"count":53},{"n":9,"t":"Amines","unit":"IX","unitName":"Amines","unitMarks":6,"count":107},{"n":10,"t":"Biomolecules","unit":"X","unitName":"Biomolecules","unitMarks":7,"count":92}],"questions":[{"id":"c0001","chapter":7,"type":"mcq","text":"Choose the compound which is more acidic than phenol :","options":{"A":"o-nitrophenol","B":"ethanol","C":"o-methylphenol","D":"o-methoxyphenol"},"answer":"A","hint":"Electron-withdrawing groups stabilise the phenoxide ion.","explanation":"The nitro group withdraws electrons and stabilises the o-nitrophenoxide ion, so o-nitrophenol is more acidic than phenol; ethanol and electron-donating substituted phenols are less acidic.","difficulty":1,"sources":[[2023,"C","56/C/1",1],[2023,"C","56/C/2",10],[2023,"C","56/C/3",6]]},{"id":"c0002","chapter":6,"type":"mcq","text":"Which of the following reactions is a halogenated exchange reaction :","options":{"A":"$>\\mathrm{C=C}< + \\mathrm{HX} \\rightarrow$ H–C–C–X (addition product, as drawn)","B":"$\\mathrm{R-X + NaI \\xrightarrow{Dry\\ acetone} R-I + NaX}$","C":"$\\mathrm{R-OH + HCl \\xrightarrow{ZnCl_2} R-Cl + H_2O}$","D":"Toluene + $\\mathrm{Br_2}$ (Fe, dark) giving o- and p-bromotoluene (structures as drawn)"},"answer":"B","hint":"One halogen is swapped for another halogen.","explanation":"Replacing X by I using NaI in dry acetone is the Finkelstein halogen exchange reaction.","difficulty":1,"figure":"figures/c0002.png","sources":[[2023,"C","56/C/1",2],[2023,"C","56/C/2",9],[2023,"C","56/C/3",14]]},{"id":"c0003","chapter":4,"type":"mcq","text":"The most common oxidation state for all lanthanoids is :","options":{"A":"$+5$","B":"$+2$","C":"$+3$","D":"$+4$"},"answer":"C","hint":"Think of the characteristic stable oxidation state of the 4f series.","explanation":"Lanthanoids characteristically show +3 as the most common oxidation state.","difficulty":1,"sources":[[2023,"C","56/C/1",3],[2023,"C","56/C/2",11],[2023,"C","56/C/3",12]]},{"id":"c0004","chapter":3,"type":"mcq","text":"A reaction follows second order kinetics. How is the rate of reaction affected if the concentration of the reactant is reduced to half ? Choose the correct value from the following :","options":{"A":"four times","B":"eight times","C":"$\\frac{1}{4}$ of the original value","D":"three times"},"answer":"C","hint":"Rate is proportional to the square of the concentration.","explanation":"Rate $= k[A]^2$; with $[A]$ halved, rate becomes $(1/2)^2 = 1/4$ of the original.","difficulty":1,"sources":[[2023,"C","56/C/1",4]]},{"id":"c0005","chapter":2,"type":"mcq","text":"Solutions of two electrolytes X and Y are diluted. Molar conductivity of X increases 25 times whereas that of Y increases $1{\\cdot}5$ times. Which one is a stronger electrolyte ?","options":{"A":"X","B":"Y","C":"Both X and Y","D":"None of the above"},"answer":"B","hint":"A strong electrolyte shows only a small rise in $\\Lambda_m$ on dilution.","explanation":"Molar conductivity of a strong electrolyte rises only slightly on dilution (already fully ionised), whereas a weak electrolyte rises sharply; so Y is stronger.","difficulty":2,"sources":[[2023,"C","56/C/1",5],[2023,"C","56/C/2",1],[2023,"C","56/C/3",11]]},{"id":"c0006","chapter":3,"type":"mcq","text":"Unit of rate constant for the zero order reaction is :","options":{"A":"$\\mathrm{s^{-1}}$","B":"$\\mathrm{mol^{-1}\\,L\\,s^{-1}}$","C":"$\\mathrm{mol^{-2}\\,L^{2}\\,s^{-1}}$","D":"$\\mathrm{mol\\,L^{-1}\\,s^{-1}}$"},"answer":"D","hint":"For zero order, rate = k.","explanation":"Rate = k for a zero order reaction, so k has the units of rate, $\\mathrm{mol\\,L^{-1}\\,s^{-1}}$.","difficulty":1,"sources":[[2023,"C","56/C/1",6],[2023,"C","56/C/2",12],[2023,"C","56/C/3",13]]},{"id":"c0007","chapter":9,"type":"mcq","text":"Three compounds are given below : I (p-nitroaniline), II (p-methylaniline, i.e. p-toluidine), III (aniline), drawn as structures.\nThe correct decreasing order of their basic strength is :","options":{"A":"II $>$ III $>$ I","B":"III $>$ II $>$ I","C":"III $>$ I $>$ II","D":"I $>$ III $>$ II"},"answer":"A","hint":"Electron-donating groups raise and electron-withdrawing groups lower basicity of aniline.","explanation":"The methyl group increases electron density on N while the nitro group decreases it, so basic strength is II > III > I.","difficulty":2,"figure":"figures/c0007.png","sources":[[2023,"C","56/C/1",7],[2023,"C","56/C/2",7]]},{"id":"c0008","chapter":5,"type":"mcq","text":"Which type of isomerism is shown by the complexes $\\mathrm{[Co(NH_3)_5Br]SO_4}$ and $\\mathrm{[Co(NH_3)_5SO_4]Br}$ ?","options":{"A":"Linkage","B":"Ionisation","C":"Optical","D":"Solvate"},"answer":"B","hint":"Compare which ion is inside and outside the coordination sphere.","explanation":"The two complexes exchange $\\mathrm{Br^-}$ and $\\mathrm{SO_4^{2-}}$ between the coordination sphere and the counter ion, which is ionisation isomerism.","difficulty":1,"sources":[[2023,"C","56/C/1",8]]},{"id":"c0009","chapter":8,"type":"mcq","text":"What would be the major product of the given reaction ?\n$\\mathrm{HCHO + CH_3MgI \\xrightarrow{H_2O}}$","options":{"A":"Ethanal","B":"Propanol","C":"Ethanol","D":"Propanal"},"answer":"C","hint":"Grignard reagent plus formaldehyde gives a primary alcohol.","explanation":"$\\mathrm{CH_3MgI}$ adds to HCHO to give $\\mathrm{CH_3CH_2OMgI}$, which on hydrolysis gives ethanol.","difficulty":1,"sources":[[2023,"C","56/C/1",9],[2023,"C","56/C/2",13],[2023,"C","56/C/3",2]]},{"id":"c0010","chapter":8,"type":"mcq","text":"Pentan-2-one and Pentan-3-one can be distinguished by :","options":{"A":"Fehling's test","B":"Sodium bicarbonate test","C":"Tollens' test","D":"Iodoform test"},"answer":"D","hint":"Look for the $\\mathrm{CH_3CO-}$ group.","explanation":"Pentan-2-one is a methyl ketone and gives the iodoform test; pentan-3-one does not.","difficulty":1,"sources":[[2023,"C","56/C/1",10],[2023,"C","56/C/2",3],[2023,"C","56/C/3",1]]},{"id":"c0011","chapter":9,"type":"mcq","text":"Hoffmann Bromamide Degradation reaction is given by :","options":{"A":"Structure (A)","B":"Structure (B)","C":"$\\mathrm{CH_3-C\\equiv N}$","D":"$\\mathrm{CH_3-CH_2-CONH_2}$"},"answer":"D","hint":"The reaction starts from a primary amide with $\\mathrm{Br_2}$ and NaOH.","explanation":"Hoffmann bromamide degradation converts a primary amide such as propanamide into a primary amine with one carbon less.","difficulty":1,"figure":"figures/c0011.png","sources":[[2023,"C","56/C/1",11],[2023,"C","56/C/3",9]]},{"id":"c0012","chapter":3,"type":"mcq","text":"Given below is the decomposition of hydrogen peroxide in alkaline medium, which is catalysed by iodide ions :\n$2\\mathrm{H_2O_2} \\xrightarrow[\\text{alkaline medium}]{\\mathrm{I^-}} 2\\mathrm{H_2O} + \\mathrm{O_2}$\nThe above reaction takes place in two steps :\nStep I : $\\mathrm{H_2O_2 + I^- \\rightarrow H_2O + IO^-}$ (slow)\nStep II : $\\mathrm{H_2O_2 + IO^- \\rightarrow H_2O + I^- + O_2}$\nMolecularity of Step I and Step II is :","options":{"A":"Step I $-$ 2, Step II $-$ 2","B":"Step I $-$ 1, Step II $-$ 2","C":"Step I $-$ 2, Step II $-$ 1","D":"Step I $-$ 3, Step II $-$ 1"},"answer":"A","hint":"Molecularity is the number of reacting species colliding in an elementary step.","explanation":"Each step has two reactant species colliding, so both steps are bimolecular (2 and 2).","difficulty":1,"sources":[[2023,"C","56/C/1",12],[2023,"C","56/C/2",6],[2023,"C","56/C/3",5]]},{"id":"c0013","chapter":5,"type":"mcq","text":"Oxidation state of central metal atom in the given complex is :\n$\\mathrm{[Co(NH_3)_4(H_2O)_2]Cl_3}$","options":{"A":"$+2$","B":"$+3$","C":"$+1$","D":"$+4$"},"answer":"B","hint":"Neutral ligands contribute zero; balance the charge of the cation with the chloride ions.","explanation":"Three $\\mathrm{Cl^-}$ outside means the complex ion is 3+; $\\mathrm{NH_3}$ and $\\mathrm{H_2O}$ are neutral, so Co is +3.","difficulty":1,"sources":[[2023,"C","56/C/1",13],[2023,"C","56/C/2",2],[2023,"C","56/C/3",10]]},{"id":"c0014","chapter":2,"type":"mcq","text":"A galvanic cell can behave as an electrolytic cell when :","options":{"A":"$E_\\mathrm{cell} = E_\\mathrm{ext}$","B":"$E_\\mathrm{cell} > E_\\mathrm{ext}$","C":"$E_\\mathrm{cell} = 0$","D":"$E_\\mathrm{ext} > E_\\mathrm{cell}$"},"answer":"D","hint":"Which direction does current flow when an opposing voltage dominates?","explanation":"When the external opposing potential exceeds the cell potential, the cell reactions are reversed and it works as an electrolytic cell.","difficulty":1,"sources":[[2023,"C","56/C/1",14],[2023,"C","56/C/2",5],[2023,"C","56/C/2",14],[2023,"C","56/C/3",3]]},{"id":"c0015","chapter":7,"type":"ar","text":"Assertion (A): Phenol gives 2,4,6-trinitrophenol on treatment with concentrated $\\mathrm{HNO_3}$ and concentrated $\\mathrm{H_2SO_4}$.\nReason (R): $-$OH group in phenol is $m$-directing.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Consider the directing influence of the OH group.","explanation":"A is true (picric acid forms). R is false because OH is ortho/para directing.","difficulty":1,"sources":[[2023,"C","56/C/1",15],[2023,"C","56/C/2",17],[2023,"C","56/C/3",18]]},{"id":"c0016","chapter":10,"type":"ar","text":"Assertion (A): D (+)-Glucose is dextrorotatory.\nReason (R): Symbol 'D' represents its dextrorotatory nature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"What does the prefix D denote in carbohydrate nomenclature?","explanation":"A is true. R is false: D refers to the configuration of the highest-numbered chiral carbon, not to the direction of rotation.","difficulty":1,"sources":[[2023,"C","56/C/1",16]]},{"id":"c0017","chapter":4,"type":"ar","text":"Assertion (A): Zn, Cd and Hg are not regarded as transition elements.\nReason (R): Zn, Cd and Hg do not have partially filled d-orbitals in their ground state or in any one of their common oxidation states.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Definition of a transition element.","explanation":"A is true and R is true; R is exactly the reason, since $d^{10}$ configuration is retained in the common +2 state, so R explains A.","difficulty":1,"sources":[[2023,"C","56/C/1",17],[2023,"C","56/C/2",18],[2023,"C","56/C/3",15],[2023,"C","56/C/B",17]]},{"id":"c0018","chapter":9,"type":"ar","text":"Assertion (A): Benzene diazonium salt is stable and can be easily stored.\nReason (R): Benzene diazonium chloride decomposes easily.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Diazonium chlorides are unstable at room temperature.","explanation":"A is false because benzene diazonium chloride is unstable and used in situ at 0-5 degrees C; R is true.","difficulty":1,"sources":[[2023,"C","56/C/1",18],[2023,"C","56/C/2",15],[2023,"C","56/C/3",17]]},{"id":"c0019","chapter":3,"type":"mcq","text":"The rate law for a particular reaction is given as rate $= k[A][B]^2$.\nHow is the rate of reaction affected if we double the concentration of B ? Choose the correct option :","options":{"A":"two times","B":"four times","C":"three times","D":"becomes half $\\left(\\frac{1}{2}\\right)$"},"answer":"B","hint":"B appears squared in the rate law.","explanation":"Rate depends on $[B]^2$, so doubling $[B]$ makes the rate $2^2 = 4$ times.","difficulty":1,"sources":[[2023,"C","56/C/2",4]]},{"id":"c0020","chapter":5,"type":"mcq","text":"Which type of isomerism is exhibited by the given complex ?\n$\\mathrm{[Pt(NH_3)_2Cl_2]}$","options":{"A":"Optical isomerism","B":"Geometrical isomerism","C":"Ionisation isomerism","D":"Coordination isomerism"},"answer":"B","hint":"Square planar $MA_2B_2$ complexes have cis and trans forms.","explanation":"Square planar $[Pt(NH_3)_2Cl_2]$ exists as cis and trans forms, i.e. geometrical isomerism.","difficulty":1,"sources":[[2023,"C","56/C/2",8]]},{"id":"c0021","chapter":10,"type":"ar","text":"Assertion (A): All monosaccharides are reducing sugars.\nReason (R): They reduce Fehling's and Tollens' reagent.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"What makes a sugar reducing?","explanation":"Monosaccharides have a free aldehyde/ketone (hemiacetal) group so they reduce Fehling's and Tollens' reagents; R explains A.","difficulty":2,"sources":[[2023,"C","56/C/2",16]]},{"id":"c0022","chapter":3,"type":"mcq","text":"A reaction is first order in A and second order in B. How is rate affected when concentration of both A and B are doubled ? Choose the correct option :","options":{"A":"eight times","B":"three times","C":"four times","D":"two times"},"answer":"A","hint":"Overall order is the sum of the individual orders.","explanation":"Rate $= k[A][B]^2$; doubling both gives $2 \\times 2^2 = 8$ times.","difficulty":1,"sources":[[2023,"C","56/C/3",4]]},{"id":"c0023","chapter":5,"type":"mcq","text":"Which type of isomerism is shown by the given complex ?\n$\\mathrm{[Co(en)_3]^{3+}}$","options":{"A":"Coordination isomerism","B":"Optical isomerism","C":"Linkage isomerism","D":"Ionisation isomerism"},"answer":"B","hint":"Tris-chelate octahedral complexes lack a mirror plane.","explanation":"$[Co(en)_3]^{3+}$ is a chiral octahedral complex and exists as a pair of enantiomers, so it shows optical isomerism.","difficulty":1,"sources":[[2023,"C","56/C/3",8]]},{"id":"c0024","chapter":10,"type":"ar","text":"Assertion (A): Glucose gets oxidised to six carbon carboxylic acid on reaction with bromine water.\nReason (R): Glucose contains a ketonic group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Bromine water oxidises an aldehyde group.","explanation":"A is true (gluconic acid forms) because glucose has an aldehyde group; R is false since glucose is an aldose, not a ketose.","difficulty":1,"sources":[[2023,"C","56/C/3",16]]},{"id":"c0025","chapter":1,"type":"mcq","text":"A solution that obeys Raoult's law is called :","options":{"A":"a non-ideal solution","B":"a molar solution","C":"an ideal solution","D":"a saturated solution"},"answer":"C","hint":"Definition of an ideal solution.","explanation":"A solution obeying Raoult's law over the whole range of concentration is an ideal solution.","difficulty":1,"sources":[[2023,"C","56/C/B",1]]},{"id":"c0026","chapter":2,"type":"mcq","text":"The products of the electrolysis of aqueous NaCl are :","options":{"A":"$\\mathrm{H_2}$ and $\\mathrm{O_2}$","B":"$\\mathrm{H_2}$, $\\mathrm{Cl_2}$ and NaOH","C":"$\\mathrm{H_2}$, $\\mathrm{O_2}$ and Na","D":"$\\mathrm{O_2}$ and NaOH"},"answer":"B","hint":"Water is reduced at the cathode in preference to $\\mathrm{Na^+}$ (chlor-alkali process).","explanation":"$\\mathrm{H_2}$ forms at the cathode, $\\mathrm{Cl_2}$ at the anode and NaOH remains in solution.","difficulty":1,"sources":[[2023,"C","56/C/B",2]]},{"id":"c0027","chapter":2,"type":"mcq","text":"Which of the following cells is not rechargeable ?","options":{"A":"Dry cell","B":"Lead storage battery","C":"Ni-Cd battery","D":"Fuel cell"},"answer":"A","hint":"Primary cells cannot be recharged.","explanation":"The dry cell is a primary cell, whose reactions are not reversible; lead storage and Ni-Cd are secondary cells.","difficulty":1,"sources":[[2023,"C","56/C/B",3]]},{"id":"c0028","chapter":3,"type":"mcq","text":"The unit of zero order reaction is :","options":{"A":"$\\mathrm{s^{-1}}$","B":"$\\mathrm{L^2\\,mol^{-1}\\,s^{-1}}$","C":"$\\mathrm{mol\\,L^{-1}\\,s^{-1}}$","D":"$\\mathrm{L\\,s^{-1}}$"},"answer":"C","hint":"For zero order, rate = k.","explanation":"Rate constant of a zero order reaction has the units of rate, $\\mathrm{mol\\,L^{-1}\\,s^{-1}}$.","difficulty":1,"sources":[[2023,"C","56/C/B",4]]},{"id":"c0029","chapter":4,"type":"mcq","text":"Which of the following transition metal ions is a strong oxidising agent in aqueous solution ?","options":{"A":"$\\mathrm{Zn^{2+}}$","B":"$\\mathrm{Mn^{2+}}$","C":"$\\mathrm{Mn^{3+}}$","D":"$\\mathrm{Cr^{2+}}$"},"answer":"C","hint":"Look for a large positive $E^\\circ$ for reduction.","explanation":"$\\mathrm{Mn^{3+}/Mn^{2+}}$ has a very high positive reduction potential (+1.57 V), so $\\mathrm{Mn^{3+}}$ is a strong oxidising agent; $\\mathrm{Cr^{2+}}$ is a reducing agent.","difficulty":2,"sources":[[2023,"C","56/C/B",5]]},{"id":"c0030","chapter":5,"type":"mcq","text":"Which of the following ligands is an ambidentate ligand ?","options":{"A":"$\\mathrm{OH^-}$","B":"$\\mathrm{NH_3}$","C":"CO","D":"$\\mathrm{NO_2^-}$"},"answer":"D","hint":"Ambidentate ligands have two different donor atoms.","explanation":"$\\mathrm{NO_2^-}$ can bind through N or O, so it is ambidentate.","difficulty":1,"sources":[[2023,"C","56/C/B",6]]},{"id":"c0031","chapter":5,"type":"mcq","text":"How many hydrate isomers are possible of the complex with the formula $\\mathrm{CrCl_3\\cdot 6H_2O}$ ?","options":{"A":"Six","B":"Four","C":"Three","D":"Two"},"answer":"C","hint":"Vary how many water molecules lie inside the coordination sphere.","explanation":"The standard hydrate isomers are $\\mathrm{[Cr(H_2O)_6]Cl_3}$, $\\mathrm{[CrCl(H_2O)_5]Cl_2\\cdot H_2O}$ and $\\mathrm{[CrCl_2(H_2O)_4]Cl\\cdot 2H_2O}$: three.","difficulty":3,"note":"Official answer C (three). Some books also count a fourth, [CrCl3(H2O)3]·3H2O.","sources":[[2023,"C","56/C/B",7]]},{"id":"c0032","chapter":8,"type":"mcq","text":"Which of the following, on reaction with $\\mathrm{CH_3MgI}$ and subsequent hydrolysis, will form a primary alcohol ?","options":{"A":"HCHO","B":"$\\mathrm{CH_3CHO}$","C":"$\\mathrm{CH_3COCH_3}$","D":"Benzaldehyde"},"answer":"A","hint":"Which carbonyl compound gives a primary alcohol with a Grignard reagent?","explanation":"Formaldehyde with a Grignard reagent gives a primary alcohol; other aldehydes give secondary and ketones give tertiary alcohols.","difficulty":1,"sources":[[2023,"C","56/C/B",8]]},{"id":"c0033","chapter":7,"type":"mcq","text":"Which of the following compound is called Picric acid ?","options":{"A":"p-Nitrophenol","B":"2,4-Dinitrophenol","C":"2,4,6-Trinitrophenol","D":"2,6-Dinitrophenol"},"answer":"C","hint":"Picric acid has three nitro groups.","explanation":"Picric acid is 2,4,6-trinitrophenol.","difficulty":1,"sources":[[2023,"C","56/C/B",9]]},{"id":"c0034","chapter":6,"type":"mcq","text":"1,2-Dichloroethane is heated with KOH (1 mole) in ethanol. The major product formed is :","options":{"A":"Acetylene","B":"Vinyl chloride","C":"2-Chloroethanol","D":"Ethylene glycol"},"answer":"B","hint":"One mole of alcoholic KOH removes only one HCl.","explanation":"Alcoholic KOH causes dehydrohalogenation; with 1 mole one HCl is eliminated giving vinyl chloride.","difficulty":2,"sources":[[2023,"C","56/C/B",10]]},{"id":"c0035","chapter":1,"type":"mcq","text":"The osmotic pressure of a solution increases if the :","options":{"A":"number of solute molecules is increased.","B":"temperature is decreased.","C":"volume is increased.","D":"number of solute molecules is decreased."},"answer":"A","hint":"Use $\\pi = CRT$.","explanation":"$\\pi = CRT$ rises with more solute molecules (higher concentration); lower T or larger volume decreases it.","difficulty":1,"sources":[[2023,"C","56/C/B",11]]},{"id":"c0036","chapter":8,"type":"mcq","text":"Clemmensen Reduction of aldehydes and ketonic carbonyl groups into methylene group is effected by the reagent :","options":{"A":"$\\mathrm{H_2}$, Pd","B":"$\\mathrm{LiAlH_4}$","C":"Zn$-$Hg, conc. HCl","D":"$\\mathrm{NH_2-NH_2}$, KOH"},"answer":"C","hint":"Name reaction reagent recall.","explanation":"Clemmensen reduction uses zinc amalgam and concentrated HCl; hydrazine/KOH is Wolff-Kishner.","difficulty":1,"sources":[[2023,"C","56/C/B",12]]},{"id":"c0037","chapter":10,"type":"mcq","text":"Vitamin $\\mathrm{B_{12}}$ is also called :","options":{"A":"Riboflavin","B":"Thiamine","C":"Pyridoxine","D":"Cyanocobalamin"},"answer":"D","hint":"Vitamin B12 contains cobalt.","explanation":"Vitamin $B_{12}$ is cyanocobalamin; riboflavin is $B_2$, thiamine $B_1$, pyridoxine $B_6$.","difficulty":1,"sources":[[2023,"C","56/C/B",13]]},{"id":"c0038","chapter":10,"type":"mcq","text":"Which one among the following bases is present in RNA but usually not in DNA ?","options":{"A":"Uracil","B":"Thymine","C":"Adenine","D":"Guanine"},"answer":"A","hint":"RNA replaces one of DNA's bases.","explanation":"Uracil replaces thymine in RNA.","difficulty":1,"sources":[[2023,"C","56/C/B",14]]},{"id":"c0039","chapter":9,"type":"ar","text":"Assertion (A): Ammonolysis of alkyl halides is not a suitable method for the preparation of pure primary amines.\nReason (R): Ammonolysis of alkyl halides yields mainly tertiary amines.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Ammonolysis gives a mixture of amines.","explanation":"A is true because a mixture of primary, secondary, tertiary amines and quaternary salt forms; R is false since the product is a mixture, not mainly tertiary amine.","difficulty":2,"sources":[[2023,"C","56/C/B",15],[2023,"R","56/1/3",15]]},{"id":"c0040","chapter":10,"type":"ar","text":"Assertion (A): Sucrose is a non-reducing sugar.\nReason (R): Sucrose has a glycosidic linkage.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Why does sucrose not reduce Tollens' reagent?","explanation":"Both statements are true; sucrose is non-reducing because the glycosidic link joins both anomeric carbons, so no free aldehyde/hemiacetal exists. A glycosidic linkage by itself (also in reducing disaccharides like maltose) does not explain it, hence R is not the correct explanation.","difficulty":3,"sources":[[2023,"C","56/C/B",16]]},{"id":"c0041","chapter":3,"type":"ar","text":"Assertion (A): Hydrolysis of an ester in acidic medium is a second order reaction.\nReason (R): For a complex reaction, order is given by the slowest step.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Water is present in large excess.","explanation":"A is false: acid-catalysed ester hydrolysis is pseudo first order because water is in large excess; R is true.","difficulty":2,"sources":[[2023,"C","56/C/B",18]]},{"id":"c0042","chapter":1,"type":"mcq","text":"For an electrolyte undergoing dissociation in an aqueous solution the Van't Hoff factor :","options":{"A":"is always less than one.","B":"is always greater than one.","C":"has zero value.","D":"has negative value."},"answer":"B","hint":"Dissociation increases the number of particles.","explanation":"Dissociation increases the number of solute particles, so $i > 1$.","difficulty":1,"sources":[[2023,"R","56(B)",1]]},{"id":"c0043","chapter":2,"type":"mcq","text":"Which of the following cells has a constant voltage throughout its life ?","options":{"A":"Dry cell","B":"Electrolytic cell","C":"Mercury cell","D":"Daniell cell"},"answer":"C","hint":"Which cell has no ion concentration change in its overall reaction?","explanation":"The overall mercury cell reaction involves no ions in solution, so its potential stays constant (about 1.35 V).","difficulty":1,"sources":[[2023,"R","56(B)",2]]},{"id":"c0044","chapter":2,"type":"mcq","text":"How many Faradays are required to reduce one mole of $\\mathrm{Sn^{4+}}$ to $\\mathrm{Sn^{2+}}$ ?","options":{"A":"$2{\\cdot}0$","B":"$4{\\cdot}0$","C":"$1{\\cdot}0$","D":"$6{\\cdot}0$"},"answer":"A","hint":"Count the electrons gained per ion.","explanation":"$\\mathrm{Sn^{4+}} + 2e^- \\rightarrow \\mathrm{Sn^{2+}}$ needs 2 mol of electrons, i.e. 2 F.","difficulty":1,"sources":[[2023,"R","56(B)",3]]},{"id":"c0045","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{A + 2B \\rightarrow 3C + D}$, $\\frac{d[C]}{dt}$ is equal to :","options":{"A":"$-\\frac{d[A]}{dt}$","B":"$-\\frac{d[B]}{dt}$","C":"$+\\frac{3\\,d[A]}{dt}$","D":"$\\frac{-3}{2}\\frac{d[B]}{dt}$"},"answer":"D","hint":"Divide each rate by its stoichiometric coefficient and equate.","explanation":"Rate $= -d[A]/dt = -\\tfrac12 d[B]/dt = \\tfrac13 d[C]/dt$, so $d[C]/dt = -\\tfrac32\\, d[B]/dt$.","difficulty":2,"sources":[[2023,"R","56(B)",4]]},{"id":"c0046","chapter":3,"type":"mcq","text":"The unit of rate constant and rate of reaction are identical for a :","options":{"A":"zero order reaction","B":"first order reaction","C":"second order reaction","D":"third order reaction"},"answer":"A","hint":"For which order does rate = k?","explanation":"Only in a zero order reaction rate $= k$, so the units are the same.","difficulty":1,"sources":[[2023,"R","56(B)",5]]},{"id":"c0047","chapter":4,"type":"mcq","text":"Which of the following transition metals do not show variable oxidation states ?","options":{"A":"Cu","B":"Ti","C":"Mn","D":"Sc"},"answer":"D","hint":"Which metal has only one stable oxidation state?","explanation":"Sc shows only the +3 state; Cu, Ti and Mn show several.","difficulty":1,"sources":[[2023,"R","56(B)",6]]},{"id":"c0048","chapter":5,"type":"mcq","text":"The coordination number of Ag in $\\mathrm{[Ag(NH_3)_2]Cl}$ is :","options":{"A":"3","B":"1","C":"2","D":"4"},"answer":"C","hint":"Count the ligand donor atoms bonded to the metal.","explanation":"Each $\\mathrm{NH_3}$ is monodentate and there are two, so the coordination number is 2.","difficulty":1,"sources":[[2023,"R","56(B)",7]]},{"id":"c0049","chapter":5,"type":"mcq","text":"Amongst the following, the most stable complex is :","options":{"A":"$\\mathrm{[Fe(C_2O_4)_3]^{3-}}$","B":"$\\mathrm{[FeCl_6]^{3-}}$","C":"$\\mathrm{[Fe(H_2O)_6]^{3+}}$","D":"$\\mathrm{[Fe(NH_3)_6]^{3+}}$"},"answer":"A","hint":"Which ligand forms chelate rings?","explanation":"Oxalate is a bidentate chelating ligand forming three five-membered rings, giving the chelate effect and greatest stability.","difficulty":1,"sources":[[2023,"R","56(B)",8],[2026,"C","56(B)/7",8]]},{"id":"c0050","chapter":8,"type":"mcq","text":"Acetyl chloride is treated with $\\mathrm{H_2}$ in the presence of $\\mathrm{Pd\\text{-}BaSO_4}$.\nThe product formed is :","options":{"A":"$\\mathrm{CH_3CH_2OH}$","B":"$\\mathrm{CH_3CHO}$","C":"$\\mathrm{CH_3COOH}$","D":"$\\mathrm{CH_3COCH_3}$"},"answer":"B","hint":"Think of the poisoned catalyst used in a named reduction of acyl chlorides.","explanation":"This is the Rosenmund reduction, which stops at the aldehyde, giving $\\mathrm{CH_3CHO}$.","difficulty":1,"sources":[[2023,"R","56(B)",9]]},{"id":"c0051","chapter":9,"type":"mcq","text":"The Gabriel phthalimide synthesis is used for the preparation of :","options":{"A":"primary aromatic amines","B":"primary aliphatic amines","C":"secondary amines","D":"tertiary amines"},"answer":"B","hint":"Alkyl halide reacts with potassium phthalimide, then hydrolysis.","explanation":"Aryl halides do not undergo nucleophilic substitution with phthalimide anion, so only primary aliphatic amines are made.","difficulty":1,"sources":[[2023,"R","56(B)",10],[2025,"C","56(B)/S",6],[2025,"R","56(B)",2]]},{"id":"c0052","chapter":9,"type":"mcq","text":"The action of nitrous acid on ethylamine gives mainly :","options":{"A":"ethyl nitrite","B":"ethane","C":"nitroethane","D":"ethyl alcohol"},"answer":"D","hint":"Primary aliphatic amines give diazonium salts that are unstable.","explanation":"$\\mathrm{C_2H_5NH_2 + HNO_2 \\rightarrow C_2H_5OH + N_2 + H_2O}$; ethyl alcohol is the main product.","difficulty":1,"sources":[[2023,"R","56(B)",11]]},{"id":"c0053","chapter":10,"type":"mcq","text":"The helix structure of proteins is stabilized by :","options":{"A":"peptide bonds","B":"disulphide bonds","C":"hydrogen bonds","D":"Van der Waals forces"},"answer":"C","hint":"Secondary structure involves interactions between C=O and N-H groups.","explanation":"In the $\\alpha$-helix, hydrogen bonds between the C=O of one residue and the N-H of another stabilise the coil.","difficulty":1,"sources":[[2023,"R","56(B)",12]]},{"id":"c0054","chapter":10,"type":"mcq","text":"The deficiency of which Vitamin causes rickets ?","options":{"A":"Vitamin A","B":"Vitamin B","C":"Vitamin C","D":"Vitamin D"},"answer":"D","hint":"This vitamin helps calcium absorption and bone formation.","explanation":"Deficiency of vitamin D causes rickets in children (osteomalacia in adults).","difficulty":1,"sources":[[2023,"R","56(B)",13]]},{"id":"c0055","chapter":1,"type":"ar","text":"Assertion (A): Molarity of solution in liquid state changes with temperature.\nReason (R): The volume of a solution changes with change in temperature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Molarity = moles per litre of solution.","explanation":"A is true and R is true; volume change alters moles per litre, so R explains A.","difficulty":1,"sources":[[2023,"R","56(B)",15]]},{"id":"c0056","chapter":4,"type":"ar","text":"Assertion (A): $\\mathrm{Fe^{2+}}$ acts as a reducing agent.\nReason (R): $\\mathrm{Fe^{3+}}$ state is stable due to $3d^5$ configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Half-filled d subshell gives extra stability.","explanation":"$\\mathrm{Fe^{2+}}$ readily loses an electron to reach stable $3d^5$ $\\mathrm{Fe^{3+}}$; both true and R explains A.","difficulty":2,"sources":[[2023,"R","56(B)",16],[2023,"R","56/3/3",18]]},{"id":"c0057","chapter":6,"type":"ar","text":"Assertion (A): Nucleophilic substitution reaction of an optically active halide gives a mixture of enantiomers.\nReason (R): $\\mathrm{S_N2}$ reactions of optically active halides are accompanied by inversion of configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Racemisation arises from SN1, not SN2.","explanation":"Both statements are true (A for SN1 pathways), but inversion in SN2 does not explain a racemic mixture.","difficulty":2,"sources":[[2023,"R","56(B)",17]]},{"id":"c0058","chapter":7,"type":"ar","text":"Assertion (A): The boiling point of ethanol is lower than that of diethyl ether.\nReason (R): In ethanol, the molecules are associated due to intermolecular hydrogen bonding, whereas in diethyl ether it is not possible.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Compare hydrogen bonding with boiling point.","explanation":"A is false because ethanol (78 C) boils higher than diethyl ether (35 C); R is true.","difficulty":1,"sources":[[2023,"R","56(B)",18]]},{"id":"c0059","chapter":1,"type":"mcq","text":"The colligative property used for the determination of molar mass of polymers and proteins is :","options":{"A":"Osmotic pressure","B":"Depression in freezing point","C":"Relative lowering in vapour pressure","D":"Elevation is boiling point"},"answer":"A","hint":"Which property is measurable for very dilute, high-molar-mass solutes?","explanation":"Osmotic pressure is measured at room temperature with large, observable values even for tiny molar concentrations.","difficulty":1,"sources":[[2023,"R","56/1/1",1],[2023,"R","56/1/2",8]]},{"id":"c0060","chapter":1,"type":"mcq","text":"Low concentration of oxygen in the blood and tissues of people living at high altitude is due to :","options":{"A":"high atmospheric pressure","B":"low temperature","C":"low atmospheric pressure","D":"both low temperature and high atmospheric pressure"},"answer":"C","hint":"Think of Henry's law.","explanation":"Lower pressure at altitude lowers the partial pressure and hence the dissolved concentration of oxygen.","difficulty":1,"sources":[[2023,"R","56/1/1",2],[2023,"R","56/1/2",9]]},{"id":"c0061","chapter":2,"type":"mcq","text":"The correct cell to represent the following reaction is :\n$\\mathrm{Zn + 2Ag^+ \\rightarrow Zn^{2+} + 2Ag}$","options":{"A":"$\\mathrm{2Ag \\mid Ag^+ \\parallel Zn \\mid Zn^{2+}}$","B":"$\\mathrm{Ag^+ \\mid Ag \\parallel Zn^{2+} \\mid Zn}$","C":"$\\mathrm{Ag \\mid Ag^+ \\parallel Zn \\mid Zn^{2+}}$","D":"$\\mathrm{Zn \\mid Zn^{2+} \\parallel Ag^+ \\mid Ag}$"},"answer":"D","hint":"Oxidation (anode) is written on the left.","explanation":"Zn is oxidised at the anode (left) and $\\mathrm{Ag^+}$ reduced at the cathode (right).","difficulty":1,"sources":[[2023,"R","56/1/1",3],[2023,"R","56/1/3",11]]},{"id":"c0062","chapter":2,"type":"mcq","text":"$\\Delta G$ and $E^\\circ_\\mathrm{cell}$ for a spontaneous reaction will be :","options":{"A":"positive, negative","B":"negative, negative","C":"negative, positive","D":"positive, positive"},"answer":"C","hint":"Use $\\Delta G^\\circ = -nFE^\\circ$.","explanation":"A spontaneous reaction has $\\Delta G<0$ and hence $E^\\circ_\\mathrm{cell}>0$.","difficulty":1,"sources":[[2023,"R","56/1/1",4],[2023,"R","56/1/3",12]]},{"id":"c0063","chapter":3,"type":"mcq","text":"Which of the following is affected by catalyst ?","options":{"A":"$\\Delta H$","B":"$\\Delta G$","C":"$E_a$","D":"$\\Delta S$"},"answer":"C","hint":"A catalyst provides an alternative pathway.","explanation":"A catalyst lowers the activation energy $E_a$ and leaves state functions $\\Delta H$, $\\Delta G$, $\\Delta S$ unchanged.","difficulty":1,"sources":[[2023,"R","56/1/1",5],[2023,"R","56/1/2",10],[2023,"R","56/1/3",13]]},{"id":"c0064","chapter":4,"type":"mcq","text":"The most common and stable oxidation state of a Lanthanoid is :","options":{"A":"+ 2","B":"+ 3","C":"+ 4","D":"+ 6"},"answer":"B","hint":"Recall the characteristic oxidation state of f-block elements.","explanation":"Lanthanoids most commonly show the +3 state.","difficulty":1,"sources":[[2023,"R","56/1/1",7],[2023,"R","56/1/2",13],[2023,"R","56/1/3",10]]},{"id":"c0065","chapter":5,"type":"mcq","text":"The compounds $\\mathrm{[Co(SO_4)(NH_3)_5]Br}$ and $\\mathrm{[Co(Br)(NH_3)_5]SO_4}$ represent :","options":{"A":"optical isomerism","B":"linkage isomerism","C":"ionisation isomerism","D":"coordination isomerism"},"answer":"C","hint":"Which ion is outside the coordination sphere in each?","explanation":"They differ in the ion (bromide vs sulphate) inside versus outside the sphere, i.e. ionisation isomers.","difficulty":1,"sources":[[2023,"R","56/1/1",8],[2023,"R","56/1/2",11],[2023,"R","56/1/3",5]]},{"id":"c0066","chapter":6,"type":"mcq","text":"The synthesis of alkyl fluoride is best obtained from :","options":{"A":"Free radicals","B":"Swartz reaction","C":"Sandmeyer reaction","D":"Finkelstein reaction"},"answer":"B","hint":"Which named reaction uses metallic fluorides?","explanation":"Swarts reaction heats an alkyl chloride/bromide with $\\mathrm{AgF}$ or $\\mathrm{Hg_2F_2}$ to give the alkyl fluoride.","difficulty":1,"sources":[[2023,"R","56/1/1",9],[2023,"R","56/1/2",12]]},{"id":"c0067","chapter":7,"type":"mcq","text":"In the reaction $\\mathrm{R-OH + HCl \\xrightarrow{ZnCl_2} RCl + H_2O}$, what is the correct order of reactivity of alcohol ?","options":{"A":"$1^\\circ < 2^\\circ < 3^\\circ$","B":"$1^\\circ > 3^\\circ > 2^\\circ$","C":"$1^\\circ > 2^\\circ > 3^\\circ$","D":"$3^\\circ > 1^\\circ > 2^\\circ$"},"answer":"A","hint":"Lucas reagent reacts via carbocation intermediates.","explanation":"Reactivity follows carbocation stability, $3^\\circ>2^\\circ>1^\\circ$.","difficulty":1,"sources":[[2023,"R","56/1/1",10],[2023,"R","56/1/2",7],[2023,"R","56/1/3",4]]},{"id":"c0068","chapter":9,"type":"mcq","text":"$\\mathrm{CH_3CONH_2}$ on reaction with $\\mathrm{NaOH}$ and $\\mathrm{Br_2}$ in alcoholic medium gives :","options":{"A":"$\\mathrm{CH_3COONa}$","B":"$\\mathrm{CH_3NH_2}$","C":"$\\mathrm{CH_3CH_2Br}$","D":"$\\mathrm{CH_3CH_2NH_2}$"},"answer":"B","hint":"Hofmann bromamide degradation loses one carbon.","explanation":"The amide gives a primary amine with one carbon fewer, $\\mathrm{CH_3NH_2}$.","difficulty":1,"sources":[[2023,"R","56/1/1",11],[2023,"R","56/1/2",6],[2023,"R","56/1/3",3]]},{"id":"c0069","chapter":9,"type":"mcq","text":"Which of the following is least basic ?","options":{"A":"$\\mathrm{(CH_3)_2NH}$","B":"$\\mathrm{NH_3}$","C":"Aniline (benzene ring bonded to $\\mathrm{NH_2}$, drawn as a structure)","D":"$\\mathrm{(CH_3)_3N}$"},"answer":"C","hint":"Lone pair delocalisation into the ring lowers basicity.","explanation":"In aniline the lone pair on N is delocalised into the benzene ring, making it the weakest base.","difficulty":1,"figure":"figures/c0069.png","sources":[[2023,"R","56/1/1",12],[2023,"R","56/1/2",5],[2023,"R","56/1/3",6]]},{"id":"c0070","chapter":10,"type":"mcq","text":"An $\\alpha$-helix is a structural feature of :","options":{"A":"Sucrose","B":"Starch","C":"Polypeptides","D":"Nucleotides"},"answer":"C","hint":"Secondary structure of proteins.","explanation":"$\\alpha$-Helix is a secondary structure of polypeptides/proteins.","difficulty":1,"sources":[[2023,"R","56/1/1",14],[2023,"R","56/1/2",1]]},{"id":"c0071","chapter":9,"type":"ar","text":"Assertion (A): $\\mathrm{-NH_2}$ group is $o$- and $p$-directing in electrophilic substitution reactions.\nReason (R): Aniline cannot undergo Friedel-Crafts reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Amino group is activating, but Lewis acid complexes with it.","explanation":"Both true: the -NH2 donates electrons to o/p positions; aniline fails Friedel-Crafts because $\\mathrm{AlCl_3}$ forms a salt, which does not explain o,p-direction.","difficulty":2,"sources":[[2023,"R","56/1/1",15]]},{"id":"c0072","chapter":9,"type":"ar","text":"Assertion (A): Acetylation of aniline gives a monosubstituted product.\nReason (R): Activating effect of $\\mathrm{-NHCOCH_3}$ group is more than that of amino group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Compare the electron donation of NHCOCH3 with NH2.","explanation":"A is true; R is false since the acetamido group is less activating than the amino group, which restricts reaction to monosubstitution.","difficulty":2,"sources":[[2023,"R","56/1/1",16],[2023,"R","56/1/2",17],[2023,"R","56/1/3",18]]},{"id":"c0073","chapter":3,"type":"ar","text":"Assertion (A): The molecularity of the reaction $\\mathrm{H_2 + Br_2 \\rightarrow 2HBr}$ appears to be 2.\nReason (R): Two molecules of the reactants are involved in the given elementary reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Molecularity counts reacting species in an elementary step.","explanation":"As written, two reactant molecules are involved, so molecularity appears to be 2, and R explains A.","difficulty":2,"sources":[[2023,"R","56/1/1",17],[2023,"R","56/1/2",16],[2023,"R","56/1/3",16],[2025,"C","56/S/1",15],[2025,"C","56/S/2",13],[2025,"C","56/S/3",14]]},{"id":"c0074","chapter":5,"type":"ar","text":"Assertion (A): Low spin tetrahedral complexes are rarely observed.\nReason (R): Crystal field splitting energy is less than pairing energy for tetrahedral complexes.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Compare $\\Delta_t$ with pairing energy.","explanation":"$\\Delta_t\\approx\\tfrac{4}{9}\\Delta_o$ is small, below pairing energy, so high spin is favoured; R explains A.","difficulty":2,"sources":[[2023,"R","56/1/1",18],[2023,"R","56/1/3",17]]},{"id":"c0075","chapter":2,"type":"mcq","text":"$\\mathrm{Ag^+(aq) + e^- \\rightarrow Ag(s)}$   $E^\\circ = +0.80\\ \\mathrm{V}$\n$\\mathrm{Fe^{2+}(aq) + 2e^- \\rightarrow Fe(s)}$   $E^\\circ = -0.44\\ \\mathrm{V}$\nFind the $E^\\circ_\\mathrm{cell}$ for :\n$\\mathrm{Fe(s) + 2Ag^+(aq) \\rightarrow Fe^{2+}(aq) + 2Ag(s)}$","options":{"A":"$1.6\\ \\mathrm{V}$","B":"$-1.16\\ \\mathrm{V}$","C":"$2.04\\ \\mathrm{V}$","D":"$1.24\\ \\mathrm{V}$"},"answer":"D","hint":"$E^\\circ_\\mathrm{cell}=E^\\circ_\\mathrm{cathode}-E^\\circ_\\mathrm{anode}$ (do not multiply by stoichiometry).","explanation":"$E^\\circ_\\mathrm{cell}=0.80-(-0.44)=1.24\\ \\mathrm{V}$.","difficulty":1,"sources":[[2023,"R","56/1/2",3]]},{"id":"c0076","chapter":9,"type":"ar","text":"Assertion (A): $\\mathrm{(C_2H_5)_2NH}$ is more basic than $\\mathrm{(C_2H_5)_3N}$ in aqueous solution.\nReason (R): In $\\mathrm{(C_2H_5)_2NH}$, there is more steric hindrance and $+I$ effect than $\\mathrm{(C_2H_5)_3N}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"In water, solvation (H-bonding) and sterics decide basicity of ethylamines.","explanation":"A is true (better solvation of the ammonium ion); R is false since the tertiary amine has more steric hindrance and +I effect.","difficulty":2,"sources":[[2023,"R","56/1/2",15]]},{"id":"c0077","chapter":5,"type":"ar","text":"Assertion (A): EDTA is used to determine hardness of water.\nReason (R): EDTA is a bidentate ligand.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Count donor atoms in EDTA.","explanation":"A is true (complexometric titration); R is false because EDTA is hexadentate.","difficulty":1,"sources":[[2023,"R","56/1/2",18]]},{"id":"c0078","chapter":1,"type":"mcq","text":"On dissolving ammonium chloride in water at room temperature, the solution feels cool to touch. Under which of the following conditions does salt dissolve faster ?","options":{"A":"Powdered salt in cold water","B":"Powdered salt in hot water","C":"Salt crystals in cold water","D":"Salt crystals in hot water"},"answer":"B","hint":"Dissolution is endothermic; consider temperature and surface area.","explanation":"Heat favours an endothermic dissolution and powder has larger surface area, so powdered salt in hot water dissolves fastest.","difficulty":1,"sources":[[2023,"R","56/1/3",1]]},{"id":"c0079","chapter":4,"type":"mcq","text":"Lanthanoid contraction is due to increase in :","options":{"A":"atomic number","B":"shielding by 4f electrons","C":"effective nuclear charge","D":"atomic radius"},"answer":"C","hint":"Poor shielding by 4f electrons.","explanation":"Poor shielding by 4f electrons increases effective nuclear charge across the series, so size decreases.","difficulty":2,"sources":[[2023,"R","56/1/3",2]]},{"id":"c0080","chapter":6,"type":"mcq","text":"The species that attacks benzene in following is :\nBenzene + $\\mathrm{Cl_2}$ with $\\mathrm{AlCl_3}$ gives chlorobenzene (reaction scheme drawn as a figure).","options":{"A":"$\\mathrm{Cl^-}$","B":"$\\mathrm{AlCl_4^-}$","C":"$\\mathrm{AlCl_3}$","D":"$\\mathrm{Cl^+}$"},"answer":"D","hint":"Lewis acid generates an electrophile.","explanation":"$\\mathrm{AlCl_3}$ polarises $\\mathrm{Cl_2}$ to give the electrophile $\\mathrm{Cl^+}$ that attacks benzene.","difficulty":1,"figure":"figures/c0080.png","sources":[[2023,"R","56/1/3",9]]},{"id":"c0081","chapter":10,"type":"mcq","text":"Which of the following is a non-reducing sugar ?","options":{"A":"Sucrose","B":"Maltose","C":"Glucose","D":"Lactose"},"answer":"A","hint":"Both anomeric carbons involved in the glycosidic bond.","explanation":"In sucrose the glycosidic bond uses both anomeric carbons, leaving no free aldehyde/hemiacetal group.","difficulty":1,"sources":[[2023,"R","56/1/3",14]]},{"id":"c0082","chapter":6,"type":"mcq","text":"The conversion of an alkyl halide into an alkene by alcoholic KOH is classified as","options":{"A":"a substitution reaction","B":"an addition reaction","C":"a dehydrohalogenation reaction","D":"a dehydration reaction"},"answer":"C","hint":"Loss of HX.","explanation":"Alcoholic KOH removes H and X (beta-elimination), i.e. dehydrohalogenation.","difficulty":1,"sources":[[2023,"R","56/2/1",1]]},{"id":"c0083","chapter":5,"type":"mcq","text":"The oxidation state of Fe in $\\mathrm{[Fe(CO)_5]}$ is","options":{"A":"+ 2","B":"0","C":"+ 3","D":"+ 5"},"answer":"B","hint":"CO is a neutral ligand.","explanation":"The complex is neutral and CO is neutral, so Fe is in oxidation state 0.","difficulty":1,"sources":[[2023,"R","56/2/1",2]]},{"id":"c0084","chapter":9,"type":"mcq","text":"Among the following, which is the strongest base ?\n(Options are drawn structures: (A) aniline, (B) 4-methylaniline, (C) benzylamine, (D) 4-nitroaniline.)","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"C","hint":"Where is the nitrogen lone pair, delocalised or not?","explanation":"In benzylamine the lone pair is not conjugated with the ring, so it is the strongest base.","difficulty":2,"figure":"figures/c0084.png","sources":[[2023,"R","56/2/1",3]]},{"id":"c0085","chapter":3,"type":"mcq","text":"The slope in the plot of $\\ln[R]$ vs. time for a first order reaction is","options":{"A":"$\\dfrac{+k}{2.303}$","B":"$-k$","C":"$\\dfrac{-k}{2.303}$","D":"$+k$"},"answer":"B","hint":"Integrated form $\\ln[R]=\\ln[R]_0-kt$.","explanation":"$\\ln[R]=\\ln[R]_0-kt$ is linear with slope $-k$.","difficulty":1,"sources":[[2023,"R","56/2/1",4],[2023,"R","56/2/2",4],[2025,"R","56/7/3",4]]},{"id":"c0086","chapter":10,"type":"mcq","text":"An $\\alpha$-helix is a structural feature of","options":{"A":"Sucrose","B":"Polypeptides","C":"Nucleotides","D":"Starch"},"answer":"B","hint":"Secondary structure of proteins.","explanation":"$\\alpha$-Helix is a secondary structure of polypeptides/proteins.","difficulty":1,"sources":[[2023,"R","56/2/1",5]]},{"id":"c0087","chapter":6,"type":"mcq","text":"Racemisation occurs in","options":{"A":"$\\mathrm{S_N1}$ reaction","B":"$\\mathrm{S_N2}$ reaction","C":"Neither $\\mathrm{S_N1}$ nor $\\mathrm{S_N2}$ reaction","D":"$\\mathrm{S_N2}$ reaction as well as $\\mathrm{S_N1}$ reaction"},"answer":"A","hint":"Planar carbocation intermediate.","explanation":"$\\mathrm{S_N1}$ proceeds through a planar carbocation attacked from both faces, giving a racemic mixture.","difficulty":1,"sources":[[2023,"R","56/2/1",6]]},{"id":"c0088","chapter":1,"type":"mcq","text":"Value of Henry's constant $K_H$ :","options":{"A":"increases with decrease in temperature.","B":"decreases with increase in temperature.","C":"increases with increase in temperature.","D":"remains constant."},"answer":"C","hint":"Gas solubility falls as temperature rises.","explanation":"Solubility of gases decreases with temperature, so $K_H$ increases with temperature.","difficulty":1,"sources":[[2023,"R","56/2/1",7]]},{"id":"c0089","chapter":2,"type":"mcq","text":"Which of the following solutions of KCl will have the highest value of molar conductivity ?","options":{"A":"0.01 M","B":"1 M","C":"0.5 M","D":"0.1 M"},"answer":"A","hint":"Molar conductivity rises on dilution.","explanation":"$\\Lambda_m$ increases with dilution, so the most dilute (0.01 M) solution has the highest value.","difficulty":1,"sources":[[2023,"R","56/2/1",8],[2023,"R","56/2/2",8]]},{"id":"c0090","chapter":7,"type":"mcq","text":"Which of the following reactions are feasible ?","options":{"A":"$\\mathrm{CH_3CH_2Br + Na^+\\,O^-C(CH_3)_3 \\rightarrow CH_3CH_2-O-C(CH_3)_3}$","B":"$\\mathrm{(CH_3)_3C-Cl + Na^+\\,O^-CH_2CH_3 \\rightarrow CH_3CH_2-O-C(CH_3)_3}$","C":"Both (a) and (b)","D":"Neither (a) nor (b)"},"answer":"A","hint":"Williamson synthesis needs a primary alkyl halide.","explanation":"A primary halide with tert-butoxide undergoes SN2 to give the ether; tertiary chloride with alkoxide mainly eliminates.","difficulty":2,"sources":[[2023,"R","56/2/1",9],[2023,"R","56/2/2",10],[2023,"R","56/2/3",10]]},{"id":"c0091","chapter":8,"type":"mcq","text":"Which of the following is most reactive in nucleophilic addition reactions ?","options":{"A":"$\\mathrm{HCHO}$","B":"$\\mathrm{CH_3CHO}$","C":"$\\mathrm{CH_3COCH_3}$","D":"$\\mathrm{CH_3COC_2H_5}$"},"answer":"A","hint":"Less steric hindrance and fewer +I groups increase reactivity.","explanation":"Formaldehyde has no alkyl groups, so least hindered and most electrophilic carbonyl carbon.","difficulty":1,"sources":[[2023,"R","56/2/1",10]]},{"id":"c0092","chapter":8,"type":"mcq","text":"Which of the following does not give aldol condensation reaction ?","options":{"A":"$\\mathrm{CH_3-CHO}$","B":"Cyclohexane ring bonded to $\\mathrm{-CHO}$ (structure drawn)","C":"Benzene ring bonded to $\\mathrm{-CHO}$ (structure drawn)","D":"$\\mathrm{CH_3COCH_3}$"},"answer":"C","hint":"Aldol condensation needs alpha-hydrogens.","explanation":"Benzaldehyde has no alpha-hydrogen, so it cannot give aldol condensation.","difficulty":1,"figure":"figures/c0092.png","sources":[[2023,"R","56/2/1",11]]},{"id":"c0093","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{3A \\rightarrow 2B}$, rate of reaction $+\\dfrac{d[B]}{dt}$ is equal to","options":{"A":"$\\dfrac{-3}{2}\\dfrac{d[A]}{dt}$","B":"$\\dfrac{-2}{3}\\dfrac{d[A]}{dt}$","C":"$\\dfrac{-1}{3}\\dfrac{d[A]}{dt}$","D":"$+\\dfrac{2d[A]}{dt}$"},"answer":"B","hint":"Relate rates of change through stoichiometric coefficients.","explanation":"$-\\frac{1}{3}\\frac{d[A]}{dt}=\\frac{1}{2}\\frac{d[B]}{dt}$, so $\\frac{d[B]}{dt}=-\\frac{2}{3}\\frac{d[A]}{dt}$.","difficulty":2,"sources":[[2023,"R","56/2/1",12],[2023,"R","56/2/2",12]]},{"id":"c0094","chapter":4,"type":"mcq","text":"Which of the following characteristics of transition metals is associated with their catalytic activity ?","options":{"A":"Paramagnetic nature","B":"Colour of hydrated ions","C":"High enthalpy of atomisation","D":"Variable oxidation states"},"answer":"D","hint":"Intermediate formation requires multiple oxidation states.","explanation":"Variable oxidation states let transition metals form unstable intermediates, enabling catalysis.","difficulty":1,"sources":[[2023,"R","56/2/1",13]]},{"id":"c0095","chapter":5,"type":"mcq","text":"The formula of the complex dichloridobis (ethane-1, 2-diamine) platinum (IV) nitrate is","options":{"A":"$\\mathrm{[PtCl_2(en)_2(NO_3)_2]}$","B":"$\\mathrm{[PtCl_2(en)_2](NO_3)_2}$","C":"$\\mathrm{[PtCl_2(en)_2(NO_3)]NO_3}$","D":"$\\mathrm{[Pt(en)_2(NO_3)_2]Cl_2}$"},"answer":"B","hint":"Name lists ligands inside the bracket; nitrate is the counter ion.","explanation":"Pt(IV) with two Cl- and two neutral en gives a 2+ cation, balanced by two nitrate ions.","difficulty":2,"sources":[[2023,"R","56/2/1",14],[2023,"R","56/2/2",13]]},{"id":"c0096","chapter":1,"type":"ar","text":"Assertion (A): Osmotic pressure is a colligative property.\nReason (R): Osmotic pressure is proportional to the molality.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"$\\pi = CRT$ uses molarity.","explanation":"A is true; R is false because osmotic pressure is proportional to molarity (concentration), not molality in the strict sense.","difficulty":1,"sources":[[2023,"R","56/2/1",15]]},{"id":"c0097","chapter":2,"type":"ar","text":"Assertion (A): Conductivity decreases with decrease in concentration of electrolyte.\nReason (R): Number of ions per unit volume that carry the current in a solution decreases on dilution.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Conductivity depends on number of ions per unit volume.","explanation":"Both true; fewer ions per unit volume on dilution lowers conductivity, so R explains A.","difficulty":1,"sources":[[2023,"R","56/2/1",16],[2023,"R","56/2/2",17]]},{"id":"c0098","chapter":4,"type":"ar","text":"Assertion (A): Copper is a non-transition element.\nReason (R): Copper has completely filled d-orbitals in its ground state.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Transition elements have incomplete d orbitals in atom or ions.","explanation":"A is false: copper forms $\\mathrm{Cu^{2+}}$ ($3d^9$) and is a transition element; R is true ($3d^{10}4s^1$).","difficulty":2,"sources":[[2023,"R","56/2/1",17]]},{"id":"c0099","chapter":6,"type":"ar","text":"Assertion (A): Nucleophilic substitution of iodoethane is easier than chloroethane.\nReason (R): Bond enthalpy of C-I bond is less than that of C-Cl bond.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Weaker bond means better leaving group.","explanation":"C-I bond is weaker, so iodide leaves more easily; both true and R explains A.","difficulty":1,"sources":[[2023,"R","56/2/1",18]]},{"id":"c0100","chapter":6,"type":"mcq","text":"Which of the following belongs to the class of Vinyl halides ?","options":{"A":"$\\mathrm{CH_2=CHCH_2CH_2Cl}$","B":"$\\mathrm{CH_2=C(Br)-CH_3}$","C":"$\\mathrm{CH_2=CH-CH_2-Br}$","D":"$\\mathrm{CH\\equiv C-Br}$"},"answer":"B","hint":"Halogen must be attached to an sp2 carbon of a C=C bond.","explanation":"In $\\mathrm{CH_2=C(Br)CH_3}$ Br is on a doubly bonded carbon, a vinyl halide; (a),(c) are allylic/alkyl and (d) is alkynyl.","difficulty":1,"sources":[[2023,"R","56/2/2",1]]},{"id":"c0101","chapter":5,"type":"mcq","text":"What is the secondary valency of Cobalt in $\\mathrm{[Co(en)_2Cl_2]^+}$ ?","options":{"A":"6","B":"4","C":"2","D":"8"},"answer":"A","hint":"Secondary valency equals the coordination number.","explanation":"Two bidentate en (4 donor atoms) and two Cl give coordination number 6.","difficulty":1,"sources":[[2023,"R","56/2/2",2]]},{"id":"c0102","chapter":9,"type":"mcq","text":"When Benzene diazonium chloride reacts with phenol, it forms a dye. This reaction is called","options":{"A":"Diazotisation reaction","B":"Condensation reaction","C":"Coupling reaction","D":"Acetylation reaction"},"answer":"C","hint":"Diazonium salts attack activated aromatic rings to give azo compounds.","explanation":"Formation of the azo dye (p-hydroxyazobenzene) is a coupling reaction.","difficulty":1,"sources":[[2023,"R","56/2/2",3]]},{"id":"c0103","chapter":10,"type":"mcq","text":"Proteins are polymers of","options":{"A":"Nucleic acids","B":"Amino acids","C":"Monosaccharides","D":"Amines"},"answer":"B","hint":"Think of the peptide-bond monomers.","explanation":"Proteins are polypeptides built from amino acids.","difficulty":1,"sources":[[2023,"R","56/2/2",5]]},{"id":"c0104","chapter":6,"type":"mcq","text":"Retention of configuration is observed in","options":{"A":"$\\mathrm{S_N1}$ reaction","B":"$\\mathrm{S_N2}$ reaction","C":"Neither $\\mathrm{S_N1}$ nor $\\mathrm{S_N2}$ reaction","D":"$\\mathrm{S_N2}$ reaction as well as $\\mathrm{S_N1}$ reaction"},"answer":"A","hint":"Compare the stereochemical outcome of the two mechanisms.","explanation":"$\\mathrm{S_N2}$ always inverts; only $\\mathrm{S_N1}$ (planar carbocation, attack from both faces) can give retention along with inversion.","difficulty":2,"sources":[[2023,"R","56/2/2",6]]},{"id":"c0105","chapter":1,"type":"mcq","text":"An azeotropic mixture of two liquids will have a boiling point lower than either of the two liquids when it","options":{"A":"shows a negative deviation from Raoult's law","B":"forms an ideal solution","C":"shows a positive deviation from Raoult's law","D":"is saturated"},"answer":"C","hint":"Higher vapour pressure means lower boiling point.","explanation":"Positive deviation raises vapour pressure, giving a minimum-boiling azeotrope.","difficulty":1,"sources":[[2023,"R","56/2/2",7]]},{"id":"c0106","chapter":8,"type":"mcq","text":"Which of the following does not give Cannizzaro reaction ?","options":{"A":"$\\mathrm{(CH_3)_3C{-}CHO}$","B":"$\\mathrm{(CH_3)_2CH{-}CHO}$","C":"$\\mathrm{C_6H_5CHO}$ (benzaldehyde, drawn as a structure)","D":"$\\mathrm{HCHO}$"},"answer":"B","hint":"Cannizzaro needs an aldehyde with no alpha-hydrogen.","explanation":"Only $\\mathrm{(CH_3)_2CHCHO}$ has an alpha-H, so it undergoes aldol rather than Cannizzaro.","difficulty":1,"figure":"figures/c0106.png","sources":[[2023,"R","56/2/2",9]]},{"id":"c0107","chapter":8,"type":"mcq","text":"Aldehydes and ketones react with hydroxylamine to form","options":{"A":"hydrazones","B":"cyanohydrins","C":"semicarbazones","D":"Oxime"},"answer":"D","hint":"Name the product from the nucleophile $\\mathrm{NH_2OH}$.","explanation":"$\\mathrm{NH_2OH}$ condenses with $\\mathrm{C=O}$ to give oximes.","difficulty":1,"sources":[[2023,"R","56/2/2",11]]},{"id":"c0108","chapter":4,"type":"mcq","text":"Which one among the following metals of 3d series has the lowest melting point ?","options":{"A":"Fe","B":"Mn","C":"Zn","D":"Cu"},"answer":"C","hint":"Metals with filled d subshell have weak metallic bonding.","explanation":"Zn has no unpaired d electrons, so weakest metallic bonding and lowest melting point.","difficulty":1,"sources":[[2023,"R","56/2/2",14]]},{"id":"c0109","chapter":1,"type":"ar","text":"Assertion (A): Elevation in boiling point is a colligative property.\nReason (R): The lowering of vapour pressure of solution causes elevation in boiling point.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Is R about why the property is colligative?","explanation":"Both true; R explains why boiling point rises but not why the property depends only on the number of particles.","difficulty":2,"sources":[[2023,"R","56/2/2",15]]},{"id":"c0110","chapter":6,"type":"ar","text":"Assertion (A): Chlorobenzene is resistant to electrophilic substitution reaction.\nReason (R): C-Cl bond in chlorobenzene acquires partial double bond character due to resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Resonance of Cl lone pair also affects the ring's reactivity differently.","explanation":"Both statements accepted as true; the partial double bond character explains difficult nucleophilic substitution, not the deactivated ring toward electrophiles.","difficulty":2,"sources":[[2023,"R","56/2/2",16]]},{"id":"c0111","chapter":4,"type":"ar","text":"Assertion (A): Transition metals have high enthalpy of atomisation.\nReason (R): Greater number of unpaired electrons in transition metals results in weak metallic bonding.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"More unpaired d electrons gives stronger metallic bonds.","explanation":"A true; R false because more unpaired electrons means stronger, not weaker, metallic bonding.","difficulty":1,"sources":[[2023,"R","56/2/2",18]]},{"id":"c0112","chapter":6,"type":"mcq","text":"Auto oxidation of chloroform in air and sunlight produces a poisonous gas known as","options":{"A":"Tear gas","B":"Mustard gas","C":"Phosgene gas","D":"Chlorine gas"},"answer":"C","hint":"Stored chloroform is kept in dark bottles for this reason.","explanation":"Chloroform oxidises to carbonyl chloride, $\\mathrm{COCl_2}$, called phosgene.","difficulty":1,"sources":[[2023,"R","56/2/3",1]]},{"id":"c0113","chapter":5,"type":"mcq","text":"Which of the following ligands is an ambidentate ligand ?","options":{"A":"CO","B":"$\\mathrm{NO_2^-}$","C":"$\\mathrm{NH_3}$","D":"$\\mathrm{H_2O}$"},"answer":"B","hint":"Look for a ligand with two different donor atoms.","explanation":"$\\mathrm{NO_2^-}$ can bind through N or O.","difficulty":1,"note":"The paper omits the charge on NO2 (nitrite ion).","sources":[[2023,"R","56/2/3",2]]},{"id":"c0114","chapter":9,"type":"mcq","text":"Among the following, which has the highest value of $pK_b$ ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"D","hint":"Highest $pK_b$ means weakest base.","explanation":"Options: aniline, benzylamine, p-toluidine, p-nitroaniline; the electron-withdrawing nitro group makes p-nitroaniline the weakest base.","difficulty":2,"figure":"figures/c0114.png","sources":[[2023,"R","56/2/3",3]]},{"id":"c0115","chapter":3,"type":"mcq","text":"The slope in the plot of $\\log\\dfrac{[R]_0}{[R]}$ vs. time for a first order reaction is","options":{"A":"$\\dfrac{+k}{2.303}$","B":"$+k$","C":"$\\dfrac{-k}{2.303}$","D":"$-k$"},"answer":"A","hint":"Use $k=\\frac{2.303}{t}\\log\\frac{[R]_0}{[R]}$.","explanation":"$\\log\\frac{[R]_0}{[R]}=\\frac{k}{2.303}t$, so slope is $+k/2.303$.","difficulty":1,"sources":[[2023,"R","56/2/3",4]]},{"id":"c0116","chapter":10,"type":"mcq","text":"When D-glucose reacts with HI, it forms","options":{"A":"Gluconic acid","B":"n-hexane","C":"Saccharic acid","D":"Iodohexane"},"answer":"B","hint":"HI prolonged heating reduces all oxygen functions.","explanation":"Prolonged heating with HI reduces glucose completely to n-hexane, showing a straight six-carbon chain.","difficulty":1,"sources":[[2023,"R","56/2/3",5]]},{"id":"c0117","chapter":6,"type":"mcq","text":"Inversion of configuration occurs in","options":{"A":"$\\mathrm{S_N2}$ reaction","B":"$\\mathrm{S_N1}$ reaction","C":"Neither $\\mathrm{S_N2}$ nor $\\mathrm{S_N1}$ reaction","D":"$\\mathrm{S_N1}$ as well as $\\mathrm{S_N2}$ reaction"},"answer":"A","hint":"Backside attack.","explanation":"$\\mathrm{S_N2}$ proceeds by backside attack, giving inversion (Walden inversion).","difficulty":1,"sources":[[2023,"R","56/2/3",6]]},{"id":"c0118","chapter":1,"type":"mcq","text":"Solubility of gas in liquid decreases with increase in","options":{"A":"Pressure","B":"Temperature","C":"Volume","D":"Number of solute molecules"},"answer":"B","hint":"Dissolution of gases is exothermic.","explanation":"Gas solubility falls as temperature rises (Henry's constant increases).","difficulty":1,"sources":[[2023,"R","56/2/3",7]]},{"id":"c0119","chapter":2,"type":"mcq","text":"Which of the following relations is incorrect ?","options":{"A":"$R=\\dfrac{1}{\\kappa}\\left(\\dfrac{l}{a}\\right)$","B":"$G=\\kappa\\left(\\dfrac{a}{l}\\right)$","C":"$G=\\kappa\\left(\\dfrac{l}{a}\\right)$","D":"$\\Lambda_m=\\dfrac{\\kappa}{c}$"},"answer":"C","hint":"Conductance is the reciprocal of resistance.","explanation":"$G=1/R=\\kappa a/l$, so $G=\\kappa(l/a)$ is wrong.","difficulty":1,"note":"The paper prints k for κ (conductivity).","sources":[[2023,"R","56/2/3",8]]},{"id":"c0120","chapter":8,"type":"mcq","text":"The reagent that can be used to distinguish acetophenone and benzophenone is","options":{"A":"2,4-dinitrophenylhydrazine","B":"aqueous $\\mathrm{NaHSO_3}$","C":"Fehling solution","D":"$\\mathrm{I_2}$ and $\\mathrm{NaOH}$"},"answer":"D","hint":"Look for a methyl ketone test.","explanation":"Acetophenone ($\\mathrm{C_6H_5COCH_3}$) gives iodoform with $\\mathrm{I_2/NaOH}$; benzophenone does not.","difficulty":1,"sources":[[2023,"R","56/2/3",9]]},{"id":"c0121","chapter":8,"type":"mcq","text":"Which of the following compounds will undergo self-condensation in the presence of dilute NaOH solution ?","options":{"A":"$\\mathrm{C_6H_5CHO}$","B":"$\\mathrm{CH_3CH_2CHO}$","C":"$\\mathrm{(CH_3)_3C{-}CHO}$","D":"$\\mathrm{H{-}CHO}$"},"answer":"B","hint":"Aldol condensation needs alpha-hydrogen.","explanation":"Only propanal has alpha-hydrogens, so it undergoes aldol condensation.","difficulty":1,"sources":[[2023,"R","56/2/3",11]]},{"id":"c0122","chapter":4,"type":"mcq","text":"Which of the following transition metals shows +1 and +2 oxidation states ?","options":{"A":"Mn","B":"Zn","C":"Sc","D":"Cu"},"answer":"D","hint":"Think of Cu(I) and Cu(II).","explanation":"Copper shows +1 ($3d^{10}$) and +2 states; Zn only +2, Sc only +3, Mn many.","difficulty":1,"sources":[[2023,"R","56/2/3",13]]},{"id":"c0123","chapter":5,"type":"mcq","text":"The formula of the complex Iron (III) hexacyanidoferrate (II) is :","options":{"A":"$\\mathrm{Fe_2[Fe(CN)_6]_3}$","B":"$\\mathrm{Fe_4[Fe(CN)_6]_3}$","C":"$\\mathrm{Fe[Fe(CN)_6]}$","D":"$\\mathrm{Fe_3[Fe(CN)_6]_2}$"},"answer":"B","hint":"Balance charges: the anion carries $4-$.","explanation":"$\\mathrm{[Fe(CN)_6]^{4-}}$ needs $\\mathrm{Fe^{3+}}$ in ratio 4:3 for neutrality.","difficulty":2,"sources":[[2023,"R","56/2/3",14]]},{"id":"c0124","chapter":1,"type":"ar","text":"Assertion (A): The enthalpy of mixing $\\Delta_\\mathrm{mix}H$ is equal to zero for an ideal solution.\nReason (R): For an ideal solution the interaction between solute and solvent molecules is stronger than the interactions between solute-solute or solvent-solvent molecules.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"What does an ideal solution require of intermolecular forces?","explanation":"A true; R false because in an ideal solution A-B interactions equal A-A and B-B interactions.","difficulty":1,"sources":[[2023,"R","56/2/3",15]]},{"id":"c0125","chapter":2,"type":"ar","text":"Assertion (A): Molar conductivity decreases with increase in concentration.\nReason (R): When concentration approaches zero, the molar conductivity is known as limiting molar conductivity.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"R defines a term; does it explain the trend?","explanation":"Both true, but R only defines $\\Lambda_m^\\circ$ and does not explain the decrease.","difficulty":1,"sources":[[2023,"R","56/2/3",16]]},{"id":"c0126","chapter":4,"type":"ar","text":"Assertion (A): Transition metals show their highest oxidation state with oxygen.\nReason (R): The ability of oxygen to form multiple bonds to metals.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Multiple bonding stabilises high oxidation states.","explanation":"Both true; oxygen's ability to form $\\pi$ bonds (e.g. in oxides, oxoanions) stabilises the highest states.","difficulty":2,"sources":[[2023,"R","56/2/3",17],[2026,"R","56/3/3",14]]},{"id":"c0127","chapter":6,"type":"ar","text":"Assertion (A): Chlorobenzene is resistant to nucleophilic substitution reaction at room temperature.\nReason (R): C-Cl bond gets weaker due to resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Resonance gives partial double bond character.","explanation":"A true; R false because resonance strengthens the C-Cl bond.","difficulty":1,"sources":[[2023,"R","56/2/3",18]]},{"id":"c0128","chapter":6,"type":"mcq","text":"Which of the following is not true about enantiomers ?","options":{"A":"They have the same density.","B":"They have the same melting or boiling point.","C":"They have the same specific rotation.","D":"They have the same chemical reactivity."},"answer":"C","hint":"Enantiomers differ in optical activity.","explanation":"They rotate plane polarised light equally but in opposite directions, so specific rotations are opposite in sign.","difficulty":1,"sources":[[2023,"R","56/3/1",1],[2026,"R","56/1/2",10],[2026,"R","56/1/3",6]]},{"id":"c0129","chapter":8,"type":"mcq","text":"Aspirin is obtained by the acetylation of which of the following compounds ?","options":{"A":"Salicylaldehyde","B":"Salicylic acid","C":"Acetyl salicylic acid","D":"Phenol"},"answer":"B","hint":"Aspirin itself is acetylsalicylic acid.","explanation":"Acetylation of the phenolic OH of salicylic acid gives aspirin.","difficulty":1,"sources":[[2023,"R","56/3/1",2]]},{"id":"c0130","chapter":8,"type":"mcq","text":"The reactivities of the carbonyl compounds $\\mathrm{HCHO}$ (I), $\\mathrm{CH_3CHO}$ (II) and $\\mathrm{CH_3COCH_3}$ (III) towards nucleophilic addition reaction decreases in the order :","options":{"A":"III > II > I","B":"I > II > III","C":"II > III > I","D":"I > III > II"},"answer":"B","hint":"Consider +I effect and steric hindrance.","explanation":"Fewer alkyl groups mean greater positive charge and less hindrance: HCHO > CH3CHO > CH3COCH3.","difficulty":1,"sources":[[2023,"R","56/3/1",3]]},{"id":"c0131","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives only glucose ?","options":{"A":"Starch","B":"Fructose","C":"Lactose","D":"Sucrose"},"answer":"A","hint":"Check which is a polymer of one monomer.","explanation":"Starch is a polymer of $\\alpha$-D-glucose; lactose gives galactose, sucrose gives fructose too.","difficulty":1,"sources":[[2023,"R","56/3/1",5]]},{"id":"c0132","chapter":10,"type":"mcq","text":"Which of the following vitamins is water soluble ?","options":{"A":"Vitamin A","B":"Vitamin D","C":"Vitamin E","D":"Vitamin C"},"answer":"D","hint":"Fat-soluble vitamins are A, D, E, K.","explanation":"Vitamin C (and B group) are water soluble.","difficulty":1,"sources":[[2023,"R","56/3/1",6]]},{"id":"c0133","chapter":3,"type":"mcq","text":"The unit of the rate of reaction is the same as that of the rate constant for a :","options":{"A":"first order reaction","B":"second order reaction","C":"zero order reaction","D":"it cannot be same"},"answer":"C","hint":"Rate = $k[A]^n$; when is the concentration factor absent?","explanation":"For zero order, rate $=k$, both in $\\mathrm{mol\\,L^{-1}\\,s^{-1}}$.","difficulty":1,"sources":[[2023,"R","56/3/1",7]]},{"id":"c0134","chapter":2,"type":"mcq","text":"Kohlrausch gave the following relation for strong electrolyte : $\\Lambda=\\Lambda_\\circ-A\\sqrt{C}$. Which of the following equality holds true ?","options":{"A":"$\\Lambda=\\Lambda_\\circ$ as $C\\rightarrow\\sqrt{A}$","B":"$\\Lambda=\\Lambda_\\circ$ as $C\\rightarrow 0$","C":"$\\Lambda=\\Lambda_\\circ$ as $C\\rightarrow\\infty$","D":"$\\Lambda=\\Lambda_\\circ$ as $C\\rightarrow 1$"},"answer":"B","hint":"The correction term vanishes at which concentration?","explanation":"At infinite dilution ($C\\to0$) the $A\\sqrt{C}$ term vanishes, so $\\Lambda=\\Lambda^\\circ$.","difficulty":1,"sources":[[2023,"R","56/3/1",8],[2023,"R","56/3/2",9]]},{"id":"c0135","chapter":1,"type":"mcq","text":"An azeotropic mixture of two liquids has a boiling point higher than either of the two liquids when it :","options":{"A":"shows large negative deviation from Raoult's law.","B":"shows no deviation from Raoult's law.","C":"shows large positive deviation from Raoult's law.","D":"obeys Raoult's law."},"answer":"A","hint":"Lower vapour pressure means higher boiling point.","explanation":"Large negative deviation lowers vapour pressure, giving a maximum-boiling azeotrope.","difficulty":1,"sources":[[2023,"R","56/3/1",9],[2023,"R","56/3/2",8],[2023,"R","56/3/3",3]]},{"id":"c0136","chapter":1,"type":"mcq","text":"Which of the following colligative property is used to find the molar mass of proteins ?","options":{"A":"Osmotic pressure","B":"Elevation in boiling point","C":"Depression in freezing point","D":"Relative lowering of vapour pressure"},"answer":"A","hint":"Which property is measurable for very dilute solutions of large molecules?","explanation":"Osmotic pressure is measurable at room temperature even for tiny molar concentrations.","difficulty":1,"sources":[[2023,"R","56/3/1",10]]},{"id":"c0137","chapter":4,"type":"mcq","text":"Among the following outermost configurations of transition metals which one shows the highest oxidation state ?","options":{"A":"$3d^34s^2$","B":"$3d^54s^1$","C":"$3d^54s^2$","D":"$3d^64s^2$"},"answer":"C","hint":"Highest state uses all $4s$ and unpaired $3d$ electrons.","explanation":"$3d^54s^2$ (Mn) can lose 7 electrons, giving +7.","difficulty":1,"sources":[[2023,"R","56/3/1",11],[2025,"R","56/7/2",1]]},{"id":"c0138","chapter":5,"type":"mcq","text":"How many ions are produced in the solution from the complex $\\mathrm{[Ni(NH_3)_6]Cl_2}$ ?","options":{"A":"4","B":"3","C":"2","D":"5"},"answer":"B","hint":"Only the counter ions separate from the coordination sphere.","explanation":"It gives one $\\mathrm{[Ni(NH_3)_6]^{2+}}$ and two $\\mathrm{Cl^-}$: 3 ions.","difficulty":1,"sources":[[2023,"R","56/3/1",12]]},{"id":"c0139","chapter":5,"type":"mcq","text":"Which of the following species is not expected to be a ligand ?","options":{"A":"CO","B":"$\\mathrm{NH_4^+}$","C":"$\\mathrm{NH_3}$","D":"$\\mathrm{H_2O}$"},"answer":"B","hint":"A ligand needs a lone pair.","explanation":"$\\mathrm{NH_4^+}$ has no lone pair on N.","difficulty":1,"sources":[[2023,"R","56/3/1",13]]},{"id":"c0140","chapter":5,"type":"mcq","text":"Which of the following is the most stable complex species ?","options":{"A":"$\\mathrm{[Fe(C_2O_4)_3]^{3-}}$","B":"$\\mathrm{[Fe(CN)_6]^{3-}}$","C":"$\\mathrm{[Fe(CO)_5]}$","D":"$\\mathrm{[Fe(H_2O)_6]^{3+}}$"},"answer":"A","hint":"Chelate effect.","explanation":"Oxalate is a bidentate chelating ligand, giving extra stability (chelate effect).","difficulty":2,"sources":[[2023,"R","56/3/1",14]]},{"id":"c0141","chapter":3,"type":"ar","text":"Assertion (A): Order and molecularity of a reaction are always same.\nReason (R): Complex reactions involve a sequence of elementary reactions and the slowest step is rate determining.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Order is experimental; molecularity applies to elementary steps.","explanation":"A false (order can be zero or fractional); R true.","difficulty":2,"sources":[[2023,"R","56/3/1",15],[2023,"R","56/3/2",18],[2023,"R","56/3/3",16]]},{"id":"c0142","chapter":2,"type":"ar","text":"Assertion (A): Electrolysis of aqueous solution of NaCl gives chlorine gas at anode instead of oxygen gas.\nReason (R): Formation of oxygen gas at anode requires overpotential.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think about the kinetic barrier to $\\mathrm{O_2}$ evolution.","explanation":"Both true; the overpotential for $\\mathrm{O_2}$ makes $\\mathrm{Cl_2}$ form preferentially.","difficulty":2,"sources":[[2023,"R","56/3/1",16],[2023,"R","56/3/2",17]]},{"id":"c0143","chapter":6,"type":"ar","text":"Assertion (A): Nucleophilic substitution of iodoethane is easier than chloroethane.\nReason (R): Bond energy of C-Cl bond is less than C-I bond.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Compare C-X bond strengths.","explanation":"A true (weaker C-I bond); R false because C-Cl is stronger than C-I.","difficulty":1,"sources":[[2023,"R","56/3/1",17],[2023,"R","56/3/2",16],[2023,"R","56/3/3",15]]},{"id":"c0144","chapter":4,"type":"ar","text":"Assertion (A): Zinc is not regarded as a transition element.\nReason (R): In zinc, 3d orbitals are completely filled in its ground state as well as in its oxidised state.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Transition element needs incomplete d subshell in some state.","explanation":"Both true; $\\mathrm{Zn^{2+}}$ is $3d^{10}$, so no incomplete d level, explaining exclusion.","difficulty":1,"sources":[[2023,"R","56/3/1",18],[2023,"R","56/3/2",15],[2023,"R","56/3/3",17]]},{"id":"c0145","chapter":6,"type":"mcq","text":"Which of the following has the highest melting point ?","options":{"A":"o-Dichlorobenzene","B":"m-Dichlorobenzene","C":"p-Dichlorobenzene","D":"All have the same melting point"},"answer":"C","hint":"Symmetry affects crystal packing.","explanation":"The para isomer packs best in the crystal lattice, giving the highest melting point.","difficulty":1,"sources":[[2023,"R","56/3/2",1]]},{"id":"c0146","chapter":7,"type":"mcq","text":"Sodium phenoxide when heated with $\\mathrm{CO_2}$ under pressure, followed by acidification, yields :","options":{"A":"Sodium benzoate","B":"Salicylic acid","C":"Salicylaldehyde","D":"Benzoic acid"},"answer":"B","hint":"Kolbe's reaction.","explanation":"Kolbe reaction gives ortho-hydroxybenzoic acid (salicylic acid).","difficulty":1,"sources":[[2023,"R","56/3/2",2]]},{"id":"c0147","chapter":8,"type":"mcq","text":"A compound (A) with molecular formula $\\mathrm{C_5H_{10}O}$, forms a phenyl hydrazone and gives negative Tollens' and iodoform tests. The compound on reduction gives n-pentane. The compound (A) is :","options":{"A":"Pentan-3-one","B":"Pentanal","C":"Pentanol","D":"Pentan-2-one"},"answer":"A","hint":"Ketone, but not a methyl ketone, with straight chain.","explanation":"Phenylhydrazone and negative Tollens means a ketone; negative iodoform excludes pentan-2-one; straight chain gives pentan-3-one.","difficulty":2,"sources":[[2023,"R","56/3/2",3]]},{"id":"c0148","chapter":9,"type":"mcq","text":"Benzene diazonium chloride on hydrolysis gives :","options":{"A":"Phenol","B":"Chlorobenzene","C":"Benzene","D":"Aniline"},"answer":"A","hint":"Warming with water replaces the diazo group.","explanation":"Warming with water replaces $\\mathrm{N_2^+}$ by OH, giving phenol.","difficulty":1,"sources":[[2023,"R","56/3/2",4],[2025,"R","56(B)",10]]},{"id":"c0149","chapter":10,"type":"mcq","text":"Helical structure of proteins is stabilized by :","options":{"A":"ionic bond","B":"covalent bond","C":"hydrogen bond","D":"Van der Waals forces"},"answer":"C","hint":"Think secondary structure.","explanation":"The $\\alpha$-helix is held by N-H...O=C hydrogen bonds.","difficulty":1,"sources":[[2023,"R","56/3/2",5]]},{"id":"c0150","chapter":10,"type":"mcq","text":"A vitamin which plays a vital role in the clotting of blood is :","options":{"A":"Vitamin A","B":"Vitamin K","C":"Vitamin D","D":"Vitamin B"},"answer":"B","hint":"Think of the 'koagulation' vitamin.","explanation":"Vitamin K is required for blood clotting.","difficulty":1,"sources":[[2023,"R","56/3/2",6]]},{"id":"c0151","chapter":3,"type":"mcq","text":"The rate of reaction $\\mathrm{A+B\\rightarrow}$ Products, is given by the equation $r=k[A][B]$. If B is taken in large excess, the order of reaction would be :","options":{"A":"2","B":"0","C":"1","D":"Cannot be predicted"},"answer":"C","hint":"Pseudo order.","explanation":"[B] is effectively constant, so rate depends only on [A]: pseudo first order.","difficulty":1,"sources":[[2023,"R","56/3/2",7],[2025,"R","56(B)",8]]},{"id":"c0152","chapter":1,"type":"mcq","text":"Isotonic solutions have :","options":{"A":"same osmotic pressure","B":"same boiling point","C":"same melting point","D":"same vapour pressure"},"answer":"A","hint":"Iso means equal; think of the semipermeable membrane.","explanation":"Isotonic solutions have equal osmotic pressure at the same temperature.","difficulty":1,"sources":[[2023,"R","56/3/2",10]]},{"id":"c0153","chapter":4,"type":"mcq","text":"$\\mathrm{KMnO_4}$ acts as an oxidising agent in alkaline medium. When alkaline $\\mathrm{KMnO_4}$ is treated with KI, iodide ion is oxidised to :","options":{"A":"$\\mathrm{I_2}$","B":"$\\mathrm{IO^-}$","C":"$\\mathrm{IO_3^-}$","D":"$\\mathrm{IO_4^-}$"},"answer":"C","hint":"Alkaline permanganate oxidises iodide completely.","explanation":"In alkaline medium $\\mathrm{I^-}$ is oxidised to iodate, $\\mathrm{IO_3^-}$.","difficulty":2,"sources":[[2023,"R","56/3/2",11]]},{"id":"c0154","chapter":4,"type":"mcq","text":"Which of the following transition metals does not show variable oxidation state ?","options":{"A":"Ti","B":"Cr","C":"Cu","D":"Sc"},"answer":"D","hint":"Which has only one stable oxidation state?","explanation":"Sc shows only +3.","difficulty":1,"sources":[[2023,"R","56/3/2",12]]},{"id":"c0155","chapter":5,"type":"mcq","text":"Which of the following complexes is a 'chelate' complex ?","options":{"A":"$\\mathrm{[Co(NH_3)_6]^{3+}}$","B":"$\\mathrm{[Co(en)_3]^{3+}}$","C":"$\\mathrm{[Co(NH_3)_4Cl_2]^+}$","D":"$\\mathrm{[CoF_6]^{3-}}$"},"answer":"B","hint":"Chelates need polydentate ligands.","explanation":"en is bidentate and forms five-membered rings with the metal.","difficulty":1,"sources":[[2023,"R","56/3/2",13]]},{"id":"c0156","chapter":5,"type":"mcq","text":"Optical isomerism is not shown by the complex :","options":{"A":"$\\mathrm{[Co(en)_2Cl_2]^+}$ (trans form)","B":"$\\mathrm{[Co(en)_2Cl_2]^+}$ (cis form)","C":"$\\mathrm{[Cr(ox)_3]^{3-}}$","D":"$\\mathrm{[Cr(en)_3]^{3+}}$"},"answer":"A","hint":"Look for a mirror plane.","explanation":"Trans form has a plane of symmetry and is optically inactive; cis and tris-chelates are chiral.","difficulty":2,"sources":[[2023,"R","56/3/2",14]]},{"id":"c0157","chapter":2,"type":"mcq","text":"Kohlrausch gave the following relation for strong electrolyte:\n$\\Lambda = \\Lambda_0 - A\\sqrt{C}$\nWhich of the following equality holds true?","options":{"A":"$\\Lambda = \\Lambda_0$ as $C \\rightarrow \\sqrt{A}$","B":"$\\Lambda = \\Lambda_0$ as $C \\rightarrow 0$","C":"$\\Lambda = \\Lambda_0$ as $C \\rightarrow \\infty$","D":"$\\Lambda = \\Lambda_0$ as $C \\rightarrow 1$"},"answer":"B","hint":"Limiting molar conductivity is defined at infinite dilution.","explanation":"At infinite dilution the $\\sqrt{C}$ term vanishes, so $\\Lambda=\\Lambda_0$ as $C\\rightarrow 0$.","difficulty":1,"sources":[[2023,"R","56/3/3",1]]},{"id":"c0158","chapter":6,"type":"mcq","text":"Which of the following belongs to the class of alkyl halides?","options":{"A":"$\\mathrm{CH_2=CH-Cl}$","B":"$\\mathrm{CH_2=CH-CH_2-CH_2-Cl}$","C":"$\\mathrm{CH_2=CH-CH(Cl)-CH_3}$","D":"$\\mathrm{CH\\equiv C-CH_2-Cl}$"},"answer":"B","hint":"Alkyl halide: halogen on an sp3 carbon not next to a C=C.","explanation":"In (b) Cl is on an sp3 carbon away from the double bond; (a) is vinylic, (c) and (d) are allylic/propargylic.","difficulty":2,"sources":[[2023,"R","56/3/3",2]]},{"id":"c0159","chapter":7,"type":"mcq","text":"For the conversion of propene into 1-propanol, which of the following reagents and conditions should be used?","options":{"A":"Conc. $\\mathrm{H_2SO_4}$; $\\mathrm{H_2O}$ and heat","B":"$\\mathrm{B_2H_6}$; $\\mathrm{H_2O_2/OH^-}$","C":"Dilute $\\mathrm{H_2SO_4}$","D":"$\\mathrm{H_2O/H^+}$"},"answer":"B","hint":"Anti-Markovnikov hydration is needed.","explanation":"Hydroboration-oxidation adds water against Markovnikov's rule, giving 1-propanol.","difficulty":1,"sources":[[2023,"R","56/3/3",4]]},{"id":"c0160","chapter":8,"type":"mcq","text":"Which of the following reagents would one choose to transform $\\mathrm{CH_3COCl}$ into acetone?","options":{"A":"$\\mathrm{(CH_3)_2Cd}$","B":"$\\mathrm{CH_3MgBr}$","C":"$\\mathrm{CH_3Cl}$","D":"$\\mathrm{(CH_3O)_2Mg}$"},"answer":"A","hint":"Which organometallic stops at the ketone stage?","explanation":"Dialkylcadmium converts acid chlorides to ketones without over-addition, unlike Grignard reagents.","difficulty":2,"sources":[[2023,"R","56/3/3",5]]},{"id":"c0161","chapter":9,"type":"mcq","text":"The reaction of ammonia with a large excess of methyl chloride will yield mainly:","options":{"A":"methylamine","B":"dimethylamine","C":"tetramethylammonium chloride","D":"trimethylamine"},"answer":"C","hint":"Excess alkyl halide drives alkylation to completion.","explanation":"Repeated alkylation of $\\mathrm{NH_3}$ with excess $\\mathrm{CH_3Cl}$ ends at the quaternary ammonium salt.","difficulty":2,"sources":[[2023,"R","56/3/3",6]]},{"id":"c0162","chapter":10,"type":"mcq","text":"In the ring structure of glucose, the anomeric carbon is:","options":{"A":"C-2","B":"C-3","C":"C-4","D":"C-1"},"answer":"D","hint":"It is the former carbonyl carbon.","explanation":"The carbonyl carbon C-1 becomes the new stereocentre (anomeric carbon) on ring closure.","difficulty":1,"sources":[[2023,"R","56/3/3",7]]},{"id":"c0163","chapter":10,"type":"mcq","text":"Deficiency of Vitamin B causes:","options":{"A":"rickets","B":"muscular weakness","C":"scurvy","D":"beri-beri"},"answer":"D","hint":"Link each vitamin to its deficiency disease.","explanation":"Deficiency of vitamin B (B1) causes beri-beri; rickets is vitamin D and scurvy vitamin C.","difficulty":1,"sources":[[2023,"R","56/3/3",8]]},{"id":"c0164","chapter":1,"type":"mcq","text":"Which one of the following pairs will not form an ideal solution?","options":{"A":"Benzene and Toluene","B":"Nitric acid and Water","C":"Hexane and Heptane","D":"Ethyl chloride and Ethyl bromide"},"answer":"B","hint":"Ideal solutions need similar intermolecular forces.","explanation":"Nitric acid and water interact strongly (H-bonding, ionisation), giving non-ideal behaviour.","difficulty":1,"sources":[[2023,"R","56/3/3",10]]},{"id":"c0165","chapter":3,"type":"mcq","text":"The half-life of a reaction is doubled when the initial concentration is doubled. The order of the reaction is:","options":{"A":"1","B":"2","C":"4","D":"0"},"answer":"D","hint":"Use how $t_{1/2}$ depends on $[A]_0$ for each order.","explanation":"For zero order $t_{1/2}=[A]_0/2k$, proportional to $[A]_0$, so the order is 0.","difficulty":1,"sources":[[2023,"R","56/3/3",11]]},{"id":"c0166","chapter":4,"type":"mcq","text":"Which of the following ions has the maximum number of unpaired d-electrons?\n[Atomic number: Fe = 26, V = 23, Ti = 22, Sc = 21]","options":{"A":"$\\mathrm{Fe^{3+}}$","B":"$\\mathrm{V^{3+}}$","C":"$\\mathrm{Ti^{3+}}$","D":"$\\mathrm{Sc^{3+}}$"},"answer":"A","hint":"Write the d-configuration of each ion.","explanation":"$\\mathrm{Fe^{3+}}$ is $3d^5$ (5 unpaired), $\\mathrm{V^{3+}}$ $3d^2$, $\\mathrm{Ti^{3+}}$ $3d^1$, $\\mathrm{Sc^{3+}}$ $3d^0$.","difficulty":1,"sources":[[2023,"R","56/3/3",12]]},{"id":"c0167","chapter":5,"type":"mcq","text":"Which of the following is a polydentate ligand?","options":{"A":"$\\mathrm{NH_3}$","B":"$\\mathrm{H_2N-CH_2-CH_2-NH_2}$","C":"$\\mathrm{EDTA^{4-}}$","D":"$\\mathrm{C_2O_4^{2-}}$"},"answer":"C","hint":"Count the donor atoms; polydentate means more than two.","explanation":"EDTA is hexadentate; $\\mathrm{NH_3}$ is monodentate, en and oxalate are bidentate.","difficulty":1,"sources":[[2023,"R","56/3/3",13]]},{"id":"c0168","chapter":5,"type":"mcq","text":"Which of the following coordination compounds exhibits linkage isomerism?","options":{"A":"$\\mathrm{[Co(NH_3)_3Cl_3]}$","B":"$\\mathrm{[Co(NH_3)_5(CO_3)]Cl}$","C":"$\\mathrm{[Co(NH_3)_5NO_2](NO_3)_2}$","D":"$\\mathrm{[Co(en)_3]Cl_3}$"},"answer":"C","hint":"Look for an ambidentate ligand.","explanation":"$\\mathrm{NO_2^-}$ can bind through N or O, so (c) shows linkage isomerism.","difficulty":1,"sources":[[2023,"R","56/3/3",14]]},{"id":"c0169","chapter":1,"type":"mcq","text":"A compound undergoes complete tetramerization in a given organic solvent. The Van't Hoff factor 'i' is:","options":{"A":"4.0","B":"0.25","C":"0.125","D":"2.0"},"answer":"B","hint":"i = observed / normal number of particles.","explanation":"Four molecules form one particle, so $i = 1/4 = 0.25$.","difficulty":1,"sources":[[2023,"R","56/4/1",1]]},{"id":"c0170","chapter":3,"type":"mcq","text":"The half-life for a zero order reaction equals:\nwhere R is the initial concentration.","options":{"A":"$\\frac{2k}{R}$","B":"$\\frac{1}{2}\\frac{k}{R^2}$","C":"$\\frac{R^2}{2k}$","D":"$\\frac{R}{2k}$"},"answer":"D","hint":"Set $[A]=[R]/2$ in the zero-order integrated rate law.","explanation":"For zero order $t_{1/2}=[R]/2k$.","difficulty":1,"sources":[[2023,"R","56/4/1",2]]},{"id":"c0171","chapter":10,"type":"mcq","text":"Which of the following structures represents $\\alpha$-D-glucose?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"In the Haworth/Fischer-type ring, check the C-1 OH relative to the CH2OH-bearing carbon.","explanation":"Structure (a) has the D-configuration with the anomeric OH on the side corresponding to the alpha anomer.","difficulty":3,"figure":"figures/c0171.png","sources":[[2023,"R","56/4/1",3],[2023,"R","56/4/2",6],[2023,"R","56/4/3",4]]},{"id":"c0172","chapter":4,"type":"mcq","text":"The ions of metals of Group 12 (Zn, Cd and Hg) have completely filled d orbitals and so they:","options":{"A":"behave like semiconductors","B":"are very high melting solids","C":"do not behave like transition metals","D":"behave like superconductors"},"answer":"C","hint":"Transition metals need partly filled d orbitals.","explanation":"Filled $d^{10}$ ions lack d-d characteristics, so Group 12 is not treated as transition metals.","difficulty":1,"sources":[[2023,"R","56/4/1",4]]},{"id":"c0173","chapter":5,"type":"mcq","text":"$\\mathrm{[Co(NH_3)_5NO_3]SO_4}$ and $\\mathrm{[Co(NH_3)_5SO_4]NO_3}$ exhibit:","options":{"A":"linkage isomerism","B":"ionization isomerism","C":"optical isomerism","D":"coordination isomerism"},"answer":"B","hint":"Compare which anion is in the sphere and which is outside.","explanation":"The two differ in the ion inside versus outside the coordination sphere: ionization isomerism.","difficulty":1,"sources":[[2023,"R","56/4/1",5]]},{"id":"c0174","chapter":6,"type":"mcq","text":"Reaction of 1-phenyl-2-chloropropane with alcoholic KOH gives mainly:","options":{"A":"1-phenylpropene","B":"3-phenylpropene","C":"1-phenylpropan-3-ol","D":"1-phenylpropan-2-ol"},"answer":"A","hint":"Alcoholic KOH gives elimination following Saytzeff's rule.","explanation":"Elimination gives the more stable, conjugated 1-phenylpropene.","difficulty":2,"sources":[[2023,"R","56/4/1",6],[2023,"R","56/4/2",3],[2023,"R","56/4/3",8]]},{"id":"c0175","chapter":7,"type":"mcq","text":"When diethyl ether is heated with excess of HI, it produces:","options":{"A":"ethanol","B":"iodoform","C":"methyl iodide","D":"ethyl iodide"},"answer":"D","hint":"Excess HI cleaves both C-O bonds.","explanation":"$\\mathrm{C_2H_5OC_2H_5}$ with excess HI gives two molecules of ethyl iodide.","difficulty":1,"sources":[[2023,"R","56/4/1",7]]},{"id":"c0176","chapter":9,"type":"mcq","text":"The reduction of ethanenitrile with sodium and alcohol gives:","options":{"A":"1-aminopropane","B":"1-aminoethane","C":"Ethanoic acid","D":"Ethanamide"},"answer":"B","hint":"Mendius reduction keeps the carbon count.","explanation":"Na/alcohol reduces $\\mathrm{CH_3CN}$ to $\\mathrm{CH_3CH_2NH_2}$ (1-aminoethane).","difficulty":1,"sources":[[2023,"R","56/4/1",8]]},{"id":"c0177","chapter":2,"type":"mcq","text":"How many Faradays are required to reduce 1 mol of $\\mathrm{MnO_4^-}$ to $\\mathrm{Mn^{2+}}$?","options":{"A":"4","B":"3","C":"6","D":"5"},"answer":"D","hint":"Count electrons gained per Mn.","explanation":"Mn goes from +7 to +2, gaining 5 electrons, so 5 F.","difficulty":1,"sources":[[2023,"R","56/4/1",9],[2026,"C","56(B)/7",3]]},{"id":"c0178","chapter":3,"type":"mcq","text":"In a reaction, the initial concentration of the reactants increases four fold and the rate becomes sixteen times its initial value. The order of the reaction is:","options":{"A":"2.0","B":"3.5","C":"1.5","D":"2.5"},"answer":"A","hint":"Solve $4^n = 16$.","explanation":"Rate $\\propto C^n$, $4^n=16$ gives $n=2$.","difficulty":1,"sources":[[2023,"R","56/4/1",10]]},{"id":"c0179","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives only glucose?","options":{"A":"Maltose","B":"Sucrose","C":"Lactose","D":"Galactose"},"answer":"A","hint":"Check the monosaccharide units of each disaccharide.","explanation":"Maltose gives two glucose units; sucrose gives glucose and fructose, lactose glucose and galactose, and galactose is a monosaccharide.","difficulty":1,"sources":[[2023,"R","56/4/1",11]]},{"id":"c0180","chapter":10,"type":"mcq","text":"Deficiency of which of the following vitamins causes Pernicious anaemia?","options":{"A":"Vitamin $\\mathrm{B_1}$","B":"Vitamin $\\mathrm{B_2}$","C":"Vitamin $\\mathrm{B_6}$","D":"Vitamin $\\mathrm{B_{12}}$"},"answer":"D","hint":"Recall the vitamin linked to red blood cell formation.","explanation":"Deficiency of vitamin $\\mathrm{B_{12}}$ causes pernicious anaemia.","difficulty":1,"sources":[[2023,"R","56/4/1",12]]},{"id":"c0181","chapter":8,"type":"mcq","text":"$\\mathrm{C_6H_5CHO + CH_3COCH_3} \\xrightarrow{OH^-,\\ \\Delta} \\mathrm{C_6H_5CH=CH-COCH_3}$\nThis reaction is known as:","options":{"A":"Aldol condensation","B":"Cross-Aldol condensation","C":"Cannizzaro's reaction","D":"Friedel-Crafts reaction"},"answer":"B","hint":"Two different carbonyl compounds are involved.","explanation":"Benzaldehyde (no alpha-H) and acetone condense in a crossed aldol condensation.","difficulty":1,"sources":[[2023,"R","56/4/1",13]]},{"id":"c0182","chapter":5,"type":"mcq","text":"In which of the following does the central atom exhibit an oxidation state of +3?","options":{"A":"$\\mathrm{K_2[Ni(CN)_4]}$","B":"$\\mathrm{K_4[Fe(CN)_6]}$","C":"$\\mathrm{[Fe(C_2O_4)_3]^{3-}}$","D":"$\\mathrm{[Cu(NH_3)_4]^{2+}}$"},"answer":"C","hint":"Balance the charge using ligand charges.","explanation":"Oxalate is $2-$ each: $x-6=-3$ gives $\\mathrm{Fe}=+3$; the others are $\\mathrm{Ni^{2+}}$, $\\mathrm{Fe^{2+}}$, $\\mathrm{Cu^{2+}}$.","difficulty":1,"sources":[[2023,"R","56/4/1",14]]},{"id":"c0183","chapter":1,"type":"ar","text":"Assertion (A): When NaCl is added to water, a depression in freezing point is observed.\nReason (R): The lowering of vapour pressure of a solution causes depression in the freezing point.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Freezing point depression is a colligative property.","explanation":"Both true; the lowered vapour pressure shifts the solution's freezing point down.","difficulty":1,"sources":[[2023,"R","56/4/1",15],[2024,"R","56(B)",15]]},{"id":"c0184","chapter":2,"type":"ar","text":"Assertion (A): $\\Lambda_m$ for weak electrolytes shows a sharp decrease when the electrolytic solution is diluted.\nReason (R): For weak electrolytes, degree of dissociation increases with dilution of solution.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"How does $\\Lambda_m$ change as ionisation increases?","explanation":"A is false: $\\Lambda_m$ rises sharply on dilution; R is true.","difficulty":2,"sources":[[2023,"R","56/4/1",16]]},{"id":"c0185","chapter":4,"type":"ar","text":"Assertion (A): Zr and Hf have almost identical radii.\nReason (R): Both Zr and Hf exhibit similar properties.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Lanthanoid contraction explains identical radii.","explanation":"Both statements are true, but similar properties is a consequence, not the cause, of the identical radii (lanthanoid contraction).","difficulty":2,"sources":[[2023,"R","56/4/1",17]]},{"id":"c0186","chapter":9,"type":"ar","text":"Assertion (A): Monobromination of aniline can be conveniently done by protecting the amino group by acetylation.\nReason (R): Acetylation decreases the activating effect of the amino group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Acetylation moderates the -NH2 activation.","explanation":"Both true; reduced activation prevents polybromination, so R explains A.","difficulty":1,"sources":[[2023,"R","56/4/1",18],[2023,"R","56/4/2",17],[2023,"R","56/4/3",16]]},{"id":"c0187","chapter":1,"type":"mcq","text":"A compound undergoes complete dimerization in a given organic solvent. The Van't Hoff factor 'i' is:","options":{"A":"2.0","B":"0.5","C":"0.25","D":"1.0"},"answer":"B","hint":"Association reduces the particle count.","explanation":"Two molecules form one particle, so $i=1/2=0.5$.","difficulty":1,"sources":[[2023,"R","56/4/2",1]]},{"id":"c0188","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{A + 2B} \\rightarrow \\mathrm{C + D}$, the rate law is given by $r = k[A][B]^2$, the concentration of A is kept constant while that of B is doubled. The rate of the reaction will:","options":{"A":"double","B":"become half","C":"not change","D":"quadruple"},"answer":"D","hint":"Rate depends on $[B]^2$.","explanation":"Doubling $[B]$ multiplies rate by $2^2=4$.","difficulty":1,"sources":[[2023,"R","56/4/2",2]]},{"id":"c0189","chapter":4,"type":"mcq","text":"The interstitial compounds of transition metals are\n_____ than the metal itself.","options":{"A":"softer","B":"more ductile","C":"harder","D":"more metallic"},"answer":"C","hint":"Small atoms in lattice voids restrict slipping.","explanation":"Interstitial atoms make the lattice rigid, so the compounds are harder.","difficulty":1,"sources":[[2023,"R","56/4/2",4]]},{"id":"c0190","chapter":5,"type":"mcq","text":"What type of isomerism is shown by the following pair of complex compounds?\n$\\mathrm{[Co(NH_3)_6][Cr(CN)_6]}$ and $\\mathrm{[Cr(NH_3)_6][Co(CN)_6]}$","options":{"A":"Linkage isomerism","B":"Hydrate isomerism","C":"Coordination isomerism","D":"Ionization isomerism"},"answer":"C","hint":"Both cation and anion are complexes; ligands are swapped between metals.","explanation":"Interchange of ligands between the cationic and anionic complex is coordination isomerism.","difficulty":1,"sources":[[2023,"R","56/4/2",5]]},{"id":"c0191","chapter":8,"type":"mcq","text":"The product formed in the reaction (ethyl 3-oxocyclohexanecarboxylate treated with NaBH4) is:","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"NaBH4 reduces ketones but not esters.","explanation":"NaBH4 reduces the ketone C=O to an alcohol and leaves the ester unchanged.","difficulty":2,"figure":"figures/c0191.png","sources":[[2023,"R","56/4/2",7]]},{"id":"c0192","chapter":2,"type":"mcq","text":"The number of faradays passed through a solution of $\\mathrm{CuSO_4}$ to produce 1 mol of Cu and $\\mathrm{O_2}$ will be:","options":{"A":"1.0","B":"4.0","C":"8.0","D":"2.0"},"answer":"D","hint":"Charge for 1 mol Cu is $2F$.","explanation":"$\\mathrm{Cu^{2+}}+2e^-\\rightarrow \\mathrm{Cu}$ needs 2 F per mole of Cu.","difficulty":2,"sources":[[2023,"R","56/4/2",9]]},{"id":"c0193","chapter":3,"type":"mcq","text":"If the initial concentration is reduced to $\\frac{1}{4}$th in a zero order reaction, then the time taken for half the reaction to complete:","options":{"A":"remains the same","B":"reduces to one-fourth","C":"increases four times","D":"doubles"},"answer":"B","hint":"Zero order $t_{1/2}\\propto[A]_0$.","explanation":"$t_{1/2}=[A]_0/2k$, so quartering $[A]_0$ quarters $t_{1/2}$.","difficulty":1,"sources":[[2023,"R","56/4/2",10]]},{"id":"c0194","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives glucose and fructose?","options":{"A":"Sucrose","B":"Starch","C":"Lactose","D":"Maltose"},"answer":"A","hint":"Identify the disaccharide of glucose and fructose.","explanation":"Sucrose hydrolyses to glucose and fructose.","difficulty":1,"sources":[[2023,"R","56/4/2",11]]},{"id":"c0195","chapter":10,"type":"mcq","text":"The deficiency of which of the following vitamins causes Scurvy?","options":{"A":"Vitamin A","B":"Vitamin $\\mathrm{B_6}$","C":"Vitamin C","D":"Vitamin $\\mathrm{B_{12}}$"},"answer":"C","hint":"Recall the vitamin deficiency diseases.","explanation":"Vitamin C deficiency causes scurvy.","difficulty":1,"sources":[[2023,"R","56/4/2",12]]},{"id":"c0196","chapter":8,"type":"mcq","text":"The reaction of a methylbenzene with $\\mathrm{CrO_2Cl_2/CS_2}$ followed by $\\mathrm{H_3O^+}$ gives benzaldehyde.\nThis reaction is known as:","options":{"A":"Cannizzaro reaction","B":"Etard reaction","C":"Rosenmund reduction","D":"Aldol condensation"},"answer":"B","hint":"Chromyl chloride oxidises a methyl group to CHO.","explanation":"Oxidation of toluene to benzaldehyde with $\\mathrm{CrO_2Cl_2}$ is the Etard reaction.","difficulty":1,"sources":[[2023,"R","56/4/2",13]]},{"id":"c0197","chapter":5,"type":"mcq","text":"In which of the following does the central atom exhibit an oxidation state of +4?","options":{"A":"$\\mathrm{K_2[Ni(CN)_4]}$","B":"$\\mathrm{[Cu(NH_3)_4]^{2+}}$","C":"$\\mathrm{[Pt(NH_3)_2Cl_2]}$","D":"$\\mathrm{[Pt(en)_2Cl_2]^{2+}}$"},"answer":"D","hint":"Charge balance: ligands en and $\\mathrm{NH_3}$ are neutral.","explanation":"In (d) $x-2=+2$ gives Pt $=+4$; the others are Ni$^{2+}$, Cu$^{2+}$, Pt$^{2+}$.","difficulty":1,"sources":[[2023,"R","56/4/2",14]]},{"id":"c0198","chapter":1,"type":"ar","text":"Assertion (A): When glucose is added to water, an elevation in boiling point is observed.\nReason (R): The lowering of vapour pressure causes elevation in the boiling point.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Boiling point elevation is a colligative property.","explanation":"Both true; lower vapour pressure needs a higher temperature to boil, so R explains A.","difficulty":1,"sources":[[2023,"R","56/4/2",15],[2025,"C","56(B)/S",13]]},{"id":"c0199","chapter":4,"type":"ar","text":"Assertion (A): Manganese shows the highest oxidation state of +7 in 3d series.\nReason (R): Transition metals show variable oxidation states.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Does general variability explain Mn's maximum state?","explanation":"Both true, but variable oxidation states in general do not explain why Mn reaches +7 (all 7 valence electrons).","difficulty":2,"sources":[[2023,"R","56/4/2",18]]},{"id":"c0200","chapter":1,"type":"mcq","text":"A compound $\\mathrm{CaCl_2\\cdot 6H_2O}$ undergoes complete dissociation in water. The Van't Hoff factor 'i' is:","options":{"A":"9","B":"6","C":"3","D":"4"},"answer":"C","hint":"Count ions produced.","explanation":"$\\mathrm{CaCl_2}$ gives $\\mathrm{Ca^{2+}}$ and $2\\mathrm{Cl^-}$, so $i=3$; water of crystallisation does not add particles.","difficulty":1,"sources":[[2023,"R","56/4/3",1]]},{"id":"c0201","chapter":3,"type":"mcq","text":"For a zero order reaction of the type $A\\rightarrow$ products, the rate equation may be expressed as:","options":{"A":"$k=\\frac{[A]_0-[A]}{t}$","B":"$k=\\frac{[A]-[A]_0}{t}$","C":"$k=\\frac{[A]_0-[A]}{2t}$","D":"$k=\\frac{[A]_0-[A]}{2}\\cdot t$"},"answer":"A","hint":"Integrated zero-order law: $[A]=[A]_0-kt$.","explanation":"Rearranging $[A]=[A]_0-kt$ gives $k=([A]_0-[A])/t$.","difficulty":1,"sources":[[2023,"R","56/4/3",2]]},{"id":"c0202","chapter":4,"type":"mcq","text":"Which of the following $\\mathrm{Cu^{2+}}$ halide is not known?","options":{"A":"$\\mathrm{CuBr_2}$","B":"$\\mathrm{CuI_2}$","C":"$\\mathrm{CuCl_2}$","D":"$\\mathrm{CuF_2}$"},"answer":"B","hint":"$\\mathrm{Cu^{2+}}$ oxidises iodide.","explanation":"$\\mathrm{Cu^{2+}}$ oxidises $\\mathrm{I^-}$ to $\\mathrm{I_2}$ forming CuI, so $\\mathrm{CuI_2}$ does not exist.","difficulty":1,"sources":[[2023,"R","56/4/3",3]]},{"id":"c0203","chapter":5,"type":"mcq","text":"The compounds $\\mathrm{[Cr(H_2O)_6]Cl_3}$, $\\mathrm{[Cr(H_2O)_5Cl]Cl_2\\cdot H_2O}$ and $\\mathrm{[Cr(H_2O)_4Cl_2]Cl\\cdot 2H_2O}$ exhibit:","options":{"A":"Linkage isomerism","B":"Geometrical isomerism","C":"Ionization isomerism","D":"Hydrate isomerism"},"answer":"D","hint":"They differ in water inside versus outside the sphere.","explanation":"Different numbers of water molecules as ligands versus water of crystallisation give hydrate isomerism.","difficulty":1,"sources":[[2023,"R","56/4/3",5]]},{"id":"c0204","chapter":7,"type":"mcq","text":"Which of the following alkenes on acid catalysed hydration gives a tertiary alcohol?","options":{"A":"2-Butene","B":"2-Methylpropene","C":"Propene","D":"1-Butene"},"answer":"B","hint":"Markovnikov addition forms the most stable carbocation.","explanation":"2-Methylpropene gives the tertiary carbocation and hence tert-butyl alcohol.","difficulty":1,"sources":[[2023,"R","56/4/3",6]]},{"id":"c0205","chapter":9,"type":"mcq","text":"When nitrobenzene is heated with tin and concentrated HCl, the product formed is:","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"Sn/HCl is a reducing agent for the nitro group.","explanation":"The nitro group is reduced to the amino group, giving aniline.","difficulty":1,"figure":"figures/c0205.png","sources":[[2023,"R","56/4/3",7]]},{"id":"c0206","chapter":2,"type":"mcq","text":"Corrosion of iron is:","options":{"A":"a decomposition process","B":"a photochemical process","C":"an electrochemical process","D":"a reduction process"},"answer":"C","hint":"Anodic and cathodic regions form a tiny cell.","explanation":"Rusting occurs through oxidation at anodic and reduction at cathodic sites, an electrochemical process.","difficulty":1,"sources":[[2023,"R","56/4/3",9]]},{"id":"c0207","chapter":3,"type":"mcq","text":"The number of molecules that react with each other in an elementary reaction is a measure of the:","options":{"A":"activation energy of the reaction","B":"order of the reaction","C":"stoichiometry of the reaction","D":"molecularity of the reaction"},"answer":"D","hint":"Definition of molecularity.","explanation":"Molecularity is the number of reacting species in an elementary step.","difficulty":1,"sources":[[2023,"R","56/4/3",10]]},{"id":"c0208","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives glucose and galactose?","options":{"A":"Sucrose","B":"Lactose","C":"Maltose","D":"Cellulose"},"answer":"B","hint":"Milk sugar.","explanation":"Lactose is made of glucose and galactose.","difficulty":1,"sources":[[2023,"R","56/4/3",11]]},{"id":"c0209","chapter":10,"type":"mcq","text":"The deficiency of which of the following vitamins causes 'Rickets'?","options":{"A":"Vitamin A","B":"Vitamin D","C":"Vitamin B","D":"Vitamin C"},"answer":"B","hint":"Linked to calcium absorption.","explanation":"Vitamin D deficiency causes rickets.","difficulty":1,"sources":[[2023,"R","56/4/3",12]]},{"id":"c0210","chapter":8,"type":"mcq","text":"Which of the following is an 'Acetal'?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"C","hint":"An acetal has two OR groups on the same carbon that carries an H.","explanation":"In (c) the carbon bears H, CH$_3$ and two OCH$_3$ groups, so it is an acetal; (b) is a cyclic ketal.","difficulty":1,"figure":"figures/c0210.png","sources":[[2023,"R","56/4/3",13]]},{"id":"c0211","chapter":5,"type":"mcq","text":"The crystal field splitting energy in tetrahedral crystal field ($\\Delta_t$) is equal to :","options":{"A":"$\\frac{4}{9}\\Delta_o$","B":"$\\frac{9}{4}\\Delta_o$","C":"$\\frac{4}{3}\\Delta_o$","D":"$2\\Delta_o$"},"answer":"A","hint":"Recall the standard relation between tetrahedral and octahedral splitting.","explanation":"$\\Delta_t=\\frac{4}{9}\\Delta_o$.","difficulty":1,"sources":[[2023,"R","56/4/3",14]]},{"id":"c0212","chapter":2,"type":"ar","text":"Assertion (A): Limiting molar conductivity ($\\Lambda_m^\\circ$) is obtained by the extrapolation of the $\\Lambda_m$ versus $C^{1/2}$ curve of strong electrolyte.\nReason (R): $\\Lambda_m^\\circ$ for weak electrolytes is obtained by using Kohlrausch's law.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Consider how each method applies to a different kind of electrolyte.","explanation":"Both statements are true, but Kohlrausch's law is for weak electrolytes and does not explain the extrapolation for strong ones.","difficulty":2,"sources":[[2023,"R","56/4/3",17]]},{"id":"c0213","chapter":4,"type":"ar","text":"Assertion (A): $E^\\circ_{\\mathrm{Cu^{2+}/Cu}}$ is positive ($+0.34$ V).\nReason (R): Copper has high $\\Delta_aH^\\circ$ and low $\\Delta_{hyd}H^\\circ$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Combine atomisation and hydration enthalpies into the electrode potential.","explanation":"Cu has high $\\Delta_aH^\\circ$ and its hydration enthalpy is not enough to compensate, giving positive $E^\\circ$; R explains A.","difficulty":2,"sources":[[2023,"R","56/4/3",18]]},{"id":"c0214","chapter":6,"type":"mcq","text":"Which of the following molecules has a chiral centre correctly labelled with an asterisk (*)?","options":{"A":"$\\mathrm{CH_3C^*HBrCH_3}$","B":"$\\mathrm{CH_3C^*HClCH_2Br}$","C":"$\\mathrm{HOCH_2C^*H(OH)CH_2OH}$","D":"$\\mathrm{CH_3C^*Br_2CH_3}$"},"answer":"B","hint":"A chiral carbon bears four different groups.","explanation":"In (b) the carbon has H, Cl, CH$_3$ and CH$_2$Br, all different.","difficulty":1,"sources":[[2023,"R","56/5/1",1],[2023,"R","56/5/3",8]]},{"id":"c0215","chapter":7,"type":"mcq","text":"Which of the following alcohols will not undergo oxidation?","options":{"A":"Butanol","B":"Butan-2-ol","C":"2-Methylbutan-2-ol","D":"3-Methylbutan-2-ol"},"answer":"C","hint":"Oxidation needs a hydrogen on the carbon bearing OH.","explanation":"2-Methylbutan-2-ol is tertiary, with no $\\alpha$-H, so it resists oxidation.","difficulty":1,"sources":[[2023,"R","56/5/1",2],[2023,"R","56/5/2",11],[2023,"R","56/5/3",5]]},{"id":"c0216","chapter":2,"type":"mcq","text":"A voltaic cell is made by connecting two half cells represented by half equations below :\n$\\mathrm{Sn^{2+}_{(aq)} + 2e^- \\rightarrow Sn_{(s)}}$   $E^\\circ = -0.14$ V\n$\\mathrm{Fe^{3+}_{(aq)} + e^- \\rightarrow Fe^{2+}_{(aq)}}$   $E^\\circ = +0.77$ V\nWhich statement is correct about this voltaic cell?","options":{"A":"$\\mathrm{Fe^{2+}}$ is oxidised and the voltage of the cell is $-0.91$ V","B":"Sn is oxidised and the voltage of the cell is $0.91$ V","C":"$\\mathrm{Fe^{2+}}$ is oxidised and the voltage of the cell is $0.91$ V","D":"Sn is oxidised and the voltage of the cell is $0.63$ V"},"answer":"B","hint":"The couple with lower $E^\\circ$ is oxidised; $E^\\circ_{cell}=E^\\circ_{cathode}-E^\\circ_{anode}$.","explanation":"Sn is the anode: $0.77-(-0.14)=0.91$ V.","difficulty":1,"sources":[[2023,"R","56/5/1",3],[2023,"R","56/5/2",8]]},{"id":"c0217","chapter":2,"type":"mcq","text":"Four half reactions I to IV are shown below :\nI. $\\mathrm{2Cl^- \\rightarrow Cl_2 + 2e^-}$\nII. $\\mathrm{4OH^- \\rightarrow O_2 + 2H_2O + 2e^-}$\nIII. $\\mathrm{Na^+ + e^- \\rightarrow Na}$\nIV. $\\mathrm{2H^+ + 2e^- \\rightarrow H_2}$\nWhich two of these reactions are most likely to occur when concentrated brine is electrolysed?","options":{"A":"I and III","B":"I and IV","C":"II and III","D":"II and IV"},"answer":"B","hint":"Consider which ions are preferentially discharged in brine.","explanation":"Cl$^-$ is oxidised (over-potential favours it) at the anode and water/H$^+$ is reduced at the cathode, giving Cl$_2$ and H$_2$.","difficulty":2,"sources":[[2023,"R","56/5/1",4],[2023,"R","56/5/2",12],[2023,"R","56/5/3",11]]},{"id":"c0218","chapter":4,"type":"mcq","text":"Which property of transition metals enables them to behave as catalysts?","options":{"A":"High melting point","B":"High ionisation enthalpy","C":"Alloy formation","D":"Variable oxidation states"},"answer":"D","hint":"Catalysis involves forming intermediates through changing oxidation states.","explanation":"Variable oxidation states let them form unstable intermediates.","difficulty":1,"sources":[[2023,"R","56/5/1",5],[2023,"R","56/5/2",13],[2023,"R","56/5/3",12],[2025,"R","56/4/3",9]]},{"id":"c0219","chapter":4,"type":"mcq","text":"In the two tetrahedral structures of dichromate ion","options":{"A":"4 Cr$-$O bonds are equivalent in length.","B":"6 Cr$-$O bonds are equivalent in length.","C":"All Cr$-$O bonds are equivalent in length.","D":"All Cr$-$O bonds are non-equivalent."},"answer":"B","hint":"Separate terminal Cr-O bonds from the bridging ones.","explanation":"Dichromate has 6 equivalent terminal Cr-O bonds, while the two bridging Cr-O bonds are longer.","difficulty":2,"sources":[[2023,"R","56/5/1",6]]},{"id":"c0220","chapter":1,"type":"mcq","text":"1 mole of liquid A and 2 moles of liquid B make a solution having a total vapour pressure 40 torr. The vapour pressure of pure A and pure B are 45 torr and 30 torr respectively. The above solution","options":{"A":"is an ideal solution.","B":"shows positive deviation.","C":"shows negative deviation.","D":"is a maximum boiling azeotrope."},"answer":"B","hint":"Compare the ideal Raoult's-law pressure with the observed one.","explanation":"Ideal $P=\\frac{1}{3}(45)+\\frac{2}{3}(30)=35$ torr; observed 40 is higher, so positive deviation.","difficulty":2,"sources":[[2023,"R","56/5/1",7]]},{"id":"c0221","chapter":9,"type":"mcq","text":"Which of the following would not be a good choice for reducing nitrobenzene to aniline?","options":{"A":"$\\mathrm{LiAlH_4}$","B":"$\\mathrm{H_2/Ni}$","C":"Fe and HCl","D":"Sn and HCl"},"answer":"A","hint":"Consider which reagent gives azo compounds with aromatic nitro compounds.","explanation":"LiAlH$_4$ reduces nitroarenes to azo compounds, not aniline.","difficulty":2,"sources":[[2023,"R","56/5/1",8],[2023,"R","56/5/2",14],[2023,"R","56/5/3",13]]},{"id":"c0222","chapter":1,"type":"mcq","text":"If molality of a dilute solution is doubled, the value of the molal elevation constant ($K_b$) will be","options":{"A":"halved","B":"doubled","C":"tripled","D":"unchanged"},"answer":"D","hint":"$K_b$ depends only on the solvent.","explanation":"$K_b$ is a solvent property and does not change with concentration.","difficulty":1,"sources":[[2023,"R","56/5/1",9]]},{"id":"c0223","chapter":10,"type":"mcq","text":"Hydrolysis of sucrose is called","options":{"A":"inversion","B":"hydration","C":"esterification","D":"saponification"},"answer":"A","hint":"The optical rotation changes sign on hydrolysis.","explanation":"Dextrorotatory sucrose gives a laevorotatory glucose-fructose mixture, i.e. inversion.","difficulty":1,"sources":[[2023,"R","56/5/1",10]]},{"id":"c0224","chapter":8,"type":"mcq","text":"Which one of the following has lowest $\\mathrm{p}K_a$ value?","options":{"A":"$\\mathrm{CH_3-COOH}$","B":"$\\mathrm{O_2N-CH_2-COOH}$","C":"$\\mathrm{Cl-CH_2-COOH}$","D":"$\\mathrm{HCOOH}$"},"answer":"B","hint":"Stronger electron-withdrawing group means stronger acid.","explanation":"$-NO_2$ has a stronger $-I$ effect than Cl, so nitroacetic acid is the strongest acid.","difficulty":2,"sources":[[2023,"R","56/5/1",11],[2023,"R","56/5/2",1],[2023,"R","56/5/3",14]]},{"id":"c0225","chapter":2,"type":"mcq","text":"Which of the following cell was used in Apollo space programme?","options":{"A":"Mercury cell","B":"Daniel cell","C":"$\\mathrm{H_2{-}O_2}$ Fuel cell","D":"Dry cell"},"answer":"C","hint":"The cell produced drinking water as a by-product.","explanation":"The H$_2$-O$_2$ fuel cell powered Apollo.","difficulty":1,"sources":[[2023,"R","56/5/1",12],[2023,"R","56/5/2",2],[2023,"R","56/5/3",4]]},{"id":"c0226","chapter":3,"type":"mcq","text":"The following experimental rate data were obtained for a reaction carried out at 25 °C :\n$\\mathrm{A_{(g)} + B_{(g)} \\rightarrow C_{(g)} + D_{(g)}}$\nInitial $[\\mathrm{A}]$/mol dm$^{-3}$ | Initial $[\\mathrm{B}]$/mol dm$^{-3}$ | Initial rate/mol dm$^{-3}$ s$^{-1}$\n$3.0\\times10^{-2}$ | $2.0\\times10^{-2}$ | $1.89\\times10^{-4}$\n$3.0\\times10^{-2}$ | $4.0\\times10^{-2}$ | $1.89\\times10^{-4}$\n$6.0\\times10^{-2}$ | $4.0\\times10^{-2}$ | $7.56\\times10^{-4}$\nWhat are the orders with respect to A and B?","options":{"A":"A: Zero, B: Second","B":"A: First, B: Zero","C":"A: Second, B: Zero","D":"A: Second, B: First"},"answer":"C","hint":"Vary one concentration at a time and compare rates.","explanation":"Doubling B leaves rate unchanged (zero order in B); doubling A quadruples rate (second order in A).","difficulty":2,"sources":[[2023,"R","56/5/1",13],[2023,"R","56/5/2",4],[2023,"R","56/5/3",2]]},{"id":"c0227","chapter":5,"type":"mcq","text":"The magnetic moment of $\\mathrm{[NiCl_4]^{2-}}$ is (Atomic number: Ni = 28)","options":{"A":"1.82 BM","B":"2.82 BM","C":"4.42 BM","D":"5.46 BM"},"answer":"B","hint":"Find the geometry from the ligand, then count unpaired electrons.","explanation":"Cl$^-$ is weak field: tetrahedral $d^8$ with 2 unpaired electrons, $\\mu=\\sqrt{8}=2.82$ BM.","difficulty":2,"sources":[[2023,"R","56/5/1",14],[2023,"R","56/5/2",5],[2023,"R","56/5/3",1]]},{"id":"c0228","chapter":10,"type":"ar","text":"Assertion (A): Proteins are polymers of $\\alpha$-amino acids connected by a peptide bond.\nReason (R): A tetrapeptide contains 4 amino acids linked by 4 peptide bonds.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Count the bonds between n residues.","explanation":"A is true; a tetrapeptide has 3 peptide bonds, so R is false.","difficulty":1,"sources":[[2023,"R","56/5/1",15]]},{"id":"c0229","chapter":3,"type":"ar","text":"Assertion (A): For a zero order reaction the unit of rate constant and rate of reaction are same.\nReason (R): Rate of reaction for zero order reaction is independent of concentration of reactant.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Write the rate law for zero order.","explanation":"Rate $=k$, so units coincide; R (rate independent of concentration) is the reason.","difficulty":1,"note":"CBSE keys differ: A in 2023 (56/5/1), B in 2024 Compartment (56(B)/S). A is used.","sources":[[2023,"R","56/5/1",16],[2024,"C","56(B)/S",13]]},{"id":"c0230","chapter":8,"type":"ar","text":"Assertion (A): Acetic acid but not formic acid can be halogenated in presence of red P and $\\mathrm{Cl_2}$.\nReason (R): Acetic acid is a weaker acid than formic acid.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Hell-Volhard-Zelinsky needs an alpha hydrogen.","explanation":"A is true (formic acid has no $\\alpha$-H) and R is true, but acidity does not explain it.","difficulty":2,"sources":[[2023,"R","56/5/1",17]]},{"id":"c0231","chapter":5,"type":"ar","text":"Assertion (A): Trans $\\mathrm{[CrCl_2(ox)_2]^{3-}}$ shows optical isomerism.\nReason (R): Optical isomerism is common in octahedral complexes involving didentate ligands.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Check whether the trans isomer has a mirror plane.","explanation":"Trans isomer is achiral so A is false; R is true (the cis isomer is optically active).","difficulty":3,"sources":[[2023,"R","56/5/1",18]]},{"id":"c0232","chapter":2,"type":"mcq","text":"Consider the following standard electrode potential values :\n$\\mathrm{Fe^{3+}_{(aq)} + e^- \\rightarrow Fe^{2+}_{(aq)}}$   $E^\\circ=+0.77$ V\n$\\mathrm{MnO_4^-{}_{(aq)} + 8H^+ + 5e^- \\rightarrow Mn^{2+}_{(aq)} + 4H_2O_{(l)}}$   $E^\\circ=+1.51$ V\nWhat is the cell potential for the redox reaction?","options":{"A":"$-2.28$ V","B":"$-0.74$ V","C":"$+0.74$ V","D":"$+2.28$ V"},"answer":"C","hint":"Subtract the anode potential from the cathode potential.","explanation":"$E^\\circ_{cell}=1.51-0.77=+0.74$ V.","difficulty":1,"sources":[[2023,"R","56/5/2",3]]},{"id":"c0233","chapter":4,"type":"mcq","text":"Which of the following ions has the electronic configuration $3d^6$? (Atomic number: Mn = 25, Co = 27, Ni = 28)","options":{"A":"$\\mathrm{Ni^{3+}}$","B":"$\\mathrm{Co^{3+}}$","C":"$\\mathrm{Mn^{2+}}$","D":"$\\mathrm{Mn^{3+}}$"},"answer":"B","hint":"Remove 4s then 3d electrons from the neutral atom.","explanation":"Co is $3d^74s^2$; Co$^{3+}$ is $3d^6$ (Ni$^{3+}$ $d^7$, Mn$^{2+}$ $d^5$, Mn$^{3+}$ $d^4$).","difficulty":1,"sources":[[2023,"R","56/5/2",6]]},{"id":"c0234","chapter":1,"type":"mcq","text":"Which of the following aqueous solution will have highest boiling point?","options":{"A":"1.0 M KCl","B":"1.0 M $\\mathrm{K_2SO_4}$","C":"2.0 M KCl","D":"2.0 M $\\mathrm{K_2SO_4}$"},"answer":"D","hint":"Compare $i\\times$ concentration.","explanation":"$i\\times M$: 2, 3, 4, 6; the largest is 2.0 M K$_2$SO$_4$.","difficulty":1,"sources":[[2023,"R","56/5/2",7]]},{"id":"c0235","chapter":9,"type":"mcq","text":"Amides can be converted into amines by the reaction named","options":{"A":"Hoffmann degradation","B":"Ammonolysis","C":"Carbylamine","D":"Diazotisation"},"answer":"A","hint":"The product has one carbon fewer.","explanation":"Hoffmann bromamide degradation converts amides to primary amines.","difficulty":1,"sources":[[2023,"R","56/5/2",9]]},{"id":"c0236","chapter":10,"type":"mcq","text":"Which of the following statements is not true about glucose?","options":{"A":"It is an aldohexose.","B":"On heating with HI it forms n-hexane.","C":"It is present in pyranose form.","D":"It gives 2, 4 DNP test."},"answer":"D","hint":"Which carbonyl test fails because the aldehyde is tied up in a ring?","explanation":"Glucose exists as a cyclic hemiacetal and does not give the 2,4-DNP test.","difficulty":2,"sources":[[2023,"R","56/5/2",10]]},{"id":"c0237","chapter":10,"type":"ar","text":"Assertion (A): Vitamin C cannot be stored in our body.\nReason (R): Vitamin C is fat soluble and is excreted from the body in urine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Is vitamin C soluble in water or fat?","explanation":"A is true; vitamin C is water soluble, so R is false.","difficulty":1,"sources":[[2023,"R","56/5/2",15],[2024,"R","56(B)",13]]},{"id":"c0238","chapter":3,"type":"ar","text":"Assertion (A): The half life of a reaction is the time in which the concentration of the reactant is reduced to one half of its initial concentration.\nReason (R): In first order kinetics when concentration of reactant is doubled, its half life is doubled.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Recall what half-life depends on in first order.","explanation":"A is true; in first order $t_{1/2}=0.693/k$ is independent of concentration, so R is false.","difficulty":1,"sources":[[2023,"R","56/5/2",16]]},{"id":"c0239","chapter":8,"type":"ar","text":"Assertion (A): Bromination of benzoic acid gives m-bromobenzoic acid.\nReason (R): Carboxyl group increases the electron density at the meta position.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"-COOH is a deactivating, meta-directing group.","explanation":"A is true; the carboxyl group withdraws electrons and lowers density at all positions (least at meta), so R is false.","difficulty":1,"sources":[[2023,"R","56/5/2",17]]},{"id":"c0240","chapter":5,"type":"ar","text":"Assertion (A): EDTA is a hexadentate ligand.\nReason (R): EDTA has 2 nitrogen and 4 oxygen donor atoms.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Count the donor atoms in EDTA.","explanation":"Both true; the 2 N and 4 O donors make it hexadentate.","difficulty":1,"sources":[[2023,"R","56/5/2",18]]},{"id":"c0241","chapter":2,"type":"mcq","text":"Consider the following standard electrode potential values :\n$\\mathrm{Sn^{2+}_{(aq)} + 2e^- \\rightarrow Sn_{(s)}}$   $E^\\circ=-0.14$ V\n$\\mathrm{Fe^{3+}_{(aq)} + e^- \\rightarrow Fe^{2+}_{(aq)}}$   $E^\\circ=+0.77$ V\nWhat is the cell reaction and potential for the spontaneous reaction that occurs?","options":{"A":"$\\mathrm{2Fe^{2+}_{(aq)} + Sn^{2+}_{(aq)} \\rightarrow 2Fe^{3+}_{(aq)} + Sn_{(s)}}$   $E^\\circ=-0.91$ V","B":"$\\mathrm{2Fe^{3+}_{(aq)} + Sn_{(s)} \\rightarrow 2Fe^{2+}_{(aq)} + Sn^{2+}_{(aq)}}$   $E^\\circ=+0.91$ V","C":"$\\mathrm{2Fe^{2+}_{(aq)} + Sn^{2+}_{(aq)} \\rightarrow 2Fe^{3+}_{(aq)} + Sn_{(s)}}$   $E^\\circ=+0.91$ V","D":"$\\mathrm{2Fe^{3+}_{(aq)} + Sn_{(s)} \\rightarrow 2Fe^{2+}_{(aq)} + Sn^{2+}_{(aq)}}$   $E^\\circ=+1.68$ V"},"answer":"B","hint":"The spontaneous reaction has positive $E^\\circ_{cell}$.","explanation":"Fe$^{3+}$ is reduced and Sn oxidised: $0.77-(-0.14)=0.91$ V.","difficulty":2,"sources":[[2023,"R","56/5/3",3]]},{"id":"c0242","chapter":2,"type":"mcq","text":"The unit of molar conductivity is","options":{"A":"$\\mathrm{S\\,cm^{-2}\\,mol^{-1}}$","B":"$\\mathrm{S\\,cm^{2}\\,mol^{-1}}$","C":"$\\mathrm{S^{-1}\\,cm^{2}\\,mol^{-1}}$","D":"$\\mathrm{S\\,cm^{2}\\,mol}$"},"answer":"B","hint":"$\\Lambda_m=\\kappa\\times1000/M$.","explanation":"$\\Lambda_m=\\kappa/c$ gives S cm$^2$ mol$^{-1}$.","difficulty":1,"sources":[[2023,"R","56/5/3",6]]},{"id":"c0243","chapter":1,"type":"mcq","text":"Out of the following 1.0 M aqueous solutions, which one will show largest freezing point depression?","options":{"A":"NaCl","B":"$\\mathrm{Na_2SO_4}$","C":"$\\mathrm{C_6H_{12}O_6}$","D":"$\\mathrm{Al_2(SO_4)_3}$"},"answer":"D","hint":"Compare the number of particles produced.","explanation":"$\\mathrm{Al_2(SO_4)_3}$ gives 5 ions per formula unit, the most.","difficulty":1,"sources":[[2023,"R","56/5/3",7]]},{"id":"c0244","chapter":9,"type":"mcq","text":"In the reaction $\\mathrm{C_6H_5NH_2 + CHCl_3 + 3KOH \\rightarrow A + 3B + 3C}$ the product A is","options":{"A":"$\\mathrm{C_6H_5NC}$","B":"$\\mathrm{C_6H_5CN}$","C":"$\\mathrm{C_6H_5Cl}$","D":"$\\mathrm{C_6H_5NHCH_3}$"},"answer":"A","hint":"Primary amine, chloroform and KOH is a named test.","explanation":"Carbylamine reaction gives phenyl isocyanide.","difficulty":1,"sources":[[2023,"R","56/5/3",9]]},{"id":"c0245","chapter":10,"type":"mcq","text":"$\\beta$-pleated sheet structure in proteins refers to","options":{"A":"primary structure","B":"secondary structure","C":"tertiary structure","D":"quaternary structure"},"answer":"B","hint":"It is formed by hydrogen bonding along the backbone.","explanation":"$\\alpha$-helix and $\\beta$-sheet are secondary structures.","difficulty":1,"sources":[[2023,"R","56/5/3",10]]},{"id":"c0246","chapter":10,"type":"ar","text":"Assertion (A): The backbone of DNA and RNA molecules is a chain consisting of heterocyclic base, pentose sugar and phosphate group.\nReason (R): Nucleotides and nucleosides mainly differ from each other in presence of phosphate group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Which parts of a nucleic acid form the chain backbone?","explanation":"Both statements are taken as true (the nucleic acid chain is built from base, sugar and phosphate units; nucleotides carry a phosphate that nucleosides lack), but R does not explain A.","difficulty":2,"note":"Official answer B.","sources":[[2023,"R","56/5/3",15]]},{"id":"c0247","chapter":3,"type":"ar","text":"Assertion (A): Order of reaction is applicable to elementary as well as complex reactions.\nReason (R): For a complex reaction molecularity has no meaning.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Order is experimental; molecularity applies only to elementary steps.","explanation":"Both true, but R does not explain why order applies to both.","difficulty":2,"sources":[[2023,"R","56/5/3",16],[2026,"R","56/3/3",16]]},{"id":"c0248","chapter":8,"type":"ar","text":"Assertion (A): The final product in Aldol condensation is always $\\alpha,\\beta$-unsaturated carbonyl compound.\nReason (R): $\\alpha,\\beta$-unsaturated carbonyl compounds are stabilised due to conjugation.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Dehydration of the aldol is driven by conjugation.","explanation":"Aldol condensation ends in dehydration to the conjugated enone; stability by conjugation is the reason.","difficulty":2,"sources":[[2023,"R","56/5/3",17]]},{"id":"c0249","chapter":5,"type":"ar","text":"Assertion (A): $\\mathrm{[Co(NH_3)_5SO_4]Cl}$ gives a white precipitate with silver nitrate solution.\nReason (R): The complex dissociates to give $\\mathrm{Cl^-}$ and $\\mathrm{SO_4^{2-}}$ ions.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Which ligands are inside the coordination sphere?","explanation":"Cl$^-$ is the counter ion so AgCl forms (A true); sulfate is a ligand, so R is false.","difficulty":2,"sources":[[2023,"R","56/5/3",18],[2024,"C","56(B)/S",15]]},{"id":"c0250","chapter":9,"type":"mcq","text":"Out of the following, the strongest base in aqueous solution is :","options":{"A":"Methylamine","B":"Dimethylamine","C":"Trimethylamine","D":"Aniline"},"answer":"B","hint":"Balance +I effect with solvation in water.","explanation":"In water, secondary amines are strongest among methylamines.","difficulty":1,"sources":[[2024,"C","56(B)/S",1]]},{"id":"c0251","chapter":8,"type":"mcq","text":"Iodoform test is given by","options":{"A":"Propanol","B":"Ethyl chloride","C":"Pentanal","D":"Pentan-2-one"},"answer":"D","hint":"Look for the $\\mathrm{CH_3CO-}$ or $\\mathrm{CH_3CH(OH)-}$ group.","explanation":"Pentan-2-one has a methyl ketone group.","difficulty":1,"sources":[[2024,"C","56(B)/S",2]]},{"id":"c0252","chapter":4,"type":"mcq","text":"Out of the following transition elements, the maximum number of oxidation states is shown by","options":{"A":"Sc","B":"Cr","C":"Mn","D":"Fe"},"answer":"C","hint":"Maximum in the middle of the 3d series.","explanation":"Mn shows +2 to +7.","difficulty":1,"sources":[[2024,"C","56(B)/S",3]]},{"id":"c0253","chapter":2,"type":"mcq","text":"Which of the following cell was used in Apollo space programme?","options":{"A":"Dry cell","B":"Ni$-$Cd cell","C":"$\\mathrm{H_2{-}O_2}$ fuel cell","D":"Mercury cell"},"answer":"C","hint":"The cell produced drinking water as a by-product.","explanation":"The H$_2$-O$_2$ fuel cell powered Apollo.","difficulty":1,"sources":[[2024,"C","56(B)/S",4]]},{"id":"c0254","chapter":10,"type":"mcq","text":"Which of the following statements is not true about glucose?","options":{"A":"It is an aldohexose.","B":"It gives 2,4-DNP test.","C":"It is present in pyranose form.","D":"On heating with HI it forms n-hexane."},"answer":"B","hint":"Which test fails because the aldehyde is tied up in a ring?","explanation":"Glucose is cyclic hemiacetal and does not give the 2,4-DNP test.","difficulty":2,"sources":[[2024,"C","56(B)/S",6]]},{"id":"c0255","chapter":9,"type":"mcq","text":"Amides can be converted into amines by the reaction named","options":{"A":"Diazotisation","B":"Carbylamine","C":"Ammonolysis","D":"Hoffmann Bromamide degradation"},"answer":"D","hint":"The product has one carbon fewer.","explanation":"Hoffmann bromamide degradation converts amides to primary amines.","difficulty":1,"sources":[[2024,"C","56(B)/S",7]]},{"id":"c0256","chapter":9,"type":"mcq","text":"Which of the following would be a better choice for reducing nitrobenzene to aniline?","options":{"A":"$\\mathrm{H_2/Ni}$","B":"$\\mathrm{LiAlH_4}$","C":"Fe and HCl","D":"Sn and HCl"},"answer":"C","hint":"Consider which reagent gives azo compounds instead.","explanation":"Fe/HCl is the industrial choice (official key); LiAlH$_4$ is unsuitable.","difficulty":2,"note":"Official answer C (Fe and HCl, the preferred reagent); other reagents can also reduce nitrobenzene.","sources":[[2024,"C","56(B)/S",8]]},{"id":"c0257","chapter":4,"type":"mcq","text":"Which property of transition metals enables them to behave as catalysts?","options":{"A":"Variable oxidation states","B":"Alloy formation","C":"High ionisation enthalpy","D":"High melting point"},"answer":"A","hint":"Catalysis involves forming intermediates through changing oxidation states.","explanation":"Variable oxidation states let them form intermediates.","difficulty":1,"sources":[[2024,"C","56(B)/S",9]]},{"id":"c0258","chapter":5,"type":"mcq","text":"Which of the following is the most stable complex species?","options":{"A":"$\\mathrm{[Fe(CN)_6]^{3-}}$","B":"$\\mathrm{[Fe(CO)_5]}$","C":"$\\mathrm{[Fe(C_2O_4)_3]^{3-}}$","D":"$\\mathrm{[Fe(H_2O)_6]^{3+}}$"},"answer":"C","hint":"Chelating ligands add stability.","explanation":"Oxalate is a bidentate chelating ligand, giving the most stable complex.","difficulty":2,"sources":[[2024,"C","56(B)/S",10]]},{"id":"c0259","chapter":3,"type":"mcq","text":"The role of a catalyst is to change :","options":{"A":"equilibrium constant","B":"$\\Delta_rG$","C":"$\\Delta_rH$","D":"$E_a$"},"answer":"D","hint":"A catalyst opens a new pathway.","explanation":"A catalyst provides an alternative path with lower $E_a$.","difficulty":1,"sources":[[2024,"C","56(B)/S",11]]},{"id":"c0260","chapter":1,"type":"mcq","text":"Van't Hoff factor values for KCl and $\\mathrm{K_2SO_4}$ respectively are :","options":{"A":"1 and 2","B":"2 and 3","C":"2 and 2","D":"2 and 4"},"answer":"B","hint":"Count ions on complete dissociation.","explanation":"KCl gives 2 ions; K$_2$SO$_4$ gives 3.","difficulty":1,"sources":[[2024,"C","56(B)/S",12]]},{"id":"c0261","chapter":7,"type":"ar","text":"Assertion (A): o-nitrophenol is a weaker acid than p-nitrophenol.\nReason (R): Intramolecular hydrogen bonding makes para-isomer stronger acid than ortho-isomer.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Where does intramolecular H bonding occur?","explanation":"A is true because of intramolecular H bonding in ortho isomer; R is wrongly worded, as para has no intramolecular H bond.","difficulty":3,"sources":[[2024,"C","56(B)/S",14]]},{"id":"c0262","chapter":1,"type":"ar","text":"Assertion (A): Chloroform and acetone mixture shows negative deviation from Raoult's law.\nReason (R): In chloroform and acetone mixture, A-A or B-B type intermolecular interactions are weaker than A-B type interactions.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Relate deviation sign to A-B vs A-A strength.","explanation":"Hydrogen bonding makes A-B stronger, lowering vapour pressure; R explains A.","difficulty":1,"sources":[[2024,"C","56(B)/S",16]]},{"id":"c0263","chapter":2,"type":"mcq","text":"The standard electrode potential for $\\mathrm{Sn^{4+}/Sn^{2+}}$ couple is $+0.15$ V and for $\\mathrm{Cr^{3+}/Cr}$ couple is $-0.73$ V. These two couples are connected to make an electrochemical cell. The redox reaction is spontaneous. The cell potential will be :","options":{"A":"$+0.88$ V","B":"$+0.58$ V","C":"$-0.88$ V","D":"$-0.58$ V"},"answer":"A","hint":"Spontaneous cell has positive $E^\\circ$.","explanation":"$0.15-(-0.73)=+0.88$ V.","difficulty":1,"sources":[[2024,"C","56/S/1",1],[2024,"C","56/S/2",4]]},{"id":"c0264","chapter":5,"type":"mcq","text":"The most stable complex among the following is :","options":{"A":"$\\mathrm{[Pt(NH_3)_2Cl_2]}$","B":"$\\mathrm{[Ag(NH_3)_2]Cl}$","C":"$\\mathrm{[Pt(en)_2Cl_2]^{2+}}$","D":"$\\mathrm{K_4[Fe(CN)_6]}$"},"answer":"C","hint":"Chelate effect increases stability.","explanation":"Ethylenediamine is a chelating ligand and Pt is in +4 state.","difficulty":2,"sources":[[2024,"C","56/S/1",2],[2024,"C","56/S/3",6]]},{"id":"c0265","chapter":5,"type":"mcq","text":"The geometry of diamagnetic nickel complex $\\mathrm{[Ni(CN)_4]^{2-}}$ is :","options":{"A":"Tetrahedral","B":"Octahedral","C":"Square planar","D":"Distorted octahedral"},"answer":"C","hint":"Diamagnetic $d^8$ with strong field ligand.","explanation":"CN$^-$ pairs electrons, giving dsp$^2$ square planar.","difficulty":1,"sources":[[2024,"C","56/S/1",3],[2024,"C","56/S/2",6]]},{"id":"c0266","chapter":4,"type":"mcq","text":"Out of $\\mathrm{Fe^{2+}, Co^{2+}, Cr^{3+}, Ni^{2+}}$, the one which shows highest magnetic moment is : (Atomic number: Cr = 24, Fe = 26, Co = 27, Ni = 28)","options":{"A":"$\\mathrm{Fe^{2+}}$","B":"$\\mathrm{Co^{2+}}$","C":"$\\mathrm{Cr^{3+}}$","D":"$\\mathrm{Ni^{2+}}$"},"answer":"A","hint":"Count unpaired electrons for each ion.","explanation":"Unpaired electrons: Fe$^{2+}$ 4, Co$^{2+}$ 3, Cr$^{3+}$ 3, Ni$^{2+}$ 2.","difficulty":2,"sources":[[2024,"C","56/S/1",4],[2024,"C","56/S/2",8]]},{"id":"c0267","chapter":9,"type":"mcq","text":"If amines are arranged in increasing order of their basic strength in gaseous phase, then the correct order will be :","options":{"A":"$\\mathrm{NH_3<CH_3NH_2<(CH_3)_3N<(CH_3)_2NH}$","B":"$\\mathrm{NH_3<(CH_3)_2NH<(CH_3)_3N<CH_3NH_2}$","C":"$\\mathrm{(CH_3)_3N<(CH_3)_2NH<CH_3NH_2<NH_3}$","D":"$\\mathrm{NH_3<CH_3NH_2<(CH_3)_2NH<(CH_3)_3N}$"},"answer":"D","hint":"In the gas phase only the +I effect matters (no solvation).","explanation":"Gas-phase order follows alkyl count: NH$_3$ < primary < secondary < tertiary.","difficulty":2,"sources":[[2024,"C","56/S/1",5],[2024,"C","56/S/3",7]]},{"id":"c0268","chapter":8,"type":"mcq","text":"Which of the following does not undergo Aldol condensation ?","options":{"A":"$\\mathrm{CH_3CHO}$","B":"$\\mathrm{CH_3COCH_3}$","C":"$\\mathrm{CH_3CH_2CHO}$","D":"$\\mathrm{C_6H_5CHO}$"},"answer":"D","hint":"Aldol condensation needs alpha-hydrogen atoms.","explanation":"Benzaldehyde has no alpha-hydrogen, so it cannot undergo aldol condensation.","difficulty":1,"sources":[[2024,"C","56/S/1",6],[2024,"C","56/S/2",10]]},{"id":"c0269","chapter":6,"type":"mcq","text":"The correct IUPAC name of $\\mathrm{(CH_3)_3C-CH_2Br}$ is :","options":{"A":"2,2-Dimethyl-2-bromopropane","B":"1-Bromo-2,2,2-trimethylethane","C":"2-Bromo-1,1,1-trimethylethane","D":"1-Bromo-2,2-dimethylpropane"},"answer":"D","hint":"Choose the longest chain, then number from the end nearer the substituents (lowest locants).","explanation":"Longest chain is propane with Br on C-1 and two methyls on C-2: 1-bromo-2,2-dimethylpropane.","difficulty":1,"sources":[[2024,"C","56/S/1",7],[2024,"C","56/S/2",12],[2024,"C","56/S/3",9]]},{"id":"c0270","chapter":5,"type":"mcq","text":"Considering the strength of the ligand, the highest excitation energy will be observed in :","options":{"A":"$\\mathrm{[Co(H_2O)_6]^{3+}}$","B":"$\\mathrm{[Co(NH_3)_6]^{3+}}$","C":"$\\mathrm{[Co(CN)_6]^{3-}}$","D":"$\\mathrm{[CoCl_6]^{3-}}$"},"answer":"C","hint":"Compare ligands in the spectrochemical series: larger splitting means larger excitation energy.","explanation":"CN$^-$ is the strongest field ligand, giving the largest $\\Delta_o$ and hence the highest excitation energy.","difficulty":2,"sources":[[2024,"C","56/S/1",8],[2024,"C","56/S/3",10]]},{"id":"c0271","chapter":3,"type":"mcq","text":"For a chemical reaction, $\\mathrm{A \\rightarrow B}$, it was observed that the rate of reaction doubles when the concentration of A is increased four times. The order of the reaction is :","options":{"A":"2","B":"1","C":"1/2","D":"Zero"},"answer":"C","hint":"Write rate $\\propto [A]^n$ and compare the two cases.","explanation":"$2 = 4^n$ gives $n = 1/2$.","difficulty":1,"sources":[[2024,"C","56/S/1",9],[2024,"C","56/S/2",11],[2024,"C","56/S/3",11]]},{"id":"c0272","chapter":5,"type":"mcq","text":"The IUPAC name of the complex $\\mathrm{[Co(NH_3)_5(NO_2)]Cl_2}$ is :","options":{"A":"Pentaamminenitrito-O-cobalt(III) chloride","B":"Pentaamminenitrito-N-cobalt(III) chloride","C":"Pentaamminenitro-cobalt(III) chloride","D":"Pentaaminenitrito-cobalt(II) chloride"},"answer":"B","hint":"Decide how the nitrite ligand is bonded (through N or O) and the oxidation state of Co.","explanation":"Ligand is bonded through N, and Co is +3; the nitrite-N name is pentaamminenitrito-N-cobalt(III) chloride.","difficulty":2,"sources":[[2024,"C","56/S/1",10],[2024,"C","56/S/2",9]]},{"id":"c0273","chapter":7,"type":"mcq","text":"Williamson's synthesis of preparing dimethyl ether is a/an :","options":{"A":"electrophilic substitution","B":"$\\mathrm{S_N}$1 reaction","C":"electrophilic addition","D":"$\\mathrm{S_N}$2 reaction"},"answer":"D","hint":"Methoxide attacks a primary methyl halide from the back side.","explanation":"Sodium methoxide attacks a methyl halide in a one-step backside attack, an $S_N2$ reaction.","difficulty":1,"sources":[[2024,"C","56/S/1",11],[2024,"C","56/S/2",7],[2024,"C","56/S/3",12]]},{"id":"c0274","chapter":9,"type":"mcq","text":"The chemical test which can be used to distinguish between ethanamine and aniline is :","options":{"A":"Haloform test","B":"Tollens' test","C":"Azo dye test","D":"Hinsberg test"},"answer":"C","hint":"One of the two amines is aromatic and can be diazotised and coupled.","explanation":"Aniline (aromatic primary amine) gives a diazonium salt that couples to form an orange azo dye; ethanamine does not.","difficulty":1,"sources":[[2024,"C","56/S/1",12],[2024,"C","56/S/2",5],[2024,"C","56/S/3",8]]},{"id":"c0275","chapter":10,"type":"ar","text":"Assertion (A): Maltose is a reducing sugar.\nReason (R): Maltose is composed of two glucose units in which C-1 of one glucose unit is linked to C-4 of another glucose unit.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Does maltose retain a free anomeric carbon?","explanation":"Both are true, but maltose is reducing because of the free hemiacetal group at C-1 of the second glucose unit, which R does not state.","difficulty":2,"note":"Official answer B; some argue R explains A.","sources":[[2024,"C","56/S/1",13],[2024,"C","56/S/2",15]]},{"id":"c0276","chapter":9,"type":"ar","text":"Assertion (A): Acetanilide ($\\mathrm{C_6H_5NHCOCH_3}$) is less basic than aniline.\nReason (R): Acetylation of aniline results in decrease of electron density on nitrogen.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think about the lone pair on N delocalised into C=O.","explanation":"The lone pair on N in acetanilide is delocalised into the carbonyl, lowering electron density and basicity. Both true and R explains A.","difficulty":2,"sources":[[2024,"C","56/S/1",14],[2024,"C","56/S/2",16],[2024,"R","56/2/2",16]]},{"id":"c0277","chapter":3,"type":"ar","text":"Assertion (A): Rate constant increases with increase in temperature.\nReason (R): Increasing the temperature of the substance increases the fraction of molecules, which collide with energies greater than activation energy.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Recall the Arrhenius factor $e^{-E_a/RT}$.","explanation":"Higher temperature raises the fraction of molecules with energy $\\geq E_a$, so $k$ increases. Both true and R explains A.","difficulty":1,"sources":[[2024,"C","56/S/1",15],[2024,"C","56/S/2",13],[2024,"C","56/S/3",13]]},{"id":"c0278","chapter":4,"type":"ar","text":"Assertion (A): $\\mathrm{Cu^{2+}}$ iodide is not known.\nReason (R): $\\mathrm{Cu^{2+}}$ has strong tendency to oxidise $\\mathrm{I^-}$ to iodine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Compare the reduction potential of Cu(II)/Cu(I) with that of iodine.","explanation":"$\\mathrm{Cu^{2+}}$ oxidises $\\mathrm{I^-}$ to $\\mathrm{I_2}$ (forming CuI), so $\\mathrm{CuI_2}$ cannot exist. Both true and R explains A.","difficulty":2,"sources":[[2024,"C","56/S/1",16],[2024,"C","56/S/2",14]]},{"id":"c0279","chapter":5,"type":"mcq","text":"The most stable complex among the following is :","options":{"A":"$\\mathrm{Na_2[Na(CN)_5(NO)]}$","B":"$\\mathrm{K_3[Fe(CN)_6]}$","C":"$\\mathrm{[Cr(NH_3)_6]^{3+}}$","D":"$\\mathrm{Na_2[Ni(EDTA)]}$"},"answer":"D","hint":"Look for a polydentate chelating ligand.","explanation":"EDTA is a hexadentate chelating ligand, so the chelate effect makes $\\mathrm{[Ni(EDTA)]^{2-}}$ the most stable.","difficulty":2,"note":"Option A is printed as Na2[Na(CN)5(NO)] in the paper (misprint for Fe); it does not affect the answer.","sources":[[2024,"C","56/S/2",1]]},{"id":"c0280","chapter":5,"type":"mcq","text":"Considering the strength of the ligand, the lowest excitation energy will be observed in :","options":{"A":"$\\mathrm{[Co(H_2O)_6]^{3+}}$","B":"$\\mathrm{[Co(NH_3)_6]^{3+}}$","C":"$\\mathrm{[Co(CN)_6]^{3-}}$","D":"$\\mathrm{[CoCl_6]^{3-}}$"},"answer":"D","hint":"Weakest field ligand gives smallest splitting.","explanation":"Cl$^-$ is the weakest field ligand here, giving the smallest $\\Delta$ and the lowest excitation energy.","difficulty":2,"sources":[[2024,"C","56/S/2",3]]},{"id":"c0281","chapter":2,"type":"mcq","text":"The standard electrode potential for $\\mathrm{Ni^{2+}/Ni}$ couple is $-0.25$ V and for $\\mathrm{Ag^+/Ag}$ couple is $0.80$ V. These two couples are connected to make an electrochemical cell. The redox reaction is spontaneous. The cell potential will be :","options":{"A":"$+1.05$ V","B":"$-1.05$ V","C":"$+0.55$ V","D":"$-0.55$ V"},"answer":"A","hint":"$E^\\circ_\\mathrm{cell} = E^\\circ_\\mathrm{cathode} - E^\\circ_\\mathrm{anode}$.","explanation":"Ag is cathode, Ni anode: $0.80-(-0.25)=+1.05$ V.","difficulty":1,"sources":[[2024,"C","56/S/3",1]]},{"id":"c0282","chapter":4,"type":"mcq","text":"Out of $\\mathrm{Fe^{2+}}$, $\\mathrm{Co^{2+}}$, $\\mathrm{Cr^{3+}}$, $\\mathrm{Ni^{2+}}$, the one which shows lowest magnetic moment is :\n[Atomic number : Fe = 26, Co = 27, Ni = 28, Cr = 24]","options":{"A":"$\\mathrm{Fe^{2+}}$","B":"$\\mathrm{Co^{2+}}$","C":"$\\mathrm{Cr^{3+}}$","D":"$\\mathrm{Ni^{2+}}$"},"answer":"D","hint":"Count unpaired electrons in each ion: $\\mu=\\sqrt{n(n+2)}$.","explanation":"Unpaired electrons: Fe$^{2+}$ 4, Co$^{2+}$ 3, Cr$^{3+}$ 3, Ni$^{2+}$ 2, so Ni$^{2+}$ has the lowest moment.","difficulty":2,"sources":[[2024,"C","56/S/3",2]]},{"id":"c0283","chapter":5,"type":"mcq","text":"The geometry of paramagnetic nickel complex $\\mathrm{[NiCl_4]^{2-}}$ is :","options":{"A":"tetrahedral","B":"octahedral","C":"square planar","D":"distorted octahedral"},"answer":"A","hint":"Weak field Cl$^-$ does not pair the electrons.","explanation":"With weak field Cl$^-$, Ni$^{2+}$ ($d^8$) keeps 2 unpaired electrons and uses $sp^3$ hybridisation: tetrahedral.","difficulty":1,"sources":[[2024,"C","56/S/3",3]]},{"id":"c0284","chapter":8,"type":"mcq","text":"Which of the following does not undergo Aldol condensation ?","options":{"A":"$\\mathrm{HCHO}$","B":"$\\mathrm{CH_3CH_2CHO}$","C":"$\\mathrm{CH_3COCH_3}$","D":"$\\mathrm{CH_3CHO}$"},"answer":"A","hint":"Aldol condensation needs alpha-hydrogen atoms.","explanation":"Formaldehyde has no alpha-hydrogen, so it does not undergo aldol condensation.","difficulty":1,"sources":[[2024,"C","56/S/3",4]]},{"id":"c0285","chapter":5,"type":"mcq","text":"The IUPAC name of the complex $\\mathrm{[Co(NH_3)_5(ONO)]Cl_2}$ is :","options":{"A":"Pentaamminenitrito-O-cobalt(III) chloride","B":"Pentaamminenitrito-N-cobalt(III) chloride","C":"Pentaamminenitro-cobalt(III) chloride","D":"Pentaaminenitrito-cobalt(II) chloride"},"answer":"A","hint":"ONO means the ligand is bonded through oxygen.","explanation":"Nitrite bonded through O is nitrito-O; Co is +3: pentaamminenitrito-O-cobalt(III) chloride.","difficulty":2,"sources":[[2024,"C","56/S/3",5]]},{"id":"c0286","chapter":4,"type":"ar","text":"Assertion (A): $\\mathrm{Cu^{2+}}$ iodide is known.\nReason (R): $\\mathrm{Cu^{2+}}$ has strong tendency to oxidise $\\mathrm{I^-}$ to Iodine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Does Cu(II) survive in the presence of iodide?","explanation":"$\\mathrm{Cu^{2+}}$ oxidises $\\mathrm{I^-}$ to $\\mathrm{I_2}$, so copper(II) iodide is not known: A false, R true.","difficulty":2,"sources":[[2024,"C","56/S/3",14]]},{"id":"c0287","chapter":9,"type":"ar","text":"Assertion (A): Acetanilide ($\\mathrm{C_6H_5NHCOCH_3}$) is more basic than aniline.\nReason (R): Acetylation of aniline results in decrease of electron density on nitrogen.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Think about the lone pair on N delocalised into C=O.","explanation":"Acetylation lowers electron density on N, so acetanilide is less basic: A false, R true.","difficulty":2,"sources":[[2024,"C","56/S/3",16]]},{"id":"c0288","chapter":1,"type":"mcq","text":"Low concentration of oxygen in the blood and tissues of people living at high altitudes is due to:","options":{"A":"Low temperature","B":"Low atmospheric pressure","C":"High atmospheric pressure","D":"High temperature"},"answer":"B","hint":"Henry's law: solubility depends on partial pressure.","explanation":"At high altitude the partial pressure of $\\mathrm{O_2}$ is low, so less dissolves in blood (Henry's law).","difficulty":1,"sources":[[2024,"R","56(B)",1]]},{"id":"c0289","chapter":2,"type":"mcq","text":"The quantity of charge required to obtain one mole of Al from $\\mathrm{Al_2O_3}$ is:","options":{"A":"1 F","B":"6 F","C":"3 F","D":"2 F"},"answer":"C","hint":"$\\mathrm{Al^{3+}} + 3e^- \\rightarrow \\mathrm{Al}$.","explanation":"Each Al$^{3+}$ needs 3 electrons, so 3 F per mole of Al.","difficulty":1,"sources":[[2024,"R","56(B)",2]]},{"id":"c0290","chapter":4,"type":"mcq","text":"Which of the following oxidation state is common for all lanthanoids?","options":{"A":"+ 2","B":"+ 4","C":"+ 6","D":"+ 3"},"answer":"D","hint":"The characteristic oxidation state of the f-block series.","explanation":"+3 is the common oxidation state of all lanthanoids.","difficulty":1,"sources":[[2024,"R","56(B)",3]]},{"id":"c0291","chapter":4,"type":"mcq","text":"Which of the following ions has the electronic configuration $3d^3$? [Atomic number: Cr = 24, Mn = 25, Fe = 26, Co = 27]","options":{"A":"$\\mathrm{Cr^{3+}}$","B":"$\\mathrm{Mn^{3+}}$","C":"$\\mathrm{Fe^{3+}}$","D":"$\\mathrm{Co^{3+}}$"},"answer":"A","hint":"Remove 4s electrons first, then 3d.","explanation":"$\\mathrm{Cr}$ is $3d^54s^1$; losing three electrons gives $3d^3$. Mn$^{3+}$ is $3d^4$, Fe$^{3+}$ $3d^5$, Co$^{3+}$ $3d^6$.","difficulty":2,"sources":[[2024,"R","56(B)",4]]},{"id":"c0292","chapter":5,"type":"mcq","text":"When 1 mole of $\\mathrm{CoCl_3{\\cdot}5NH_3}$ is treated with excess of $\\mathrm{AgNO_3}$, 2 moles of AgCl are obtained. The secondary valency of Co will be:","options":{"A":"6","B":"4","C":"3","D":"5"},"answer":"A","hint":"Two ionisable Cl$^-$ means one Cl is inside the sphere.","explanation":"The complex is $\\mathrm{[Co(NH_3)_5Cl]Cl_2}$; five $\\mathrm{NH_3}$ plus one Cl give coordination number 6.","difficulty":2,"sources":[[2024,"R","56(B)",5]]},{"id":"c0293","chapter":6,"type":"mcq","text":"A primary alkyl halide would prefer to undergo ____________.","options":{"A":"$\\mathrm{S_N2}$ reaction","B":"$\\mathrm{S_N1}$ reaction","C":"Electrophilic substitution reaction","D":"Racemisation"},"answer":"A","hint":"Primary carbocations are unstable and the carbon is unhindered.","explanation":"Primary halides are unhindered and give unstable carbocations, so they favour $\\mathrm{S_N2}$.","difficulty":1,"sources":[[2024,"R","56(B)",6]]},{"id":"c0294","chapter":7,"type":"mcq","text":"Phenol is less acidic than:","options":{"A":"Ethanol","B":"$o$-cresol","C":"$p$-cresol","D":"$o$-nitrophenol"},"answer":"D","hint":"Electron-withdrawing groups raise acidity.","explanation":"The $-\\mathrm{NO_2}$ group stabilises the phenoxide ion, making o-nitrophenol more acidic than phenol.","difficulty":1,"sources":[[2024,"R","56(B)",7]]},{"id":"c0295","chapter":9,"type":"mcq","text":"Reduction of aromatic nitro compounds using Sn and HCl gives:","options":{"A":"Aromatic amide","B":"Aromatic oxime","C":"Aromatic primary amine","D":"Aromatic hydrocarbon"},"answer":"C","hint":"$-\\mathrm{NO_2}$ is reduced fully.","explanation":"Sn/HCl reduces $\\mathrm{Ar{-}NO_2}$ to $\\mathrm{Ar{-}NH_2}$.","difficulty":1,"sources":[[2024,"R","56(B)",8]]},{"id":"c0296","chapter":10,"type":"mcq","text":"Nucleic acids are the polymers of:","options":{"A":"Nucleotides","B":"Nucleosides","C":"Bases","D":"Sugars"},"answer":"A","hint":"Monomer = sugar + base + phosphate.","explanation":"Nucleic acids are polynucleotides, linked by phosphodiester bonds.","difficulty":1,"sources":[[2024,"R","56(B)",9]]},{"id":"c0297","chapter":9,"type":"mcq","text":"Methylamine reacts with $\\mathrm{HNO_2}$ to form:","options":{"A":"$\\mathrm{CH_3{-}O{-}N=O}$","B":"$\\mathrm{CH_3{-}O{-}CH_3}$","C":"$\\mathrm{CH_3{-}OH}$","D":"$\\mathrm{CH_3{-}CHO}$"},"answer":"C","hint":"Primary aliphatic amine gives an unstable diazonium salt.","explanation":"$\\mathrm{CH_3NH_2 + HNO_2 \\rightarrow CH_3OH + N_2 + H_2O}$ (via unstable diazonium salt).","difficulty":1,"sources":[[2024,"R","56(B)",10]]},{"id":"c0298","chapter":9,"type":"mcq","text":"Which one of the following has the lowest $\\mathrm{pK_b}$ value?","options":{"A":"Ammonia","B":"Aniline","C":"Methylamine","D":"Dimethylamine"},"answer":"D","hint":"Lowest pKb means strongest base.","explanation":"In aqueous solution dimethylamine is the strongest base listed, so it has the lowest $\\mathrm{pK_b}$.","difficulty":2,"sources":[[2024,"R","56(B)",11]]},{"id":"c0299","chapter":8,"type":"mcq","text":"Which of the following compounds is most reactive towards nucleophilic addition reactions?","options":{"A":"$\\mathrm{CH_3CHO}$","B":"$\\mathrm{CH_3{-}CO{-}CH_3}$","C":"Benzaldehyde (structure shown in figure)","D":"Acetophenone (structure shown in figure)"},"answer":"A","hint":"Less steric hindrance and more positive carbonyl C.","explanation":"Aliphatic aldehydes are more reactive than ketones and aromatic carbonyls, so $\\mathrm{CH_3CHO}$ is most reactive.","difficulty":1,"figure":"figures/c0299.png","sources":[[2024,"R","56(B)",12]]},{"id":"c0300","chapter":8,"type":"ar","text":"Assertion (A): Bromination of benzoic acid gives m-bromobenzoic acid.\nReason (R): Carboxyl group acts as a deactivating and meta-directing group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Electron-withdrawing groups direct meta.","explanation":"Both true; the deactivating, meta-directing $-\\mathrm{COOH}$ explains the meta product.","difficulty":1,"sources":[[2024,"R","56(B)",14]]},{"id":"c0301","chapter":5,"type":"ar","text":"Assertion (A): Linkage isomerism arises in coordination compounds containing ambidentate ligand.\nReason (R): Ambidentate ligand has two same donor atoms.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Ambidentate ligands bind through different atoms.","explanation":"A is true. R is false: an ambidentate ligand has two different donor atoms (e.g. N or O in $\\mathrm{NO_2^-}$).","difficulty":1,"sources":[[2024,"R","56(B)",16]]},{"id":"c0302","chapter":4,"type":"mcq","text":"Which one of the following first row transition elements is expected to have the highest third ionization enthalpy ?","options":{"A":"Iron (Z = 26)","B":"Manganese (Z = 25)","C":"Chromium (Z = 24)","D":"Vanadium (Z = 23)"},"answer":"B","hint":"Third ionisation removes an electron from $M^{2+}$; look for a stable half-filled configuration.","explanation":"$\\mathrm{Mn^{2+}}$ is $3d^5$ (half-filled, extra stable), so removing a third electron is hardest.","difficulty":2,"sources":[[2024,"R","56/1/1",1]]},{"id":"c0303","chapter":7,"type":"mcq","text":"Which of the following compounds will give a ketone on oxidation with chromic anhydride ($\\mathrm{CrO_3}$) ?","options":{"A":"$\\mathrm{(CH_3)_2CH-CH_2OH}$","B":"$\\mathrm{CH_3CH_2CH_2OH}$","C":"$\\mathrm{(CH_3)_3C-OH}$","D":"$\\mathrm{CH_3-CH_2-CH(OH)-CH_3}$"},"answer":"D","hint":"Only one class of alcohol oxidises to a ketone.","explanation":"Secondary alcohols (butan-2-ol) are oxidised to ketones; primary give acids/aldehydes, tertiary resist.","difficulty":1,"sources":[[2024,"R","56/1/1",2]]},{"id":"c0304","chapter":10,"type":"mcq","text":"Two among the three components of DNA are $\\beta$-D-2-deoxyribose and a heterocyclic base. The third component is :","options":{"A":"Adenine","B":"Phosphoric acid","C":"Sulphuric acid","D":"Uracil"},"answer":"B","hint":"DNA = sugar + base + one inorganic acid unit.","explanation":"DNA nucleotides contain a sugar, a nitrogenous base and a phosphate (phosphoric acid).","difficulty":1,"sources":[[2024,"R","56/1/1",3]]},{"id":"c0305","chapter":1,"type":"mcq","text":"For an electrolyte undergoing association in a solvent, the van't Hoff factor :","options":{"A":"is always greater than one","B":"has negative value","C":"has zero value","D":"is always less than one"},"answer":"D","hint":"Association reduces the number of particles.","explanation":"Association decreases the number of solute particles, so $i<1$.","difficulty":1,"sources":[[2024,"R","56/1/1",4]]},{"id":"c0306","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{X + 2Y \\rightarrow P}$, the differential form equation of the rate law is :","options":{"A":"$\\dfrac{2\\,d[P]}{dt}=\\dfrac{-d[Y]}{dt}$","B":"$\\dfrac{-d[P]}{dt}=\\dfrac{-d[X]}{dt}$","C":"$\\dfrac{+d[X]}{dt}=\\dfrac{-d[P]}{dt}$","D":"$\\dfrac{-2\\,d[Y]}{dt}=\\dfrac{+d[P]}{dt}$"},"answer":"A","hint":"Rate = $-\\frac{1}{\\text{coeff}}\\frac{d[\\text{reactant}]}{dt}=+\\frac{1}{\\text{coeff}}\\frac{d[\\text{product}]}{dt}$.","explanation":"Rate $=-\\frac12\\frac{d[Y]}{dt}=\\frac{d[P]}{dt}$, i.e. $2\\frac{d[P]}{dt}=-\\frac{d[Y]}{dt}$.","difficulty":2,"sources":[[2024,"R","56/1/1",5]]},{"id":"c0307","chapter":6,"type":"mcq","text":"The compound which undergoes $\\mathrm{S_N}$1 reaction most rapidly is :","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"The fastest $S_N1$ gives the most stabilised carbocation.","explanation":"(A) is an allylic bromide, giving a resonance-stabilised allyl carbocation; the aryl bromide (D) is least reactive.","difficulty":2,"figure":"figures/c0307.png","sources":[[2024,"R","56/1/1",6]]},{"id":"c0308","chapter":8,"type":"mcq","text":"Acetic acid reacts with $\\mathrm{PCl_5}$ to give :","options":{"A":"$\\mathrm{Cl-CH_2-COCl}$","B":"$\\mathrm{Cl-CH_2-COOH}$","C":"$\\mathrm{CH_3-COCl}$","D":"$\\mathrm{CCl_3-COOH}$"},"answer":"C","hint":"PCl$_5$ replaces the OH of a carboxylic acid.","explanation":"PCl$_5$ converts $-\\mathrm{COOH}$ to $-\\mathrm{COCl}$, giving acetyl chloride.","difficulty":1,"sources":[[2024,"R","56/1/1",7]]},{"id":"c0309","chapter":8,"type":"mcq","text":"The formation of cyanohydrin from an aldehyde is an example of :","options":{"A":"nucleophilic addition","B":"electrophilic addition","C":"nucleophilic substitution","D":"electrophilic substitution"},"answer":"A","hint":"CN$^-$ attacks the carbonyl carbon.","explanation":"$\\mathrm{CN^-}$ adds to the electrophilic C=O carbon: nucleophilic addition.","difficulty":1,"sources":[[2024,"R","56/1/1",8]]},{"id":"c0310","chapter":3,"type":"mcq","text":"In the Arrhenius equation, when $\\log k$ is plotted against $1/T$, a straight line is obtained whose :","options":{"A":"slope is $\\dfrac{A}{R}$ and intercept is $E_a$.","B":"slope is $A$ and intercept is $\\dfrac{-E_a}{R}$.","C":"slope is $\\dfrac{-E_a}{RT}$ and intercept is $\\log A$.","D":"slope is $\\dfrac{-E_a}{2.303\\,R}$ and intercept is $\\log A$."},"answer":"D","hint":"Take the logarithm of $k=Ae^{-E_a/RT}$.","explanation":"$\\log k=\\log A-\\frac{E_a}{2.303R}\\cdot\\frac1T$, so slope $=-E_a/2.303R$ and intercept $=\\log A$.","difficulty":1,"sources":[[2024,"R","56/1/1",9],[2024,"R","56/1/2",10]]},{"id":"c0311","chapter":7,"type":"mcq","text":"The reaction of an alkyl halide with sodium alkoxide forming ether is known as :","options":{"A":"Wurtz reaction","B":"Reimer-Tiemann reaction","C":"Williamson synthesis","D":"Kolbe reaction"},"answer":"C","hint":"Name reaction for making ethers from RX and RONa.","explanation":"This is the Williamson synthesis.","difficulty":1,"sources":[[2024,"R","56/1/1",10]]},{"id":"c0312","chapter":7,"type":"mcq","text":"The correct order of the ease of dehydration of the following alcohols by the action of conc. $\\mathrm{H_2SO_4}$ is :","options":{"A":"$\\mathrm{(CH_3)_3C-OH > (CH_3)_2CH-OH > CH_3CH_2-OH}$","B":"$\\mathrm{(CH_3)_2CH-OH > CH_3CH_2-OH > (CH_3)_3C-OH}$","C":"$\\mathrm{CH_3CH_2-OH > (CH_3)_2CH-OH > (CH_3)_3C-OH}$","D":"$\\mathrm{(CH_3)_2CH-OH > (CH_3)_3C-OH > CH_3CH_2-OH}$"},"answer":"A","hint":"Ease of dehydration follows carbocation stability.","explanation":"Dehydration goes via carbocations: tertiary > secondary > primary.","difficulty":1,"sources":[[2024,"R","56/1/1",11]]},{"id":"c0313","chapter":10,"type":"mcq","text":"Which functional groups of glucose interact to form cyclic hemiacetal leading to pyranose structure ?","options":{"A":"Aldehyde group and hydroxyl group at C-4","B":"Aldehyde group and hydroxyl group at C-5","C":"Ketone group and hydroxyl group at C-4","D":"Ketone group and hydroxyl group at C-5"},"answer":"B","hint":"Pyranose is a six-membered ring including oxygen.","explanation":"The C-1 aldehyde reacts with the C-5 OH to give a six-membered hemiacetal ring (pyranose).","difficulty":1,"sources":[[2024,"R","56/1/1",12]]},{"id":"c0314","chapter":1,"type":"ar","text":"Assertion (A): When NaCl is added to water a depression in freezing point is observed.\nReason (R): NaCl undergoes dissociation in water.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Colligative properties depend on the number of particles.","explanation":"Both are true; any non-volatile solute depresses the freezing point, so dissociation of NaCl is not the reason for the depression itself.","difficulty":1,"note":"Official answer B; some argue R explains A.","sources":[[2024,"R","56/1/1",13]]},{"id":"c0315","chapter":4,"type":"ar","text":"Assertion (A): Separation of Zr and Hf is difficult.\nReason (R): Zr and Hf have similar radii due to lanthanoid contraction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Similar size means similar chemical properties.","explanation":"Lanthanoid contraction makes Zr and Hf almost equal in radius, so they are chemically alike and hard to separate.","difficulty":1,"sources":[[2024,"R","56/1/1",14]]},{"id":"c0316","chapter":8,"type":"ar","text":"Assertion (A): The $\\mathrm{p}K_a$ of ethanoic acid is lower than that of $\\mathrm{Cl-CH_2-COOH}$.\nReason (R): Chlorine shows electron withdrawing ($-I$) effect which increases the acidic character of $\\mathrm{Cl-CH_2-COOH}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which acid is stronger, and what does lower $pK_a$ mean?","explanation":"Chloroacetic acid is stronger, so ethanoic acid has the higher $pK_a$: A false; R is true.","difficulty":2,"sources":[[2024,"R","56/1/1",15]]},{"id":"c0317","chapter":9,"type":"ar","text":"Assertion (A): Aniline is a stronger base than ammonia.\nReason (R): The unshared electron pair on nitrogen atom in aniline becomes less available for protonation due to resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Compare lone pair availability in aniline and ammonia.","explanation":"Aniline is a weaker base than ammonia because the lone pair is delocalised into the ring: A false, R true.","difficulty":2,"sources":[[2024,"R","56/1/1",16],[2024,"R","56/1/2",13]]},{"id":"c0318","chapter":4,"type":"mcq","text":"The most stable oxidation state of Iron is :","options":{"A":"+2","B":"+3","C":"+4","D":"$-2$"},"answer":"B","hint":"Think of the $3d^5$ configuration.","explanation":"Fe$^{3+}$ has the stable half-filled $3d^5$ configuration, so +3 is most stable.","difficulty":1,"sources":[[2024,"R","56/1/2",1]]},{"id":"c0319","chapter":8,"type":"mcq","text":"The product formed as a result of reaction of $\\mathrm{CH_3MgBr}$ and $\\mathrm{CO_2}$ followed by hydrolysis is :","options":{"A":"$\\mathrm{CH_3CHO}$","B":"$\\mathrm{CH_3COCH_3}$","C":"$\\mathrm{HCOOH}$","D":"$\\mathrm{CH_3COOH}$"},"answer":"D","hint":"Grignard reagent adds to CO$_2$ to give a carboxylic acid with one more carbon.","explanation":"$\\mathrm{CH_3MgBr + CO_2}$ gives $\\mathrm{CH_3COOMgBr}$, which on hydrolysis gives acetic acid.","difficulty":1,"sources":[[2024,"R","56/1/2",2]]},{"id":"c0320","chapter":10,"type":"mcq","text":"Nucleotides are composed of a :","options":{"A":"pentose sugar and phosphoric acid","B":"nitrogenous base, pentose sugar and phosphoric acid","C":"nitrogenous base and phosphoric acid","D":"pentose sugar and nitrogenous base"},"answer":"B","hint":"A nucleoside plus phosphate.","explanation":"A nucleotide = nitrogenous base + pentose sugar + phosphate group.","difficulty":1,"sources":[[2024,"R","56/1/2",3]]},{"id":"c0321","chapter":1,"type":"mcq","text":"Phenol dimerises in benzene having van't Hoff factor $0.54$. Its degree of association is :","options":{"A":"$0.54$","B":"$0.46$","C":"$0.92$","D":"$0.27$"},"answer":"C","hint":"For dimerisation $i=1-\\alpha/2$.","explanation":"$0.54=1-\\alpha/2$ gives $\\alpha=0.92$.","difficulty":2,"sources":[[2024,"R","56/1/2",5]]},{"id":"c0322","chapter":3,"type":"mcq","text":"A reaction $\\mathrm{A_2 + B_2 \\longrightarrow 2AB}$ occurs by the following mechanism :\n$\\mathrm{A_2 \\rightarrow A + A}$ (slow)\n$\\mathrm{A + B_2 \\rightarrow AB + B}$ (fast)\n$\\mathrm{A + B \\rightarrow AB}$ (fast)\nIts order would be :","options":{"A":"1","B":"2","C":"Zero","D":"$\\tfrac12$"},"answer":"A","hint":"The rate is set by the slow step.","explanation":"The slow step involves only $\\mathrm{A_2}$, so rate $=k[\\mathrm{A_2}]$ and the order is 1.","difficulty":2,"sources":[[2024,"R","56/1/2",6]]},{"id":"c0323","chapter":8,"type":"mcq","text":"Decarboxylation of sodium benzoate on heating with soda lime gives :","options":{"A":"benzene","B":"benzoic acid","C":"benzaldehyde","D":"toluene"},"answer":"A","hint":"Soda lime removes the carboxylate as CO$_2$.","explanation":"$\\mathrm{C_6H_5COONa + NaOH \\xrightarrow{CaO,\\,\\Delta} C_6H_6 + Na_2CO_3}$, giving benzene.","difficulty":1,"sources":[[2024,"R","56/1/2",7]]},{"id":"c0324","chapter":8,"type":"mcq","text":"The IUPAC name of $\\mathrm{CH_3-CO-CH_2-CHO}$ is :","options":{"A":"1-oxobutanal-3-one","B":"1-oxobutanal","C":"3-oxobutanal","D":"3-oxobutanone"},"answer":"C","hint":"Aldehyde is the principal group; ketone is named as oxo.","explanation":"Aldehyde carbon is C-1; the ketone at C-3 is an oxo substituent: 3-oxobutanal.","difficulty":2,"sources":[[2024,"R","56/1/2",8]]},{"id":"c0325","chapter":7,"type":"mcq","text":"Dehydration of tertiary alcohols with Cu at 573 K gives :","options":{"A":"Alkyne","B":"Alkene","C":"Aldehyde","D":"Ketone"},"answer":"B","hint":"Tertiary alcohols have no H on the carbinol carbon to lose.","explanation":"Tertiary alcohols cannot be dehydrogenated; over Cu at 573 K they lose water to give alkenes.","difficulty":1,"sources":[[2024,"R","56/1/2",9]]},{"id":"c0326","chapter":7,"type":"mcq","text":"Phenol on reaction with aqueous bromine at room temperature gives :","options":{"A":"2-bromophenol","B":"3-bromophenol","C":"4-bromophenol","D":"2,4,6-tribromophenol"},"answer":"D","hint":"Bromine water with phenol (strongly activated ring).","explanation":"The highly activated ring is brominated at all ortho and para positions, giving a white precipitate of 2,4,6-tribromophenol.","difficulty":1,"sources":[[2024,"R","56/1/2",11]]},{"id":"c0327","chapter":10,"type":"mcq","text":"The specific sequence in which amino acids are arranged in a protein is called :","options":{"A":"Secondary structure","B":"Primary structure","C":"Tertiary structure","D":"Quaternary structure"},"answer":"B","hint":"Which level of structure is just the order of amino acids?","explanation":"The linear amino acid sequence is the primary structure.","difficulty":1,"sources":[[2024,"R","56/1/2",12]]},{"id":"c0328","chapter":8,"type":"ar","text":"Assertion (A): The $\\mathrm{p}K_a$ of $\\mathrm{O_2N-CH_2-COOH}$ is lower than that of $\\mathrm{CH_3-COOH}$.\nReason (R): $\\mathrm{-NO_2}$ group shows electron withdrawing effect which increases the acidic character of $\\mathrm{O_2N-CH_2-COOH}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Electron-withdrawing groups stabilise the carboxylate.","explanation":"$-\\mathrm{NO_2}$ (strong $-I$) stabilises the anion, making the acid stronger with lower $pK_a$. Both true and R explains A.","difficulty":2,"sources":[[2024,"R","56/1/2",14]]},{"id":"c0329","chapter":4,"type":"ar","text":"Assertion (A): Transition metals have high enthalpy of atomization.\nReason (R): This is because transition metals have low melting points.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Strong metallic bonding from many unpaired d electrons.","explanation":"A is true (strong metallic bonding), but transition metals have high, not low, melting points: R false.","difficulty":1,"sources":[[2024,"R","56/1/2",15]]},{"id":"c0330","chapter":1,"type":"ar","text":"Assertion (A): When NaCl is added in water, elevation in boiling point is observed.\nReason (R): Elevation in boiling point is a colligative property.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Think about what causes boiling point elevation and what a colligative property is.","explanation":"Both statements are true. A non-volatile solute lowers vapour pressure, raising the boiling point, but merely calling it colligative does not explain the observation.","difficulty":1,"sources":[[2024,"R","56/1/2",16]]},{"id":"c0331","chapter":4,"type":"mcq","text":"The equilibrium $\\mathrm{Cr_2O_7^{2-}} \\rightleftharpoons 2\\mathrm{CrO_4^{2-}}$ :","options":{"A":"exists in basic medium","B":"exists in acidic medium","C":"exists in neutral medium","D":"does not exist"},"answer":"A","hint":"Recall how pH shifts the chromate-dichromate interconversion.","explanation":"Dichromate and chromate interconvert depending on pH; the equilibrium operates around basic medium (chromate favoured on adding OH-), as per the official key.","difficulty":1,"sources":[[2024,"R","56/1/3",1]]},{"id":"c0332","chapter":8,"type":"mcq","text":"Which of the following is the strongest acid ?","options":{"A":"$p$-Cl$-\\mathrm{C_6H_4COOH}$","B":"$p$-OH$-\\mathrm{C_6H_4COOH}$","C":"$\\mathrm{C_6H_5COOH}$","D":"$p$-$\\mathrm{NO_2}-\\mathrm{C_6H_4COOH}$"},"answer":"D","hint":"Electron-withdrawing groups stabilise the carboxylate ion.","explanation":"The strongly electron-withdrawing $-\\mathrm{NO_2}$ group stabilises the anion most, so the p-nitro acid is strongest.","difficulty":1,"sources":[[2024,"R","56/1/3",2]]},{"id":"c0333","chapter":10,"type":"mcq","text":"Maltose is made up of :","options":{"A":"glucose and fructose","B":"glucose and galactose","C":"glucose and glucose","D":"glucose and ribose"},"answer":"C","hint":"Maltose is a reducing disaccharide from starch hydrolysis.","explanation":"Maltose consists of two glucose units joined by an $\\alpha$-1,4 glycosidic linkage.","difficulty":1,"sources":[[2024,"R","56/1/3",3]]},{"id":"c0334","chapter":1,"type":"mcq","text":"The system that forms maximum boiling azeotrope is :","options":{"A":"$\\mathrm{CS_2}$ and acetone","B":"Benzene and toluene","C":"Ethanol and acetone","D":"Chloroform and acetone"},"answer":"D","hint":"Maximum boiling azeotropes arise from negative deviation (stronger A-B interactions).","explanation":"Chloroform and acetone form hydrogen bonds, giving negative deviation and a maximum boiling azeotrope.","difficulty":1,"sources":[[2024,"R","56/1/3",4]]},{"id":"c0335","chapter":3,"type":"mcq","text":"A zero-order reaction is one whose rate is independent of :","options":{"A":"Presence of light","B":"Concentration of the reactant","C":"Temperature of the reaction","D":"Pressure of the reaction"},"answer":"B","hint":"Write the rate law for order zero.","explanation":"Rate = $k[\\mathrm{A}]^0 = k$, so it does not depend on reactant concentration.","difficulty":1,"sources":[[2024,"R","56/1/3",5]]},{"id":"c0336","chapter":3,"type":"mcq","text":"In the Arrhenius equation, when $\\log k$ is plotted against $1/T$, a straight line is obtained whose :","options":{"A":"slope is $\\frac{A}{R}$ and intercept is $E_a$.","B":"slope is $A$ and intercept is $\\frac{-E_a}{R}$.","C":"slope is $\\frac{-E_a}{RT}$ and intercept is $\\log A$.","D":"slope is $\\frac{-E_a}{2.303\\,R}$ and intercept is $\\log A$."},"answer":"D","hint":"Take logarithm of $k = Ae^{-E_a/RT}$ and compare with $y = mx + c$.","explanation":"$\\log k = \\log A - \\dfrac{E_a}{2.303R}\\cdot\\dfrac1T$, so slope $= -E_a/2.303R$ and intercept $= \\log A$.","difficulty":1,"sources":[[2024,"R","56/1/3",6]]},{"id":"c0337","chapter":6,"type":"mcq","text":"Which of the following is most reactive towards nucleophilic substitution reaction ?","options":{"A":"Chlorobenzene (structure shown in figure)","B":"$\\mathrm{CH_3-CH_2-CH_2-Cl}$","C":"$\\mathrm{CH_2=CH-Cl}$","D":"$\\mathrm{CH_2=CH-CH_2-Cl}$"},"answer":"D","hint":"Allylic halides give a resonance-stabilised carbocation/transition state.","explanation":"Allyl chloride is most reactive; aryl and vinyl chlorides are inert due to partial double bond character, and propyl chloride is less reactive than allyl.","difficulty":2,"figure":"figures/c0337.png","sources":[[2024,"R","56/1/3",7],[2025,"R","56/7/3",7]]},{"id":"c0338","chapter":8,"type":"mcq","text":"The product (X) obtained in the following reaction is :\n(Reaction scheme in the figure: 4-oxocyclohexanecarbaldehyde treated with $\\mathrm{[Ag(NH_3)_2]^+OH^-}$ gives X.)","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"B","hint":"Tollens' reagent oxidises only the aldehyde group.","explanation":"The -CHO group is oxidised to the carboxylate while the ketone is untouched, so X is the keto carboxylate (B).","difficulty":2,"figure":"figures/c0338.png","sources":[[2024,"R","56/1/3",8]]},{"id":"c0339","chapter":8,"type":"mcq","text":"Which of the following has the highest boiling point ?","options":{"A":"$\\mathrm{CH_3CHO}$","B":"$\\mathrm{CH_3COCl}$","C":"$\\mathrm{CH_3COCH_3}$","D":"$\\mathrm{CH_3COOH}$"},"answer":"D","hint":"Compare intermolecular hydrogen bonding.","explanation":"Carboxylic acids form strong hydrogen-bonded dimers, giving $\\mathrm{CH_3COOH}$ the highest boiling point.","difficulty":1,"sources":[[2024,"R","56/1/3",9]]},{"id":"c0340","chapter":7,"type":"mcq","text":"Phenol does not undergo nucleophilic substitution reaction easily due to :","options":{"A":"Partial double bond character of C-OH bond","B":"Partial double bond character of C-C bond","C":"Acidic nature of phenol","D":"Instability of phenoxide ion"},"answer":"A","hint":"Think of resonance involving the lone pair on oxygen and the ring.","explanation":"Lone pair delocalisation gives the C-OH bond partial double bond character, making it hard to cleave.","difficulty":2,"sources":[[2024,"R","56/1/3",10]]},{"id":"c0341","chapter":7,"type":"mcq","text":"The suitable Grignard reagent used for the synthesis of $\\mathrm{(CH_3)_2CH-CH_2-OH}$ (2-methylpropan-1-ol) with methanal is :","options":{"A":"$\\mathrm{(CH_3)_2CH-CH_2MgBr / H_2O}$","B":"$\\mathrm{CH_3MgBr / H_2O}$","C":"$\\mathrm{(CH_3)_2CHMgBr / H_2O}$","D":"$\\mathrm{CH_3CH_2CH_2MgBr / H_2O}$"},"answer":"C","hint":"Methanal plus RMgBr gives a primary alcohol with one more carbon than R.","explanation":"$\\mathrm{HCHO} + \\mathrm{(CH_3)_2CHMgBr}$ followed by hydrolysis gives $\\mathrm{(CH_3)_2CHCH_2OH}$.","difficulty":2,"sources":[[2024,"R","56/1/3",11]]},{"id":"c0342","chapter":10,"type":"mcq","text":"All proteins on hydrolysis give :","options":{"A":"Enzymes","B":"$\\alpha$-amino acids","C":"Glucose","D":"Polypeptides"},"answer":"B","hint":"Proteins are polymers of amino acids.","explanation":"Complete hydrolysis of proteins yields $\\alpha$-amino acids.","difficulty":1,"sources":[[2024,"R","56/1/3",12]]},{"id":"c0343","chapter":8,"type":"ar","text":"Assertion (A): Fluoroacetic acid is stronger acid than chloroacetic acid.\nReason (R): This is due to greater electron withdrawing nature of F than Cl.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Inductive effect of the halogen stabilises the carboxylate.","explanation":"Both true; F has a stronger -I effect, stabilising the anion more, and so explains the acidity order.","difficulty":1,"sources":[[2024,"R","56/1/3",13]]},{"id":"c0344","chapter":9,"type":"ar","text":"Assertion (A): $p$-nitroaniline is a weaker base than $p$-toluidine.\nReason (R): The electron donating $-\\mathrm{NO_2}$ group in $p$-nitroaniline makes it a weaker base.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Is -NO2 donating or withdrawing?","explanation":"A is true, but $-\\mathrm{NO_2}$ is electron withdrawing, so R is false.","difficulty":1,"sources":[[2024,"R","56/1/3",14]]},{"id":"c0345","chapter":1,"type":"ar","text":"Assertion (A): $\\Delta_\\mathrm{mix}H$ for an ideal solution is not equal to zero.\nReason (R): A-B interactions in an ideal solution are same as between A-A and B-B interactions.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Recall the properties of an ideal solution.","explanation":"For an ideal solution $\\Delta_\\mathrm{mix}H = 0$, so A is false; R correctly describes ideal behaviour so R is true.","difficulty":1,"sources":[[2024,"R","56/1/3",15]]},{"id":"c0346","chapter":4,"type":"ar","text":"Assertion (A): Separation of Zr and Hf is difficult.\nReason (R): Zr and Hf are radioactive.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Lanthanoid contraction gives them nearly identical radii.","explanation":"A is true because of nearly identical size and properties (lanthanoid contraction); R is false as they are not radioactive.","difficulty":2,"sources":[[2024,"R","56/1/3",16]]},{"id":"c0347","chapter":4,"type":"mcq","text":"When $\\mathrm{MnO_2}$ is fused with KOH in air, it gives :","options":{"A":"$\\mathrm{KMnO_4}$","B":"$\\mathrm{K_2MnO_4}$","C":"$\\mathrm{Mn_2O_7}$","D":"$\\mathrm{Mn_2O_3}$"},"answer":"B","hint":"Fusion in air oxidises Mn(IV) to Mn(VI).","explanation":"$2\\mathrm{MnO_2} + 4\\mathrm{KOH} + \\mathrm{O_2} \\rightarrow 2\\mathrm{K_2MnO_4} + 2\\mathrm{H_2O}$.","difficulty":1,"sources":[[2024,"R","56/2/1",1]]},{"id":"c0348","chapter":5,"type":"mcq","text":"Ligand $\\mathrm{EDTA^{4-}}$ is an example of a :","options":{"A":"Monodentate ligand","B":"Didentate ligand","C":"Tridentate ligand","D":"Polydentate ligand"},"answer":"D","hint":"Count donor atoms in EDTA.","explanation":"EDTA has six donor atoms (2 N and 4 O), so it is hexadentate, i.e. polydentate.","difficulty":1,"sources":[[2024,"R","56/2/1",2]]},{"id":"c0349","chapter":5,"type":"mcq","text":"Which of the following ligand forms chelate complex ?","options":{"A":"$\\mathrm{C_2O_4^{2-}}$","B":"$\\mathrm{Cl^-}$","C":"$\\mathrm{NO_2^-}$","D":"$\\mathrm{NH_3}$"},"answer":"A","hint":"Chelation needs a ligand with more than one donor site.","explanation":"Oxalate is bidentate and forms a ring with the metal; the others are monodentate.","difficulty":1,"sources":[[2024,"R","56/2/1",3]]},{"id":"c0350","chapter":6,"type":"mcq","text":"Which of the following contains $sp^2$ hybridised carbon bonded to X ?","options":{"A":"$\\mathrm{CH_2=CH-CH_2-X}$","B":"Benzyl halide, $\\mathrm{C_6H_5CH_2-X}$ (structure shown in figure)","C":"$\\mathrm{CH_2=CH-X}$","D":"$\\mathrm{CH_3-CH_2-X}$"},"answer":"C","hint":"Look for X on a doubly bonded carbon.","explanation":"In vinyl halide the carbon carrying X is part of C=C, so it is $sp^2$ (vinylic).","difficulty":1,"figure":"figures/c0350.png","sources":[[2024,"R","56/2/1",4]]},{"id":"c0351","chapter":7,"type":"mcq","text":"Which of the following is most acidic ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"D","hint":"Compare phenols with benzyl/cyclohexyl alcohol, then check substituent effect.","explanation":"Phenols are more acidic than alcohols, and the -I effect of Cl makes p-chlorophenol the most acidic. Structures: (A) benzyl alcohol, (B) phenol, (C) cyclohexanol, (D) p-chlorophenol.","difficulty":2,"figure":"figures/c0351.png","sources":[[2024,"R","56/2/1",5],[2024,"R","56/2/3",5]]},{"id":"c0352","chapter":7,"type":"mcq","text":"Anisole reacts with HI to give :","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"Aryl-oxygen bond does not break; iodide attacks the methyl group.","explanation":"Cleavage gives phenol and $\\mathrm{CH_3I}$ because the aryl C-O bond has partial double bond character.","difficulty":2,"figure":"figures/c0352.png","sources":[[2024,"R","56/2/1",6],[2024,"R","56/2/2",6]]},{"id":"c0353","chapter":7,"type":"mcq","text":"Ethanol on heating with conc. $\\mathrm{H_2SO_4}$ at 413 K gives :","options":{"A":"$\\mathrm{C_2H_5OSO_3H}$","B":"$\\mathrm{C_2H_5-O-CH_3}$","C":"$\\mathrm{C_2H_5-O-C_2H_5}$","D":"$\\mathrm{CH_2=CH_2}$"},"answer":"C","hint":"Temperature decides ether versus alkene.","explanation":"At 413 K excess alcohol gives diethyl ether; at 443 K ethene forms.","difficulty":1,"sources":[[2024,"R","56/2/1",7]]},{"id":"c0354","chapter":1,"type":"mcq","text":"An azeotropic solution of two liquids has boiling point lower than either of them when it :","options":{"A":"is saturated","B":"shows positive deviation from Raoult's law","C":"shows negative deviation from Raoult's law","D":"shows no deviation from Raoult's law"},"answer":"B","hint":"Lower boiling point means higher vapour pressure.","explanation":"Positive deviation raises vapour pressure and gives a minimum boiling azeotrope.","difficulty":1,"sources":[[2024,"R","56/2/1",8]]},{"id":"c0355","chapter":1,"type":"mcq","text":"The relative lowering of vapour pressure of an aqueous solution containing non-volatile solute is 0.0225. The mole fraction of the non-volatile solute is :","options":{"A":"0.80","B":"0.725","C":"0.15","D":"0.0225"},"answer":"D","hint":"Raoult's law for non-volatile solute.","explanation":"$\\dfrac{p^\\circ-p}{p^\\circ} = x_\\mathrm{solute} = 0.0225$.","difficulty":1,"sources":[[2024,"R","56/2/1",9],[2024,"R","56/2/2",11],[2024,"R","56/2/3",12]]},{"id":"c0356","chapter":2,"type":"mcq","text":"During electrolysis of aqueous solution of NaCl :","options":{"A":"$\\mathrm{H_2}$ (g) is liberated at cathode","B":"Na is formed at cathode","C":"$\\mathrm{O_2}$ (g) is liberated at anode","D":"$\\mathrm{Cl_2}$ (g) is liberated at cathode"},"answer":"A","hint":"Compare reduction potentials of water and Na+.","explanation":"Water is reduced in preference to $\\mathrm{Na^+}$, so $\\mathrm{H_2}$ evolves at the cathode (and $\\mathrm{Cl_2}$ at anode).","difficulty":1,"sources":[[2024,"R","56/2/1",10]]},{"id":"c0357","chapter":3,"type":"mcq","text":"The addition of catalyst during a chemical reaction alters which of the following quantities of the reaction ?","options":{"A":"Enthalpy","B":"Activation energy","C":"Entropy","D":"Internal energy"},"answer":"B","hint":"A catalyst offers a different path.","explanation":"A catalyst lowers activation energy but leaves state functions like $\\Delta H$, $\\Delta S$ unchanged.","difficulty":1,"sources":[[2024,"R","56/2/1",11]]},{"id":"c0358","chapter":3,"type":"mcq","text":"For the elementary reaction $\\mathrm{P}\\rightarrow\\mathrm{Q}$, the rate of disappearance of 'P' increases by a factor of 8 upon doubling the concentration of 'P'. The order of the reaction with respect to 'P' is :","options":{"A":"3","B":"4","C":"2","D":"1"},"answer":"A","hint":"Use $2^n = $ rate factor.","explanation":"$2^n = 8$ gives $n = 3$.","difficulty":1,"sources":[[2024,"R","56/2/1",12]]},{"id":"c0359","chapter":9,"type":"ar","text":"Assertion (A): Aliphatic primary amines can be prepared by Gabriel phthalimide synthesis.\nReason (R): Alkyl halides undergo nucleophilic substitution with anion formed by phthalimide.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Recall the steps of Gabriel synthesis.","explanation":"Both true; phthalimide anion attacks the alkyl halide ($\\mathrm{S_N2}$) and hydrolysis releases the primary amine, so R explains A.","difficulty":1,"sources":[[2024,"R","56/2/1",13]]},{"id":"c0360","chapter":10,"type":"ar","text":"Assertion (A): Uracil base is present in DNA.\nReason (R): DNA undergoes self-replication.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which base replaces uracil in DNA?","explanation":"A is false (uracil occurs in RNA, thymine in DNA); R is true.","difficulty":1,"sources":[[2024,"R","56/2/1",14]]},{"id":"c0361","chapter":9,"type":"ar","text":"Assertion (A): Diazonium salts of aromatic amines are more stable than those of aliphatic amines.\nReason (R): Diazonium salts of aliphatic amines show resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Which diazonium salt is resonance stabilised?","explanation":"A is true because of resonance in arenediazonium ions; R is false as aliphatic ones do not show resonance.","difficulty":1,"sources":[[2024,"R","56/2/1",15],[2026,"R","56/4/1",14]]},{"id":"c0362","chapter":4,"type":"mcq","text":"The product of oxidation of $\\mathrm{SO_3^{2-}}$ with $\\mathrm{MnO_4^-}$ in acidic medium is :","options":{"A":"$\\mathrm{SO_2}$","B":"$\\mathrm{SO_4^{2-}}$","C":"$\\mathrm{S^{2-}}$","D":"$\\mathrm{S_2O_3^{2-}}$"},"answer":"B","hint":"Sulphite is oxidised to its higher oxidation state.","explanation":"Permanganate oxidises sulphite (S +4) to sulphate (S +6).","difficulty":1,"sources":[[2024,"R","56/2/2",1]]},{"id":"c0363","chapter":5,"type":"mcq","text":"The coordination number of Co in $\\mathrm{[Co(en)_3]^{3+}}$ is :","options":{"A":"3","B":"4","C":"5","D":"6"},"answer":"D","hint":"en is bidentate.","explanation":"Three bidentate en ligands give $3\\times2 = 6$.","difficulty":1,"sources":[[2024,"R","56/2/2",2],[2025,"R","56/6/2",3]]},{"id":"c0364","chapter":5,"type":"mcq","text":"Which one of the following complexes is non-ionisable ?","options":{"A":"$\\mathrm{[Co(NH_3)_3Cl_3]}$","B":"$\\mathrm{[Co(NH_3)_4Cl_2]Cl}$","C":"$\\mathrm{[Co(NH_3)_5Cl]Cl_2}$","D":"$\\mathrm{[Co(NH_3)_6]Cl_3}$"},"answer":"A","hint":"Look for no counter-ions outside the brackets.","explanation":"All three Cl- are inside the coordination sphere in $\\mathrm{[Co(NH_3)_3Cl_3]}$, so it gives no ions.","difficulty":1,"sources":[[2024,"R","56/2/2",3]]},{"id":"c0365","chapter":6,"type":"mcq","text":"Which of the following is a benzylic halide ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"C","hint":"Benzylic means halogen on a carbon directly attached to the benzene ring.","explanation":"In (C) the carbon bonded to X is directly attached to the ring. Structures: (A) 2-phenylethyl halide, (B) o-halotoluene, (C) 2-halo-2-phenylpropane, (D) 2-halo-1-phenylpropane.","difficulty":2,"figure":"figures/c0365.png","sources":[[2024,"R","56/2/2",4]]},{"id":"c0366","chapter":7,"type":"mcq","text":"Phenol is less acidic than :","options":{"A":"ethanol","B":"$o$-nitrophenol","C":"$o$-methoxyphenol","D":"$o$-methylphenol"},"answer":"B","hint":"Electron-withdrawing groups increase acidity.","explanation":"The -NO2 group stabilises the phenoxide ion, so o-nitrophenol is more acidic than phenol.","difficulty":1,"sources":[[2024,"R","56/2/2",5]]},{"id":"c0367","chapter":8,"type":"mcq","text":"Aspirin is formed by the acetylation of :","options":{"A":"Benzoic acid","B":"Phenol","C":"Salicylic acid","D":"Phthalic acid"},"answer":"C","hint":"Aspirin is acetylsalicylic acid.","explanation":"Acetylation of the -OH group of salicylic acid gives aspirin.","difficulty":1,"sources":[[2024,"R","56/2/2",7]]},{"id":"c0368","chapter":1,"type":"mcq","text":"An azeotropic solution of two liquids has boiling point higher than either of them when it :","options":{"A":"is saturated","B":"shows positive deviation from Raoult's law","C":"shows negative deviation from Raoult's law","D":"shows no deviation from Raoult's law"},"answer":"C","hint":"Higher boiling point means lower vapour pressure.","explanation":"Negative deviation lowers vapour pressure, giving a maximum boiling azeotrope.","difficulty":1,"sources":[[2024,"R","56/2/2",8]]},{"id":"c0369","chapter":2,"type":"mcq","text":"During electrolysis of aqueous $\\mathrm{CuCl_2}$ :","options":{"A":"$\\mathrm{H_2}$ (g) is liberated at cathode","B":"Cu is formed at cathode","C":"$\\mathrm{O_2}$ (g) is liberated at anode","D":"$\\mathrm{Cl_2}$ (g) is liberated at cathode"},"answer":"B","hint":"Compare reduction potentials of Cu2+ and water.","explanation":"$\\mathrm{Cu^{2+}}$ is reduced more easily than water, so Cu deposits at the cathode.","difficulty":1,"sources":[[2024,"R","56/2/2",9]]},{"id":"c0370","chapter":3,"type":"mcq","text":"Half-life period of a first order reaction is 1386 seconds. The rate constant (k) of the reaction is :","options":{"A":"$0.5\\times10^{-3}\\ \\mathrm{s^{-1}}$","B":"$5.0\\times10^{-3}\\ \\mathrm{s^{-1}}$","C":"$5\\times10^{-2}\\ \\mathrm{s^{-1}}$","D":"$0.5\\times10^{-2}\\ \\mathrm{s^{-1}}$"},"answer":"A","hint":"$k = 0.693/t_{1/2}$.","explanation":"$k = 0.693/1386 = 5\\times10^{-4} = 0.5\\times10^{-3}\\ \\mathrm{s^{-1}}$.","difficulty":1,"sources":[[2024,"R","56/2/2",10]]},{"id":"c0371","chapter":3,"type":"mcq","text":"The rate of the reaction $\\mathrm{2A + B_2 \\rightarrow 2AB}$ is given by Rate $= k[\\mathrm{A}]^2[\\mathrm{B_2}]$. The value of rate constant (k) can be increased by :","options":{"A":"increasing the concentration of A","B":"increasing the concentration of B","C":"increasing the temperature","D":"all the above three"},"answer":"C","hint":"What does k depend on?","explanation":"$k$ depends only on temperature (and catalyst), not on concentrations.","difficulty":1,"sources":[[2024,"R","56/2/2",12]]},{"id":"c0372","chapter":4,"type":"mcq","text":"The correct order for the increasing oxidizing power in 3d series of transition elements is :","options":{"A":"$\\mathrm{MnO_4^-} < \\mathrm{Cr_2O_7^{2-}} < \\mathrm{VO_2^+}$","B":"$\\mathrm{Cr_2O_7^{2-}} < \\mathrm{VO_2^+} < \\mathrm{MnO_4^-}$","C":"$\\mathrm{VO_2^+} < \\mathrm{Cr_2O_7^{2-}} < \\mathrm{MnO_4^-}$","D":"$\\mathrm{VO_2^+} < \\mathrm{MnO_4^-} < \\mathrm{Cr_2O_7^{2-}}$"},"answer":"C","hint":"Compare the standard reduction potentials of the three oxoanions.","explanation":"The oxidising power increases V < Cr < Mn as the stability of the highest oxidation state decreases.","difficulty":2,"sources":[[2024,"R","56/2/3",1]]},{"id":"c0373","chapter":5,"type":"mcq","text":"The type of isomerism shown by the complex $\\mathrm{[CoCl_2(en)_2]^+}$ is :","options":{"A":"Linkage isomerism","B":"Geometrical isomerism","C":"Coordination isomerism","D":"Ionization isomerism"},"answer":"B","hint":"Octahedral $\\mathrm{[M(AA)_2X_2]}$ type.","explanation":"The complex has cis and trans forms, so it shows geometrical isomerism (cis is also optically active).","difficulty":2,"sources":[[2024,"R","56/2/3",2],[2024,"R","56/3/1",2]]},{"id":"c0374","chapter":5,"type":"mcq","text":"Which one of the following hybrid states is associated with low spin complex ?","options":{"A":"$sp^3d$","B":"$sp^3$","C":"$sp^3d^2$","D":"$d^2sp^3$"},"answer":"D","hint":"Low spin uses inner d orbitals.","explanation":"Inner orbital complex with strong field ligands involves $d^2sp^3$ hybridisation.","difficulty":1,"sources":[[2024,"R","56/2/3",3]]},{"id":"c0375","chapter":6,"type":"mcq","text":"Butanenitrile may be prepared by heating :","options":{"A":"propyl chloride with KCN","B":"butyl chloride with KCN","C":"propyl alcohol with KCN","D":"butyl alcohol with KCN"},"answer":"A","hint":"The CN carbon adds to the carbon chain.","explanation":"KCN replaces Cl in propyl chloride, giving $\\mathrm{CH_3CH_2CH_2CN}$ (four carbons).","difficulty":1,"sources":[[2024,"R","56/2/3",4]]},{"id":"c0376","chapter":7,"type":"mcq","text":"$\\mathrm{(CH_3)_2CH-O-CH_3}$ reacts with HI to give :","options":{"A":"$\\mathrm{(CH_3)_2CH-OH + CH_3-OH}$","B":"$\\mathrm{(CH_3)_2CH-OH + CH_3-I}$","C":"$\\mathrm{(CH_3)_2CH-I + CH_3-OH}$","D":"$\\mathrm{(CH_3)_2CH-I + CH_3-I}$"},"answer":"B","hint":"For ethers with a secondary alkyl group and a methyl, iodide attacks the less hindered group ($\\mathrm{S_N2}$).","explanation":"I- attacks the methyl group, giving $\\mathrm{CH_3I}$ and isopropyl alcohol.","difficulty":2,"sources":[[2024,"R","56/2/3",6]]},{"id":"c0377","chapter":7,"type":"mcq","text":"A compound (X) with the molecular formula $\\mathrm{C_3H_8O}$ can be oxidized by strong oxidizing agents to another compound (Y) whose molecular formula is $\\mathrm{C_3H_6O_2}$. The compound (X) is :","options":{"A":"$\\mathrm{CH_3-CH_2-O-CH_3}$","B":"$\\mathrm{CH_3-CH(OH)-CH_3}$","C":"$\\mathrm{CH_3-CH_2-CH_2-OH}$","D":"None of the above"},"answer":"C","hint":"Only a primary alcohol gives an acid with the same carbon count.","explanation":"Propan-1-ol is oxidised to propanoic acid, $\\mathrm{C_3H_6O_2}$.","difficulty":1,"sources":[[2024,"R","56/2/3",7]]},{"id":"c0378","chapter":1,"type":"mcq","text":"On mixing 10 mL of acetone with 50 mL of chloroform, the total volume of the solution will be :","options":{"A":"< 60 mL","B":"> 60 mL","C":"= 60 mL","D":"= 100 mL"},"answer":"A","hint":"Acetone-chloroform shows negative deviation.","explanation":"Stronger A-B interactions give negative deviation and volume contraction, so the total is less than 60 mL.","difficulty":2,"sources":[[2024,"R","56/2/3",8]]},{"id":"c0379","chapter":2,"type":"mcq","text":"The unit of cell constant is :","options":{"A":"$\\mathrm{ohm\\,cm^{-1}}$","B":"$\\mathrm{ohm^{-1}}$","C":"$\\mathrm{cm^{-1}}$","D":"$\\mathrm{ohm^{-1}\\,cm^{2}\\,mol^{-1}}$"},"answer":"C","hint":"Cell constant $= l/A$.","explanation":"Cell constant is length divided by area, i.e. $\\mathrm{cm^{-1}}$.","difficulty":1,"sources":[[2024,"R","56/2/3",9]]},{"id":"c0380","chapter":3,"type":"mcq","text":"For a certain reaction $\\mathrm{R}\\rightarrow$ products, a plot of $\\log[\\mathrm{R}]$ vs. time gives a straight line with a slope of $-1.25\\ \\mathrm{s^{-1}}$. The order of the reaction is :","options":{"A":"One","B":"Zero","C":"Two","D":"Fractional"},"answer":"A","hint":"Which integrated rate law is linear in log of concentration?","explanation":"A linear $\\log[\\mathrm{R}]$ versus $t$ plot is the signature of a first order reaction.","difficulty":1,"sources":[[2024,"R","56/2/3",10]]},{"id":"c0381","chapter":3,"type":"mcq","text":"For a zero order reaction $\\mathrm{A}\\rightarrow$ products, $t_{1/2}$ is :  (where $[\\mathrm{A}]_0$ = initial concentration of the reactant, $k$ = rate constant.)","options":{"A":"$\\dfrac{[\\mathrm{A}]_0}{k}$","B":"$\\dfrac{2.303\\,\\log 2}{k}$","C":"$\\dfrac{1}{k[\\mathrm{A}]_0}$","D":"$\\dfrac{[\\mathrm{A}]_0}{2k}$"},"answer":"D","hint":"Set $[\\mathrm{A}] = [\\mathrm{A}]_0/2$ in $[\\mathrm{A}]_0 - [\\mathrm{A}] = kt$.","explanation":"$t_{1/2} = [\\mathrm{A}]_0/2k$.","difficulty":1,"sources":[[2024,"R","56/2/3",11]]},{"id":"c0382","chapter":10,"type":"ar","text":"Assertion (A): Vitamin C cannot be stored in our body.\nReason (R): Vitamin C is water soluble and readily excreted in urine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Water-soluble vitamins are not stored.","explanation":"Both true; being water soluble, vitamin C is excreted and not stored, which explains A.","difficulty":1,"sources":[[2024,"R","56/2/3",14]]},{"id":"c0383","chapter":9,"type":"ar","text":"Assertion (A): Ammonolysis of alkyl halides involves reaction between alkyl halide and ethanolic solution of ammonia.\nReason (R): Ammonolysis of alkyl halides mainly produces secondary amines.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Ammonolysis gives a mixture; which amine is the main product with excess NH3?","explanation":"A is true; R is false since the reaction gives a mixture of amines (primary favoured with excess NH3), not mainly secondary.","difficulty":2,"sources":[[2024,"R","56/2/3",15]]},{"id":"c0384","chapter":9,"type":"ar","text":"Assertion (A): Aniline does not undergo Friedel-Crafts reaction.\nReason (R): Friedel-Crafts reaction is a nucleophilic substitution reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Aniline forms a salt with the Lewis acid catalyst; what type of substitution is Friedel-Crafts?","explanation":"A is true because $-\\mathrm{NH_2}$ reacts with $\\mathrm{AlCl_3}$; R is false as Friedel-Crafts is electrophilic substitution.","difficulty":1,"sources":[[2024,"R","56/2/3",16]]},{"id":"c0385","chapter":4,"type":"mcq","text":"Which of the following does not show variable oxidation states ?","options":{"A":"Fe","B":"Cu","C":"Mn","D":"Sc"},"answer":"D","hint":"Check the number of unpaired d/s electrons available.","explanation":"Sc shows only the +3 state, while Fe, Cu and Mn have variable oxidation states.","difficulty":1,"sources":[[2024,"R","56/3/1",1]]},{"id":"c0386","chapter":5,"type":"mcq","text":"Which of the following is diamagnetic in nature ?  [Atomic number: Co = 27]","options":{"A":"$\\mathrm{Co^{3+}}$, octahedral complex with strong field ligand","B":"$\\mathrm{Co^{3+}}$, octahedral complex with weak field ligand","C":"$\\mathrm{Co^{3+}}$, in a square planar complex","D":"$\\mathrm{Co^{3+}}$, in a tetrahedral complex"},"answer":"A","hint":"$\\mathrm{Co^{3+}}$ is $d^6$; check pairing in strong field.","explanation":"With strong field ligands $d^6$ pairs fully as $t_{2g}^6$, giving a diamagnetic complex.","difficulty":2,"sources":[[2024,"R","56/3/1",3]]},{"id":"c0387","chapter":6,"type":"mcq","text":"Consider the reaction: 4-chlorobenzyl chloride ($p$-$\\mathrm{Cl-C_6H_4-CH_2-Cl}$) reacts with KCN. The major product of the reaction is :","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"C","hint":"Which C-Cl bond is reactive towards nucleophilic substitution?","explanation":"The benzylic Cl is substituted by CN- (C attack), while the aryl Cl is inert. Structures: (A) p-isocyano, benzyl-CN; (B) p-isocyano, benzyl-Cl; (C) p-chlorobenzyl cyanide; (D) ring-substituted cyano compound.","difficulty":2,"figure":"figures/c0387.png","sources":[[2024,"R","56/3/1",4]]},{"id":"c0388","chapter":7,"type":"mcq","text":"Which one of the following compounds has the lowest $\\mathrm{pK_a}$ value?","options":{"A":"$p$-Cresol","B":"$p$-Nitrophenol","C":"$m$-Nitrophenol","D":"2,4,6-Trinitrophenol"},"answer":"D","hint":"Lowest pKa means strongest acid.","explanation":"Three $\\mathrm{-NO_2}$ groups at o,o,p positions stabilise the phenoxide most, so 2,4,6-trinitrophenol is the strongest acid (picric acid).","difficulty":1,"sources":[[2024,"R","56/3/1",5]]},{"id":"c0389","chapter":7,"type":"mcq","text":"$\\mathrm{(CH_3)_2CH-O-CH_3}$ when treated with HI gives:","options":{"A":"$\\mathrm{(CH_3)_2CH-I + CH_3OH}$","B":"$\\mathrm{(CH_3)_2CH-OH + CH_3-I}$","C":"$\\mathrm{(CH_3)_2CH-I + CH_3-I}$","D":"$\\mathrm{(CH_3)_2CH-OH + CH_3OH}$"},"answer":"B","hint":"Iodide attacks the less hindered alkyl group in an $S_N2$ cleavage (with 1 equivalent HI, cold).","explanation":"With secondary and methyl groups, $\\mathrm{I^-}$ attacks the methyl carbon ($S_N2$), giving $\\mathrm{CH_3I}$ and isopropyl alcohol.","difficulty":2,"sources":[[2024,"R","56/3/1",6],[2024,"R","56/3/2",6]]},{"id":"c0390","chapter":9,"type":"mcq","text":"Which of the following compounds on treatment with benzene sulphonyl chloride forms an alkali-soluble precipitate?","options":{"A":"$\\mathrm{CH_3CONH_2}$","B":"$\\mathrm{(CH_3)_3N}$","C":"$\\mathrm{(CH_3)_2NH}$","D":"$\\mathrm{CH_3CH_2NH_2}$"},"answer":"D","hint":"Hinsberg test: which sulphonamide still has an acidic N-H?","explanation":"Primary amines give sulphonamides with an acidic N-H that dissolve in alkali; secondary amine products are insoluble.","difficulty":1,"sources":[[2024,"R","56/3/1",7]]},{"id":"c0391","chapter":9,"type":"mcq","text":"The order of increasing basicities of $\\mathrm{CH_3NH_2}$ (I), $\\mathrm{(CH_3)_2NH}$ (II), $\\mathrm{(CH_3)_3N}$ (III) and $\\mathrm{C_6H_5NH_2}$ (IV) in aqueous media is:","options":{"A":"IV < III < I < II","B":"II < I < IV < III","C":"I < II < III < IV","D":"II < III < I < IV"},"answer":"A","hint":"Combine +I effect, solvation and aromatic delocalisation.","explanation":"Aniline is weakest; in water the order for methylamines is $\\mathrm{(CH_3)_2NH > CH_3NH_2 > (CH_3)_3N}$, so IV < III < I < II.","difficulty":2,"sources":[[2024,"R","56/3/1",8]]},{"id":"c0392","chapter":10,"type":"mcq","text":"The vitamin which plays an important role in coagulating blood is:","options":{"A":"Vitamin A","B":"Vitamin E","C":"Vitamin D","D":"Vitamin K"},"answer":"D","hint":"Think of the clotting vitamin.","explanation":"Vitamin K is needed for synthesis of blood-clotting factors.","difficulty":1,"sources":[[2024,"R","56/3/1",9]]},{"id":"c0393","chapter":1,"type":"mcq","text":"A 1% solution of solute 'X' is isotonic with a 6% solution of sucrose (molar mass = $342\\ \\mathrm{g\\,mol^{-1}}$). The molar mass of solute 'X' is:","options":{"A":"$34.2\\ \\mathrm{g\\,mol^{-1}}$","B":"$57\\ \\mathrm{g\\,mol^{-1}}$","C":"$114\\ \\mathrm{g\\,mol^{-1}}$","D":"$3.42\\ \\mathrm{g\\,mol^{-1}}$"},"answer":"B","hint":"Isotonic solutions have equal molar concentration.","explanation":"$1/M = 6/342$, so $M = 57\\ \\mathrm{g\\,mol^{-1}}$.","difficulty":2,"sources":[[2024,"R","56/3/1",11],[2024,"R","56/3/2",10],[2024,"R","56/3/3",9]]},{"id":"c0394","chapter":2,"type":"mcq","text":"During the electrolysis of aqueous NaCl, the cathodic reaction is:","options":{"A":"Oxidation of $\\mathrm{Cl^-}$ ion","B":"Reduction of $\\mathrm{Na^+}$ ion","C":"Oxidation of $\\mathrm{H_2O}$","D":"Reduction of $\\mathrm{H_2O}$"},"answer":"D","hint":"Cathode is the site of reduction; compare reduction potentials of $\\mathrm{Na^+}$ and water.","explanation":"Water is reduced more easily than $\\mathrm{Na^+}$, giving $\\mathrm{H_2}$ and $\\mathrm{OH^-}$ at the cathode.","difficulty":1,"sources":[[2024,"R","56/3/1",12]]},{"id":"c0395","chapter":1,"type":"ar","text":"Assertion (A): Addition of ethylene glycol to water lowers its freezing point.\nReason (R): Ethylene glycol is insoluble in water due to lack of its ability to form hydrogen bonds with water molecules.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Is ethylene glycol miscible with water?","explanation":"A is true (depression of freezing point, antifreeze), but R is false since it is fully miscible through H-bonding.","difficulty":1,"sources":[[2024,"R","56/3/1",13]]},{"id":"c0396","chapter":3,"type":"ar","text":"Assertion (A): Order of reaction and molecularity are always same for complex reactions.\nReason (R): Order is determined experimentally and molecularity is applicable only for elementary reactions.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which quantity is experimental, which theoretical?","explanation":"A is false (order may differ from molecularity, and complex reactions have no single molecularity); R is true.","difficulty":2,"sources":[[2024,"R","56/3/1",14]]},{"id":"c0397","chapter":7,"type":"ar","text":"Assertion (A): The boiling point of ethanol is higher than that of dimethyl ether.\nReason (R): Ethanol molecules are associated through hydrogen bonding whereas in dimethyl ether, it is not possible.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Compare intermolecular hydrogen bonding.","explanation":"Both true; H-bonding in ethanol raises its boiling point, so R explains A.","difficulty":1,"sources":[[2024,"R","56/3/1",15]]},{"id":"c0398","chapter":5,"type":"mcq","text":"Which of the following ligands can show linkage isomerism in a coordination compound?","options":{"A":"$\\mathrm{NH_3}$","B":"$\\mathrm{SO_4^{2-}}$","C":"$\\mathrm{NO_2^-}$","D":"$\\mathrm{C_2O_4^{2-}}$"},"answer":"C","hint":"Look for an ambidentate ligand.","explanation":"$\\mathrm{NO_2^-}$ can bind through N (nitro) or O (nitrito), giving linkage isomers.","difficulty":1,"sources":[[2024,"R","56/3/2",1]]},{"id":"c0399","chapter":5,"type":"mcq","text":"On adding $\\mathrm{AgNO_3}$ solution to 1 mole of complex $\\mathrm{NiCl_2\\cdot 4NH_3}$, two moles of AgCl are formed. The secondary valency of Ni in the complex will be:","options":{"A":"4","B":"2","C":"3","D":"6"},"answer":"A","hint":"Both chlorides are ionisable; count the ligands inside the sphere.","explanation":"Two Cl precipitate, so the complex is $\\mathrm{[Ni(NH_3)_4]Cl_2}$ with coordination number 4.","difficulty":1,"sources":[[2024,"R","56/3/2",2]]},{"id":"c0400","chapter":4,"type":"mcq","text":"Transition elements form alloys easily because they have:","options":{"A":"same electronic configuration","B":"same enthalpies of atomisation","C":"same oxidation states","D":"nearly the same atomic size"},"answer":"D","hint":"Alloys form by substitution of atoms in the lattice.","explanation":"Similar atomic radii let transition metal atoms replace each other in the crystal lattice.","difficulty":1,"sources":[[2024,"R","56/3/2",3]]},{"id":"c0401","chapter":9,"type":"mcq","text":"Which of the following compounds on treatment with benzene sulphonyl chloride forms product insoluble in alkali?","options":{"A":"$\\mathrm{(CH_3)_3N}$","B":"$\\mathrm{(CH_3)_2NH}$","C":"$\\mathrm{CH_3CH_2NH_2}$","D":"$\\mathrm{C_6H_5NH_2}$"},"answer":"B","hint":"Hinsberg test: secondary amine sulphonamide has no N-H.","explanation":"A secondary amine gives $\\mathrm{N,N}$-dialkylsulphonamide with no acidic H, insoluble in alkali; tertiary amines do not react.","difficulty":2,"sources":[[2024,"R","56/3/2",7]]},{"id":"c0402","chapter":9,"type":"mcq","text":"Which of the following amines gives carbylamine reaction?","options":{"A":"$\\mathrm{C_2H_5NH_2}$","B":"$\\mathrm{(C_2H_5)_2NH}$","C":"$\\mathrm{(C_2H_5)_3N}$","D":"$\\mathrm{C_6H_5-NH-CH_3}$"},"answer":"A","hint":"Only one class of amines gives the isocyanide test.","explanation":"Carbylamine test with $\\mathrm{CHCl_3}$/KOH is given only by primary amines.","difficulty":1,"sources":[[2024,"R","56/3/2",8]]},{"id":"c0403","chapter":10,"type":"mcq","text":"'Night-Blindness' is caused by the deficiency of Vitamin:","options":{"A":"B","B":"C","C":"K","D":"A"},"answer":"D","hint":"Vitamin needed for vision.","explanation":"Deficiency of vitamin A causes night blindness.","difficulty":1,"sources":[[2024,"R","56/3/2",9]]},{"id":"c0404","chapter":3,"type":"mcq","text":"When the initial concentration of a reactant is doubled in the reaction, the half life period remains same. The order of reaction is:","options":{"A":"First","B":"Second","C":"Zero","D":"$\\frac{1}{2}$"},"answer":"A","hint":"Which order has concentration-independent half-life?","explanation":"For first order, $t_{1/2} = 0.693/k$ is independent of initial concentration.","difficulty":1,"sources":[[2024,"R","56/3/2",11]]},{"id":"c0405","chapter":2,"type":"mcq","text":"Which of the following is a secondary cell?","options":{"A":"Dry cell","B":"Lead storage cell","C":"Mercury cell","D":"Daniell cell"},"answer":"B","hint":"Secondary cells are rechargeable.","explanation":"The lead storage cell can be recharged; the others are primary cells.","difficulty":1,"sources":[[2024,"R","56/3/2",12]]},{"id":"c0406","chapter":1,"type":"ar","text":"Assertion (A): $\\Delta_\\mathrm{mix}H$ and $\\Delta_\\mathrm{mix}V$ are zero for non-ideal solutions.\nReason (R): Solute-solvent interactions are not same as pure solute-solute and pure solvent-solvent interactions in non-ideal solutions.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which solutions have zero enthalpy and volume change on mixing?","explanation":"A is false (they are zero for ideal solutions), R is true.","difficulty":1,"sources":[[2024,"R","56/3/2",13]]},{"id":"c0407","chapter":3,"type":"ar","text":"Assertion (A): Rate of reaction increases with increase in temperature.\nReason (R): Number of effective collisions increase with increase in temperature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Collision theory.","explanation":"Both true; more molecules exceed threshold energy, so more effective collisions explain the faster rate.","difficulty":1,"sources":[[2024,"R","56/3/2",14]]},{"id":"c0408","chapter":9,"type":"ar","text":"Assertion (A): Aniline undergoes Friedel-Crafts reaction.\nReason (R): Aniline forms salt with $\\mathrm{AlCl_3}$, the Lewis acid in Friedel-Crafts reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"What does the basic amino group do to the Lewis acid catalyst?","explanation":"A is false because the lone pair on N bonds to $\\mathrm{AlCl_3}$, deactivating the ring; R is true.","difficulty":2,"sources":[[2024,"R","56/3/2",16]]},{"id":"c0409","chapter":5,"type":"mcq","text":"Which of the following ligands is an ambidentate ligand?","options":{"A":"CO","B":"$\\mathrm{SCN^-}$","C":"$\\mathrm{NH_3}$","D":"$\\mathrm{H_2O}$"},"answer":"B","hint":"Look for a ligand with two different donor atoms that can bind one at a time.","explanation":"$\\mathrm{SCN^-}$ can bind through S or N.","difficulty":1,"sources":[[2024,"R","56/3/3",1]]},{"id":"c0410","chapter":5,"type":"mcq","text":"On adding $\\mathrm{AgNO_3}$ solution to 1 mole of $\\mathrm{CoCl_3\\cdot 4NH_3}$, one mole of AgCl is precipitated. The secondary valency of Co is:","options":{"A":"6","B":"4","C":"3","D":"7"},"answer":"A","hint":"One Cl is ionisable; count the rest inside the sphere.","explanation":"Complex is $\\mathrm{[Co(NH_3)_4Cl_2]Cl}$: 4 $\\mathrm{NH_3}$ + 2 Cl = coordination number 6.","difficulty":2,"sources":[[2024,"R","56/3/3",2]]},{"id":"c0411","chapter":4,"type":"mcq","text":"Which of the following elements of 3d series of transition elements has the lowest $\\Delta_\\mathrm{a}H^\\circ$?","options":{"A":"Sc","B":"Cr","C":"Cu","D":"Zn"},"answer":"D","hint":"Fewer unpaired d electrons means weaker metallic bonding.","explanation":"Zn has a filled $3d^{10}$ with no unpaired d electrons, so the weakest metallic bonding and the lowest enthalpy of atomisation.","difficulty":1,"sources":[[2024,"R","56/3/3",3]]},{"id":"c0412","chapter":7,"type":"mcq","text":"Which of the following Grignard reagent will be used with methanal to prepare cyclohexylmethanol (a saturated six-membered ring bearing a $\\mathrm{CH_2OH}$ group)?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"D","hint":"HCHO adds one carbon to the Grignard carbon.","explanation":"Cyclohexyl magnesium bromide plus HCHO then hydrolysis gives ring-$\\mathrm{CH_2OH}$.","difficulty":2,"figure":"figures/c0412.png","sources":[[2024,"R","56/3/3",5]]},{"id":"c0413","chapter":9,"type":"mcq","text":"Which of the following compounds will not react with benzene sulphonyl chloride?","options":{"A":"$\\mathrm{(C_2H_5)_3N}$","B":"$\\mathrm{C_2H_5-NH_2}$","C":"$\\mathrm{(C_2H_5)_2NH}$","D":"$\\mathrm{C_6H_5-NH_2}$"},"answer":"A","hint":"Which amine has no N-H?","explanation":"Tertiary amines have no N-H hydrogen, so they do not form a sulphonamide.","difficulty":1,"sources":[[2024,"R","56/3/3",7]]},{"id":"c0414","chapter":10,"type":"mcq","text":"'Scurvy' is caused by the deficiency of vitamin:","options":{"A":"E","B":"A","C":"C","D":"D"},"answer":"C","hint":"Ascorbic acid.","explanation":"Vitamin C deficiency causes scurvy.","difficulty":1,"sources":[[2024,"R","56/3/3",8]]},{"id":"c0415","chapter":3,"type":"mcq","text":"The half life of a first order reaction with rate constant (k) of $3\\ \\mathrm{min^{-1}}$ is:","options":{"A":"$0.693\\ \\mathrm{min}$","B":"$2.31\\ \\mathrm{min}$","C":"$6.93\\ \\mathrm{min}$","D":"$0.231\\ \\mathrm{min}$"},"answer":"D","hint":"$t_{1/2} = 0.693/k$.","explanation":"$t_{1/2} = 0.693/3 = 0.231\\ \\mathrm{min}$.","difficulty":1,"sources":[[2024,"R","56/3/3",10]]},{"id":"c0416","chapter":2,"type":"mcq","text":"Which of the following cells is used in hearing aids?","options":{"A":"Dry cell","B":"Mercury cell","C":"Nickel-cadmium cell","D":"Fuel cell"},"answer":"B","hint":"Small cell with constant voltage.","explanation":"The mercury cell is used in hearing aids, watches and cameras.","difficulty":1,"sources":[[2024,"R","56/3/3",11]]},{"id":"c0417","chapter":9,"type":"mcq","text":"Aniline on reaction with Bromine water gives:","options":{"A":"$o$-bromoaniline","B":"2,4,6-tribromoaniline","C":"$m$-bromoaniline","D":"$p$-bromoaniline"},"answer":"B","hint":"The amino group group strongly activates the ring.","explanation":"Strong activation gives substitution at all o and p positions: 2,4,6-tribromoaniline white precipitate.","difficulty":1,"sources":[[2024,"R","56/3/3",12]]},{"id":"c0418","chapter":1,"type":"ar","text":"Assertion (A): $\\Delta_\\mathrm{mix}H$ and $\\Delta_\\mathrm{mix}V$ are zero for an ideal solution.\nReason (R): The solution which obeys Raoult's law over the entire range of concentration is called an ideal solution.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Is R the definition or the reason for zero mixing effects?","explanation":"Both true, but R only defines an ideal solution; zero $\\Delta H$ and $\\Delta V$ come from equal intermolecular interactions.","difficulty":2,"sources":[[2024,"R","56/3/3",13]]},{"id":"c0419","chapter":7,"type":"ar","text":"Assertion (A): Phenol on reaction with aqueous NaOH gives sodium phenoxide.\nReason (R): This reaction supports the acidic nature of phenol.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Acid reacts with base to form salt.","explanation":"Both true; phenol neutralises NaOH, which shows it is acidic.","difficulty":1,"sources":[[2024,"R","56/3/3",15]]},{"id":"c0420","chapter":7,"type":"ar","text":"Assertion (A): Boiling point of butan-1-ol is higher than that of butan-1-amine.\nReason (R): Being more polar, butan-1-ol forms stronger intermolecular hydrogen bonds as compared to butan-1-amine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"O is more electronegative than N.","explanation":"Both true; O-H hydrogen bonds are stronger than N-H, which explains the higher boiling point.","difficulty":2,"sources":[[2024,"R","56/3/3",16]]},{"id":"c0421","chapter":2,"type":"mcq","text":"The molar ionic conductivities of $\\mathrm{Ca^{2+}}$ and $\\mathrm{Cl^-}$ are 119.0 and 76.3 $\\mathrm{S\\,cm^2\\,mol^{-1}}$ respectively. The value of limiting molar conductivity of $\\mathrm{CaCl_2}$ will be:","options":{"A":"$195.3\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","B":"$43.3\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","C":"$314.3\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","D":"$271.6\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$"},"answer":"D","hint":"Kohlrausch's law: add ionic conductivities with stoichiometric coefficients.","explanation":"$\\Lambda_m^\\circ = 119.0 + 2(76.3) = 271.6\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$.","difficulty":1,"sources":[[2024,"R","56/4/1",1]]},{"id":"c0422","chapter":8,"type":"mcq","text":"Consider the following reaction: $\\mathrm{HCHO + HCHO + conc.\\ KOH \\xrightarrow{\\Delta} A + B}$\nIdentify A and B from the given options:","options":{"A":"A - Methanol, B - Potassium formate","B":"A - Ethanol, B - Potassium formate","C":"A - Methanal, B - Ethanol","D":"A - Methanol, B - Potassium acetate"},"answer":"A","hint":"Aldehyde without alpha-hydrogen in conc. alkali.","explanation":"Cannizzaro reaction: one HCHO is reduced to methanol, the other oxidised to potassium formate.","difficulty":1,"sources":[[2024,"R","56/4/1",2],[2024,"R","56/4/2",6]]},{"id":"c0423","chapter":10,"type":"mcq","text":"Which of the following acids represents Vitamin C?","options":{"A":"Saccharic acid","B":"Gluconic acid","C":"Ascorbic acid","D":"Benzoic acid"},"answer":"C","hint":"Chemical name of vitamin C.","explanation":"Vitamin C is ascorbic acid.","difficulty":1,"sources":[[2024,"R","56/4/1",3],[2024,"R","56/4/2",4],[2024,"R","56/4/3",2]]},{"id":"c0424","chapter":8,"type":"mcq","text":"Rosenmund reduction is used for the preparation of Aldehydes. The catalyst used in this reaction is:","options":{"A":"$\\mathrm{Pd-BaSO_4}$","B":"Anhydrous $\\mathrm{AlCl_3}$","C":"Iron (III) oxide","D":"$\\mathrm{HgSO_4}$"},"answer":"A","hint":"Poisoned catalyst prevents over-reduction.","explanation":"Acyl chloride is hydrogenated over $\\mathrm{Pd-BaSO_4}$ to give the aldehyde.","difficulty":1,"sources":[[2024,"R","56/4/1",4],[2024,"R","56/4/2",5],[2024,"R","56/4/3",3]]},{"id":"c0425","chapter":6,"type":"mcq","text":"Which alkyl halide from the given options will undergo $S_N1$ reaction faster?","options":{"A":"$\\mathrm{(CH_3)_3C-Br}$","B":"$\\mathrm{(CH_3)_2CH-Br}$","C":"$\\mathrm{CH_3-CH_2-Br}$","D":"$\\mathrm{(CH_3)_3C-CH_2-Br}$"},"answer":"A","hint":"$S_N1$ speed depends on carbocation stability.","explanation":"The tertiary halide forms the most stable carbocation (neopentyl bromide is primary and hindered).","difficulty":1,"sources":[[2024,"R","56/4/1",5],[2024,"R","56/4/2",3],[2024,"R","56/4/3",6]]},{"id":"c0426","chapter":4,"type":"mcq","text":"From the elements of 3d series given below, which element shows the maximum number of oxidation states?","options":{"A":"Scandium","B":"Manganese","C":"Chromium","D":"Titanium"},"answer":"B","hint":"Count variable oxidation states from +2 to +7.","explanation":"Manganese shows oxidation states from +2 to +7.","difficulty":1,"sources":[[2024,"R","56/4/1",6],[2024,"R","56/4/2",2],[2024,"R","56/4/3",4]]},{"id":"c0427","chapter":3,"type":"mcq","text":"The correct Mathematical expression of Arrhenius equation is","options":{"A":"$k = -Ae^{E_a/RT}$","B":"$k = e^{E_a/RT}$","C":"$k = Ae^{-E_a/RT}$","D":"$k = -Ae^{-E_a/RT}$"},"answer":"C","hint":"Rate constant is positive and falls with rising $E_a$.","explanation":"The Arrhenius equation is $k = Ae^{-E_a/RT}$.","difficulty":1,"sources":[[2024,"R","56/4/1",7]]},{"id":"c0428","chapter":9,"type":"mcq","text":"Identify the tertiary amine from the following:","options":{"A":"$\\mathrm{(CH_3)_3N}$ (N bonded to three $\\mathrm{CH_3}$ groups)","B":"$\\mathrm{CH_3-CH(NH_2)-CH_3}$","C":"$\\mathrm{CH_3-NH-CH_2-CH_3}$","D":"$\\mathrm{(C_2H_5)_2CHNH_2}$"},"answer":"A","hint":"Count the alkyl groups on nitrogen.","explanation":"Nitrogen bonded to three alkyl groups, as in $\\mathrm{(CH_3)_3N}$, is a tertiary amine.","difficulty":1,"sources":[[2024,"R","56/4/1",8]]},{"id":"c0429","chapter":8,"type":"mcq","text":"Nucleophilic addition of Grignard reagent to ketones followed by hydrolysis with dilute acids forms:","options":{"A":"Alkene","B":"Primary alcohol","C":"Tertiary alcohol","D":"Secondary alcohol"},"answer":"C","hint":"Which product class arises from ketones with RMgX?","explanation":"Ketones give tertiary alcohols (HCHO gives primary, other aldehydes secondary).","difficulty":1,"sources":[[2024,"R","56/4/1",9],[2024,"R","56/4/2",11],[2024,"R","56/4/3",12]]},{"id":"c0430","chapter":3,"type":"mcq","text":"In a given graph of zero order reaction, the slope and intercept are:","options":{"A":"Slope $= k$, Intercept $= [R]_0$","B":"Slope $= -k$, Intercept $= [R]_0$","C":"Slope $= k/2.303$, Intercept $= \\ln[R]_0$","D":"Slope $= -k/2.303$, Intercept $= \\ln A$"},"answer":"B","hint":"Integrated zero order law: $[R] = -kt + [R]_0$.","explanation":"Plot of $[R]$ against t is a straight line with slope $-k$ and intercept $[R]_0$.","difficulty":1,"figure":"figures/c0430.png","sources":[[2024,"R","56/4/1",10],[2024,"R","56/4/2",9],[2024,"R","56/4/3",11]]},{"id":"c0431","chapter":7,"type":"mcq","text":"Match the reagents required for the given reactions:\nI. Oxidation of primary alcohols to aldehydes\nII. Butan-2-one to Butan-2-ol\nIII. Bromination of Phenol to 2,4,6-Tribromophenol\nIV. Dehydration of propan-2-ol to propene\n(p) $\\mathrm{NaBH_4}$\n(q) 85% phosphoric acid at 440 K\n(r) PCC\n(s) Bromine water","options":{"A":"I - (r), II - (p), III - (s), IV - (q)","B":"I - (q), II - (r), III - (p), IV - (s)","C":"I - (s), II - (q), III - (p), IV - (r)","D":"I - (p), II - (s), III - (r), IV - (q)"},"answer":"A","hint":"Match each transformation with its specific reagent.","explanation":"PCC stops at aldehyde, $\\mathrm{NaBH_4}$ reduces the ketone, bromine water gives tribromophenol, and $\\mathrm{H_3PO_4}$ dehydrates the alcohol.","difficulty":2,"sources":[[2024,"R","56/4/1",11],[2024,"R","56/4/2",12],[2024,"R","56/4/3",10]]},{"id":"c0432","chapter":4,"type":"mcq","text":"The general electronic configuration of d-block elements is:","options":{"A":"$(n-1)d^{1-10}ns^{1-2}$","B":"$(n-1)d^{10}ns^{1-2}$","C":"$(n-1)d^{10}ns^{2-3}$","D":"$(n-1)d^{0}ns^{1-2}$"},"answer":"A","hint":"d orbitals fill from 1 to 10 electrons.","explanation":"General configuration is $(n-1)d^{1-10}ns^{1-2}$.","difficulty":1,"sources":[[2024,"R","56/4/1",12],[2024,"R","56/4/2",10],[2024,"R","56/4/3",9]]},{"id":"c0433","chapter":7,"type":"ar","text":"Assertion (A): p-nitrophenol is less acidic than phenol.\nReason (R): Nitro group is electron withdrawing and helps in the stabilisation of p-nitrophenoxide ion.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Effect of the nitro group on phenoxide stability.","explanation":"A is false: p-nitrophenol is more acidic than phenol; R is true.","difficulty":1,"sources":[[2024,"R","56/4/1",13]]},{"id":"c0434","chapter":8,"type":"ar","text":"Assertion (A): Benzoic acid does not undergo Friedel-Crafts reaction.\nReason (R): Carboxyl group is deactivating and the catalyst aluminium chloride gets bonded to the carboxyl group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Ring deactivation and catalyst complexation.","explanation":"Both true; the deactivating $\\mathrm{-COOH}$ and its complexation with $\\mathrm{AlCl_3}$ stop the reaction, so R explains A.","difficulty":1,"sources":[[2024,"R","56/4/1",14],[2024,"R","56/4/2",16],[2024,"R","56/4/3",15]]},{"id":"c0435","chapter":10,"type":"ar","text":"Assertion (A): Fructose is a reducing sugar.\nReason (R): Fructose does not reduce Fehling solution and Tollen's reagent.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Fructose isomerises to glucose and mannose in basic medium.","explanation":"A is true (via enediol rearrangement), R is false as fructose does reduce both reagents.","difficulty":2,"sources":[[2024,"R","56/4/1",15],[2024,"R","56/4/2",14],[2024,"R","56/4/3",16]]},{"id":"c0436","chapter":2,"type":"ar","text":"Assertion (A): For a Daniell cell, $\\mathrm{Zn/Zn^{2+}(1M)\\,||\\,Cu^{2+}(1M)/Cu}$ with $E^\\circ_\\mathrm{cell} = 1.1\\ \\mathrm{V}$, if the external opposing potential is more than 1.1 V, the electrons flow from Cu to Zn.\nReason (R): Cell acts like a galvanic cell.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"What happens when opposing potential exceeds cell emf?","explanation":"A is true as the cell works as an electrolytic cell and the reaction reverses; R is false because it no longer acts as a galvanic cell.","difficulty":2,"sources":[[2024,"R","56/4/1",16],[2024,"R","56/4/2",15],[2024,"R","56/4/3",14]]},{"id":"c0437","chapter":2,"type":"mcq","text":"The molar ionic conductivities of $\\mathrm{Mg^{2+}}$ and $\\mathrm{SO_4^{2-}}$ are 106.0 $\\mathrm{S\\,cm^2\\,mol^{-1}}$ and 160.0 $\\mathrm{S\\,cm^2\\,mol^{-1}}$ respectively. The value of limiting molar conductivity of $\\mathrm{MgSO_4}$ will be:","options":{"A":"$266\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","B":"$622\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","C":"$288\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","D":"$822\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$"},"answer":"A","hint":"Kohlrausch's law.","explanation":"$\\Lambda_m^\\circ = 106.0 + 160.0 = 266\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$.","difficulty":1,"sources":[[2024,"R","56/4/2",1]]},{"id":"c0438","chapter":3,"type":"mcq","text":"In effective collisions the colliding molecules must have:","options":{"A":"Proper orientation only","B":"A certain minimum amount of activation energy.","C":"Threshold energy only.","D":"Threshold energy and proper orientation both."},"answer":"D","hint":"Collision theory needs two conditions.","explanation":"Effective collisions need threshold energy as well as proper orientation.","difficulty":1,"sources":[[2024,"R","56/4/2",7]]},{"id":"c0439","chapter":9,"type":"mcq","text":"Identify the secondary amine from the given options:","options":{"A":"$\\mathrm{(CH_3)_2CHNH_2}$","B":"$\\mathrm{CH_3NHCH(CH_3)_2}$","C":"$\\mathrm{(CH_3)_3CNH_2}$","D":"$\\mathrm{CH_3(CH_2)_2NH_2}$"},"answer":"B","hint":"Secondary amine has two alkyl groups on N.","explanation":"$\\mathrm{CH_3NHCH(CH_3)_2}$ has N bonded to two carbon groups and one H.","difficulty":1,"sources":[[2024,"R","56/4/2",8]]},{"id":"c0440","chapter":7,"type":"ar","text":"Assertion (A): Bromination of Phenol can be carried out even in the absence of Lewis acid.\nReason (R): -OH group of Phenol has the high activation effect.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Activated rings need no Lewis acid.","explanation":"Both true; strong activation by OH makes the ring react with bromine directly, so R explains A.","difficulty":1,"sources":[[2024,"R","56/4/2",13]]},{"id":"c0441","chapter":2,"type":"mcq","text":"The molar ionic conductivities of $\\mathrm{Al^{3+}}$ and $\\mathrm{SO_4^{2-}}$ are 189 $\\mathrm{S\\,cm^2\\,mol^{-1}}$ and 160 $\\mathrm{S\\,cm^2\\,mol^{-1}}$ respectively. The value of limiting molar conductivity of $\\mathrm{Al_2(SO_4)_3}$ will be:","options":{"A":"$198\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","B":"$858\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","C":"$588\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$","D":"$891\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$"},"answer":"B","hint":"Kohlrausch's law with coefficients 2 and 3.","explanation":"$\\Lambda_m^\\circ = 2(189) + 3(160) = 858\\ \\mathrm{S\\,cm^2\\,mol^{-1}}$.","difficulty":1,"sources":[[2024,"R","56/4/3",1]]},{"id":"c0442","chapter":8,"type":"mcq","text":"Consider the reaction of two molecules of formaldehyde (methanal) with conc. KOH on heating, shown in the figure: HCHO + HCHO + conc. KOH $\\xrightarrow{\\Delta}$ A + B.\nIdentify A and B from the given options:","options":{"A":"A – Methanol, B – Potassium formate","B":"A – Ethanol, B – Potassium formate","C":"A – Methanal, B – Ethanol","D":"A – Methanol, B – Potassium acetate"},"answer":"A","hint":"Aldehyde with no $\\alpha$-hydrogen and conc. alkali.","explanation":"This is the Cannizzaro reaction: one HCHO is reduced to methanol and the other oxidised to potassium formate.","difficulty":1,"figure":"figures/c0442.png","sources":[[2024,"R","56/4/3",5]]},{"id":"c0443","chapter":3,"type":"mcq","text":"The fraction of molecules having energy equal to or greater than activation energy is:","options":{"A":"$A$","B":"$e^{-E_a/RT}$","C":"$k$","D":"$A\\,e^{-E_a/RT}$"},"answer":"B","hint":"Arrhenius equation: $k = A e^{-E_a/RT}$.","explanation":"The factor $e^{-E_a/RT}$ is the fraction of molecules with energy $\\ge E_a$; $A$ is the frequency factor.","difficulty":1,"sources":[[2024,"R","56/4/3",7]]},{"id":"c0444","chapter":9,"type":"mcq","text":"Identify the primary amine from the given options:","options":{"A":"$\\mathrm{(C_2H_5)_3N}$","B":"$\\mathrm{(C_2H_5)_2NH}$","C":"$\\mathrm{C_2H_5NH_2}$","D":"$\\mathrm{(CH_3)_3N}$"},"answer":"C","hint":"A primary amine has one alkyl group on N.","explanation":"$\\mathrm{C_2H_5NH_2}$ has one alkyl group and two H on nitrogen.","difficulty":1,"sources":[[2024,"R","56/4/3",8]]},{"id":"c0445","chapter":7,"type":"ar","text":"Assertion (A): Phenols are stronger acids than alcohols.\nReason (R): Alkoxide ion is more stable than phenoxide ion.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Resonance stabilises the conjugate base.","explanation":"A is true because phenoxide is resonance stabilised. R is false: phenoxide is more stable than alkoxide.","difficulty":1,"sources":[[2024,"R","56/4/3",13]]},{"id":"c0446","chapter":10,"type":"mcq","text":"The specific sequence in which amino acids are arranged in a protein is called its","options":{"A":"Primary structure","B":"Secondary structure","C":"Tertiary structure","D":"Quaternary structure"},"answer":"A","hint":"Think of the polypeptide chain order only.","explanation":"The linear order of amino acids is the primary structure.","difficulty":1,"sources":[[2024,"R","56/5/1",1],[2024,"R","56/5/2",4],[2024,"R","56/5/3",12]]},{"id":"c0447","chapter":9,"type":"mcq","text":"The correct name of the given reaction is\n$\\mathrm{Ar{-}N_2^+X^-} \\xrightarrow{\\mathrm{CuCN/KCN}} \\mathrm{Ar{-}CN + N_2}$","options":{"A":"Sandmeyer's reaction","B":"Gabriel Phthalimide synthesis","C":"Carbyl amine reaction","D":"Hoffmann bromamide degradation reaction"},"answer":"A","hint":"Diazonium salt with cuprous salt.","explanation":"Replacement of the diazonium group by CN using CuCN is Sandmeyer's reaction.","difficulty":1,"sources":[[2024,"R","56/5/1",2],[2024,"R","56/5/3",11]]},{"id":"c0448","chapter":7,"type":"mcq","text":"Out of the following alkenes, the one which will produce tertiary butyl alcohol on acid catalysed hydration is","options":{"A":"$\\mathrm{CH_3CH_2CH=CH_2}$","B":"$\\mathrm{CH_3CH=CH_2}$","C":"$\\mathrm{CH_3{-}CH=CH{-}CH_3}$","D":"$\\mathrm{(CH_3)_2C=CH_2}$"},"answer":"D","hint":"Markovnikov addition of water; the product skeleton must be branched.","explanation":"Only 2-methylpropene has the isobutane skeleton; protonation gives the tert-butyl cation and hence tert-butyl alcohol.","difficulty":1,"sources":[[2024,"R","56/5/1",3],[2024,"R","56/5/3",10]]},{"id":"c0449","chapter":6,"type":"mcq","text":"Auto-oxidation of chloroform in air and light produces a poisonous gas known as","options":{"A":"Phosphine","B":"Mustard gas","C":"Phosgene","D":"Tear gas"},"answer":"C","hint":"Carbonyl chloride.","explanation":"Chloroform slowly oxidises to phosgene, $\\mathrm{COCl_2}$.","difficulty":1,"sources":[[2024,"R","56/5/1",4],[2024,"R","56/5/2",2],[2024,"R","56/5/3",9]]},{"id":"c0450","chapter":4,"type":"mcq","text":"Transition metals are known to make interstitial compounds. Formation of interstitial compounds makes the transition metal","options":{"A":"more hard","B":"more soft","C":"more ductile","D":"more metallic"},"answer":"A","hint":"Small atoms fill the lattice voids.","explanation":"Interstitial atoms in the lattice make the metal harder and less malleable.","difficulty":1,"sources":[[2024,"R","56/5/1",5],[2024,"R","56/5/2",5],[2024,"R","56/5/3",8]]},{"id":"c0451","chapter":1,"type":"mcq","text":"Isotonic solutions have the same","options":{"A":"density","B":"refractive index","C":"osmotic pressure","D":"volume"},"answer":"C","hint":"Iso = equal; tonic relates to osmosis.","explanation":"Isotonic solutions have equal osmotic pressure at the same temperature.","difficulty":1,"sources":[[2024,"R","56/5/1",6],[2024,"R","56/5/2",3],[2024,"R","56/5/3",7]]},{"id":"c0452","chapter":2,"type":"mcq","text":"Which of the following cell was used in Apollo space programme?","options":{"A":"Mercury cell","B":"$\\mathrm{H_2{-}O_2}$ fuel cell","C":"Dry cell","D":"Ni-Cd cell"},"answer":"B","hint":"The by-product was drinking water for astronauts.","explanation":"The $\\mathrm{H_2{-}O_2}$ fuel cell powered the Apollo missions.","difficulty":1,"sources":[[2024,"R","56/5/1",7]]},{"id":"c0453","chapter":3,"type":"mcq","text":"The rate of a reaction increases sixteen times when the concentration of the reactant increases four times. The order of the reaction is","options":{"A":"2.5","B":"2.0","C":"1.5","D":"0.5"},"answer":"B","hint":"Rate $\\propto [A]^n$.","explanation":"$16 = 4^n$ gives $n = 2$.","difficulty":1,"sources":[[2024,"R","56/5/1",8],[2024,"R","56/5/3",5],[2026,"C","56(B)/7",4]]},{"id":"c0454","chapter":6,"type":"mcq","text":"In which of the following molecules, C atom marked with asterisk is chiral? (Structures I to IV are shown in the figure.)","options":{"A":"I, II, III","B":"I, II, III, IV","C":"II, III, IV","D":"I, III, IV"},"answer":"A","hint":"A chiral carbon has four different groups.","explanation":"I (H, CH3, Cl, Br), II (D, I, Cl, Br) and III (D, OH, CH2CH3, CH3) have four different groups; IV has two CH3 groups.","difficulty":2,"figure":"figures/c0454.png","sources":[[2024,"R","56/5/1",9],[2024,"R","56/5/3",4]]},{"id":"c0455","chapter":7,"type":"mcq","text":"Which of the following species can act as the strongest base?","options":{"A":"$\\mathrm{OH^-}$","B":"$\\mathrm{C_6H_5O^-}$","C":"$\\mathrm{RO^-}$","D":"Structure (D)"},"answer":"C","hint":"Strongest base is the conjugate base of the weakest acid.","explanation":"Alcohols are weaker acids than water and phenols, so $\\mathrm{RO^-}$ is the strongest base. Option D is m-nitrophenoxide (shown in figure).","difficulty":2,"figure":"figures/c0455.png","sources":[[2024,"R","56/5/1",10],[2024,"R","56/5/2",1],[2024,"R","56/5/3",3]]},{"id":"c0456","chapter":2,"type":"mcq","text":"Dilution affects both conductivity as well as molar conductivity. Effect of dilution on both is as follows:","options":{"A":"both increase with dilution.","B":"both decrease with dilution.","C":"conductivity increases whereas molar conductivity decreases on dilution.","D":"conductivity decreases whereas molar conductivity increases on dilution."},"answer":"D","hint":"Fewer ions per unit volume, but more complete dissociation per mole.","explanation":"Conductivity falls as ions per unit volume decrease; molar conductivity rises as dissociation and ion mobility increase.","difficulty":1,"sources":[[2024,"R","56/5/1",11],[2024,"R","56/5/3",2]]},{"id":"c0457","chapter":1,"type":"mcq","text":"Van't Hoff factor for $\\mathrm{Na_2SO_4{\\cdot}10H_2O}$ solution, assuming complete ionization is","options":{"A":"1","B":"3","C":"13","D":"2"},"answer":"B","hint":"Count ions produced; water of crystallisation is not a solute.","explanation":"$\\mathrm{Na_2SO_4 \\rightarrow 2Na^+ + SO_4^{2-}}$ gives 3 ions, so $i=3$.","difficulty":1,"sources":[[2024,"R","56/5/1",12]]},{"id":"c0458","chapter":4,"type":"ar","text":"Assertion (A): Zr and Hf are of almost similar atomic radii.\nReason (R): This is due to Lanthanoid contraction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Poor shielding by 4f electrons.","explanation":"Both true; lanthanoid contraction cancels the normal size increase from 4d to 5d, so R explains A.","difficulty":1,"sources":[[2024,"R","56/5/1",13],[2024,"R","56/5/2",16],[2024,"R","56/5/3",14]]},{"id":"c0459","chapter":6,"type":"ar","text":"Assertion (A): Inversion of configuration is observed in $\\mathrm{S_N2}$ reaction.\nReason (R): The reaction proceeds with the formation of carbocation.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"SN2 is a single concerted step.","explanation":"A is true (backside attack). R is false: $\\mathrm{S_N2}$ proceeds through a transition state, not a carbocation.","difficulty":1,"sources":[[2024,"R","56/5/1",15],[2024,"R","56/5/2",14]]},{"id":"c0460","chapter":7,"type":"ar","text":"Assertion (A): p-methoxyphenol is a stronger acid than p-nitrophenol.\nReason (R): Methoxy group shows +I effect whereas nitro group shows –I effect.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Electron-withdrawing groups raise acidity.","explanation":"A is false: p-nitrophenol is the stronger acid. R is true as a statement about the groups' inductive effects.","difficulty":2,"sources":[[2024,"R","56/5/1",16],[2024,"R","56/5/2",13],[2025,"C","56/S/2",14]]},{"id":"c0461","chapter":9,"type":"mcq","text":"The correct name of the given reaction is\n$\\mathrm{Ar{-}N_2^+X^-} \\xrightarrow[\\mathrm{Cu\\ powder}]{\\mathrm{HBr}} \\mathrm{Ar{-}Br + N_2}$","options":{"A":"Hoffmann Bromamide degradation reaction.","B":"Gabriel Phthalimide synthesis","C":"Carbyl amine reaction","D":"Gatterman reaction"},"answer":"D","hint":"Which named reaction uses copper powder with HX?","explanation":"Replacement of the diazonium group by halogen using Cu powder and HX is the Gattermann reaction.","difficulty":1,"sources":[[2024,"R","56/5/2",6]]},{"id":"c0462","chapter":7,"type":"mcq","text":"Visha took 4 test-tubes namely A, B, C & D containing $\\mathrm{CH_3CH=CH_2}$, $\\mathrm{CH_3CH_2CH=CH_2}$, $\\mathrm{CH_3CH=CH{-}CH_3}$ and $\\mathrm{(CH_3)_2C=CH_2}$ respectively and tried to convert them into tertbutylalcohol. She carried out acid catalysed hydration reaction on every alkene. Out of the four test-tubes, the one which will give desired result is","options":{"A":"A","B":"B","C":"C","D":"D"},"answer":"D","hint":"Only one alkene has the tert-butyl skeleton.","explanation":"2-Methylpropene (D) forms the tert-butyl cation on protonation and gives tert-butyl alcohol.","difficulty":1,"sources":[[2024,"R","56/5/2",7]]},{"id":"c0463","chapter":1,"type":"mcq","text":"Van't Hoff factor for $\\mathrm{KCl}$ solution assuming the complete dissociation is","options":{"A":"1","B":"2","C":"0.5","D":"1.5"},"answer":"B","hint":"Count ions per formula unit.","explanation":"$\\mathrm{KCl \\rightarrow K^+ + Cl^-}$, so $i=2$.","difficulty":1,"sources":[[2024,"R","56/5/2",8]]},{"id":"c0464","chapter":2,"type":"mcq","text":"Dilution affects both molar conductivity as well as conductivity. Effect of dilution on both is","options":{"A":"molar conductivity decreases whereas conductivity increases on dilution.","B":"molar conductivity increases whereas conductivity decreases on dilution.","C":"both decrease with dilution.","D":"both increase with dilution."},"answer":"B","hint":"Fewer ions per unit volume, but more dissociation per mole.","explanation":"Conductivity falls on dilution while molar conductivity rises.","difficulty":1,"sources":[[2024,"R","56/5/2",9]]},{"id":"c0465","chapter":2,"type":"mcq","text":"Which of the following cell is used in inverter?","options":{"A":"Fuel cell","B":"Mercury cell","C":"Lead storage cell","D":"Dry cell"},"answer":"C","hint":"It must be rechargeable and give high current.","explanation":"Inverters use lead storage (secondary) batteries.","difficulty":1,"sources":[[2024,"R","56/5/2",10]]},{"id":"c0466","chapter":6,"type":"mcq","text":"In which of the following molecules, C atom marked with asterisk is chiral? (Structures I to IV are shown in the figure.)","options":{"A":"I, II, III","B":"II, III, IV","C":"I, II, III, IV","D":"I, III, IV"},"answer":"B","hint":"A chiral carbon has four different groups.","explanation":"I has two CH3 groups so it is achiral; II, III and IV each have four different groups.","difficulty":2,"figure":"figures/c0466.png","sources":[[2024,"R","56/5/2",11]]},{"id":"c0467","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{A + 2B \\rightarrow C + D}$. The order of the reaction is","options":{"A":"1 with respect to A","B":"2 with respect to B","C":"can't be predicted as order is determined experimentally.","D":"3"},"answer":"C","hint":"Order is not from stoichiometry.","explanation":"Order must be found experimentally; it cannot be read from the balanced equation.","difficulty":1,"sources":[[2024,"R","56/5/2",12]]},{"id":"c0468","chapter":1,"type":"mcq","text":"Van't Hoff factor for $\\mathrm{K_2SO_4}$ solution, assuming complete ionization is","options":{"A":"1","B":"3","C":"13","D":"2"},"answer":"B","hint":"Count ions produced.","explanation":"$\\mathrm{K_2SO_4 \\rightarrow 2K^+ + SO_4^{2-}}$ gives 3 ions, so $i=3$.","difficulty":1,"sources":[[2024,"R","56/5/3",1]]},{"id":"c0469","chapter":2,"type":"mcq","text":"Which of the following cell is used in hearing aids?","options":{"A":"Mercury cell","B":"$\\mathrm{H_2{-}O_2}$ fuel cell","C":"Dry cell","D":"Ni-Cd cell"},"answer":"A","hint":"Small button cell with constant voltage.","explanation":"Mercury (button) cells are used in hearing aids, watches and cameras.","difficulty":1,"sources":[[2024,"R","56/5/3",6]]},{"id":"c0470","chapter":7,"type":"ar","text":"Assertion (A): p-methoxyphenol is a stronger acid than m-methoxy phenol.\nReason (R): Methoxy group exerts +R effect at both ortho and para position.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"+R effect destabilises the phenoxide when at o/p positions.","explanation":"A is false: +R at para destabilises the phenoxide, so m-methoxyphenol is more acidic. R is true.","difficulty":2,"sources":[[2024,"R","56/5/3",15]]},{"id":"c0471","chapter":6,"type":"ar","text":"Assertion (A): Inversion of configuration is observed when 1-Bromobutane is hydrolysed.\nReason (R): The reaction is $\\mathrm{S_N2}$ and proceeds with the formation of transition state.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Primary halide, backside attack.","explanation":"1-Bromobutane reacts by $\\mathrm{S_N2}$ via a transition state, giving inversion; R explains A.","difficulty":1,"sources":[[2024,"R","56/5/3",16]]},{"id":"c0472","chapter":2,"type":"mcq","text":"Which of the following cells has a constant voltage throughout its life?","options":{"A":"Dry cell","B":"Daniell cell","C":"Electrolytic cell","D":"Mercury cell"},"answer":"D","hint":"Ion concentrations stay constant in this button cell.","explanation":"In the mercury cell the overall reaction involves no ions whose concentration changes, so voltage stays constant.","difficulty":1,"sources":[[2025,"C","56(B)/S",1]]},{"id":"c0473","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{A + 2B \\rightarrow 3C + D}$, $\\dfrac{d[C]}{dt}$ is equal to:","options":{"A":"$-\\dfrac{d[B]}{dt}$","B":"$-\\dfrac{3}{2}\\dfrac{d[B]}{dt}$","C":"$-\\dfrac{d[A]}{dt}$","D":"$+3\\dfrac{d[A]}{dt}$"},"answer":"B","hint":"Equate rates divided by stoichiometric coefficients.","explanation":"$-\\tfrac{1}{2}\\tfrac{d[B]}{dt} = \\tfrac{1}{3}\\tfrac{d[C]}{dt}$, so $\\tfrac{d[C]}{dt} = -\\tfrac{3}{2}\\tfrac{d[B]}{dt}$.","difficulty":2,"sources":[[2025,"C","56(B)/S",2]]},{"id":"c0474","chapter":4,"type":"mcq","text":"Which of the following transition metals shows maximum number of oxidation states?","options":{"A":"Mn","B":"Ti","C":"Sc","D":"Cu"},"answer":"A","hint":"Many unpaired d and s electrons are available.","explanation":"Mn shows oxidation states from +2 to +7.","difficulty":1,"sources":[[2025,"C","56(B)/S",3]]},{"id":"c0475","chapter":5,"type":"mcq","text":"The secondary valence of Co in $\\mathrm{[Co(NH_3)_6]Cl_3}$ is:","options":{"A":"3","B":"6","C":"5","D":"9"},"answer":"B","hint":"Secondary valence = coordination number.","explanation":"Six $\\mathrm{NH_3}$ ligands are attached, so the secondary valence is 6.","difficulty":1,"sources":[[2025,"C","56(B)/S",4]]},{"id":"c0476","chapter":9,"type":"mcq","text":"The action of $\\mathrm{HNO_2}$ on methylamine gives mainly:","options":{"A":"Methyl nitrite","B":"Nitromethane","C":"Methane","D":"Methyl alcohol"},"answer":"D","hint":"Primary aliphatic amine gives an unstable diazonium salt.","explanation":"$\\mathrm{CH_3NH_2 + HNO_2 \\rightarrow CH_3OH + N_2 + H_2O}$.","difficulty":1,"sources":[[2025,"C","56(B)/S",5]]},{"id":"c0477","chapter":10,"type":"mcq","text":"The deficiency of which vitamin causes pernicious anaemia ?","options":{"A":"Vitamin $\\mathrm{B_{12}}$","B":"Vitamin $\\mathrm{B_6}$","C":"Vitamin $\\mathrm{B_1}$","D":"Vitamin $\\mathrm{B_2}$"},"answer":"A","hint":"Recall the vitamin linked to red blood cell formation.","explanation":"Deficiency of vitamin B12 causes pernicious anaemia.","difficulty":1,"sources":[[2025,"C","56(B)/S",7]]},{"id":"c0478","chapter":6,"type":"mcq","text":"The synthesis of alkyl iodide is best done by :","options":{"A":"Swarts reaction","B":"Wurtz reaction","C":"Sandmeyer reaction","D":"Finkelstein reaction"},"answer":"D","hint":"Halogen exchange with NaI in dry acetone.","explanation":"Finkelstein reaction converts alkyl chlorides/bromides to iodides using NaI in dry acetone.","difficulty":1,"sources":[[2025,"C","56(B)/S",9]]},{"id":"c0479","chapter":6,"type":"mcq","text":"Major product obtained when chlorobenzene reacts with methyl chloride and sodium in the presence of dry ether is :","options":{"A":"Toluene","B":"o-Dichlorobenzene","C":"Benzene","D":"Methane"},"answer":"A","hint":"Think of the Wurtz-Fittig reaction.","explanation":"Wurtz-Fittig coupling of aryl halide with alkyl halide gives toluene.","difficulty":2,"sources":[[2025,"C","56(B)/S",10]]},{"id":"c0480","chapter":1,"type":"mcq","text":"The colligative property preferred for the determination of molar mass of polymers is :","options":{"A":"Depression in freezing point","B":"Osmotic pressure","C":"Relative lowering in vapour pressure","D":"Elevation in boiling point"},"answer":"B","hint":"Which property gives a measurable effect even at very low molarity?","explanation":"Osmotic pressure is measurable at room temperature and at very low concentration, so it suits macromolecules.","difficulty":1,"sources":[[2025,"C","56(B)/S",11]]},{"id":"c0481","chapter":4,"type":"mcq","text":"The most common and stable oxidation state of lanthanoids is :","options":{"A":"$+4$","B":"$+2$","C":"$+3$","D":"$+6$"},"answer":"C","hint":"Recall the characteristic oxidation state of the 4f series.","explanation":"The +3 state is the most common and stable for lanthanoids.","difficulty":1,"sources":[[2025,"C","56(B)/S",12]]},{"id":"c0482","chapter":7,"type":"ar","text":"Assertion (A): Methoxyethane reacts with HI to give ethanol and iodomethane.\nReason (R): Reaction of methoxyethane with HI follows $\\mathrm{S_N1}$ mechanism.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Ether with primary alkyl groups cleaves by which mechanism?","explanation":"A is true: I- attacks the smaller methyl group giving CH3I and ethanol. R is false: primary ethers react by SN2, not SN1.","difficulty":2,"sources":[[2025,"C","56(B)/S",14]]},{"id":"c0483","chapter":3,"type":"ar","text":"Assertion (A): All collisions of reactant molecules lead to product formation.\nReason (R): Only those collisions in which molecules have proper orientation and sufficient kinetic energy (threshold energy) lead to product formation.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Collision theory needs orientation and threshold energy.","explanation":"A is false since most collisions are ineffective. R is true (collision theory).","difficulty":1,"sources":[[2025,"C","56(B)/S",15]]},{"id":"c0484","chapter":6,"type":"ar","text":"Assertion (A): AgCN reacts with methyl chloride to give methyl cyanide.\nReason (R): $\\mathrm{CN^-}$ is an ambident nucleophile.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"AgCN is largely covalent; which atom attacks?","explanation":"A is false: covalent AgCN gives methyl isocyanide (N attacks). R is true.","difficulty":2,"sources":[[2025,"C","56(B)/S",16]]},{"id":"c0485","chapter":2,"type":"mcq","text":"A conductivity cell contains electrodes made up of :","options":{"A":"Silver","B":"Copper","C":"Platinum","D":"Zinc"},"answer":"C","hint":"The electrodes must be inert and coated with platinum black.","explanation":"Conductivity cells have platinum electrodes (platinised).","difficulty":1,"sources":[[2025,"C","56/S/1",1],[2025,"C","56/S/3",2]]},{"id":"c0486","chapter":1,"type":"mcq","text":"The value of $K_\\mathrm{H}$ at 298 K for $\\mathrm{Ar(g)}$, $\\mathrm{CO_2(g)}$, $\\mathrm{HCHO(g)}$ and $\\mathrm{CH_4(g)}$ are $40\\cdot32$, $1\\cdot68$, $1\\cdot84\\times10^{-5}$ and $0\\cdot416$ kbar respectively. When these gases are arranged in increasing order of solubility, the correct order is :","options":{"A":"$\\mathrm{HCHO < CH_4 < CO_2 < Ar}$","B":"$\\mathrm{HCHO < CO_2 < CH_4 < Ar}$","C":"$\\mathrm{Ar < CO_2 < CH_4 < HCHO}$","D":"$\\mathrm{Ar < CH_4 < CO_2 < HCHO}$"},"answer":"C","hint":"Solubility is inversely related to Henry's constant.","explanation":"Higher K_H means lower solubility, so increasing solubility follows decreasing K_H: Ar < CO2 < CH4 < HCHO.","difficulty":2,"sources":[[2025,"C","56/S/1",2],[2025,"C","56/S/3",3]]},{"id":"c0487","chapter":7,"type":"mcq","text":"Out of the following organic compounds, the one which will react with Lucas reagent at room temperature is :","options":{"A":"$\\mathrm{CH_2=CH-CH_2OH}$","B":"$\\mathrm{CH_3CH_2CH_2OH}$","C":"$\\mathrm{C_6H_5CH_2OH}$","D":"$\\mathrm{(CH_3)_3COH}$"},"answer":"D","hint":"Lucas reagent distinguishes alcohols by carbocation stability.","explanation":"Tertiary alcohols give turbidity immediately with ZnCl2/HCl at room temperature.","difficulty":2,"sources":[[2025,"C","56/S/1",3],[2025,"C","56/S/2",2],[2025,"C","56/S/3",4]]},{"id":"c0488","chapter":6,"type":"mcq","text":"Identify the Freon from the following compounds :","options":{"A":"$\\mathrm{CCl_2F_2}$","B":"$\\mathrm{CCl_2Br_2}$","C":"$\\mathrm{CH_2Cl-CHCl_2}$","D":"$\\mathrm{CHCl_2-CHCl_2}$"},"answer":"A","hint":"Freons are chlorofluorocarbons.","explanation":"Freon-12 is CCl2F2, a chlorofluorocarbon.","difficulty":1,"sources":[[2025,"C","56/S/1",4],[2025,"C","56/S/2",6],[2025,"C","56/S/3",1]]},{"id":"c0489","chapter":2,"type":"mcq","text":"The standard electrode potential of 'A', 'B' and 'C' are $+0\\cdot68$ V, $-2\\cdot54$ V and $-0\\cdot50$ V respectively. The order of their reducing power is :","options":{"A":"$\\mathrm{A > B > C}$","B":"$\\mathrm{A > C > B}$","C":"$\\mathrm{B > C > A}$","D":"$\\mathrm{C > B > A}$"},"answer":"C","hint":"More negative E° means stronger reducing agent.","explanation":"Reducing power increases as E° decreases: B (-2.54) > C (-0.50) > A (+0.68).","difficulty":1,"sources":[[2025,"C","56/S/1",6],[2025,"C","56/S/2",9]]},{"id":"c0490","chapter":10,"type":"mcq","text":"Glucose on reaction with $\\mathrm{Br_2}$ water gives :","options":{"A":"Gluconic acid","B":"Hexanoic acid","C":"Saccharic acid","D":"Glycolic acid"},"answer":"A","hint":"Bromine water is a mild oxidant of the aldehyde group.","explanation":"Br2 water oxidises only the CHO group of glucose to COOH giving gluconic acid.","difficulty":1,"sources":[[2025,"C","56/S/1",7]]},{"id":"c0491","chapter":1,"type":"mcq","text":"A compound $\\mathrm{CaCl_2.6H_2O}$ undergoes complete dissociation in water. The Van't Hoff factor (i) is :","options":{"A":"9","B":"6","C":"4","D":"3"},"answer":"D","hint":"Count ions produced; water of crystallisation does not ionise.","explanation":"CaCl2 gives Ca2+ and 2 Cl-, so i = 3.","difficulty":1,"sources":[[2025,"C","56/S/1",8],[2025,"C","56/S/2",4],[2025,"C","56/S/3",11]]},{"id":"c0492","chapter":4,"type":"mcq","text":"The transition element which shows both $+1$ and $+2$ oxidation states is :","options":{"A":"Sc","B":"Mn","C":"Cu","D":"Zn"},"answer":"C","hint":"Think of $3d^{10}4s^1$ configuration.","explanation":"Cu shows +1 (Cu2O, CuCl) and +2 states.","difficulty":1,"sources":[[2025,"C","56/S/1",9],[2025,"C","56/S/2",7],[2025,"C","56/S/3",10]]},{"id":"c0493","chapter":6,"type":"mcq","text":"Which one of the following halides contains $\\mathrm{C_{sp^2}-X}$ bond ?","options":{"A":"Alkyl halide","B":"Allyl halide","C":"Benzyl halide","D":"Vinyl halide"},"answer":"D","hint":"The halogen must be on a doubly bonded carbon.","explanation":"In vinyl halides X is attached directly to an sp2 carbon of C=C.","difficulty":1,"sources":[[2025,"C","56/S/1",10],[2025,"C","56/S/2",5],[2025,"C","56/S/3",7]]},{"id":"c0494","chapter":9,"type":"mcq","text":"Which of the following amines has the highest boiling point ?","options":{"A":"2,2-Dimethyl propanamine","B":"3-Methylbutanamine","C":"2-Methylbutanamine","D":"Pentanamine"},"answer":"D","hint":"Among isomers, less branching gives larger surface area.","explanation":"All are isomeric primary amines; the straight-chain pentanamine has the greatest surface area and boiling point.","difficulty":1,"sources":[[2025,"C","56/S/1",11],[2025,"C","56/S/2",3],[2025,"C","56/S/3",6]]},{"id":"c0495","chapter":7,"type":"mcq","text":"When phenyl methyl ether is heated with HI, it produces :","options":{"A":"Methyl chloride and Iodobenzene","B":"Benzene and Methanol","C":"Iodobenzene and Methanol","D":"Phenol and Methyl iodide"},"answer":"D","hint":"The $\\mathrm{C_{aryl}-O}$ bond is stronger than $\\mathrm{C_{alkyl}-O}$.","explanation":"Iodide attacks the methyl carbon, giving phenol and CH3I.","difficulty":1,"sources":[[2025,"C","56/S/1",12],[2025,"C","56/S/2",1]]},{"id":"c0496","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show a wide range of oxidation states.\nReason (R): Actinoids are radioactive in nature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Cause of variable oxidation states is comparable orbital energies.","explanation":"Both statements are true, but the wide range arises from comparable energies of 5f, 6d, 7s orbitals, not radioactivity.","difficulty":2,"sources":[[2025,"C","56/S/1",13],[2025,"C","56/S/3",15],[2025,"R","56/6/1",13],[2026,"R","56/1/1",15]]},{"id":"c0497","chapter":6,"type":"ar","text":"Assertion (A): Presence of $-\\mathrm{NO_2}$ group at ortho or para position increases the reactivity of haloarenes towards nucleophilic substitution reactions.\nReason (R): Nitro group decreases the electron density over the benzene ring.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Electron withdrawal stabilises the Meisenheimer intermediate.","explanation":"Both true; reduced ring electron density at o/p positions facilitates nucleophilic attack.","difficulty":2,"sources":[[2025,"C","56/S/1",14]]},{"id":"c0498","chapter":7,"type":"ar","text":"Assertion (A): p-methoxyphenol is a stronger acid than p-nitrophenol.\nReason (R): Methoxy group is electron-donating group whereas nitro group is electron-withdrawing.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Electron-withdrawing groups stabilise the phenoxide ion.","explanation":"A is false: p-nitrophenol is the stronger acid. R is true.","difficulty":2,"sources":[[2025,"C","56/S/1",16],[2025,"C","56/S/3",13]]},{"id":"c0499","chapter":2,"type":"mcq","text":"Silver nitrate is not stored in Zn vessel because :","options":{"A":"Silver nitrate gets decomposed","B":"$\\mathrm{Ag^+}$ gets reduced","C":"Ag gets oxidised","D":"Zn gets reduced"},"answer":"B","hint":"Compare the electrode potentials of Zn and Ag.","explanation":"Zn is a stronger reducing agent, so it reduces Ag+ to Ag (and itself oxidises).","difficulty":1,"sources":[[2025,"C","56/S/2",10]]},{"id":"c0500","chapter":10,"type":"mcq","text":"Glucose on reaction with nitric acid gives :","options":{"A":"Gluconic acid","B":"Hexanoic acid","C":"Saccharic acid","D":"Glycolic acid"},"answer":"C","hint":"Nitric acid is a strong oxidant of both end groups.","explanation":"Conc. HNO3 oxidises both CHO and terminal CH2OH to COOH, giving saccharic acid.","difficulty":1,"sources":[[2025,"C","56/S/2",11]]},{"id":"c0501","chapter":1,"type":"mcq","text":"The value of $K_\\mathrm{H}$ for $\\mathrm{Ar(g)}$, $\\mathrm{CO_2(g)}$, $\\mathrm{HCHO(g)}$ and $\\mathrm{CH_4(g)}$, are $40\\cdot38$, $1\\cdot69$, $1\\cdot84\\times10^{-5}$ and $0\\cdot418$ kbar respectively at 298 K. When these gases are arranged in decreasing order of solubility, the correct order is :","options":{"A":"$\\mathrm{HCHO > CH_4 > CO_2 > Ar}$","B":"$\\mathrm{HCHO > CO_2 > CH_4 > Ar}$","C":"$\\mathrm{Ar > CO_2 > CH_4 > HCHO}$","D":"$\\mathrm{CH_4 > CO_2 > Ar > HCHO}$"},"answer":"A","hint":"Solubility is inversely related to Henry's constant.","explanation":"Lower K_H means higher solubility: HCHO > CH4 > CO2 > Ar.","difficulty":2,"sources":[[2025,"C","56/S/2",12]]},{"id":"c0502","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show wide range of oxidation states.\nReason (R): Due to comparable energies of 5f, 6d and 7s orbitals.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Which orbitals take part in bonding?","explanation":"Both true; comparable energies let 5f, 6d and 7s electrons participate, explaining variable oxidation states.","difficulty":2,"sources":[[2025,"C","56/S/2",15],[2025,"R","56/6/2",13]]},{"id":"c0503","chapter":6,"type":"ar","text":"Assertion (A): Presence of $-\\mathrm{NO_2}$ group at meta position increases the reactivity of haloarenes towards nucleophilic substitution reactions.\nReason (R): $-\\mathrm{NO_2}$ group decreases the electron density over the benzene ring and thus facilitates the attack of nucleophile on haloarenes.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"The activating effect operates only at ortho and para positions.","explanation":"A is false: at meta position nitro does not stabilise the intermediate by resonance. R is true in general.","difficulty":2,"sources":[[2025,"C","56/S/2",16]]},{"id":"c0504","chapter":10,"type":"mcq","text":"Glucose on reaction with hydrogen iodide gives :","options":{"A":"Gluconic acid","B":"n-Hexane","C":"Saccharic acid","D":"Hexanoic acid"},"answer":"B","hint":"HI is a strong reducing agent on prolonged heating.","explanation":"Prolonged heating with HI reduces glucose completely to n-hexane.","difficulty":1,"sources":[[2025,"C","56/S/3",5]]},{"id":"c0505","chapter":3,"type":"mcq","text":"If the half-life period of a first order reaction is 2772 s, then the rate constant of this reaction is :","options":{"A":"$2\\cdot5\\times10^{-4}\\ \\mathrm{s^{-1}}$","B":"$2\\cdot5\\times10^{-3}\\ \\mathrm{s^{-1}}$","C":"$25\\times10^{-4}\\ \\mathrm{s^{-1}}$","D":"$25\\times10^{-3}\\ \\mathrm{s^{-1}}$"},"answer":"A","hint":"Use $k = 0.693/t_{1/2}$.","explanation":"k = 0.693/2772 = 2.5 x 10^-4 s^-1.","difficulty":1,"sources":[[2025,"C","56/S/3",8]]},{"id":"c0506","chapter":6,"type":"ar","text":"Assertion (A): Presence of $-\\mathrm{NO_2}$ group at ortho and para positions decreases the reactivity of haloarenes towards nucleophilic substitution reactions.\nReason (R): Nitro group decreases the electron density over the benzene ring.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Electron withdrawal stabilises the intermediate carbanion.","explanation":"A is false: o/p nitro increases reactivity. R is true.","difficulty":2,"sources":[[2025,"C","56/S/3",16]]},{"id":"c0507","chapter":10,"type":"mcq","text":"Which of the following is a polysaccharide ?","options":{"A":"Maltose","B":"Glucose","C":"Cellulose","D":"Sucrose"},"answer":"C","hint":"Polysaccharides contain many monosaccharide units.","explanation":"Cellulose is a polymer of glucose; the others are mono- or disaccharides.","difficulty":1,"sources":[[2025,"R","56(B)",1]]},{"id":"c0508","chapter":7,"type":"mcq","text":"The compound which undergoes dehydration most easily is","options":{"A":"2-Methylpropan-2-ol","B":"Ethanol","C":"2-Methylbutan-2-ol","D":"Propan-1-ol"},"answer":"C","hint":"Ease of dehydration follows carbocation stability and alkene stability.","explanation":"Both tertiary alcohols dehydrate easily, but 2-methylbutan-2-ol gives a more substituted, more stable alkene.","difficulty":2,"sources":[[2025,"R","56(B)",3]]},{"id":"c0509","chapter":6,"type":"mcq","text":"The conversion of an alkyl halide into an alcohol by aqueous NaOH is classified as","options":{"A":"an addition reaction","B":"a substitution reaction","C":"a dehydrohalogenation reaction","D":"a dehydration reaction"},"answer":"B","hint":"OH replaces the halogen.","explanation":"Halide is replaced by OH, so it is nucleophilic substitution.","difficulty":1,"sources":[[2025,"R","56(B)",4]]},{"id":"c0510","chapter":4,"type":"mcq","text":"Which of the following transition metals does not show variable oxidation states ?","options":{"A":"Cu","B":"Sc","C":"Ti","D":"Fe"},"answer":"B","hint":"Check how many oxidation states are possible for $3d^1 4s^2$.","explanation":"Sc shows only the +3 state.","difficulty":1,"sources":[[2025,"R","56(B)",5]]},{"id":"c0511","chapter":1,"type":"mcq","text":"An azeotropic mixture of two liquids has a boiling point higher than that of either of the two liquids when it","options":{"A":"obeys Raoult's law.","B":"shows positive deviation from Raoult's law.","C":"shows negative deviation from Raoult's law.","D":"obeys Henry's law."},"answer":"C","hint":"Maximum boiling azeotropes arise from stronger interactions.","explanation":"Negative deviation forms maximum-boiling azeotropes.","difficulty":1,"sources":[[2025,"R","56(B)",6]]},{"id":"c0512","chapter":2,"type":"mcq","text":"Kohlrausch gave the following relation for strong electrolytes at low concentration :\n$\\Lambda_m = \\Lambda_m^0 - A\\sqrt{C}$\nWhich of the following equality holds true ?","options":{"A":"$\\Lambda_m = \\Lambda_m^0$ as $C \\rightarrow \\sqrt{A}$","B":"$\\Lambda_m = \\Lambda_m^0$ as $C \\rightarrow 0$","C":"$\\Lambda_m = \\Lambda_m^0$ as $C \\rightarrow \\infty$","D":"$\\Lambda_m = \\Lambda_m^0$ as $C \\rightarrow 1$"},"answer":"B","hint":"Limiting molar conductivity corresponds to infinite dilution.","explanation":"When C tends to 0 the sqrt(C) term vanishes, so Lambda_m = Lambda_m^0.","difficulty":1,"sources":[[2025,"R","56(B)",7]]},{"id":"c0513","chapter":6,"type":"mcq","text":"The synthesis of alkyl fluoride is best accomplished by","options":{"A":"Sandmeyer reaction","B":"Finkelstein reaction","C":"Wurtz reaction","D":"Swarts reaction"},"answer":"D","hint":"Heating alkyl halide with a metallic fluoride.","explanation":"Swarts reaction uses AgF or Hg2F2 to prepare alkyl fluorides.","difficulty":1,"sources":[[2025,"R","56(B)",9]]},{"id":"c0514","chapter":1,"type":"mcq","text":"Solubility of gases in liquid decreases with increase in","options":{"A":"pressure","B":"volume","C":"number of solute particles","D":"temperature"},"answer":"D","hint":"Dissolution of gases is exothermic.","explanation":"Gas solubility falls as temperature rises.","difficulty":1,"sources":[[2025,"R","56(B)",11]]},{"id":"c0515","chapter":2,"type":"mcq","text":"$\\Delta_rG^0$ and $E^\\circ_\\mathrm{cell}$ for a spontaneous reaction will respectively be","options":{"A":"positive and positive","B":"positive and negative","C":"negative and positive","D":"negative and negative"},"answer":"C","hint":"Use $\\Delta G^\\circ = -nFE^\\circ$.","explanation":"Spontaneous means negative Delta G and positive E_cell.","difficulty":1,"sources":[[2025,"R","56(B)",12]]},{"id":"c0516","chapter":4,"type":"ar","text":"Assertion (A): Zinc is not regarded as a transition element.\nReason (R): Zinc has completely filled 3d orbitals in its ground state as well as in its oxidised state.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Definition of transition element needs incomplete d subshell.","explanation":"Both true; R explains A since $\\mathrm{Zn^{2+}}$ is $3d^{10}$.","difficulty":1,"sources":[[2025,"R","56(B)",13]]},{"id":"c0517","chapter":3,"type":"ar","text":"Assertion (A): In a first order reaction, if the concentration of the reactant is doubled, its half-life is also doubled.\nReason (R): The half-life of a reaction does not depend upon the initial concentration of the reactant in a first order reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"First order half-life is $0.693/k$.","explanation":"A is false since t1/2 is independent of concentration. R is true.","difficulty":1,"sources":[[2025,"R","56(B)",14]]},{"id":"c0518","chapter":7,"type":"ar","text":"Assertion (A): $\\mathrm{(CH_3)_3C-O-CH_3}$ gives $\\mathrm{(CH_3)_3C-I}$ and $\\mathrm{CH_3OH}$ on treatment with HI.\nReason (R): The reaction occurs by $\\mathrm{S_N1}$ mechanism.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Tertiary alkyl ethers cleave via the stable tertiary carbocation.","explanation":"Both true; the stable tert-butyl carbocation forms (SN1), so iodide ends up on the tertiary carbon.","difficulty":2,"sources":[[2025,"R","56(B)",15],[2026,"R","56/4/3",13]]},{"id":"c0519","chapter":6,"type":"ar","text":"Assertion (A): Nucleophilic substitution reaction of chlorobenzene is easier than that of chloroethane.\nReason (R): C-Cl bond in chlorobenzene has partial double bond character due to resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Resonance strengthens the C-Cl bond in aryl halides.","explanation":"A is false: chlorobenzene is less reactive. R is true.","difficulty":2,"sources":[[2025,"R","56(B)",16]]},{"id":"c0520","chapter":1,"type":"mcq","text":"In case of association, abnormal molar mass of solute will","options":{"A":"increase","B":"decrease","C":"remain same","D":"first increase and then decrease"},"answer":"A","hint":"Association reduces number of particles.","explanation":"Fewer particles lower the colligative effect, so observed molar mass is higher than normal.","difficulty":1,"sources":[[2025,"R","56/1/1",1],[2025,"R","56/1/2",16],[2025,"R","56/1/3",3]]},{"id":"c0521","chapter":2,"type":"mcq","text":"Standard electrode potential for $\\mathrm{Sn^{4+}/Sn^{2+}}$ couple is $+0\\cdot15$ V and that for the $\\mathrm{Cr^{3+}/Cr}$ couple is $-0\\cdot74$ V. The two couples in their standard states are connected to make a cell. The cell potential will be","options":{"A":"$+1\\cdot19$ V","B":"$+0\\cdot89$ V","C":"$+0\\cdot18$ V","D":"$+1\\cdot83$ V"},"answer":"B","hint":"$E^\\circ_\\mathrm{cell} = E^\\circ_\\mathrm{cathode} - E^\\circ_\\mathrm{anode}$.","explanation":"Cathode is Sn4+/Sn2+, anode Cr3+/Cr: 0.15 - (-0.74) = +0.89 V.","difficulty":1,"sources":[[2025,"R","56/1/1",2],[2025,"R","56/1/2",15]]},{"id":"c0522","chapter":4,"type":"mcq","text":"The magnetic moment is associated with its spin angular momentum and orbital angular momentum. Spin only magnetic moment value of $\\mathrm{Cr^{3+}}$ ion (Atomic no. : Cr = 24) is ________.","options":{"A":"2.87 B.M.","B":"3.87 B.M.","C":"3.47 B.M.","D":"3.57 B.M."},"answer":"B","hint":"Count unpaired electrons and use $\\sqrt{n(n+2)}$.","explanation":"Cr3+ is $3d^3$ with n = 3, so mu = sqrt(15) = 3.87 B.M.","difficulty":1,"sources":[[2025,"R","56/1/1",3],[2025,"R","56/1/2",14],[2025,"R","56/1/3",2]]},{"id":"c0523","chapter":4,"type":"mcq","text":"Acidified $\\mathrm{KMnO_4}$ oxidises sulphite to","options":{"A":"$\\mathrm{S_2O_3^{2-}}$","B":"$\\mathrm{S_2O_8^{2-}}$","C":"$\\mathrm{SO_2(g)}$","D":"$\\mathrm{SO_4^{2-}}$"},"answer":"D","hint":"Permanganate is a strong oxidant.","explanation":"Sulphite is oxidised to sulphate.","difficulty":1,"sources":[[2025,"R","56/1/1",4],[2025,"R","56/1/2",13],[2025,"R","56/1/3",8]]},{"id":"c0524","chapter":5,"type":"mcq","text":"The correct IUPAC name of $\\mathrm{[Pt(NH_3)_2Cl_2]^{2+}}$ is","options":{"A":"Diamminedichloridoplatinum (II)","B":"Diamminedichloridoplatinum (IV)","C":"Diamminedichloridoplatinum (O)","D":"Diamminedichloridoplatinate (IV)"},"answer":"B","hint":"Find oxidation state from the overall charge of +2.","explanation":"x + 0 + 2(-1) = +2 gives x = +4; cationic complex so no -ate.","difficulty":2,"sources":[[2025,"R","56/1/1",5],[2025,"R","56/1/2",12],[2025,"R","56/1/3",6]]},{"id":"c0525","chapter":6,"type":"mcq","text":"Arrange the following compounds in increasing order of their boiling points :\n(i) isobutyl bromide, $\\mathrm{(CH_3)_2CH-CH_2Br}$  (ii) $\\mathrm{CH_3CH_2CH_2CH_2Br}$  (iii) tert-butyl bromide, $\\mathrm{(CH_3)_3C-Br}$\nThe correct order is","options":{"A":"(ii) < (i) < (iii)","B":"(i) < (ii) < (iii)","C":"(iii) < (i) < (ii)","D":"(iii) < (ii) < (i)"},"answer":"C","hint":"Among isomeric halides, branching lowers boiling point.","explanation":"Boiling point rises with decreasing branching: tertiary (iii) < isobutyl (i) < n-butyl (ii).","difficulty":2,"figure":"figures/c0525.png","sources":[[2025,"R","56/1/1",6]]},{"id":"c0526","chapter":6,"type":"mcq","text":"Alkyl halides undergoing nucleophilic bimolecular substitution reaction involve","options":{"A":"retention of configuration","B":"formation of racemic mixture","C":"inversion of configuration","D":"formation of carbocation"},"answer":"C","hint":"Backside attack in $\\mathrm{S_N2}$.","explanation":"SN2 proceeds by backside attack giving inversion of configuration.","difficulty":1,"sources":[[2025,"R","56/1/1",7],[2025,"R","56/1/2",10],[2025,"R","56/1/3",4]]},{"id":"c0527","chapter":7,"type":"mcq","text":"Which is the correct order of acid strength from the following ?","options":{"A":"$\\mathrm{C_6H_5OH > H_2O > ROH}$","B":"$\\mathrm{C_6H_5OH > ROH > H_2O}$","C":"$\\mathrm{ROH > C_6H_5OH > H_2O}$","D":"$\\mathrm{H_2O > C_6H_5OH > ROH}$"},"answer":"A","hint":"Phenoxide is resonance stabilised; alkoxide is destabilised by +I.","explanation":"Phenol is more acidic than water, which is more acidic than alcohols.","difficulty":1,"sources":[[2025,"R","56/1/1",8],[2025,"R","56/1/2",9],[2025,"R","56/1/3",9]]},{"id":"c0528","chapter":8,"type":"mcq","text":"The acid formed when propyl magnesium bromide is treated with $\\mathrm{CO_2}$ followed by acid hydrolysis is :","options":{"A":"$\\mathrm{C_3H_7COOH}$","B":"$\\mathrm{C_2H_5COOH}$","C":"$\\mathrm{CH_3COOH}$","D":"$\\mathrm{C_3H_7OH}$"},"answer":"A","hint":"Grignard reagent adds one carbon from CO2.","explanation":"C3H7MgBr + CO2 then H3O+ gives butanoic acid, C3H7COOH.","difficulty":1,"sources":[[2025,"R","56/1/1",9],[2025,"R","56/1/2",8],[2025,"R","56/1/3",7]]},{"id":"c0529","chapter":9,"type":"mcq","text":"The best reagent for converting propanamide into propanamine is ________.","options":{"A":"excess $\\mathrm{H_2}$","B":"$\\mathrm{Br_2}$ in aqueous NaOH","C":"iodine in the presence of red phosphorus","D":"$\\mathrm{LiAlH_4}$ in ether"},"answer":"D","hint":"Same carbon count must be retained.","explanation":"LiAlH4 reduces amide to amine with same carbons; Br2/NaOH (Hofmann) would give ethanamine.","difficulty":2,"sources":[[2025,"R","56/1/1",10],[2025,"R","56/1/2",7],[2025,"R","56/1/3",11]]},{"id":"c0530","chapter":10,"type":"mcq","text":"Which of the following statements is not true about glucose ?","options":{"A":"It is an aldohexose.","B":"On heating with HI it forms n-hexane.","C":"It exists in furanose form.","D":"It does not give Schiff's test."},"answer":"C","hint":"Glucose ring form is six-membered.","explanation":"Glucose exists in the pyranose form, not furanose; the other statements are true.","difficulty":2,"sources":[[2025,"R","56/1/1",11],[2025,"R","56/1/2",6],[2025,"R","56/1/3",12]]},{"id":"c0531","chapter":1,"type":"mcq","text":"An unripe mango placed in a concentrated salt solution to prepare pickle, shrivels because ________.","options":{"A":"it gains water due to osmosis","B":"it loses water due to reverse osmosis","C":"it gains water due to reverse osmosis","D":"it loses water due to osmosis"},"answer":"D","hint":"Water moves toward the more concentrated solution.","explanation":"Water flows out of the mango into the hypertonic salt solution by osmosis.","difficulty":1,"sources":[[2025,"R","56/1/1",12],[2025,"R","56/1/2",5],[2025,"R","56/1/3",10],[2026,"C","56(B)/7",2]]},{"id":"c0532","chapter":5,"type":"ar","text":"Assertion (A): $\\mathrm{[Cr(H_2O)_6]Cl_2}$ and $\\mathrm{[Fe(H_2O)_6]Cl_2}$ are examples of homoleptic complexes.\nReason (R): All the ligands attached to the metal are the same.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Define homoleptic.","explanation":"Both true; homoleptic means all ligands are identical, which is the case here.","difficulty":1,"sources":[[2025,"R","56/1/1",13],[2025,"R","56/1/2",4],[2025,"R","56/1/3",16]]},{"id":"c0533","chapter":6,"type":"ar","text":"Assertion (A): The boiling points of alkyl halides decrease in the order: $\\mathrm{RI > RBr > RCl > RF}$.\nReason (R): The boiling points of alkyl chlorides, bromides and iodides are considerably higher than that of the hydrocarbon of comparable molecular mass.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Compare boiling-point trend with size and polarisability, and check what R actually explains.","explanation":"A true (larger, more polarisable halogen, stronger van der Waals forces); R true (dipole-dipole attractions) but it does not explain the order among halides.","difficulty":2,"sources":[[2025,"R","56/1/1",14],[2025,"R","56/1/2",3],[2025,"R","56/1/3",15]]},{"id":"c0534","chapter":7,"type":"ar","text":"Assertion (A): The boiling point of ethanol is higher than that of methoxymethane.\nReason (R): There is intramolecular hydrogen bonding in ethanol.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Ask what kind of hydrogen bonding ethanol can form.","explanation":"A true (ethanol forms intermolecular H-bonds, ether cannot); R false because the H-bonding in ethanol is intermolecular.","difficulty":1,"sources":[[2025,"R","56/1/1",15],[2025,"R","56/1/2",2],[2025,"R","56/1/3",14]]},{"id":"c0535","chapter":10,"type":"ar","text":"Assertion (A): All naturally occurring $\\alpha$-amino acids except glycine are optically active.\nReason (R): Most naturally occurring amino acids have L-configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Think about which carbon makes amino acids chiral and what L/D describes.","explanation":"A true (only glycine lacks a chiral carbon); R true (L-amino acids dominate in nature), but L-configuration describes the arrangement, not the cause of optical activity, so R does not explain A.","difficulty":2,"sources":[[2025,"R","56/1/1",16],[2025,"R","56/1/2",1],[2025,"R","56/1/3",13]]},{"id":"c0536","chapter":6,"type":"mcq","text":"Arrange the following compounds in increasing order of their boiling points:\n(i) $\\mathrm{(CH_3)_2CH-CH_2Br}$ (drawn as a structure)\n(ii) $\\mathrm{CH_3CH_2CH_2CH_2Br}$\n(iii) $\\mathrm{(CH_3)_3C-Br}$ (drawn as a structure)\nThe correct order is","options":{"A":"(ii) < (i) < (iii)","B":"(i) < (ii) < (iii)","C":"(iii) < (i) < (ii)","D":"(iii) < (ii) < (i)"},"answer":"C","hint":"Branching lowers surface area and boiling point.","explanation":"Among isomeric bromobutanes, the straight chain has the highest boiling point and the most branched tertiary isomer the lowest: (iii) < (i) < (ii).","difficulty":2,"figure":"figures/c0536.png","sources":[[2025,"R","56/1/2",11]]},{"id":"c0537","chapter":2,"type":"mcq","text":"Standard electrode potential for $\\mathrm{Sn^{4+}/Sn^{2+}}$ couple is $+0.15\\ \\mathrm{V}$ and that for the $\\mathrm{Cr^{3+}/Cr}$ couple is $-0.74\\ \\mathrm{V}$. The two couples in their standard states are connected to make a cell. The cell potential will be","options":{"A":"$+1.19\\ \\mathrm{V}$","B":"$+0.89\\ \\mathrm{V}$","C":"$+0.18\\ \\mathrm{V}$","D":"$+1.83\\ \\mathrm{V}$"},"answer":"B","hint":"$E^\\circ_\\mathrm{cell}=E^\\circ_\\mathrm{cathode}-E^\\circ_\\mathrm{anode}$.","explanation":"Cr is the anode: $E^\\circ_\\mathrm{cell}=0.15-(-0.74)=+0.89\\ \\mathrm{V}$.","difficulty":1,"sources":[[2025,"R","56/1/3",1]]},{"id":"c0538","chapter":6,"type":"mcq","text":"Arrange the following compounds in increasing order of their boiling points :\n(i) $\\mathrm{(CH_3)_2CH{-}CH_2Br}$ (ii) $\\mathrm{CH_3CH_2CH_2CH_2Br}$ (iii) $\\mathrm{(CH_3)_3C{-}Br}$\nThe correct order is","options":{"A":"(ii) < (i) < (iii)","B":"(i) < (ii) < (iii)","C":"(iii) < (i) < (ii)","D":"(iii) < (ii) < (i)"},"answer":"C","hint":"More branching means smaller surface area and lower boiling point.","explanation":"Isomeric bromides: the most branched (iii) boils lowest and the straight chain (ii) highest, so (iii) < (i) < (ii).","difficulty":2,"sources":[[2025,"R","56/1/3",5]]},{"id":"c0539","chapter":2,"type":"mcq","text":"The charge required for the reduction of 1 mol of $\\mathrm{MnO_4^-}$ to $\\mathrm{MnO_2}$ is","options":{"A":"$\\mathrm{1\\,F}$","B":"$\\mathrm{3\\,F}$","C":"$\\mathrm{5\\,F}$","D":"$\\mathrm{6\\,F}$"},"answer":"B","hint":"Find the change in oxidation state of Mn.","explanation":"Mn goes from +7 to +4, a gain of 3 electrons, so 3 F are needed per mole.","difficulty":1,"sources":[[2025,"R","56/2/1",1],[2025,"R","56/2/2",16],[2025,"R","56/2/3",2]]},{"id":"c0540","chapter":3,"type":"mcq","text":"Which among the following is a false statement?","options":{"A":"Rate of zero order reaction is independent of initial concentration of reactant.","B":"Half-life of a zero order reaction is inversely proportional to the rate constant.","C":"Molecularity of a reaction may be zero.","D":"For a first order reaction, $t_{1/2} = 0.693/k$."},"answer":"C","hint":"Molecularity is the number of reacting species in an elementary step.","explanation":"Molecularity cannot be zero; it is a positive whole number.","difficulty":1,"sources":[[2025,"R","56/2/1",2],[2025,"R","56/2/2",15],[2025,"R","56/2/3",1]]},{"id":"c0541","chapter":3,"type":"mcq","text":"The number of molecules that react with each other in an elementary reaction is a measure of the:","options":{"A":"activation energy of the reaction","B":"stoichiometry of the reaction","C":"molecularity of the reaction","D":"order of the reaction"},"answer":"C","hint":"Think of the definition of molecularity.","explanation":"The number of molecules colliding in an elementary step is its molecularity.","difficulty":1,"sources":[[2025,"R","56/2/1",3],[2025,"R","56/2/3",4]]},{"id":"c0542","chapter":4,"type":"mcq","text":"The element having $\\mathrm{[Ar]3d^{10}4s^1}$ electronic configuration is","options":{"A":"Cu","B":"Zn","C":"Cr","D":"Mn"},"answer":"A","hint":"Recall the exceptional configuration in group 11.","explanation":"Copper has the anomalous $3d^{10}4s^1$ configuration (stable filled d subshell).","difficulty":1,"sources":[[2025,"R","56/2/1",4],[2025,"R","56/2/2",13],[2025,"R","56/2/3",3]]},{"id":"c0543","chapter":5,"type":"mcq","text":"The complex ions $\\mathrm{[Co(NH_3)_5(NO_2)]^{2+}}$ and $\\mathrm{[Co(NH_3)_5(ONO)]^{2+}}$ are called","options":{"A":"Ionization isomers","B":"Linkage isomers","C":"Co-ordination isomers","D":"Geometrical isomers"},"answer":"B","hint":"The ligand can bind through two different donor atoms.","explanation":"$\\mathrm{NO_2^-}$ binds through N (nitro) or O (nitrito), giving linkage isomers.","difficulty":1,"sources":[[2025,"R","56/2/1",5],[2025,"R","56/2/2",12],[2025,"R","56/2/3",6]]},{"id":"c0544","chapter":5,"type":"mcq","text":"The diamagnetic species is:\n[At. No. Co = 27, Fe = 26, Ni = 28]","options":{"A":"$\\mathrm{[Ni(CN)_4]^{2-}}$","B":"$\\mathrm{[NiCl_4]^{2-}}$","C":"$\\mathrm{[Fe(CN)_6]^{3-}}$","D":"$\\mathrm{[CoF_6]^{3-}}$"},"answer":"A","hint":"Count unpaired electrons; strong-field ligands and square planar geometry matter.","explanation":"$\\mathrm{Ni^{2+}}$ ($d^8$) with strong-field $\\mathrm{CN^-}$ is square planar with all electrons paired.","difficulty":2,"sources":[[2025,"R","56/2/1",6],[2025,"R","56/2/2",11],[2025,"R","56/2/3",5]]},{"id":"c0545","chapter":6,"type":"mcq","text":"Which is the correct IUPAC name for the compound shown (a benzene ring with a $\\mathrm{CH_3}$ group and a $\\mathrm{Cl}$ atom at the para positions)?","options":{"A":"Methylchlorobenzene","B":"Toluene","C":"1-Chloro-4-methylbenzene","D":"1-Methyl-4-chlorobenzene"},"answer":"C","hint":"Substituents are cited alphabetically with lowest locants.","explanation":"Chloro precedes methyl alphabetically, giving 1-chloro-4-methylbenzene.","difficulty":1,"figure":"figures/c0545.png","sources":[[2025,"R","56/2/1",7],[2025,"R","56/2/2",10],[2025,"R","56/2/3",8]]},{"id":"c0546","chapter":7,"type":"mcq","text":"What will be formed after oxidation reaction of secondary alcohol with chromic anhydride ($\\mathrm{CrO_3}$)?","options":{"A":"Aldehyde","B":"Ketone","C":"Carboxylic acid","D":"Ester"},"answer":"B","hint":"A secondary alcohol has one H on the carbinol carbon.","explanation":"Secondary alcohols are oxidised to ketones.","difficulty":1,"sources":[[2025,"R","56/2/1",8],[2025,"R","56/2/2",9],[2025,"R","56/2/3",7]]},{"id":"c0547","chapter":7,"type":"mcq","text":"The conversion of phenol to salicylic acid can be accomplished by","options":{"A":"Reimer-Tiemann reaction","B":"Friedel-Crafts reaction","C":"Kolbe reaction","D":"Coupling reaction"},"answer":"C","hint":"Sodium phenoxide reacts with carbon dioxide under pressure.","explanation":"Kolbe reaction (phenoxide + $\\mathrm{CO_2}$, then acidification) gives salicylic acid.","difficulty":1,"sources":[[2025,"R","56/2/1",9],[2025,"R","56/2/2",8],[2025,"R","56/2/3",10]]},{"id":"c0548","chapter":10,"type":"mcq","text":"Which of the following is/are examples of denaturation of protein?","options":{"A":"Coagulation of egg white","B":"Curdling of milk","C":"Clotting of blood","D":"Both (A) and (B)"},"answer":"D","hint":"Denaturation destroys the secondary and tertiary structure.","explanation":"Boiling an egg and curdling of milk are denaturation; blood clotting is not.","difficulty":1,"sources":[[2025,"R","56/2/1",10],[2025,"R","56/2/2",7],[2025,"R","56/2/3",9]]},{"id":"c0549","chapter":10,"type":"mcq","text":"Nucleotides are joined together by","options":{"A":"Glycosidic linkage","B":"Peptide linkage","C":"Hydrogen bonding","D":"Phosphodiester linkage"},"answer":"D","hint":"Think of the backbone of DNA and RNA.","explanation":"Nucleotides are linked through phosphodiester bonds between sugar units.","difficulty":1,"sources":[[2025,"R","56/2/1",11],[2025,"R","56/2/2",6],[2025,"R","56/2/3",12]]},{"id":"c0550","chapter":10,"type":"mcq","text":"Scurvy is caused due to deficiency of","options":{"A":"Vitamin B1","B":"Vitamin B2","C":"Ascorbic acid","D":"Glutamic acid"},"answer":"C","hint":"Scurvy is linked to a vitamin found in citrus fruits.","explanation":"Deficiency of vitamin C (ascorbic acid) causes scurvy.","difficulty":1,"sources":[[2025,"R","56/2/1",12],[2025,"R","56/2/2",5],[2025,"R","56/2/3",11]]},{"id":"c0551","chapter":3,"type":"ar","text":"Assertion (A): In a first order reaction, if the concentration of the reactant is doubled, its half-life is also doubled.\nReason (R): The half-life of a reaction does not depend upon the initial concentration of the reactant in a first order reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Use $t_{1/2}=0.693/k$ for first order.","explanation":"A false (half-life is unchanged); R true.","difficulty":1,"sources":[[2025,"R","56/2/1",13],[2025,"R","56/2/2",4],[2025,"R","56/2/3",14]]},{"id":"c0552","chapter":2,"type":"ar","text":"Assertion (A): Cu cannot liberate $\\mathrm{H_2}$ on reaction with dilute mineral acids.\nReason (R): Cu has positive electrode potential.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Compare $E^\\circ$ of Cu with that of hydrogen.","explanation":"$E^\\circ(\\mathrm{Cu^{2+}/Cu})=+0.34$ V so Cu cannot reduce $\\mathrm{H^+}$; both true and R explains A.","difficulty":1,"sources":[[2025,"R","56/2/1",14],[2025,"R","56/2/2",3],[2025,"R","56/2/3",13]]},{"id":"c0553","chapter":9,"type":"ar","text":"Assertion (A): Aromatic primary amines cannot be prepared by Gabriel Phthalimide synthesis.\nReason (R): Aryl halides do not undergo nucleophilic substitution reaction with the anion formed by phthalimide.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Gabriel synthesis needs an alkyl halide for substitution.","explanation":"Aryl halides are unreactive to $S_N2$ with phthalimide anion, which is why aromatic amines cannot be made; R explains A.","difficulty":2,"sources":[[2025,"R","56/2/1",15],[2025,"R","56/2/2",2],[2025,"R","56/2/3",16]]},{"id":"c0554","chapter":10,"type":"ar","text":"Assertion (A): Vitamin D cannot be stored in our body.\nReason (R): Vitamin D is fat soluble vitamin and is not excreted from the body in urine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Fat-soluble vitamins accumulate in adipose tissue.","explanation":"A false (fat-soluble vitamin D is stored); R true.","difficulty":1,"sources":[[2025,"R","56/2/1",16],[2025,"R","56/2/2",1],[2025,"R","56/2/3",15]]},{"id":"c0555","chapter":2,"type":"mcq","text":"In an electrochemical cell, the following reaction takes place:\n$\\mathrm{2Cu^+(aq) + Zn(s) \\rightarrow 2Cu(s) + Zn^{2+}(aq)}$\n$E^\\circ_\\mathrm{cell} = 1.28\\ \\mathrm{V}$\nAs the reaction progresses, what will happen to the overall voltage of the cell?","options":{"A":"Voltage will remain constant.","B":"It will decrease as $\\mathrm{[Zn^{2+}]}$ increases.","C":"It will increase as $\\mathrm{[Cu^+]}$ increases.","D":"It will increase as $\\mathrm{[Zn^{2+}]}$ increases."},"answer":"B","hint":"Apply the Nernst equation with $Q=[\\mathrm{Zn^{2+}}]/[\\mathrm{Cu^+}]^2$.","explanation":"As the reaction proceeds $Q$ rises, so $E_\\mathrm{cell}=E^\\circ-\\frac{0.059}{2}\\log Q$ falls.","difficulty":2,"sources":[[2025,"R","56/4/1",1],[2025,"R","56/4/3",1]]},{"id":"c0556","chapter":4,"type":"mcq","text":"Out of $\\mathrm{Fe^{3+}}$, $\\mathrm{Sc^{3+}}$, $\\mathrm{Cr^{3+}}$ and $\\mathrm{Co^{3+}}$ ions, the one which is colourless in aqueous solution is:\n[Atomic number: Fe = 26, Sc = 21, Cr = 24, Co = 27]","options":{"A":"$\\mathrm{Sc^{3+}}$","B":"$\\mathrm{Fe^{3+}}$","C":"$\\mathrm{Cr^{3+}}$","D":"$\\mathrm{Co^{3+}}$"},"answer":"A","hint":"Colour needs unpaired d electrons for d-d transitions.","explanation":"$\\mathrm{Sc^{3+}}$ is $3d^0$, so no d-d transition and it is colourless.","difficulty":1,"sources":[[2025,"R","56/4/1",2]]},{"id":"c0557","chapter":9,"type":"mcq","text":"Hoffmann Bromamide degradation reaction is given by:","options":{"A":"$\\mathrm{ArNO_2}$","B":"$\\mathrm{ArNH_2}$","C":"$\\mathrm{ArCONH_2}$","D":"$\\mathrm{ArCH_2NH_2}$"},"answer":"C","hint":"The reaction starts from an amide.","explanation":"Amides react with $\\mathrm{Br_2}$/NaOH to give a primary amine with one carbon less, so $\\mathrm{ArCONH_2}$ undergoes it.","difficulty":1,"sources":[[2025,"R","56/4/1",3]]},{"id":"c0558","chapter":10,"type":"mcq","text":"In the Haworth structure of the following carbohydrate (drawn in the figure), various carbon atoms have been numbered. The anomeric carbon is numbered as:","options":{"A":"1","B":"2","C":"3","D":"5"},"answer":"A","hint":"The anomeric carbon is the former carbonyl carbon.","explanation":"C-1 is the aldehyde-derived carbon that forms the hemiacetal, so it is anomeric.","difficulty":1,"figure":"figures/c0558.png","sources":[[2025,"R","56/4/1",4],[2025,"R","56/4/2",6],[2025,"R","56/4/3",5]]},{"id":"c0559","chapter":1,"type":"mcq","text":"The value of Henry's constant $K_\\mathrm{H}$ is:","options":{"A":"greater for gases with higher solubility","B":"greater for gases with lower solubility","C":"constant for all gases","D":"not related to the solubility of gases"},"answer":"B","hint":"Use $p=K_\\mathrm{H}x$.","explanation":"At a given pressure higher $K_\\mathrm{H}$ means lower mole fraction dissolved, i.e. lower solubility.","difficulty":1,"sources":[[2025,"R","56/4/1",5],[2025,"R","56/4/2",7],[2025,"R","56/4/3",4]]},{"id":"c0560","chapter":4,"type":"mcq","text":"Out of the following statements, the incorrect statement is:","options":{"A":"La is actually an element of transition series.","B":"Zr and Hf have almost identical atomic radii because of lanthanoid contraction.","C":"Ionic radius decreases from $\\mathrm{La^{3+}}$ to $\\mathrm{Lu^{3+}}$ ion.","D":"Lanthanoids are radioactive in nature."},"answer":"D","hint":"Only one lanthanoid is radioactive.","explanation":"Lanthanoids are not radioactive in general (only Pm is), so D is incorrect.","difficulty":2,"sources":[[2025,"R","56/4/1",6],[2025,"R","56/4/2",8]]},{"id":"c0561","chapter":6,"type":"mcq","text":"Out of 2-Bromobutane, 1-Bromobutane, 2-Bromopropane and 1-Bromopropane, the molecule which is chiral in nature is:","options":{"A":"2-Bromobutane","B":"1-Bromobutane","C":"2-Bromopropane","D":"1-Bromopropane"},"answer":"A","hint":"Look for a carbon bonded to four different groups.","explanation":"In 2-bromobutane C-2 bears H, Br, $\\mathrm{CH_3}$ and $\\mathrm{C_2H_5}$, so it is chiral.","difficulty":1,"sources":[[2025,"R","56/4/1",7],[2025,"R","56/4/2",5],[2025,"R","56/4/3",8]]},{"id":"c0562","chapter":9,"type":"mcq","text":"In the given reaction sequence, the structure of Y would be:\nAniline $\\xrightarrow[0-5^\\circ\\mathrm{C}]{\\mathrm{NaNO_2/HCl}}$ X $\\xrightarrow{\\mathrm{C_2H_5OH}}$ Y\n(structures in the figure)","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"B","hint":"Ethanol can act as a reducing agent for diazonium salts.","explanation":"Benzenediazonium chloride is reduced by ethanol to benzene (with acetaldehyde), so Y is benzene.","difficulty":2,"figure":"figures/c0562.png","sources":[[2025,"R","56/4/1",8],[2025,"R","56/4/2",4],[2025,"R","56/4/3",7]]},{"id":"c0563","chapter":4,"type":"mcq","text":"The product of the oxidation of $\\mathrm{I^-}$ with $\\mathrm{MnO_4^-}$ in alkaline medium is:","options":{"A":"$\\mathrm{IO_4^-}$","B":"$\\mathrm{I_2}$","C":"$\\mathrm{IO^-}$","D":"$\\mathrm{IO_3^-}$"},"answer":"D","hint":"Recall the behaviour of permanganate in alkaline medium.","explanation":"In alkaline medium iodide is oxidised to iodate: $\\mathrm{2MnO_4^- + H_2O + I^- \\rightarrow 2MnO_2 + 2OH^- + IO_3^-}$.","difficulty":2,"sources":[[2025,"R","56/4/1",9],[2025,"R","56/4/2",3]]},{"id":"c0564","chapter":6,"type":"mcq","text":"Polyhalogen compounds have wide application in industries and agriculture. DDT is also a very important polyhalogen compound. It is a:","options":{"A":"greenhouse gas","B":"fertilizer","C":"biodegradable insecticide","D":"non-biodegradable insecticide"},"answer":"D","hint":"DDT persists in the environment.","explanation":"DDT is an insecticide that is not broken down easily and accumulates in the food chain.","difficulty":1,"sources":[[2025,"R","56/4/1",10],[2025,"R","56/4/2",2],[2025,"R","56/4/3",12]]},{"id":"c0565","chapter":2,"type":"mcq","text":"What amount of electric charge is required for the reduction of 1 mole of $\\mathrm{MnO_4^-}$ into $\\mathrm{Mn^{2+}}$?","options":{"A":"$\\mathrm{1\\,F}$","B":"$\\mathrm{5\\,F}$","C":"$\\mathrm{4\\,F}$","D":"$\\mathrm{6\\,F}$"},"answer":"B","hint":"Find the change in oxidation state of Mn.","explanation":"Mn goes from +7 to +2, a gain of 5 electrons, so 5 F are needed.","difficulty":1,"sources":[[2025,"R","56/4/1",11]]},{"id":"c0566","chapter":7,"type":"mcq","text":"Alkenes are formed by heating alcohols with conc. $\\mathrm{H_2SO_4}$. The first step in the reaction is:","options":{"A":"formation of carbocation","B":"formation of ester","C":"protonation of alcohol molecule","D":"elimination of water"},"answer":"C","hint":"Think of how $\\mathrm{-OH}$ becomes a good leaving group.","explanation":"The alcohol oxygen is first protonated, then water leaves to give the carbocation.","difficulty":1,"sources":[[2025,"R","56/4/1",12],[2025,"R","56/4/2",1],[2025,"R","56/4/3",11]]},{"id":"c0567","chapter":2,"type":"ar","text":"Assertion (A): Electrolysis of aqueous NaCl gives $\\mathrm{H_2}$ at cathode and $\\mathrm{Cl_2}$ at anode.\nReason (R): Chlorine has higher oxidation potential than $\\mathrm{H_2O}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Compare oxidation of $\\mathrm{Cl^-}$ and water at the anode.","explanation":"A true; R false because water has the higher oxidation potential, and $\\mathrm{Cl_2}$ forms due to overpotential of $\\mathrm{O_2}$ evolution.","difficulty":3,"sources":[[2025,"R","56/4/1",13],[2025,"R","56/4/2",15],[2025,"R","56/4/3",16]]},{"id":"c0568","chapter":4,"type":"ar","text":"Assertion (A): Cuprous salts are diamagnetic.\nReason (R): Cuprous ion has completely filled 3d-orbitals.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Count unpaired electrons in $\\mathrm{Cu^+}$.","explanation":"$\\mathrm{Cu^+}$ is $3d^{10}$, no unpaired electrons, so it is diamagnetic; R explains A.","difficulty":1,"sources":[[2025,"R","56/4/1",14],[2025,"R","56/4/3",14]]},{"id":"c0569","chapter":6,"type":"ar","text":"Assertion (A): n-Butyl chloride has higher boiling point than n-Butyl bromide.\nReason (R): C - Cl bond is more polar than C - Br bond.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Compare size and molecular mass of the halogens.","explanation":"A false (bromide has larger mass and polarisability, so higher boiling point); R true.","difficulty":2,"sources":[[2025,"R","56/4/1",15],[2025,"R","56/4/2",16],[2025,"R","56/4/3",15]]},{"id":"c0570","chapter":9,"type":"ar","text":"Assertion (A): Acetanilide is less basic than aniline.\nReason (R): Acetylation of aniline results in decrease of electron density on nitrogen.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"The N lone pair is delocalised toward the carbonyl group.","explanation":"Both true: the acetyl C=O withdraws the N lone pair, lowering basicity, so R explains A.","difficulty":2,"sources":[[2025,"R","56/4/1",16],[2025,"R","56/4/3",13]]},{"id":"c0571","chapter":2,"type":"mcq","text":"In an electrochemical cell, the following reaction takes place:\n$\\mathrm{2Ag^+(aq) + Mg(s) \\rightarrow 2Ag(s) + Mg^{2+}(aq)}$\n$E^\\circ_\\mathrm{cell} = 2.96\\ \\mathrm{V}$\nAs the reaction progresses, what will happen to the overall voltage of the cell?","options":{"A":"Voltage will remain constant.","B":"It will decrease as $\\mathrm{[Mg^{2+}]}$ increases.","C":"It will increase as $\\mathrm{[Ag^+]}$ increases.","D":"It will increase as $\\mathrm{[Mg^{2+}]}$ increases."},"answer":"B","hint":"Apply the Nernst equation with $Q=[\\mathrm{Mg^{2+}}]/[\\mathrm{Ag^+}]^2$.","explanation":"As the reaction proceeds $Q$ rises, so $E_\\mathrm{cell}$ falls.","difficulty":2,"sources":[[2025,"R","56/4/2",9]]},{"id":"c0572","chapter":4,"type":"mcq","text":"Out of $\\mathrm{Ti^{3+}}$, $\\mathrm{Cr^{3+}}$, $\\mathrm{Mn^{2+}}$ and $\\mathrm{Ni^{2+}}$ ions, the one which has the highest magnetic moment is:\n[Atomic number: Ti = 22, Cr = 24, Mn = 25, Ni = 28]","options":{"A":"$\\mathrm{Ti^{3+}}$","B":"$\\mathrm{Cr^{3+}}$","C":"$\\mathrm{Mn^{2+}}$","D":"$\\mathrm{Ni^{2+}}$"},"answer":"C","hint":"Magnetic moment grows with the number of unpaired electrons.","explanation":"Unpaired electrons: Ti$^{3+}$ 1, Cr$^{3+}$ 3, Mn$^{2+}$ 5, Ni$^{2+}$ 2, so Mn$^{2+}$ is highest.","difficulty":2,"sources":[[2025,"R","56/4/2",10]]},{"id":"c0573","chapter":9,"type":"mcq","text":"Hoffmann Bromamide degradation reaction is given by :","options":{"A":"$\\mathrm{CH_3NO_2}$","B":"$\\mathrm{CH_3NH_2}$","C":"$\\mathrm{CH_3CONH_2}$","D":"$\\mathrm{CH_3CH_2NH_2}$"},"answer":"C","hint":"The reaction starts from a primary amide.","explanation":"Hoffmann bromamide degradation converts an amide ($\\mathrm{RCONH_2}$) to a primary amine with one carbon less; so the substrate is acetamide.","difficulty":1,"sources":[[2025,"R","56/4/2",11]]},{"id":"c0574","chapter":2,"type":"mcq","text":"What amount of electric charge is required for the oxidation of 1 mole of $\\mathrm{H_2O}$ to $\\mathrm{O_2}$ ?","options":{"A":"1 F","B":"2 F","C":"3 F","D":"4 F"},"answer":"B","hint":"Write the half-reaction and count electrons per mole of water.","explanation":"$\\mathrm{2H_2O \\rightarrow O_2 + 4H^+ + 4e^-}$, so 2 mol water need 4 F; 1 mol needs 2 F.","difficulty":2,"sources":[[2025,"R","56/4/2",12]]},{"id":"c0575","chapter":4,"type":"ar","text":"Assertion (A): Cuprous salts are diamagnetic.\nReason (R): In cuprous ion, 3d-orbitals are partially filled.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Write the configuration of $\\mathrm{Cu^+}$.","explanation":"$\\mathrm{Cu^+}$ is $3d^{10}$: all electrons paired, so diamagnetic (A true), but the 3d subshell is completely filled, not partially (R false).","difficulty":1,"sources":[[2025,"R","56/4/2",13]]},{"id":"c0576","chapter":9,"type":"ar","text":"Assertion (A): Acetanilide is more basic than aniline.\nReason (R): Acetylation of aniline results in decrease of electron density on nitrogen.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Nitrogen lone pair is delocalised toward the carbonyl group in acetanilide.","explanation":"In acetanilide the N lone pair is drawn into the C=O group, lowering electron density on N, so it is less basic than aniline: A false, R true.","difficulty":2,"sources":[[2025,"R","56/4/2",14]]},{"id":"c0577","chapter":4,"type":"mcq","text":"Out of $\\mathrm{Ti^{3+}}$, $\\mathrm{Cr^{3+}}$, $\\mathrm{Fe^{2+}}$ and $\\mathrm{Ni^{2+}}$ ions, the one which is the most stable ion in aqueous solution is :\n[Atomic number : Ti = 22, Cr = 24, Fe = 26, Ni = 28]","options":{"A":"$\\mathrm{Ti^{3+}}$","B":"$\\mathrm{Cr^{3+}}$","C":"$\\mathrm{Fe^{2+}}$","D":"$\\mathrm{Ni^{2+}}$"},"answer":"B","hint":"Compare standard reduction potentials / $t_{2g}^3$ configuration.","explanation":"$\\mathrm{Cr^{3+}}$ ($3d^3$, half-filled $t_{2g}$) is very stable; $E^\\circ(\\mathrm{Cr^{3+}/Cr^{2+}})$ is negative, so it resists reduction and oxidation.","difficulty":2,"sources":[[2025,"R","56/4/3",2]]},{"id":"c0578","chapter":9,"type":"mcq","text":"Hoffmann Bromamide degradation reaction is given by :","options":{"A":"$\\mathrm{R-NO_2}$","B":"$\\mathrm{R-NH_2}$","C":"$\\mathrm{R-CH_2-NH_2}$","D":"$\\mathrm{R-CO-NH_2}$"},"answer":"D","hint":"The reaction starts from a primary amide.","explanation":"Amides $\\mathrm{RCONH_2}$ react with $\\mathrm{Br_2}$/NaOH to give $\\mathrm{RNH_2}$.","difficulty":1,"sources":[[2025,"R","56/4/3",3]]},{"id":"c0579","chapter":4,"type":"mcq","text":"Out of the following statements, the correct statement is :","options":{"A":"La is actually not an element of transition series.","B":"Zr and Hf have almost identical atomic radii.","C":"Lanthanoids are radioactive.","D":"Ionic radius increases from $\\mathrm{La^{3+}}$ to $\\mathrm{Lu^{3+}}$."},"answer":"B","hint":"Think of lanthanoid contraction.","explanation":"Lanthanoid contraction makes Zr and Hf nearly equal in size; ionic radii decrease from La to Lu, and only Pm is radioactive.","difficulty":2,"sources":[[2025,"R","56/4/3",6]]},{"id":"c0580","chapter":2,"type":"mcq","text":"What amount of electric charge is required for the oxidation of 1 mole of FeO to $\\mathrm{Fe_2O_3}$ ?","options":{"A":"1 F","B":"2 F","C":"3 F","D":"4 F"},"answer":"A","hint":"Find the change in oxidation state of iron.","explanation":"$\\mathrm{Fe^{2+} \\rightarrow Fe^{3+} + e^-}$: one electron per FeO, so 1 F per mole.","difficulty":2,"sources":[[2025,"R","56/4/3",10]]},{"id":"c0581","chapter":3,"type":"mcq","text":"The role of a catalyst is to change :","options":{"A":"equilibrium constant","B":"enthalpy of reaction","C":"Gibbs energy of reaction","D":"activation energy of reaction"},"answer":"D","hint":"A catalyst offers an alternative pathway.","explanation":"A catalyst lowers the activation energy; $K$, $\\Delta H$ and $\\Delta G$ are unchanged.","difficulty":1,"sources":[[2025,"R","56/5/1",1],[2025,"R","56/5/2",2],[2025,"R","56/5/3",3]]},{"id":"c0582","chapter":6,"type":"mcq","text":"Which of the following molecules is chiral in nature ?","options":{"A":"1-chloropropane","B":"2-chloropropane","C":"1-chlorobutane","D":"2-chlorobutane"},"answer":"D","hint":"Look for a carbon bearing four different groups.","explanation":"In 2-chlorobutane C-2 carries H, Cl, $\\mathrm{CH_3}$ and $\\mathrm{C_2H_5}$, so it is a stereocentre.","difficulty":1,"sources":[[2025,"R","56/5/1",2],[2025,"R","56/5/2",11],[2025,"R","56/5/3",4]]},{"id":"c0583","chapter":7,"type":"mcq","text":"$\\mathrm{CH_3CH_2OH}$ can be converted to $\\mathrm{CH_3CHO}$ by :","options":{"A":"catalytic hydrogenation","B":"treatment with $\\mathrm{LiAlH_4}$","C":"treatment with PCC","D":"treatment with $\\mathrm{KMnO_4}$"},"answer":"C","hint":"Need a mild oxidising agent that stops at the aldehyde.","explanation":"PCC oxidises primary alcohols to aldehydes without over-oxidation; $\\mathrm{KMnO_4}$ would give the acid.","difficulty":1,"sources":[[2025,"R","56/5/1",3],[2025,"R","56/5/2",4],[2025,"R","56/5/3",5]]},{"id":"c0584","chapter":9,"type":"mcq","text":"The IUPAC name for $\\mathrm{CH_3-CH_2-N(CH_3)-CH_2-CH_2-CH_3}$ is :","options":{"A":"N-methylpentan-2-amine","B":"N-ethyl-N-methylpropan-1-amine","C":"N,N-diethylpropan-1-amine","D":"N,N-dimethylpropan-1-amine"},"answer":"B","hint":"Choose the longest alkyl chain on N as parent and name the others as N-substituents.","explanation":"Parent is propyl (propan-1-amine); the other two groups on N are ethyl and methyl.","difficulty":2,"sources":[[2025,"R","56/5/1",4],[2025,"R","56/5/2",5],[2025,"R","56/5/3",6]]},{"id":"c0585","chapter":3,"type":"mcq","text":"A plot between concentration of reactant [R] and time 't' is shown below. Which of the given order of reaction is indicated by the graph ?","options":{"A":"Third order","B":"Second order","C":"First order","D":"Zero order"},"answer":"D","hint":"Which order gives a straight line for [R] vs t?","explanation":"A linear fall of [R] with t with $k = -\\text{slope}$ is characteristic of a zero order reaction.","difficulty":1,"figure":"figures/c0585.png","sources":[[2025,"R","56/5/1",5],[2025,"R","56/5/2",6],[2025,"R","56/5/3",7]]},{"id":"c0586","chapter":6,"type":"mcq","text":"The treatment of ethyl bromide with alcoholic silver nitrite gives :","options":{"A":"ethyl nitrite","B":"nitroethane","C":"nitromethane","D":"ethene"},"answer":"B","hint":"Silver nitrite is covalent, so N attacks.","explanation":"Covalent $\\mathrm{AgNO_2}$ attacks through nitrogen, giving the nitroalkane (nitroethane).","difficulty":2,"sources":[[2025,"R","56/5/1",6],[2025,"R","56/5/2",7],[2025,"R","56/5/3",8]]},{"id":"c0587","chapter":1,"type":"mcq","text":"Which of the following aqueous solutions will have the highest freezing point ?","options":{"A":"1.0 M KCl","B":"1.0 M $\\mathrm{Na_2SO_4}$","C":"1.0 M Glucose","D":"1.0 M $\\mathrm{AlCl_3}$"},"answer":"C","hint":"Smallest depression of freezing point means fewest particles.","explanation":"Glucose does not dissociate ($i=1$), so it has the smallest $\\Delta T_f$ and highest freezing point.","difficulty":1,"sources":[[2025,"R","56/5/1",7],[2025,"R","56/5/2",8],[2025,"R","56/5/3",9]]},{"id":"c0588","chapter":8,"type":"mcq","text":"Which of the following aldehydes will undergo Cannizzaro reaction ?","options":{"A":"$\\mathrm{CH_3-CH(CH_3)-CHO}$","B":"$\\mathrm{(CH_3)_3C\\,CHO}$","C":"$\\mathrm{CH_3-CH_2-CHO}$","D":"$\\mathrm{CH_3-CH(CH_3)-CH(CH_3)-CHO}$"},"answer":"B","hint":"Cannizzaro reaction needs an aldehyde with no alpha-hydrogen.","explanation":"Only $\\mathrm{(CH_3)_3CCHO}$ has no $\\alpha$-H, so it undergoes Cannizzaro; the others have $\\alpha$-H and give aldol reactions.","difficulty":2,"sources":[[2025,"R","56/5/1",8],[2025,"R","56/5/2",9],[2025,"R","56/5/3",10]]},{"id":"c0589","chapter":4,"type":"mcq","text":"In which of the following groups are both ions coloured in aqueous solution ?\nI. $\\mathrm{Cu^+}$   II. $\\mathrm{Ti^{4+}}$   III. $\\mathrm{Co^{2+}}$   IV. $\\mathrm{Fe^{2+}}$\n[Atomic number : Cu = 29, Ti = 22, Co = 27, Fe = 26]","options":{"A":"I and II","B":"II and III","C":"III and IV","D":"I and IV"},"answer":"C","hint":"Coloured ions need unpaired d electrons.","explanation":"$\\mathrm{Cu^+}$ ($3d^{10}$) and $\\mathrm{Ti^{4+}}$ ($3d^0$) are colourless; $\\mathrm{Co^{2+}}$ ($3d^7$) and $\\mathrm{Fe^{2+}}$ ($3d^6$) are coloured.","difficulty":1,"sources":[[2025,"R","56/5/1",9],[2025,"R","56/5/2",10],[2025,"R","56/5/3",11]]},{"id":"c0590","chapter":8,"type":"mcq","text":"$\\mathrm{CH_3CH_2CHO}$ and $\\mathrm{CH_3CH_2COOH}$ can be distinguished by :","options":{"A":"Sodium bicarbonate test","B":"Hinsberg test","C":"Iodoform test","D":"Lucas test"},"answer":"A","hint":"Which reagent reacts only with the acid?","explanation":"The carboxylic acid liberates $\\mathrm{CO_2}$ with $\\mathrm{NaHCO_3}$; the aldehyde does not (neither gives iodoform).","difficulty":1,"sources":[[2025,"R","56/5/1",10],[2025,"R","56/5/2",12],[2025,"R","56/5/3",1]]},{"id":"c0591","chapter":2,"type":"mcq","text":"Match the type of cell given in Column I with their use given in Column II.\nColumn I: i. Lead storage cell; ii. Mercury cell; iii. Dry cell; iv. Fuel cell\nColumn II: a. Wall clock; b. Apollo Space Programme; c. Wrist watch; d. Inverter","options":{"A":"i-a, ii-b, iii-c, iv-d","B":"i-d, ii-c, iii-a, iv-b","C":"i-c, ii-d, iii-b, iv-a","D":"i-b, ii-a, iii-d, iv-c"},"answer":"B","hint":"Recall the common uses of batteries.","explanation":"Lead storage cell: inverter; mercury cell: wrist watch; dry cell: wall clock; fuel cell: Apollo space programme.","difficulty":1,"sources":[[2025,"R","56/5/1",11],[2025,"R","56/5/2",3],[2025,"R","56/5/3",12]]},{"id":"c0592","chapter":4,"type":"mcq","text":"While doing qualitative analysis in chemistry lab, Abhishek added yellow coloured potassium chromate solution into a test tube. He was surprised to see the colour of the solution changing immediately to orange. He realised that the test tube was not clean and contained a few drops of some liquid. Which of the following substances will be the most likely liquid to be present in the test tube before adding potassium chromate solution ?","options":{"A":"Sodium hydrogen carbonate solution","B":"Methyl orange solution","C":"Sodium hydroxide solution","D":"HCl solution"},"answer":"D","hint":"Chromate-dichromate equilibrium depends on pH.","explanation":"Acid shifts $\\mathrm{2CrO_4^{2-} + 2H^+ \\rightleftharpoons Cr_2O_7^{2-} + H_2O}$ toward orange dichromate, so HCl was present.","difficulty":2,"sources":[[2025,"R","56/5/1",12],[2025,"R","56/5/2",1],[2025,"R","56/5/3",2]]},{"id":"c0593","chapter":2,"type":"ar","text":"Assertion (A): For measuring resistance of an ionic solution an AC source is used.\nReason (R): Concentration of ionic solution will change if DC source is used.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think of electrolysis under direct current.","explanation":"DC would cause electrolysis and change concentration near electrodes, so AC is used; R explains A.","difficulty":1,"sources":[[2025,"R","56/5/1",13],[2025,"R","56/5/2",14],[2025,"R","56/5/3",15]]},{"id":"c0594","chapter":1,"type":"ar","text":"Assertion (A): Henry's law constant ($K_\\mathrm{H}$) decreases with increase in temperature.\nReason (R): As the temperature increases, solubility of gases in liquids decreases.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Solubility is inversely related to $K_H$.","explanation":"Solubility falls with temperature (R true), so $K_H$ in $p = K_H x$ increases; A is false.","difficulty":2,"sources":[[2025,"R","56/5/1",14],[2025,"R","56/5/2",15],[2025,"R","56/5/3",16]]},{"id":"c0595","chapter":8,"type":"ar","text":"Assertion (A): The solubility of aldehydes and ketones in water decreases with increase in size of the alkyl group.\nReason (R): Aldehydes and ketones have dipole-dipole interaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Which factor actually lowers solubility with chain length?","explanation":"Both are true, but the decrease arises from the growing hydrophobic alkyl part, not from dipole-dipole interactions.","difficulty":2,"sources":[[2025,"R","56/5/1",15],[2025,"R","56/5/2",16],[2025,"R","56/5/3",13]]},{"id":"c0596","chapter":6,"type":"ar","text":"Assertion (A): The boiling points of alkyl halides decrease in the order RI > RBr > RCl > RF.\nReason (R): The van der Waals forces of attraction decrease in the order RI > RBr > RCl > RF.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Larger halogen means larger polarisable electron cloud.","explanation":"Greater size and polarisability of I give stronger van der Waals forces and thus higher boiling points; R explains A.","difficulty":1,"sources":[[2025,"R","56/5/1",16],[2025,"R","56/5/2",13],[2025,"R","56/5/3",14]]},{"id":"c0597","chapter":7,"type":"mcq","text":"Williamson synthesis of preparing unsymmetrical ether is :","options":{"A":"$\\mathrm{S_N1}$ reaction","B":"$\\mathrm{S_N2}$ reaction","C":"Electrophilic addition reaction","D":"Elimination reaction"},"answer":"B","hint":"Alkoxide attacks a primary alkyl halide.","explanation":"Williamson synthesis is a bimolecular nucleophilic substitution of alkyl halide by alkoxide ion.","difficulty":1,"sources":[[2025,"R","56/6/1",1]]},{"id":"c0598","chapter":6,"type":"mcq","text":"Which of the following compounds would be hydrolysed by aqueous KOH most easily ?","options":{"A":"$\\mathrm{CH_2=CH-Br}$","B":"$\\mathrm{CH_3-CH_2-Br}$","C":"$\\mathrm{CH_3-CH(Br)-CH_3}$","D":"$\\mathrm{CH_2=CH-CH_2-Br}$"},"answer":"D","hint":"Allylic halides give resonance-stabilised intermediates.","explanation":"Allyl bromide ionises to a resonance-stabilised allyl carbocation and is also reactive in $S_N2$, so it hydrolyses fastest; vinyl bromide is least reactive.","difficulty":2,"sources":[[2025,"R","56/6/1",2]]},{"id":"c0599","chapter":5,"type":"mcq","text":"According to Werner's theory of coordination compounds :","options":{"A":"Primary valences are ionisable.","B":"Secondary valences are ionisable.","C":"Both primary and secondary valences are non-ionisable.","D":"Both primary and secondary valences are ionisable."},"answer":"A","hint":"Recall which valence corresponds to oxidation state.","explanation":"In Werner's theory primary valences (oxidation state) are ionisable; secondary valences (coordination number) are non-ionisable.","difficulty":1,"sources":[[2025,"R","56/6/1",3]]},{"id":"c0600","chapter":5,"type":"mcq","text":"Which of the following complex ion is not optically active ?","options":{"A":"$\\mathrm{[Co(ox)_3]^{3-}}$","B":"cis-$\\mathrm{[Co(en)_2Cl_2]^+}$","C":"trans-$\\mathrm{[Co(en)_2Cl_2]^+}$","D":"$\\mathrm{[Co(en)_3]^{3+}}$"},"answer":"C","hint":"Optical activity needs a non-superimposable mirror image.","explanation":"The trans isomer has a plane of symmetry and is achiral; the tris-chelate and cis-bis-chelate complexes are chiral.","difficulty":2,"sources":[[2025,"R","56/6/1",4]]},{"id":"c0601","chapter":5,"type":"mcq","text":"Which of the following is the softest metal ?","options":{"A":"Zn","B":"Sc","C":"Cu","D":"Fe"},"answer":"A","hint":"Softness relates to size, polarisability and d-electron configuration.","explanation":"Official key gives Zn (filled $3d^{10}4s^2$, highly polarisable, lowest melting/softest physically).","difficulty":3,"note":"Official answer A (Zn).","sources":[[2025,"R","56/6/1",5]]},{"id":"c0602","chapter":9,"type":"mcq","text":"In the Hinsberg's method for separation of primary, secondary and tertiary amines, the reagent used is :","options":{"A":"Nitrous acid","B":"$\\mathrm{CHCl_3}$ + aq. NaOH","C":"Benzenesulfonyl chloride, $\\mathrm{C_6H_5SO_2Cl}$","D":"$\\mathrm{HCl / ZnCl_2}$"},"answer":"C","hint":"The reagent is a sulfonyl chloride.","explanation":"Hinsberg reagent is benzenesulfonyl chloride, which reacts differently with 1°, 2° and 3° amines.","difficulty":1,"sources":[[2025,"R","56/6/1",6]]},{"id":"c0603","chapter":9,"type":"mcq","text":"Which one of the following amines gives an alcohol on reaction with $\\mathrm{HNO_2}$ ?","options":{"A":"Aniline, $\\mathrm{C_6H_5NH_2}$","B":"$\\mathrm{C_2H_5NH_2}$","C":"$\\mathrm{(C_2H_5)_2NH}$","D":"$\\mathrm{(C_2H_5)_3N}$"},"answer":"B","hint":"Which class of amine gives a diazonium salt that decomposes?","explanation":"Aliphatic primary amines react with $\\mathrm{HNO_2}$ to give unstable diazonium salts that yield alcohols; aniline gives a stable diazonium salt at 273-278 K.","difficulty":2,"sources":[[2025,"R","56/6/1",7]]},{"id":"c0604","chapter":1,"type":"mcq","text":"The freezing point of one molal KCl solution, assuming KCl to be completely dissociated in water, is : ($K_f$ for water = 1.86 $\\mathrm{K\\,kg\\,mol^{-1}}$)","options":{"A":"$-3.72\\,{}^\\circ\\mathrm{C}$","B":"$+3.72\\,{}^\\circ\\mathrm{C}$","C":"$-1.86\\,{}^\\circ\\mathrm{C}$","D":"$+2.72\\,{}^\\circ\\mathrm{C}$"},"answer":"A","hint":"Use $\\Delta T_f = i K_f m$ with $i=2$.","explanation":"$\\Delta T_f = 2\\times1.86\\times1 = 3.72$ K; the freezing point is $0-3.72=-3.72\\,{}^\\circ\\mathrm{C}$.","difficulty":1,"sources":[[2025,"R","56/6/1",8],[2025,"R","56/6/2",9],[2025,"R","56/6/3",5]]},{"id":"c0605","chapter":1,"type":"mcq","text":"A solution of acetone in ethanol :","options":{"A":"obeys Raoult's law.","B":"forms an ideal solution.","C":"shows a positive deviation from Raoult's law.","D":"shows a negative deviation from Raoult's law."},"answer":"C","hint":"Acetone disrupts hydrogen bonding in ethanol.","explanation":"Acetone breaks the hydrogen bonds of ethanol, weakening interactions, so the vapour pressure is higher than ideal (positive deviation).","difficulty":2,"sources":[[2025,"R","56/6/1",9]]},{"id":"c0606","chapter":2,"type":"mcq","text":"Which of the following cell converts the energy of combustion of fuel into electrical energy ?","options":{"A":"Mercury cell","B":"Fuel cell","C":"Dry cell","D":"Lead storage cell"},"answer":"B","hint":"Name of the cell hints at the answer.","explanation":"A fuel cell converts the energy of combustion of fuels such as $\\mathrm{H_2}$ directly into electricity.","difficulty":1,"sources":[[2025,"R","56/6/1",10]]},{"id":"c0607","chapter":3,"type":"mcq","text":"The unit of rate and rate constant are same for a :","options":{"A":"First order reaction","B":"Second order reaction","C":"Zero order reaction","D":"Third order reaction"},"answer":"C","hint":"Compare rate = k[A]^n for each n.","explanation":"For $n=0$, rate $=k$, so both have unit $\\mathrm{mol\\,L^{-1}\\,s^{-1}}$.","difficulty":1,"sources":[[2025,"R","56/6/1",11]]},{"id":"c0608","chapter":10,"type":"mcq","text":"Pyranose ring of glucose is formed due to the reaction between :","options":{"A":"$\\mathrm{C_1}$ and $\\mathrm{C_3}$","B":"$\\mathrm{C_1}$ and $\\mathrm{C_5}$","C":"$\\mathrm{C_1}$ and $\\mathrm{C_4}$","D":"$\\mathrm{C_1}$ and $\\mathrm{C_2}$"},"answer":"B","hint":"A six-membered ring includes one oxygen.","explanation":"The C-5 hydroxyl adds to the C-1 aldehyde, forming a six-membered pyranose ring.","difficulty":1,"sources":[[2025,"R","56/6/1",12]]},{"id":"c0609","chapter":3,"type":"ar","text":"Assertion (A): Hydrolysis of an ester follows first order kinetics.\nReason (R): The concentration of water does not get altered much during the reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think pseudo first order reactions.","explanation":"Water is in large excess so its concentration is constant, making the hydrolysis pseudo first order; R explains A.","difficulty":2,"sources":[[2025,"R","56/6/1",14]]},{"id":"c0610","chapter":9,"type":"ar","text":"Assertion (A): Boiling point of $\\mathrm{(CH_3)_3N}$ is higher than that of $\\mathrm{CH_3CH_2CH_2NH_2}$.\nReason (R): Hydrogen bonding is more extensive in $\\mathrm{CH_3CH_2CH_2NH_2}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Tertiary amines cannot form N-H hydrogen bonds.","explanation":"Primary amine forms intermolecular H-bonds so it boils higher; A is false, R is true.","difficulty":2,"sources":[[2025,"R","56/6/1",15]]},{"id":"c0611","chapter":7,"type":"ar","text":"Assertion (A): Phenol is strongly acidic as compared to ethanol.\nReason (R): Phenoxide ion is more stable than ethoxide ion.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Compare stability of conjugate bases.","explanation":"Phenoxide is resonance stabilised, which makes phenol more acidic than ethanol; R explains A.","difficulty":1,"sources":[[2025,"R","56/6/1",16]]},{"id":"c0612","chapter":7,"type":"mcq","text":"Which by-product is obtained in the manufacture of phenol from cumene ?","options":{"A":"Acetaldehyde","B":"Acetone","C":"Anisole","D":"$o$-Cresol"},"answer":"B","hint":"Cumene hydroperoxide is cleaved in acid.","explanation":"Cumene is oxidised to cumene hydroperoxide, which on acid treatment gives phenol and acetone.","difficulty":1,"sources":[[2025,"R","56/6/2",1]]},{"id":"c0613","chapter":6,"type":"mcq","text":"Which reagents are required for one step conversion of chlorobenzene to toluene ?","options":{"A":"$\\mathrm{NaNO_2 + HCl}$","B":"$\\mathrm{CH_3Cl}$/Anhydrous $\\mathrm{AlCl_3}$","C":"$\\mathrm{CH_3Cl}$/Fe, Dark","D":"$\\mathrm{CH_3Cl}$, Na, Dry ether"},"answer":"D","hint":"Aryl halide plus alkyl halide with sodium.","explanation":"Wurtz-Fittig reaction: $\\mathrm{C_6H_5Cl + CH_3Cl + 2Na \\rightarrow C_6H_5CH_3 + 2NaCl}$ in dry ether.","difficulty":2,"sources":[[2025,"R","56/6/2",2],[2025,"R","56/6/3",2]]},{"id":"c0614","chapter":5,"type":"mcq","text":"Which of the following complexes shows geometrical isomerism ?","options":{"A":"$\\mathrm{[Co(NH_3)_6]^{3+}}$","B":"$\\mathrm{[Co(NH_3)_5Cl]^{2+}}$","C":"$\\mathrm{[Co(NH_3)_4Cl_2]^+}$","D":"$\\mathrm{[Co(NH_3)_5(ONO)]^{2+}}$"},"answer":"C","hint":"Look for an octahedral $\\mathrm{MA_4B_2}$ type.","explanation":"$\\mathrm{[Co(NH_3)_4Cl_2]^+}$ (MA$_4$B$_2$) exists as cis and trans forms; the others have no geometrical isomers.","difficulty":2,"sources":[[2025,"R","56/6/2",4]]},{"id":"c0615","chapter":4,"type":"mcq","text":"Which of the following does not show variable oxidation state ?","options":{"A":"Sc","B":"Mn","C":"Cr","D":"Cu"},"answer":"A","hint":"Check for more than one stable d-electron count.","explanation":"Sc shows only +3 (loses $3d^1 4s^2$); Mn, Cr and Cu show several oxidation states.","difficulty":1,"sources":[[2025,"R","56/6/2",5]]},{"id":"c0616","chapter":9,"type":"mcq","text":"The reagent that can be used to convert benzenediazonium chloride to benzene is :","options":{"A":"Cu/HCl","B":"$\\mathrm{H_2O}$","C":"$\\mathrm{CH_3CH_2OH}$","D":"CuCN"},"answer":"C","hint":"A mild reducing agent replaces $\\mathrm{N_2^+}$ by H.","explanation":"Ethanol (or hypophosphorous acid) reduces the diazonium salt to benzene with loss of $\\mathrm{N_2}$.","difficulty":2,"sources":[[2025,"R","56/6/2",6],[2025,"R","56/6/3",6]]},{"id":"c0617","chapter":9,"type":"mcq","text":"The gas evolved when methylamine reacts with $\\mathrm{HNO_2}$ is :","options":{"A":"NO","B":"$\\mathrm{N_2}$","C":"$\\mathrm{NH_3}$","D":"$\\mathrm{NO_2}$"},"answer":"B","hint":"Primary aliphatic amine gives an unstable diazonium salt.","explanation":"$\\mathrm{CH_3NH_2 + HNO_2 \\rightarrow CH_3OH + N_2 + H_2O}$; nitrogen gas is evolved.","difficulty":1,"sources":[[2025,"R","56/6/2",7]]},{"id":"c0618","chapter":1,"type":"mcq","text":"A solution of acetone in chloroform :","options":{"A":"obeys Raoult's law.","B":"forms azeotrope.","C":"shows a positive deviation from Raoult's law.","D":"shows a negative deviation from Raoult's law."},"answer":"D","hint":"Acetone and chloroform can hydrogen bond.","explanation":"Hydrogen bonding between $\\mathrm{CHCl_3}$ and acetone strengthens interactions, giving negative deviation.","difficulty":2,"sources":[[2025,"R","56/6/2",8]]},{"id":"c0619","chapter":2,"type":"mcq","text":"A galvanic cell can behave like an electrolytic cell when","options":{"A":"$E_\\mathrm{cell} = E_\\mathrm{ext}$","B":"$E_\\mathrm{ext} > E_\\mathrm{cell}$","C":"$E_\\mathrm{cell} > E_\\mathrm{ext}$","D":"$E_\\mathrm{cell} = 0$"},"answer":"B","hint":"Which source forces the reaction in reverse?","explanation":"When an external potential exceeds the cell's emf, the reaction is reversed and the cell acts as an electrolytic cell.","difficulty":1,"sources":[[2025,"R","56/6/2",10]]},{"id":"c0620","chapter":3,"type":"mcq","text":"The value of rate constant for a pseudo first order reaction :","options":{"A":"depends only on temperature.","B":"depends on the concentration of reactants present in small amount.","C":"depends on the concentration of reactants present in large excess.","D":"is not dependent on the concentration of reactants."},"answer":"C","hint":"Pseudo rate constant absorbs the excess reactant's concentration.","explanation":"For rate $=k[A][B]$ with B in large excess, $k' = k[B]$, so it depends on the excess reactant's concentration.","difficulty":2,"sources":[[2025,"R","56/6/2",11]]},{"id":"c0621","chapter":10,"type":"mcq","text":"Furanose ring of fructose is formed due to reaction between :","options":{"A":"$\\mathrm{C_1}$ and $\\mathrm{C_5}$","B":"$\\mathrm{C_2}$ and $\\mathrm{C_5}$","C":"$\\mathrm{C_1}$ and $\\mathrm{C_4}$","D":"$\\mathrm{C_1}$ and $\\mathrm{C_2}$"},"answer":"B","hint":"Fructose has its keto group at C-2.","explanation":"The C-5 hydroxyl adds to the C-2 keto group giving a five-membered furanose ring.","difficulty":2,"sources":[[2025,"R","56/6/2",12]]},{"id":"c0622","chapter":3,"type":"ar","text":"Assertion (A): Order of the reaction can be zero or fractional.\nReason (R): We cannot determine order from balanced chemical equation.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Order is found experimentally.","explanation":"Order can be zero or fractional (A true) because it comes from experiment and not stoichiometry (R true), explaining A.","difficulty":2,"sources":[[2025,"R","56/6/2",14]]},{"id":"c0623","chapter":9,"type":"ar","text":"Assertion (A): Boiling point of $\\mathrm{(C_2H_5)_2NH}$ is lower than that of $\\mathrm{n\\text{-}C_4H_9NH_2}$.\nReason (R): Hydrogen bonding is much more extensive in $\\mathrm{n\\text{-}C_4H_9NH_2}$ as compared to $\\mathrm{(C_2H_5)_2NH}$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Primary amines have two N-H bonds for H-bonding.","explanation":"Isomeric amines: primary amine has more extensive hydrogen bonding and a more linear shape, so boils higher; R explains A.","difficulty":2,"sources":[[2025,"R","56/6/2",15],[2025,"R","56/6/3",15]]},{"id":"c0624","chapter":7,"type":"ar","text":"Assertion (A): Phenol is less acidic than alcohol.\nReason (R): Phenoxide ion is more stable than alkoxide ion.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Compare acidity via conjugate base stability.","explanation":"Phenol is more acidic than alcohols (A false) because phenoxide is resonance stabilised (R true).","difficulty":1,"sources":[[2025,"R","56/6/2",16]]},{"id":"c0625","chapter":7,"type":"mcq","text":"During dehydration of alcohol to alkene by heating with conc. $\\mathrm{H_2SO_4}$, the initiation step is :","options":{"A":"Formation of an ester","B":"Formation of carbocation","C":"Protonation of alcohol","D":"Elimination of water"},"answer":"C","hint":"Think of the first mechanistic step with an acid.","explanation":"Step 1 is protonation of the alcohol OH to form alkyloxonium ion, then water leaves to give the carbocation.","difficulty":1,"sources":[[2025,"R","56/6/3",1]]},{"id":"c0626","chapter":5,"type":"mcq","text":"Which of the following complexes show linkage isomerism ?","options":{"A":"$\\mathrm{[Co(NH_3)_5Cl]^{2+}}$","B":"$\\mathrm{[Co(NH_3)_4Cl_2]Br_2}$","C":"$\\mathrm{[Co(H_2O)_6]^{3+}}$","D":"$\\mathrm{[Co(NH_3)_5(ONO)]^{2+}}$"},"answer":"D","hint":"Need an ambidentate ligand.","explanation":"$\\mathrm{NO_2^-}$ (bound via O as ONO or via N as $\\mathrm{NO_2}$) is ambidentate, giving linkage isomers.","difficulty":1,"sources":[[2025,"R","56/6/3",3]]},{"id":"c0627","chapter":4,"type":"mcq","text":"Which of the following transition metals has the highest melting point ?","options":{"A":"Sc","B":"Cr","C":"Mn","D":"Zn"},"answer":"B","hint":"Melting point peaks where d-electrons give most metallic bonding.","explanation":"Cr has $3d^5 4s^1$, the most unpaired electrons available for metallic bonding among these, giving the highest melting point.","difficulty":2,"sources":[[2025,"R","56/6/3",4]]},{"id":"c0628","chapter":9,"type":"mcq","text":"The strongest base in aqueous solution among the following amines is :","options":{"A":"$\\mathrm{(C_2H_5)_2NH}$","B":"$\\mathrm{(C_2H_5)_3N}$","C":"$\\mathrm{C_2H_5NH_2}$","D":"$\\mathrm{C_6H_5NH_2}$"},"answer":"A","hint":"Balance +I effect against solvation in water.","explanation":"In water the order for ethyl amines is secondary > primary > tertiary; aniline is far weaker.","difficulty":2,"sources":[[2025,"R","56/6/3",7]]},{"id":"c0629","chapter":1,"type":"mcq","text":"On mixing 30 mL of acetone with 20 mL of chloroform, the total volume of solution is :","options":{"A":"equal to 10 mL","B":"less than 50 mL","C":"greater than 50 mL","D":"equal to 50 mL"},"answer":"B","hint":"Consider the type of deviation for acetone-chloroform.","explanation":"The mixture shows negative deviation (stronger interactions), so $\\Delta V_\\mathrm{mix}<0$ and volume is less than 50 mL.","difficulty":2,"sources":[[2025,"R","56/6/3",8]]},{"id":"c0630","chapter":2,"type":"mcq","text":"We cannot measure the resistance of an ionic solution using DC because :","options":{"A":"it changes the composition of the solution.","B":"it can cause sparks and shocks.","C":"it does not affect the composition of the solution.","D":"it converts electrolytic cell to galvanic cell."},"answer":"A","hint":"Direct current causes electrolysis.","explanation":"DC causes electrolysis at the electrodes, altering the solution's concentration, so AC is used.","difficulty":1,"sources":[[2025,"R","56/6/3",9]]},{"id":"c0631","chapter":5,"type":"mcq","text":"The primary and secondary valences of Co in $\\mathrm{[Co(en)_3]Cl_3}$ respectively are :","options":{"A":"3, 3","B":"0, 3","C":"6, 3","D":"3, 6"},"answer":"D","hint":"Primary valence = oxidation state; secondary = coordination number.","explanation":"Co is $+3$ (primary valence 3) and en is bidentate, three of them give coordination number 6 (secondary valence 6).","difficulty":2,"sources":[[2025,"R","56/6/3",10]]},{"id":"c0632","chapter":3,"type":"mcq","text":"In the Arrhenius equation $k = Ae^{-E_a/RT}$, 'A' represents :","options":{"A":"effective collisions","B":"frequency factor","C":"fraction of collisions","D":"threshold energy"},"answer":"B","hint":"A is the pre-exponential term.","explanation":"A is the frequency (pre-exponential) factor, related to collision frequency and orientation.","difficulty":1,"sources":[[2025,"R","56/6/3",11]]},{"id":"c0633","chapter":10,"type":"mcq","text":"$\\alpha$-D-glucose and $\\beta$-D-glucose differ from each other with respect to the :","options":{"A":"size of the hemiacetal ring","B":"configuration at the $\\mathrm{C_2}$ carbon","C":"number of $-$OH groups","D":"configuration at the $\\mathrm{C_1}$ carbon"},"answer":"D","hint":"Anomers differ at the new stereocentre formed on ring closure.","explanation":"They are anomers differing in configuration at the anomeric carbon C-1.","difficulty":1,"sources":[[2025,"R","56/6/3",12]]},{"id":"c0634","chapter":4,"type":"ar","text":"Assertion (A): Actinoid contraction is greater from element to element than lanthanoid contraction.\nReason (R): Actinoids show wide range of oxidation states.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Poorer shielding by 5f electrons; check whether R explains it.","explanation":"A is true (5f electrons shield poorly). R is also true but is not the reason for the greater contraction.","difficulty":2,"sources":[[2025,"R","56/6/3",13]]},{"id":"c0635","chapter":3,"type":"ar","text":"Assertion (A): Molecularity of reaction is determined experimentally.\nReason (R): Molecularity is applicable only for an elementary reaction and not for a complex reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Molecularity is a theoretical concept; order is experimental.","explanation":"A is false since molecularity is theoretical (order is found experimentally). R is true.","difficulty":1,"sources":[[2025,"R","56/6/3",14]]},{"id":"c0636","chapter":7,"type":"ar","text":"Assertion (A): The bond angle $\\mathrm{C-O-C}$ in ethers is slightly greater than tetrahedral angle.\nReason (R): This is because of the repulsive interaction between the two bulky alkyl groups.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think of repulsion between the alkyl groups on oxygen.","explanation":"A is true (about 111.7 degrees) and R correctly explains it.","difficulty":1,"sources":[[2025,"R","56/6/3",16]]},{"id":"c0637","chapter":4,"type":"mcq","text":"Which of the following transition metal ion is not coloured ?","options":{"A":"$\\mathrm{Cu^+}$","B":"$\\mathrm{Ni^{2+}}$","C":"$\\mathrm{Co^{2+}}$","D":"$\\mathrm{V^{3+}}$"},"answer":"A","hint":"Colour needs unpaired d electrons (d-d transition).","explanation":"$\\mathrm{Cu^+}$ is $3d^{10}$, no unpaired electrons, so colourless.","difficulty":1,"sources":[[2025,"R","56/7/1",1]]},{"id":"c0638","chapter":1,"type":"mcq","text":"Which of the following solutions will have the highest boiling point in water ?","options":{"A":"1% KCl","B":"1% glucose","C":"1% urea","D":"1% $\\mathrm{CaCl_2}$"},"answer":"D","hint":"Compare i x moles for equal mass percent.","explanation":"Compare i x (1/molar mass): $\\mathrm{CaCl_2}$ 3/111 = 0.0270 is slightly above KCl 2/74.5 = 0.0268 and far above glucose and urea, so it has the largest elevation.","difficulty":2,"sources":[[2025,"R","56/7/1",2]]},{"id":"c0639","chapter":2,"type":"mcq","text":"During electrolysis of dilute $\\mathrm{H_2SO_4}$, using platinum electrodes, the gas evolved at the anode is :","options":{"A":"$\\mathrm{H_2}$ gas","B":"$\\mathrm{O_2}$ gas","C":"$\\mathrm{SO_2}$ gas","D":"$\\mathrm{SO_3}$ gas"},"answer":"B","hint":"Water is oxidised at the anode.","explanation":"At the anode water is oxidised: $\\mathrm{2H_2O \\rightarrow O_2 + 4H^+ + 4e^-}$.","difficulty":1,"sources":[[2025,"R","56/7/1",3]]},{"id":"c0640","chapter":3,"type":"mcq","text":"The activation energy ($E_a$) of a reaction can be determined from the slope of which of the following plots ?","options":{"A":"$\\ln k$ vs. $T$","B":"$\\dfrac{\\ln k}{T}$ vs. $T$","C":"$\\ln k$ vs. $\\dfrac{1}{T}$","D":"$\\dfrac{T}{\\ln k}$ vs. $\\dfrac{1}{T}$"},"answer":"C","hint":"Take the log of the Arrhenius equation.","explanation":"$\\ln k = \\ln A - E_a/RT$, so slope of $\\ln k$ vs $1/T$ is $-E_a/R$.","difficulty":1,"sources":[[2025,"R","56/7/1",4]]},{"id":"c0641","chapter":3,"type":"mcq","text":"Which of the following represents the fraction of molecules with energies equal to or greater than $E_a$ ?","options":{"A":"$-\\dfrac{E_a}{RT}$","B":"$e^{-E_a/RT}$","C":"$e^{+E_a/RT}$","D":"$+\\dfrac{E_a}{RT}$"},"answer":"B","hint":"Boltzmann factor.","explanation":"The fraction of molecules with energy $\\geq E_a$ is $e^{-E_a/RT}$.","difficulty":1,"sources":[[2025,"R","56/7/1",5],[2025,"R","56/7/2",5],[2025,"R","56/7/3",5]]},{"id":"c0642","chapter":5,"type":"mcq","text":"The number of moles of AgCl precipitated when excess $\\mathrm{AgNO_3}$ solution is mixed with one mole of $\\mathrm{[Co(NH_3)_3Cl_3]}$ is :","options":{"A":"0","B":"1","C":"2","D":"3"},"answer":"A","hint":"Are the chlorides inside or outside the coordination sphere?","explanation":"All three $\\mathrm{Cl^-}$ are ligands (non-ionisable), so no AgCl precipitates.","difficulty":1,"sources":[[2025,"R","56/7/1",6],[2025,"R","56/7/2",6],[2025,"R","56/7/3",6]]},{"id":"c0643","chapter":6,"type":"mcq","text":"Which of the following haloalkanes react with aqueous KOH most rapidly by $\\mathrm{S_N1}$ reaction ?","options":{"A":"2-Chlorobutane","B":"1-Bromobutane","C":"2-Bromo-2-Methylpropane","D":"2,2-Dimethyl-1-Chloropropane"},"answer":"C","hint":"S_N1 rate follows carbocation stability and leaving group ability.","explanation":"2-Bromo-2-methylpropane is tertiary with Br as a good leaving group, giving a stable tertiary carbocation.","difficulty":1,"sources":[[2025,"R","56/7/1",7]]},{"id":"c0644","chapter":7,"type":"mcq","text":"The reaction $\\mathrm{R-OH + Na \\rightarrow RO^-Na^+ + \\tfrac{1}{2}H_2(g)}$ suggests that alcohols are :","options":{"A":"Acidic","B":"Basic","C":"Neutral","D":"Amphoteric"},"answer":"A","hint":"Which species gives up a proton to sodium?","explanation":"Alcohols donate a proton to the metal, showing acidic character.","difficulty":1,"sources":[[2025,"R","56/7/1",8],[2025,"R","56/7/3",8]]},{"id":"c0645","chapter":7,"type":"mcq","text":"At low temperature, phenol reacts with $\\mathrm{Br_2}$ in $\\mathrm{CS_2}$ to form :","options":{"A":"2,4,6-tribromophenol","B":"p-bromophenol","C":"o- and p-bromophenol","D":"2,4-dibromophenol"},"answer":"C","hint":"Non-polar solvent suppresses ionisation of phenol.","explanation":"In $\\mathrm{CS_2}$ at low temperature monobromination occurs giving a mixture of o- and p-bromophenol (para major).","difficulty":1,"sources":[[2025,"R","56/7/1",9]]},{"id":"c0646","chapter":9,"type":"mcq","text":"When alkyl iodide is treated with large excess of ammonia, the major product obtained is :","options":{"A":"Tertiary amine","B":"Quaternary ammonium salt","C":"Secondary amine","D":"Primary amine"},"answer":"D","hint":"Excess ammonia keeps the amine from reacting further.","explanation":"Excess $\\mathrm{NH_3}$ favours the primary amine by Hofmann ammonolysis.","difficulty":1,"sources":[[2025,"R","56/7/1",10]]},{"id":"c0647","chapter":9,"type":"mcq","text":"An amine 'X' reacts with Hinsberg reagent and the product obtained is soluble in alkali. The amine 'X' is :","options":{"A":"$\\mathrm{CH_3-NH_2}$","B":"$\\mathrm{(CH_3)_2NH}$","C":"$\\mathrm{(CH_3)_3N}$","D":"N-methylaniline, $\\mathrm{C_6H_5-NH-CH_3}$ (structure shown in figure)"},"answer":"A","hint":"Only primary amines give an alkali-soluble sulphonamide.","explanation":"Primary amine gives sulphonamide with an acidic N-H, soluble in alkali.","difficulty":1,"figure":"figures/c0647.png","sources":[[2025,"R","56/7/1",11],[2025,"R","56/7/2",11]]},{"id":"c0648","chapter":10,"type":"mcq","text":"$\\alpha$-helix structure refers to :","options":{"A":"primary structure of protein","B":"secondary structure of protein","C":"tertiary structure of protein","D":"quaternary structure of protein"},"answer":"B","hint":"It is formed by hydrogen bonding within the chain.","explanation":"The alpha-helix is a secondary structure held by N-H...O=C hydrogen bonds.","difficulty":1,"sources":[[2025,"R","56/7/1",12]]},{"id":"c0649","chapter":7,"type":"ar","text":"Assertion (A): A mixture of $o$-nitrophenol and $p$-nitrophenol can be separated by steam distillation.\nReason (R): $o$-nitrophenol is steam volatile due to intermolecular hydrogen bonding.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Which kind of hydrogen bonding makes o-nitrophenol volatile?","explanation":"A is true, but o-nitrophenol is steam volatile because of intramolecular H-bonding, so R is false.","difficulty":2,"sources":[[2025,"R","56/7/1",13],[2025,"R","56/7/2",13],[2025,"R","56/7/3",13]]},{"id":"c0650","chapter":1,"type":"ar","text":"Assertion (A): Cooking time is reduced in pressure cooker.\nReason (R): Boiling point of water inside the pressure cooker is elevated.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Higher pressure raises boiling point.","explanation":"Both true; the elevated boiling point means a higher cooking temperature, reducing time.","difficulty":1,"sources":[[2025,"R","56/7/1",14],[2025,"R","56/7/2",14]]},{"id":"c0651","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show irregularities in their electronic configurations.\nReason (R): Actinoids are radioactive in nature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Irregularities arise from 5f/6d energy closeness.","explanation":"Both statements are true, but radioactivity does not explain the irregular configurations.","difficulty":2,"sources":[[2025,"R","56/7/1",15]]},{"id":"c0652","chapter":10,"type":"ar","text":"Assertion (A): Vitamin K can be stored in our body.\nReason (R): Vitamin K is a water soluble vitamin.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Fat-soluble vs water-soluble vitamins.","explanation":"A is true as vitamin K is fat soluble and stored in the body; R is false.","difficulty":1,"sources":[[2025,"R","56/7/1",16]]},{"id":"c0653","chapter":1,"type":"mcq","text":"Which of the following solution in water will have the lowest freezing point ?","options":{"A":"1% KCl","B":"1% glucose","C":"1% urea","D":"1% $\\mathrm{CaCl_2}$"},"answer":"D","hint":"Largest i x moles gives the largest depression.","explanation":"$\\mathrm{CaCl_2}$ gives the largest $i \\times$ moles per unit mass, hence the largest depression and lowest freezing point.","difficulty":2,"sources":[[2025,"R","56/7/2",2]]},{"id":"c0654","chapter":2,"type":"mcq","text":"Kohlrausch gave the following relation for strong electrolytes : $\\Lambda_m = \\Lambda_m^\\circ - A\\sqrt{C}$. Which of the following equality holds true ?","options":{"A":"$\\Lambda_m = \\Lambda_m^\\circ$ as $C \\rightarrow 1$","B":"$\\Lambda_m = \\Lambda_m^\\circ$ as $C \\rightarrow 0$","C":"$\\Lambda_m = \\Lambda_m^\\circ$ as $C \\rightarrow \\infty$","D":"$\\Lambda_m = \\Lambda_m^\\circ$ as $C \\rightarrow \\sqrt{A}$"},"answer":"B","hint":"Set the concentration term to zero.","explanation":"When $C \\rightarrow 0$, $A\\sqrt{C} \\rightarrow 0$ so $\\Lambda_m \\rightarrow \\Lambda_m^\\circ$.","difficulty":1,"sources":[[2025,"R","56/7/2",3]]},{"id":"c0655","chapter":3,"type":"mcq","text":"Unit of rate constant 'k' for a second order reaction is :","options":{"A":"$\\mathrm{s^{-1}}$","B":"$\\mathrm{mol\\,L^{-1}\\,s^{-1}}$","C":"$\\mathrm{mol^{-1}\\,L\\,s^{-1}}$","D":"$\\mathrm{mol^{-2}\\,L\\,s^{-1}}$"},"answer":"C","hint":"Unit is (mol/L)^(1-n) per second.","explanation":"For order $n$ the unit is $\\mathrm{mol^{1-n}L^{n-1}s^{-1}}$; $n=2$ gives $\\mathrm{mol^{-1}L\\,s^{-1}}$.","difficulty":1,"sources":[[2025,"R","56/7/2",4]]},{"id":"c0656","chapter":6,"type":"mcq","text":"The synthesis of alkyl fluoride is best carried out by :","options":{"A":"Finkelstein reaction","B":"Swarts reaction","C":"Sandmeyer reaction","D":"Wurtz reaction"},"answer":"B","hint":"Metal fluoride with alkyl halide.","explanation":"Swarts reaction uses $\\mathrm{AgF}$ or $\\mathrm{Hg_2F_2}$ to convert alkyl chloride/bromide to alkyl fluoride.","difficulty":1,"sources":[[2025,"R","56/7/2",7]]},{"id":"c0657","chapter":7,"type":"mcq","text":"In the reaction $\\mathrm{R-OH + HCl \\xrightarrow{ZnCl_2} RCl + H_2O}$, what is the correct order of reactivity of alcohols ?","options":{"A":"$1^\\circ < 2^\\circ < 3^\\circ$","B":"$2^\\circ < 1^\\circ < 3^\\circ$","C":"$3^\\circ > 1^\\circ < 2^\\circ$","D":"$1^\\circ > 2^\\circ > 3^\\circ$"},"answer":"A","hint":"Lucas reagent reactivity follows carbocation stability.","explanation":"Lucas test proceeds via carbocations, so tertiary is most reactive and primary least.","difficulty":1,"sources":[[2025,"R","56/7/2",8]]},{"id":"c0658","chapter":7,"type":"mcq","text":"Phenol reacts with Bromine ($\\mathrm{Br_2}$) water to form :","options":{"A":"2,4-dibromophenol","B":"2-bromophenol","C":"2,4,6-tribromophenol","D":"4-bromophenol"},"answer":"C","hint":"Polar solvent activates the ring fully.","explanation":"Bromine water gives a white precipitate of 2,4,6-tribromophenol.","difficulty":1,"sources":[[2025,"R","56/7/2",9]]},{"id":"c0659","chapter":9,"type":"mcq","text":"When excess of alkyl iodide is treated with ammonia, the product obtained is :","options":{"A":"Primary amine","B":"Secondary amine","C":"Tertiary amine","D":"A mixture of amines"},"answer":"D","hint":"Successive alkylation continues.","explanation":"Repeated alkylation gives a mixture of primary, secondary, tertiary amines and the quaternary salt.","difficulty":1,"sources":[[2025,"R","56/7/2",10]]},{"id":"c0660","chapter":10,"type":"mcq","text":"'Scurvy' is caused due to the deficiency of :","options":{"A":"Vitamin A","B":"Vitamin $\\mathrm{B_2}$","C":"Vitamin C","D":"Vitamin D"},"answer":"C","hint":"Ascorbic acid.","explanation":"Scurvy results from vitamin C deficiency.","difficulty":1,"sources":[[2025,"R","56/7/2",12]]},{"id":"c0661","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show irregularities in their electronic configurations.\nReason (R): This is due to varying stability of $f^0$, $f^7$ and $f^{14}$ configurations.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Extra stability of empty, half-filled, filled f subshell.","explanation":"Both true; stability of f0, f7, f14 explains the irregular configurations.","difficulty":2,"sources":[[2025,"R","56/7/2",15]]},{"id":"c0662","chapter":10,"type":"ar","text":"Assertion (A): Maltose is a reducing sugar.\nReason (R): One of the two glucose units can open to expose free aldehydic group in solution.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Free hemiacetal OH on one glucose unit.","explanation":"Both true; the free anomeric carbon opens to an aldehyde, so R explains A.","difficulty":1,"sources":[[2025,"R","56/7/2",16]]},{"id":"c0663","chapter":4,"type":"mcq","text":"With increase in atomic number, the melting point of transition metals :","options":{"A":"first increases and then decreases","B":"increases continuously","C":"first decreases and then increases","D":"remains constant"},"answer":"A","hint":"Think of unpaired d electrons across the series.","explanation":"Melting point rises to a maximum near the middle (most unpaired d electrons) then falls.","difficulty":1,"sources":[[2025,"R","56/7/3",1]]},{"id":"c0664","chapter":1,"type":"mcq","text":"Which of the following aqueous solutions will have the highest osmotic pressure ?","options":{"A":"1% KCl","B":"1% glucose","C":"1% urea","D":"1% $\\mathrm{CaCl_2}$"},"answer":"D","hint":"Compare i x moles for equal mass percent.","explanation":"$\\mathrm{CaCl_2}$ (i = 3, M = 111) gives the highest $i/M$, hence highest osmotic pressure.","difficulty":2,"sources":[[2025,"R","56/7/3",2]]},{"id":"c0665","chapter":2,"type":"mcq","text":"A conductivity cell usually consists of two :","options":{"A":"Copper electrodes","B":"Platinum electrodes","C":"Zinc electrodes","D":"Iron electrodes"},"answer":"B","hint":"Inert, platinised electrodes are used.","explanation":"Conductivity cells use platinum electrodes (platinised) which do not react with the solution.","difficulty":1,"sources":[[2025,"R","56/7/3",3]]},{"id":"c0666","chapter":7,"type":"mcq","text":"Phenol reacts with conc. $\\mathrm{HNO_3}$ to form :","options":{"A":"Salicylic acid","B":"Picric acid","C":"Benzoic acid","D":"Phthalic acid"},"answer":"B","hint":"Three nitro groups at o, o, p.","explanation":"Conc. nitric acid nitrates phenol to 2,4,6-trinitrophenol (picric acid).","difficulty":1,"sources":[[2025,"R","56/7/3",9]]},{"id":"c0667","chapter":9,"type":"mcq","text":"Anilinium hydrogen sulphate on heating at 453 - 473 K produces which of the following as a major product ?","options":{"A":"2-aminobenzene sulphonic acid","B":"benzene sulphonic acid","C":"2-aminobenzoic acid","D":"sulphanilic acid"},"answer":"D","hint":"Sulphonation of aniline gives the para product.","explanation":"Heating gives p-aminobenzenesulphonic acid (sulphanilic acid), existing as a zwitterion.","difficulty":1,"sources":[[2025,"R","56/7/3",10]]},{"id":"c0668","chapter":9,"type":"mcq","text":"Which of the following amines does not give foul smell of isocyanide on heating with chloroform and ethanolic KOH ?","options":{"A":"$\\mathrm{CH_3-CH_2-NH_2}$","B":"$\\mathrm{(CH_3)_2CH-CH_2-NH_2}$","C":"$\\mathrm{(CH_3-CH_2)_3N}$","D":"Aniline, $\\mathrm{C_6H_5-NH_2}$ (benzene ring drawn in figure)"},"answer":"C","hint":"Carbylamine test works only for primary amines.","explanation":"The carbylamine reaction needs a primary amine; triethylamine is tertiary.","difficulty":1,"figure":"figures/c0668.png","sources":[[2025,"R","56/7/3",11]]},{"id":"c0669","chapter":10,"type":"mcq","text":"Deficiency of vitamin $\\mathrm{B_1}$ causes the disease :","options":{"A":"Convulsions","B":"Beri-Beri","C":"Fissuring at corners of mouth and lips (Cheilosis)","D":"Muscular weakness"},"answer":"B","hint":"Thiamine.","explanation":"Deficiency of thiamine (B1) causes beri-beri.","difficulty":1,"sources":[[2025,"R","56/7/3",12]]},{"id":"c0670","chapter":1,"type":"ar","text":"Assertion (A): Aquatic species are more comfortable in cold water than in warm water.\nReason (R): Solubility of oxygen gas in water decreases with increase in temperature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Gas solubility versus temperature.","explanation":"Both true; less dissolved oxygen in warm water is why aquatic life is stressed there.","difficulty":1,"sources":[[2025,"R","56/7/3",14]]},{"id":"c0671","chapter":4,"type":"ar","text":"Assertion (A): First ionisation enthalpy of Cr is lower than that of Zn.\nReason (R): Zinc is a non-transition element.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Compare 3d5 4s1 and 3d10 4s2 and whether R explains it.","explanation":"Both true, but the higher IE of Zn is due to its stable fully filled 3d10 4s2 configuration, not just its classification.","difficulty":2,"sources":[[2025,"R","56/7/3",15]]},{"id":"c0672","chapter":10,"type":"ar","text":"Assertion (A): Vitamin C cannot be stored in our body.\nReason (R): Vitamin C is water soluble and excreted in urine.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Water-soluble vitamins are not stored.","explanation":"Both true; being water soluble, vitamin C is excreted and cannot be stored.","difficulty":1,"sources":[[2025,"R","56/7/3",16]]},{"id":"c0673","chapter":1,"type":"mcq","text":"The value of Henry's law constant ($K_H$) ________.","options":{"A":"increases with an increase in temperature","B":"remains constant with an increase in temperature","C":"decreases with an increase in temperature","D":"first increases, then decreases with an increase in temperature"},"answer":"A","hint":"Gas solubility falls as temperature rises.","explanation":"Solubility of gases decreases with temperature, so $K_H$ increases.","difficulty":1,"sources":[[2026,"C","56(B)/7",1]]},{"id":"c0674","chapter":9,"type":"mcq","text":"Among the following, the least basic compound is :","options":{"A":"$\\mathrm{CH_3-NH_2}$","B":"$\\mathrm{C_6H_5-NH_2}$","C":"$\\mathrm{(CH_3)_3N}$","D":"$\\mathrm{(CH_3)_2NH}$"},"answer":"B","hint":"Aryl amines are weaker bases than alkyl amines.","explanation":"The lone pair of aniline is delocalised into the ring, making it the least basic.","difficulty":1,"sources":[[2026,"C","56(B)/7",5]]},{"id":"c0675","chapter":4,"type":"mcq","text":"Which of the following transition metals does not show variable oxidation states ?","options":{"A":"Ti","B":"Cu","C":"Mn","D":"Sc"},"answer":"D","hint":"Look at the d electron count of the ions.","explanation":"Sc shows only +3 (noble gas configuration); the others show several oxidation states.","difficulty":1,"sources":[[2026,"C","56(B)/7",6]]},{"id":"c0676","chapter":4,"type":"mcq","text":"The most common oxidation states of cerium are :","options":{"A":"+2 and +4","B":"+3 and +4","C":"+3 and +5","D":"+2 and +3"},"answer":"B","hint":"Ce(IV) is stable as $4f^0$.","explanation":"Cerium commonly shows +3 and +4.","difficulty":1,"sources":[[2026,"C","56(B)/7",7]]},{"id":"c0677","chapter":5,"type":"mcq","text":"The pair $\\mathrm{[Co(NH_3)_5(NO_3)]SO_4}$ and $\\mathrm{[Co(NH_3)_5(SO_4)]NO_3}$ will show :","options":{"A":"linkage isomerism","B":"coordination isomerism","C":"ionization isomerism","D":"hydrate isomerism"},"answer":"C","hint":"The anion inside the sphere is swapped with the counter-ion.","explanation":"Nitrate and sulphate exchange between the coordination sphere and the counter-ion, giving ionization isomers.","difficulty":1,"sources":[[2026,"C","56(B)/7",9]]},{"id":"c0678","chapter":6,"type":"mcq","text":"In the preparation of an alkyl halide from alcohol, which of the following reagents is preferred ?","options":{"A":"$\\mathrm{PCl_5}$","B":"$\\mathrm{SOCl_2}$","C":"$\\mathrm{PCl_3}$","D":"$\\mathrm{HCl/ZnCl_2}$"},"answer":"B","hint":"Look for the reagent with gaseous by-products.","explanation":"$\\mathrm{SOCl_2}$ gives pure alkyl chloride since $\\mathrm{SO_2}$ and HCl escape as gases.","difficulty":1,"sources":[[2026,"C","56(B)/7",10]]},{"id":"c0679","chapter":6,"type":"mcq","text":"The reaction of an alkyl halide with sodium forming alkane is known as :","options":{"A":"Williamson synthesis","B":"Wurtz reaction","C":"Swarts reaction","D":"Friedel-Crafts reaction"},"answer":"B","hint":"Coupling of two alkyl halides in dry ether.","explanation":"$\\mathrm{2RX + 2Na \\rightarrow R-R + 2NaX}$ is the Wurtz reaction.","difficulty":1,"sources":[[2026,"C","56(B)/7",11]]},{"id":"c0680","chapter":9,"type":"mcq","text":"Nitrobenzene on reduction with Fe and HCl will yield :","options":{"A":"Chlorobenzene","B":"Phenol","C":"Aniline","D":"Benzonitrile"},"answer":"C","hint":"Nitro group reduces to amino group.","explanation":"Fe/HCl reduces $\\mathrm{-NO_2}$ to $\\mathrm{-NH_2}$, giving aniline.","difficulty":1,"sources":[[2026,"C","56(B)/7",12]]},{"id":"c0681","chapter":9,"type":"ar","text":"Assertion (A): Ammonolysis of alkyl halides involves the reaction of an alkyl halide with an ethanolic solution of ammonia.\nReason (R): Ammonolysis is not a good method to prepare pure primary amines.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Does the reason say what ammonolysis involves?","explanation":"Both true, but R (mixture of amines formed) does not explain what ammonolysis involves.","difficulty":2,"sources":[[2026,"C","56(B)/7",13]]},{"id":"c0682","chapter":10,"type":"ar","text":"Assertion (A): Sucrose is a non-reducing sugar.\nReason (R): A free aldehydic functional group is present in sucrose.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Both anomeric carbons are involved in the glycosidic bond.","explanation":"A is true but sucrose has no free aldehyde group, so R is false.","difficulty":1,"sources":[[2026,"C","56(B)/7",14]]},{"id":"c0683","chapter":3,"type":"ar","text":"Assertion (A): Hydrolysis of an ester follows first order kinetics.\nReason (R): Concentration of water remains almost constant during the course of the reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Pseudo-first-order reaction.","explanation":"Water is in large excess so its concentration is constant, giving pseudo-first-order kinetics; R explains A.","difficulty":2,"sources":[[2026,"C","56(B)/7",15]]},{"id":"c0684","chapter":9,"type":"ar","text":"Assertion (A): At low temperatures (273 - 278 K), arenediazonium salts are more stable in solution than alkyldiazonium salts.\nReason (R): The arenediazonium ion shows resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Resonance stabilises the cation.","explanation":"Both true; resonance delocalisation stabilises the arenediazonium ion.","difficulty":1,"sources":[[2026,"C","56(B)/7",16]]},{"id":"c0685","chapter":9,"type":"mcq","text":"Which of the following reactions is used for the preparation of Aniline ?","options":{"A":"Reaction of ethanolic $\\mathrm{NH_3}$ with $\\mathrm{C_6H_5Cl}$","B":"Reaction of Nitrobenzene with Hydrogen gas in presence of finely divided Nickel","C":"Reaction of Benzamide with $\\mathrm{LiAlH_4}$","D":"Reaction of Benzonitrile with $\\mathrm{LiAlH_4}$"},"answer":"B","hint":"Which reaction converts the nitro group to amino without extra carbon?","explanation":"Catalytic hydrogenation of nitrobenzene gives aniline; the others give benzylamine or fail.","difficulty":1,"sources":[[2026,"C","56/7/1",1],[2026,"C","56/7/2",4],[2026,"C","56/7/3",12]]},{"id":"c0686","chapter":4,"type":"mcq","text":"Which of the following elements exhibits maximum number of oxidation states ?","options":{"A":"Scandium","B":"Zinc","C":"Manganese","D":"Cobalt"},"answer":"C","hint":"Count the oxidation states in the first transition series.","explanation":"Manganese shows +2 to +7.","difficulty":1,"sources":[[2026,"C","56/7/1",2],[2026,"C","56/7/2",3],[2026,"C","56/7/3",11]]},{"id":"c0687","chapter":5,"type":"mcq","text":"According to Alfred Werner, the secondary valence(s) of the central metal atom/ion in a complex :\nIdentify the incorrect statement from the following.","options":{"A":"are non-ionisable","B":"are ionisable","C":"are satisfied by neutral molecules or negative ions","D":"is equal to the coordination number and is normally fixed for a metal"},"answer":"B","hint":"Secondary valences are the coordination sites.","explanation":"Secondary valences are non-ionisable, so the statement that they are ionisable is incorrect.","difficulty":1,"sources":[[2026,"C","56/7/1",3],[2026,"C","56/7/2",11],[2026,"C","56/7/3",4]]},{"id":"c0688","chapter":2,"type":"mcq","text":"A galvanic cell functions like an electrolytic cell when :","options":{"A":"$E_\\mathrm{cell} = E_\\mathrm{ext}$","B":"$E_\\mathrm{cell} > E_\\mathrm{ext}$","C":"$E_\\mathrm{ext} > E_\\mathrm{cell}$","D":"$E_\\mathrm{cell} = 0$"},"answer":"C","hint":"Direction of reaction reverses when opposing voltage is larger.","explanation":"If external potential exceeds the cell potential, the cell reaction is reversed, as in electrolysis.","difficulty":1,"sources":[[2026,"C","56/7/1",4],[2026,"C","56/7/2",12],[2026,"C","56/7/3",7]]},{"id":"c0689","chapter":7,"type":"mcq","text":"Phenol, on heating with conc. $\\mathrm{HNO_3}$, gives :","options":{"A":"o-Nitrophenol","B":"p-Nitrophenol","C":"Picric acid","D":"Sodium phenoxide"},"answer":"C","hint":"Heating with concentrated acid leads to trinitration.","explanation":"Conc. nitric acid converts phenol to 2,4,6-trinitrophenol (picric acid).","difficulty":1,"sources":[[2026,"C","56/7/1",5],[2026,"C","56/7/2",9],[2026,"C","56/7/3",8]]},{"id":"c0690","chapter":1,"type":"mcq","text":"Match Column I with Column II and choose the correct option :\nColumn I: a. Osmotic pressure; b. Elevation of boiling point; c. Depression of freezing point; d. Relative lowering of vapour pressure\nColumn II: i. $\\Delta T_f = K_f m$; ii. $\\pi = CRT$; iii. $\\dfrac{P_1^0 - P_1}{P_1^0} = \\dfrac{W_2 \\times M_1}{M_2 \\times W_1}$; iv. $\\Delta T_b = K_b m$","options":{"A":"a-i, b-ii, c-iii, d-iv","B":"a-ii, b-i, c-iii, d-iv","C":"a-iv, b-iii, c-ii, d-i","D":"a-ii, b-iv, c-i, d-iii"},"answer":"D","hint":"Match each property with its formula.","explanation":"Osmotic pressure is $\\pi = CRT$; boiling elevation $K_b m$; freezing depression $K_f m$; relative lowering is the Raoult's law expression.","difficulty":1,"sources":[[2026,"C","56/7/1",6],[2026,"C","56/7/2",8],[2026,"C","56/7/3",1]]},{"id":"c0691","chapter":7,"type":"mcq","text":"The products of the following reaction are :\nBenzyl phenyl ether ($\\mathrm{C_6H_5-CH_2-O-C_6H_5}$) $\\xrightarrow{HI}$ ?\n(i) benzyl iodide, $\\mathrm{C_6H_5CH_2I}$; (ii) phenol, $\\mathrm{C_6H_5OH}$; (iii) anisole, $\\mathrm{C_6H_5OCH_3}$ (structures shown in figure)","options":{"A":"(i) and (ii)","B":"(i) and (iii)","C":"(ii) and (iii)","D":"(i), (ii) and (iii)"},"answer":"A","hint":"HI cleaves the alkyl-oxygen bond of the more reactive (benzylic) side.","explanation":"The benzyl-O bond cleaves (aryl-O bond is stronger), giving benzyl iodide and phenol.","difficulty":2,"figure":"figures/c0691.png","sources":[[2026,"C","56/7/1",7],[2026,"C","56/7/2",5]]},{"id":"c0692","chapter":7,"type":"mcq","text":"The correct order of reactivity of alcohols with Lucas reagent is :","options":{"A":"$3^\\circ > 1^\\circ > 2^\\circ$","B":"$2^\\circ > 1^\\circ > 3^\\circ$","C":"$1^\\circ > 2^\\circ > 3^\\circ$","D":"$3^\\circ > 2^\\circ > 1^\\circ$"},"answer":"D","hint":"Reactivity follows carbocation stability.","explanation":"Lucas reagent reaction proceeds via carbocation: $3^\\circ > 2^\\circ > 1^\\circ$.","difficulty":1,"sources":[[2026,"C","56/7/1",8],[2026,"C","56/7/2",7],[2026,"C","56/7/3",3]]},{"id":"c0693","chapter":10,"type":"mcq","text":"Functional groups present in amino acids are :","options":{"A":"$-\\mathrm{NH_2}$ and $-\\mathrm{OH}$","B":"$-\\mathrm{OH}$ and $-\\mathrm{COOH}$","C":"$-\\mathrm{COOH}$ and $-\\mathrm{NH_2}$","D":"$-\\mathrm{NH_2}$ and $-\\mathrm{SO_3H}$"},"answer":"C","hint":"Name amino and acid parts.","explanation":"Amino acids contain an amino group and a carboxyl group.","difficulty":1,"sources":[[2026,"C","56/7/1",9],[2026,"C","56/7/2",10],[2026,"C","56/7/3",2]]},{"id":"c0694","chapter":2,"type":"mcq","text":"The relationship between $E^\\circ_\\mathrm{(cell)}$ and $\\Delta_rG^\\ominus$ is :","options":{"A":"$\\Delta_rG^\\ominus = E^\\ominus_\\mathrm{(cell)}$","B":"$\\Delta_rG^\\ominus = nF\\,E^\\ominus_\\mathrm{(cell)}$","C":"$\\Delta_rG^\\ominus = nE^\\circ_\\mathrm{cell}$","D":"$\\Delta_rG^\\ominus = -nF\\,E^\\ominus_\\mathrm{(cell)}$"},"answer":"D","hint":"Spontaneous reactions have positive E and negative G.","explanation":"$\\Delta_rG^\\ominus = -nFE^\\ominus_\\mathrm{cell}$.","difficulty":1,"sources":[[2026,"C","56/7/1",10],[2026,"C","56/7/2",2],[2026,"C","56/7/3",6]]},{"id":"c0695","chapter":2,"type":"mcq","text":"The quantity of electricity in Faraday, required to reduce 1 mol of $\\mathrm{Cr_2O_7^{2-}}$ to $\\mathrm{Cr^{3+}}$ is :","options":{"A":"4F","B":"3F","C":"6F","D":"5F"},"answer":"C","hint":"Count electrons: two Cr from +6 to +3.","explanation":"Each Cr gains 3 electrons, so 2 x 3 = 6 mol of electrons, i.e. 6 F.","difficulty":1,"sources":[[2026,"C","56/7/1",11],[2026,"C","56/7/2",1],[2026,"C","56/7/3",10]]},{"id":"c0696","chapter":2,"type":"mcq","text":"Which of the following statements is true about a galvanic cell consisting of Cu and $\\mathrm{H_2}$ electrodes ?\n[Given : $E^\\circ_{\\mathrm{Cu^{2+}/Cu}} = +0.34\\ \\mathrm{V}$, $E^\\circ_{\\mathrm{H^+/H_2,Pt}} = +0.00\\ \\mathrm{V}$]","options":{"A":"Oxidation occurs at copper electrode","B":"Reduction occurs at $\\mathrm{H_2}$ electrode","C":"$\\mathrm{H_2}$ is cathode and Cu is anode","D":"$\\mathrm{H_2}$ is anode and Cu is cathode"},"answer":"D","hint":"The electrode with the higher reduction potential is the cathode.","explanation":"Cu has the higher $E^\\circ$ (+0.34 V), so Cu is reduced (cathode) and $\\mathrm{H_2}$ is oxidised (anode).","difficulty":1,"sources":[[2026,"C","56/7/1",12],[2026,"C","56/7/2",6],[2026,"C","56/7/3",5]]},{"id":"c0697","chapter":1,"type":"ar","text":"Assertion (A): The volume of an ideal solution is equal to the sum of the volumes of the two components, i.e., $\\Delta_\\mathrm{mix}V = 0$.\nReason (R): The intermolecular forces of attraction between the solute-solvent molecules are weaker than those between the solute-solute and solvent-solvent molecules.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Compare solute-solvent interactions in an ideal solution.","explanation":"A is true for an ideal solution; R is false because in an ideal solution the A-B interactions are equal to A-A and B-B interactions (weaker interactions give positive deviation).","difficulty":2,"sources":[[2026,"C","56/7/1",13],[2026,"C","56/7/2",14],[2026,"C","56/7/3",16]]},{"id":"c0698","chapter":5,"type":"ar","text":"Assertion (A): Out of $\\mathrm{[Co(en)_3]^{3+}}$ and $\\mathrm{[Co(CN)_6]^{3-}}$, coordination compound $\\mathrm{[Co(en)_3]^{3+}}$ is a more stable complex.\nReason (R): Ethane-1,2-diamine is a chelating ligand.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think of the chelate effect.","explanation":"Chelating (bidentate) en forms five-membered rings, making the complex more stable; R correctly explains A.","difficulty":2,"sources":[[2026,"C","56/7/1",14],[2026,"C","56/7/2",15],[2026,"C","56/7/3",13]]},{"id":"c0699","chapter":6,"type":"ar","text":"Assertion (A): Phosphorus halides are preferred over thionyl chloride for the preparation of alkyl halides from alcohols.\nReason (R): Reaction of alcohols with thionyl chloride forms pure alkyl halides.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Look at the by-products of the thionyl chloride reaction.","explanation":"A is false: $\\mathrm{SOCl_2}$ is preferred because the by-products $\\mathrm{SO_2}$ and HCl are gases, giving pure alkyl halide. R is true.","difficulty":2,"sources":[[2026,"C","56/7/1",15],[2026,"C","56/7/2",16],[2026,"C","56/7/3",14]]},{"id":"c0700","chapter":8,"type":"ar","text":"Assertion (A): Aromatic carboxylic acids do not undergo Friedel-Crafts reaction.\nReason (R): Carboxyl group is deactivating and the catalyst aluminium chloride gets bonded to carboxyl group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Consider the effect of -COOH on the ring and on $\\mathrm{AlCl_3}$.","explanation":"Both true: the deactivated ring and complexation of $\\mathrm{AlCl_3}$ with -COOH stop the reaction, so R explains A.","difficulty":2,"sources":[[2026,"C","56/7/1",16],[2026,"C","56/7/2",13],[2026,"C","56/7/3",15]]},{"id":"c0701","chapter":7,"type":"mcq","text":"The products of the following reaction are :\nBenzyl phenyl ether (C6H5-CH2-O-C6H5) reacts with HI.\n(i), (ii) and (iii) are the structures shown in the figure.","options":{"A":"(i) and (ii)","B":"(i) and (iii)","C":"(ii) and (iii)","D":"(i), (ii) and (iii)"},"answer":"A","hint":"HI cleaves the ether at the alkyl-oxygen bond; the aryl-oxygen bond does not break.","explanation":"The benzylic C-O bond is cleaved (SN1/SN2) giving benzyl iodide, and the aryl-O part gives phenol; phenol is not converted to aryl iodide.","difficulty":2,"figure":"figures/c0701.png","sources":[[2026,"C","56/7/3",9]]},{"id":"c0702","chapter":1,"type":"mcq","text":"Which of the following colligative properties can preferably determine the molar mass of proteins ?","options":{"A":"Relative lowering of vapour pressure","B":"Osmotic pressure","C":"Elevation of boiling point","D":"Depression of freezing point"},"answer":"B","hint":"Which property gives a measurable effect for very dilute solutions of macromolecules?","explanation":"Osmotic pressure is measurable at room temperature even at very low concentration, so it suits large biomolecules.","difficulty":1,"sources":[[2026,"R","56(B)",1]]},{"id":"c0703","chapter":1,"type":"mcq","text":"For an electrolyte consisting of a monovalent cation and a monovalent anion undergoing dissociation in water, the van't Hoff factor (i) is :","options":{"A":"less than 1","B":"equal to 1","C":"greater than 1","D":"greater than 2"},"answer":"C","hint":"Dissociation increases the number of particles.","explanation":"Dissociation of $\\mathrm{AB}$ into $\\mathrm{A^+ + B^-}$ gives $i = 1+\\alpha$, which is greater than 1 (and at most 2).","difficulty":1,"sources":[[2026,"R","56(B)",2]]},{"id":"c0704","chapter":2,"type":"mcq","text":"The standard electrode potentials of three metals A, B and C are, respectively, $+0.34\\ \\mathrm{V}$, $-1.18\\ \\mathrm{V}$ and $-0.25\\ \\mathrm{V}$. The correct order of reducing power of these metals is :","options":{"A":"B > C > A","B":"A > B > C","C":"C > B > A","D":"A > C > B"},"answer":"A","hint":"Lower reduction potential means stronger reducing agent.","explanation":"Reducing power increases as $E^\\circ$ decreases: B (-1.18) > C (-0.25) > A (+0.34).","difficulty":1,"sources":[[2026,"R","56(B)",3]]},{"id":"c0705","chapter":3,"type":"mcq","text":"The rate of a reaction is doubled when the concentration of the reactant is doubled. The order of the reaction is :","options":{"A":"0","B":"1","C":"2","D":"0.5"},"answer":"B","hint":"Rate $\\propto [R]^n$.","explanation":"$2^n = 2$ gives $n = 1$.","difficulty":1,"sources":[[2026,"R","56(B)",4]]},{"id":"c0706","chapter":4,"type":"mcq","text":"Which of the following is not a transition metal ?","options":{"A":"Hg","B":"Cu","C":"Ag","D":"Pt"},"answer":"A","hint":"Check the d-subshell in the metal and in its common ions.","explanation":"Hg has a completely filled $5d^{10}$ in its atom and ions, so it is not counted as a transition element.","difficulty":1,"sources":[[2026,"R","56(B)",5]]},{"id":"c0707","chapter":5,"type":"mcq","text":"The secondary valency of Co in $\\mathrm{[Co(en)_3]_2(SO_4)_3}$ is :","options":{"A":"12","B":"2","C":"3","D":"6"},"answer":"D","hint":"Secondary valency equals coordination number.","explanation":"en is bidentate, so three en donate six donor atoms; coordination number is 6.","difficulty":1,"sources":[[2026,"R","56(B)",6]]},{"id":"c0708","chapter":5,"type":"mcq","text":"Vitamin $\\mathrm{B_{12}}$ is a complex compound of :","options":{"A":"$\\mathrm{Fe^{2+}}$","B":"$\\mathrm{Mg^{2+}}$","C":"$\\mathrm{Co^{3+}}$","D":"$\\mathrm{Cu^{2+}}$"},"answer":"C","hint":"Think of cobalamin.","explanation":"Vitamin $\\mathrm{B_{12}}$ (cyanocobalamin) is a coordination complex of cobalt, $\\mathrm{Co^{3+}}$.","difficulty":1,"sources":[[2026,"R","56(B)",7]]},{"id":"c0709","chapter":6,"type":"mcq","text":"Chloroform, in the presence of air and sunlight, produces a poisonous gas known as :","options":{"A":"Phosgene","B":"Phosphine","C":"Tear gas","D":"Mustard gas"},"answer":"A","hint":"Oxidation of $\\mathrm{CHCl_3}$.","explanation":"Chloroform is slowly oxidised by air and light to carbonyl chloride (phosgene).","difficulty":1,"sources":[[2026,"R","56(B)",8]]},{"id":"c0710","chapter":7,"type":"mcq","text":"Propan-2-ol on oxidation with $\\mathrm{CrO_3}$ gives :","options":{"A":"Propanal","B":"Propanoic acid","C":"Propene","D":"Propanone"},"answer":"D","hint":"Secondary alcohols oxidise to ketones.","explanation":"Propan-2-ol is a secondary alcohol and is oxidised to propanone.","difficulty":1,"sources":[[2026,"R","56(B)",9]]},{"id":"c0711","chapter":9,"type":"mcq","text":"The reaction of ammonia with a large excess of ethyl chloride will give mainly :","options":{"A":"Ethylamine","B":"Tetraethylammonium chloride","C":"Triethylamine","D":"Diethylamine"},"answer":"B","hint":"Repeated alkylation continues when the alkyl halide is in excess.","explanation":"Ammonolysis proceeds stepwise through 1°, 2°, 3° amines; excess alkyl halide gives the quaternary ammonium salt.","difficulty":2,"sources":[[2026,"R","56(B)",10]]},{"id":"c0712","chapter":9,"type":"mcq","text":"Acetamide reacts with $\\mathrm{Br_2}$ and aqueous KOH to form :","options":{"A":"Ethanamine","B":"Ammonia","C":"Methanamine","D":"Ethanenitrile"},"answer":"C","hint":"Hofmann bromamide degradation loses one carbon.","explanation":"Hofmann degradation of $\\mathrm{CH_3CONH_2}$ gives $\\mathrm{CH_3NH_2}$ (methanamine).","difficulty":1,"sources":[[2026,"R","56(B)",11]]},{"id":"c0713","chapter":10,"type":"mcq","text":"In the ring structure of fructose, the anomeric carbon is :","options":{"A":"C2","B":"C3","C":"C4","D":"C1"},"answer":"A","hint":"The anomeric carbon is the former carbonyl carbon.","explanation":"Fructose is a ketohexose with its carbonyl at C2, which becomes the anomeric carbon in the ring.","difficulty":1,"sources":[[2026,"R","56(B)",12]]},{"id":"c0714","chapter":4,"type":"ar","text":"Assertion (A): Transition metals have high melting points.\nReason (R): Transition metals have incompletely filled d-orbitals.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Link melting point to number of unpaired d electrons in metallic bonding.","explanation":"Both statements are true; high melting points come from strong metallic bonding involving many unpaired (n-1)d electrons, and the statement R is only an incomplete explanation.","difficulty":2,"sources":[[2026,"R","56(B)",13]]},{"id":"c0715","chapter":7,"type":"ar","text":"Assertion (A): p-nitrophenol is less acidic than phenol.\nReason (R): Nitro group is an electron-withdrawing group, which stabilises the phenoxide ion.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Effect of -NO2 on the stability of the conjugate base.","explanation":"A is false: p-nitrophenol is more acidic than phenol. R is true.","difficulty":1,"sources":[[2026,"R","56(B)",15]]},{"id":"c0716","chapter":9,"type":"ar","text":"Assertion (A): Boiling point of propylamine is higher than that of trimethylamine.\nReason (R): In propylamine, intermolecular hydrogen bonding occurs, whereas trimethylamine does not undergo intermolecular hydrogen bonding.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Primary amines have N-H bonds; tertiary amines do not.","explanation":"Both true: propylamine is a primary amine with intermolecular N-H...N hydrogen bonds; trimethylamine is tertiary with none.","difficulty":1,"sources":[[2026,"R","56(B)",16]]},{"id":"c0717","chapter":3,"type":"mcq","text":"Which of the following curve represents the first order reaction ?","options":{"A":"Graph: $t_{1/2}$ (y-axis) vs $[R]_0$ (x-axis), straight line rising from origin","B":"Graph: $t_{1/2}$ (y-axis) vs $[R]_0$ (x-axis), horizontal line","C":"Graph: Rate (y-axis) vs Concentration (x-axis), horizontal line","D":"Graph: Rate (y-axis) vs Concentration (x-axis), decreasing curve"},"answer":"B","hint":"Half-life of a first order reaction does not depend on initial concentration.","explanation":"For first order, $t_{1/2} = 0.693/k$ is independent of $[R]_0$, a horizontal line.","difficulty":1,"figure":"figures/c0717.png","sources":[[2026,"R","56/1/1",1],[2026,"R","56/1/2",2],[2026,"R","56/1/3",4]]},{"id":"c0718","chapter":1,"type":"mcq","text":"Which of the following solutions will have the lowest freezing point in water ?","options":{"A":"0.1 M Glucose","B":"0.1 M $\\mathrm{CaCl_2}$","C":"0.1 M KCl","D":"0.1 M Urea"},"answer":"B","hint":"Compare the number of particles (van't Hoff factor).","explanation":"$\\mathrm{CaCl_2}$ gives three ions ($i \\approx 3$), the largest depression of freezing point.","difficulty":1,"sources":[[2026,"R","56/1/1",2]]},{"id":"c0719","chapter":4,"type":"mcq","text":"Which of the following is not a transition metal ?","options":{"A":"Sc","B":"Ag","C":"Hg","D":"Cu"},"answer":"C","hint":"Look for a completely filled d-subshell in all its oxidation states.","explanation":"Hg has $5d^{10}$ in its atom and ions, so it is not a transition metal.","difficulty":1,"sources":[[2026,"R","56/1/1",3]]},{"id":"c0720","chapter":3,"type":"mcq","text":"Which of the following represents the fraction of molecules with energies equal to or greater than $E_\\mathrm{a}$ ?","options":{"A":"$+\\dfrac{E_\\mathrm{a}}{RT}$","B":"$e^{-E_\\mathrm{a}/RT}$","C":"$-\\dfrac{E_\\mathrm{a}}{RT}$","D":"$e^{+E_\\mathrm{a}/RT}$"},"answer":"B","hint":"Boltzmann factor in the Arrhenius equation.","explanation":"The fraction of molecules with $E \\ge E_\\mathrm{a}$ is $e^{-E_\\mathrm{a}/RT}$.","difficulty":1,"sources":[[2026,"R","56/1/1",4]]},{"id":"c0721","chapter":2,"type":"mcq","text":"What will happen during the electrolysis of aqueous solution of $\\mathrm{CuCl_2}$ by using platinum electrodes ?","options":{"A":"Cu will deposit at Anode","B":"$\\mathrm{H_2}$ gas will be released at cathode","C":"$\\mathrm{O_2}$ gas will be released at anode","D":"$\\mathrm{Cl_2}$ gas will be released at anode"},"answer":"D","hint":"Decide which species is preferentially oxidised and reduced with inert electrodes.","explanation":"$\\mathrm{Cu^{2+}}$ is reduced at the cathode (Cu deposits) and $\\mathrm{Cl^-}$ is oxidised at the anode giving $\\mathrm{Cl_2}$.","difficulty":2,"sources":[[2026,"R","56/1/1",5]]},{"id":"c0722","chapter":7,"type":"mcq","text":"Aspirin is obtained by acetylation of :","options":{"A":"Phenol","B":"Salicylaldehyde","C":"2-Hydroxybenzoic acid","D":"Benzoic acid"},"answer":"C","hint":"Aspirin is acetylsalicylic acid.","explanation":"Acetylation of the phenolic -OH of salicylic acid (2-hydroxybenzoic acid) gives aspirin.","difficulty":1,"sources":[[2026,"R","56/1/1",6]]},{"id":"c0723","chapter":5,"type":"mcq","text":"The secondary valency of Co in the complex $\\mathrm{[Co(NH_3)_5(NO_2)]^{2+}}$ is","options":{"A":"5","B":"1","C":"4","D":"6"},"answer":"D","hint":"Count donor atoms attached to the metal.","explanation":"Five $\\mathrm{NH_3}$ and one $\\mathrm{NO_2}$ are monodentate, so the coordination number is 6.","difficulty":1,"sources":[[2026,"R","56/1/1",7]]},{"id":"c0724","chapter":7,"type":"mcq","text":"At low temperature, phenol reacts with dil. $\\mathrm{HNO_3}$ to yield","options":{"A":"2, 4, 6-Trinitrophenol","B":"o-Nitrophenol only","C":"p-Nitrophenol only","D":"ortho-and para-nitrophenol"},"answer":"D","hint":"-OH is an ortho/para director; dilute acid mononitrates.","explanation":"Dilute $\\mathrm{HNO_3}$ at low temperature gives a mixture of o- and p-nitrophenol.","difficulty":1,"sources":[[2026,"R","56/1/1",8]]},{"id":"c0725","chapter":9,"type":"mcq","text":"Aniline on direct nitration yields","options":{"A":"51%-ortho, 47%-para, 2%-meta derivatives","B":"51%-meta, 47%-ortho, 2%-para derivatives","C":"51%-para, 47%-meta, 2%-ortho derivatives","D":"51%-ortho, 47%-meta, 2%-para derivatives"},"answer":"C","hint":"In acid, aniline is protonated to the anilinium ion.","explanation":"Protonation gives the meta-directing $-\\mathrm{NH_3^+}$, so meta (47%) is large, but para (51%) is still the major product.","difficulty":2,"sources":[[2026,"R","56/1/1",10],[2026,"R","56/1/2",9],[2026,"R","56/1/3",5]]},{"id":"c0726","chapter":9,"type":"mcq","text":"Which of the following amines has lowest $\\mathrm{p}K_\\mathrm{b}$ value ?","options":{"A":"$\\mathrm{C_6H_5-N(CH_3)_2}$","B":"$\\mathrm{C_6H_5-NH(CH_3)}$","C":"$\\mathrm{C_6H_5-NH_2}$","D":"p-Nitroaniline (structure $\\mathrm{O_2N-C_6H_4-NH_2}$ drawn)"},"answer":"A","hint":"Lowest $\\mathrm{p}K_\\mathrm{b}$ means strongest base.","explanation":"Alkyl groups raise basicity of the aniline nitrogen, so $\\mathrm{C_6H_5N(CH_3)_2}$ is the strongest base; the nitro group lowers it.","difficulty":2,"figure":"figures/c0726.png","sources":[[2026,"R","56/1/1",11]]},{"id":"c0727","chapter":10,"type":"mcq","text":"The deficiency of which of the following vitamins causes increased fragility of red blood cells and muscular weakness :","options":{"A":"Vitamin A","B":"Vitamin K","C":"Vitamin E","D":"Vitamin D"},"answer":"C","hint":"Recall deficiency diseases table.","explanation":"Vitamin E deficiency causes fragility of RBCs and muscular weakness.","difficulty":1,"sources":[[2026,"R","56/1/1",12]]},{"id":"c0728","chapter":1,"type":"ar","text":"Assertion (A): It is not possible to separate the components of an azeotrope by fractional distillation.\nReason (R): Components of an azeotrope have the same composition in liquid and vapour phase and boil at a constant temperature.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"What does fractional distillation depend on?","explanation":"Both true; because liquid and vapour have the same composition at constant boiling point, distillation cannot separate them, so R explains A.","difficulty":1,"sources":[[2026,"R","56/1/1",13]]},{"id":"c0729","chapter":7,"type":"ar","text":"Assertion (A): The presence of -OH group in phenols directs the incoming group to meta position in the ring.\nReason (R): -OH group in phenols activates the aromatic ring towards electrophilic substitution reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Directing effect of the -OH group.","explanation":"A is false: -OH is ortho/para directing. R is true.","difficulty":1,"sources":[[2026,"R","56/1/1",14]]},{"id":"c0730","chapter":10,"type":"ar","text":"Assertion (A): The pentaacetate of glucose does not react with $\\mathrm{H_2N-OH}$.\nReason (R): It indicates the presence of free -CHO group in glucose.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Pentaacetate means all five -OH groups are acetylated.","explanation":"A is true; its non-reaction shows absence of free -CHO, so R is false (it indicates the cyclic structure).","difficulty":2,"sources":[[2026,"R","56/1/1",16]]},{"id":"c0731","chapter":4,"type":"mcq","text":"Which of the following is most basic ?","options":{"A":"$\\mathrm{Mn_2O_7}$","B":"$\\mathrm{MnO_2}$","C":"MnO","D":"$\\mathrm{Mn_2O_3}$"},"answer":"C","hint":"Basicity of oxides falls as oxidation state rises.","explanation":"MnO has Mn in the lowest oxidation state (+2), making it the most basic.","difficulty":1,"sources":[[2026,"R","56/1/2",1]]},{"id":"c0732","chapter":1,"type":"mcq","text":"Which of the following solutions will have the highest osmotic pressure ?","options":{"A":"0.1 M KCl","B":"0.1 M $\\mathrm{CaCl_2}$","C":"0.1 M Glucose","D":"0.1 M Urea"},"answer":"B","hint":"$\\pi = iCRT$.","explanation":"$\\mathrm{CaCl_2}$ has the largest van't Hoff factor ($i \\approx 3$) at equal molarity.","difficulty":1,"sources":[[2026,"R","56/1/2",3]]},{"id":"c0733","chapter":3,"type":"mcq","text":"For a reaction : $\\mathrm{N_2 + 3H_2 \\longrightarrow 2NH_3}$, the rate of reaction with respect to $\\mathrm{NH_3}$ is","options":{"A":"$+\\dfrac{1}{3}\\dfrac{\\Delta[\\mathrm{NH_3}]}{\\Delta t}$","B":"$-\\dfrac{1}{2}\\dfrac{\\Delta[\\mathrm{NH_3}]}{\\Delta t}$","C":"$+\\dfrac{1}{4}\\dfrac{\\Delta[\\mathrm{NH_3}]}{\\Delta t}$","D":"$+\\dfrac{1}{2}\\dfrac{\\Delta[\\mathrm{NH_3}]}{\\Delta t}$"},"answer":"D","hint":"Divide by the stoichiometric coefficient; products have positive sign.","explanation":"Rate $= +\\frac{1}{2}\\Delta[\\mathrm{NH_3}]/\\Delta t$.","difficulty":1,"sources":[[2026,"R","56/1/2",4]]},{"id":"c0734","chapter":2,"type":"mcq","text":"How many Faradays are required to reduce 1 mol of $\\mathrm{Cr_2O_7^{2-}}$ to $\\mathrm{Cr^{3+}}$ in acidic medium ?","options":{"A":"2","B":"3","C":"6","D":"4"},"answer":"C","hint":"Count electrons in the half reaction.","explanation":"$\\mathrm{Cr_2O_7^{2-} + 14H^+ + 6e^- \\rightarrow 2Cr^{3+} + 7H_2O}$ needs 6 F.","difficulty":1,"sources":[[2026,"R","56/1/2",5]]},{"id":"c0735","chapter":7,"type":"mcq","text":"Which of the following Grignard Reagent will be used to prepare the alcohol shown in the figure when treated with methanal ?\n(The target alcohol is cyclohexylmethanol, $\\mathrm{C_6H_{11}CH_2OH}$, drawn as a structure.)","options":{"A":"$\\mathrm{CH_3MgBr}$","B":"Structure (B): cyclohexyl-$\\mathrm{CH_2MgBr}$","C":"Structure (C): cyclohexyl-$\\mathrm{MgBr}$","D":"Structure (D): cyclohexyl-$\\mathrm{CH_2CH_2MgBr}$"},"answer":"C","hint":"Grignard reagent plus HCHO adds one carbon and gives a primary alcohol.","explanation":"The carbon of HCHO becomes the $\\mathrm{CH_2OH}$, so the Grignard reagent is cyclohexylmagnesium bromide (C).","difficulty":2,"figure":"figures/c0735.png","sources":[[2026,"R","56/1/2",6]]},{"id":"c0736","chapter":5,"type":"mcq","text":"The secondary valency of Pt in $\\mathrm{[Pt(en)_2Cl_2]^{2+}}$ is","options":{"A":"6","B":"5","C":"4","D":"2"},"answer":"A","hint":"Secondary valency is the coordination number.","explanation":"Two bidentate en (4) plus two $\\mathrm{Cl^-}$ (2) give 6.","difficulty":1,"sources":[[2026,"R","56/1/2",7]]},{"id":"c0737","chapter":7,"type":"mcq","text":"$\\mathrm{(CH_3)_3C-OC_2H_5}$ on reaction with HI gives","options":{"A":"$\\mathrm{(CH_3)_3C-I}$ and $\\mathrm{C_2H_5-I}$","B":"$\\mathrm{(CH_3)_3C-OH}$ and $\\mathrm{C_2H_5-I}$","C":"$\\mathrm{(CH_3)_3C-I}$ and $\\mathrm{C_2H_5-OH}$","D":"$\\mathrm{(CH_3)_3C-OH}$ and $\\mathrm{C_2H_5-OH}$"},"answer":"C","hint":"Ethers with a tertiary alkyl group cleave by SN1.","explanation":"The tertiary carbocation forms, so iodide attaches to the tertiary carbon, leaving ethanol.","difficulty":2,"sources":[[2026,"R","56/1/2",8]]},{"id":"c0738","chapter":10,"type":"mcq","text":"An example of non-reducing sugar is","options":{"A":"Glucose","B":"Sucrose","C":"Lactose","D":"Maltose"},"answer":"B","hint":"Non-reducing sugars have both anomeric carbons in the glycosidic bond.","explanation":"In sucrose the C1 of glucose and C2 of fructose are linked, leaving no free anomeric -OH.","difficulty":1,"sources":[[2026,"R","56/1/2",11]]},{"id":"c0739","chapter":9,"type":"mcq","text":"Benzene diazonium chloride on reaction with phenol in weakly basic medium gives","options":{"A":"Azobenzene","B":"Benzene","C":"Chlorobenzene","D":"p-hydroxyazobenzene"},"answer":"D","hint":"Coupling reaction of diazonium salts.","explanation":"Coupling with phenol at the para position gives p-hydroxyazobenzene.","difficulty":1,"sources":[[2026,"R","56/1/2",12]]},{"id":"c0740","chapter":7,"type":"ar","text":"Assertion (A): The presence of -OH group in phenols directs the incoming group to ortho and para positions.\nReason (R): -OH group in phenols activates the aromatic ring towards electrophilic substitution reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Resonance donation from -OH increases electron density at o/p positions.","explanation":"Both true; activation by +R effect of -OH at o- and p- positions explains the directing effect.","difficulty":1,"sources":[[2026,"R","56/1/2",13]]},{"id":"c0741","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show irregularities in their electronic configurations.\nReason (R): In actinoids 5f, 6d and 7s orbitals are of comparable energies.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Why do 5f/6d electrons shift in actinoids?","explanation":"Both statements are true; the official key treats R as not the correct explanation of A.","difficulty":2,"note":"Official answer B; some argue R explains A.","sources":[[2026,"R","56/1/2",14]]},{"id":"c0742","chapter":1,"type":"ar","text":"Assertion (A): Components of azeotropes are easily separated by fractional distillation.\nReason (R): Components of an azeotrope have same composition in liquid and vapour phase.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Azeotropes boil at constant composition.","explanation":"A is false because azeotropes cannot be separated by fractional distillation; R is true.","difficulty":1,"sources":[[2026,"R","56/1/2",15]]},{"id":"c0743","chapter":10,"type":"ar","text":"Assertion (A): The two strands of DNA are complementary to each other.\nReason (R): The hydrogen bonds are formed between specific pairs of bases.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Base pairing A-T and G-C.","explanation":"Both true; specific hydrogen bonding of base pairs makes the strands complementary.","difficulty":1,"sources":[[2026,"R","56/1/2",16]]},{"id":"c0744","chapter":10,"type":"mcq","text":"In the ring structure of fructose, the anomeric carbon is","options":{"A":"C - 1","B":"C - 2","C":"C - 3","D":"C - 5"},"answer":"B","hint":"Anomeric carbon is the former carbonyl carbon.","explanation":"Fructose is a ketose with carbonyl at C-2, which becomes anomeric in the ring.","difficulty":1,"sources":[[2026,"R","56/1/3",1]]},{"id":"c0745","chapter":1,"type":"mcq","text":"Which of the following is the correct expression of $K_\\mathrm{f}$ which depends upon the nature of solvent ?","options":{"A":"$K_\\mathrm{f}=\\dfrac{M_1\\times T_\\mathrm{f}^2}{R\\times 1000\\times\\Delta_\\mathrm{fus}H}$","B":"$K_\\mathrm{f}=\\dfrac{R\\times M_1\\times\\Delta_\\mathrm{fus}H}{1000\\times T_\\mathrm{f}^2}$","C":"$K_\\mathrm{f}=\\dfrac{R\\times T_\\mathrm{f}^2\\times\\Delta_\\mathrm{fus}H}{1000\\times M_1}$","D":"$K_\\mathrm{f}=\\dfrac{R\\times M_1\\times T_\\mathrm{f}^2}{1000\\times\\Delta_\\mathrm{fus}H}$"},"answer":"D","hint":"Recall $K_\\mathrm{f}$ in terms of solvent properties.","explanation":"$K_\\mathrm{f} = RM_1T_\\mathrm{f}^2/(1000\\,\\Delta_\\mathrm{fus}H)$.","difficulty":2,"sources":[[2026,"R","56/1/3",2]]},{"id":"c0746","chapter":4,"type":"mcq","text":"Which of the following transition metals has lowest enthalpy of atomisation ?","options":{"A":"Cr","B":"V","C":"Mn","D":"Fe"},"answer":"C","hint":"Atomisation enthalpy depends on number of unpaired d electrons.","explanation":"Mn has weak metallic bonding (half-filled $3d^5$ stability, low delocalisation), giving the lowest enthalpy of atomisation among these.","difficulty":2,"sources":[[2026,"R","56/1/3",3]]},{"id":"c0747","chapter":5,"type":"mcq","text":"The secondary valency of Co in $\\mathrm{[Co(en)_3]^{3+}}$ is","options":{"A":"4","B":"3","C":"5","D":"6"},"answer":"D","hint":"en is bidentate.","explanation":"Three bidentate en ligands give coordination number 6.","difficulty":1,"sources":[[2026,"R","56/1/3",7]]},{"id":"c0748","chapter":7,"type":"mcq","text":"At low temperature, phenol on reaction with $\\mathrm{Br_2}$ in $\\mathrm{CS_2}$ gives","options":{"A":"2, 4, 6-Tribromophenol","B":"a mixture of ortho-and para-bromophenol","C":"ortho-bromophenol only","D":"para-bromophenol only"},"answer":"B","hint":"Non-polar solvent and low temperature limit the reaction to mono-bromination.","explanation":"In $\\mathrm{CS_2}$ at low temperature phenol gives monobromophenols, a mixture of o- and p-isomers.","difficulty":1,"sources":[[2026,"R","56/1/3",8]]},{"id":"c0749","chapter":2,"type":"mcq","text":"How the conductivity varies on decreasing concentration for both weak and strong electrolytes ?","options":{"A":"It increases for weak electrolyte and decreases for strong electrolyte.","B":"It decreases for weak electrolyte and increases for strong electrolyte.","C":"It increases for both weak and strong electrolytes.","D":"It decreases for both weak and strong electrolytes."},"answer":"D","hint":"Conductivity depends on number of ions per unit volume.","explanation":"On dilution the number of ions per unit volume decreases, so conductivity (not molar conductivity) decreases for both.","difficulty":1,"sources":[[2026,"R","56/1/3",9]]},{"id":"c0750","chapter":9,"type":"mcq","text":"$\\mathrm{CH_3-NH_2}$ on reaction with $\\mathrm{(CH_3CO)_2O}$ gives","options":{"A":"$\\mathrm{CH_3CONH_2}$","B":"$\\mathrm{CH_3COONHCH_3}$","C":"$\\mathrm{CH_3-NH-CO-CH_3}$","D":"$\\mathrm{CH_3-CO-CH_2-NH_2}$"},"answer":"C","hint":"Think of acylation of a primary amine.","explanation":"Acid anhydride acylates the amine to give the N-substituted amide N-methylethanamide, $\\mathrm{CH_3NHCOCH_3}$.","difficulty":1,"sources":[[2026,"R","56/1/3",10]]},{"id":"c0751","chapter":3,"type":"mcq","text":"The activation energy of a reaction can be determined from the slope of which of the following curves ?","options":{"A":"$\\ln k$ vs. $T$","B":"$\\ln k$ vs. $\\frac{1}{T}$","C":"$\\ln\\frac{k}{T}$ vs. $T$","D":"$\\frac{T}{\\ln k}$ vs. $\\frac{1}{T}$"},"answer":"B","hint":"Use the logarithmic form of the Arrhenius equation.","explanation":"$\\ln k=\\ln A-E_a/RT$, so the plot of $\\ln k$ vs. $1/T$ is linear with slope $-E_a/R$.","difficulty":1,"sources":[[2026,"R","56/1/3",11]]},{"id":"c0752","chapter":8,"type":"mcq","text":"Identify 'X' in the following reaction :\n$\\mathrm{CH_3-CO-CH_2-CO-O-CH_3}\\xrightarrow{\\mathrm{NaBH_4}}$ 'X'\n'X' is","options":{"A":"$\\mathrm{CH_3-CH(OH)-CH_2-CO-O-CH_3}$","B":"$\\mathrm{CH_3-CO-CH_2-CH_2-OH}$","C":"$\\mathrm{CH_3-CH(OH)-CH_2-CH_2-OH}$","D":"$\\mathrm{CH_3-CH(OH)-CH_2-COOH}$"},"answer":"A","hint":"Recall the selectivity of sodium borohydride.","explanation":"$\\mathrm{NaBH_4}$ reduces aldehydes and ketones but not esters, so only the ketone group becomes a secondary alcohol.","difficulty":2,"sources":[[2026,"R","56/1/3",12]]},{"id":"c0753","chapter":7,"type":"ar","text":"Assertion (A): The presence of –OH group in phenols directs the incoming group at ortho- and para- positions.\nReason (R): –OH group in phenols deactivates the aromatic ring.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Does –OH activate or deactivate the ring?","explanation":"A is true (–OH is o,p-directing); R is false since –OH activates the ring by +R effect.","difficulty":1,"sources":[[2026,"R","56/1/3",13]]},{"id":"c0754","chapter":4,"type":"ar","text":"Assertion (A): Actinoids show irregularities in their electronic configurations.\nReason (R): Due to varying stabilities of $f^0$, $f^7$ and $f^{14}$ occupancies of the 5f orbitals.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Think of the extra stability of empty, half-filled and fully filled f subshell.","explanation":"Both true; the stability of $5f^0$, $5f^7$, $5f^{14}$ causes the irregular configurations, so R explains A.","difficulty":1,"sources":[[2026,"R","56/1/3",14]]},{"id":"c0755","chapter":10,"type":"ar","text":"Assertion (A): The pentaacetate of glucose does not react with $\\mathrm{H_2N-OH}$.\nReason (R): It indicates the absence of free –CHO group in glucose.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Which group reacts with hydroxylamine?","explanation":"Pentaacetate formation uses all five –OH groups, and non-reaction with $\\mathrm{NH_2OH}$ shows no free –CHO (cyclic structure); R explains A.","difficulty":2,"sources":[[2026,"R","56/1/3",15]]},{"id":"c0756","chapter":1,"type":"ar","text":"Assertion (A): It is not possible to separate the components of an azeotrope by fractional distillation.\nReason (R): Minimum boiling azeotrope is formed by the solutions showing large positive deviation from Raoult's law.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"An azeotrope boils at constant composition.","explanation":"Both true; azeotropes have the same composition in liquid and vapour so cannot be separated, but positive deviation is not the reason for that.","difficulty":2,"sources":[[2026,"R","56/1/3",16]]},{"id":"c0757","chapter":2,"type":"mcq","text":"Consider the following reaction :\n$\\mathrm{Zn_{(s)}+Ag_2O_{(s)}+H_2O(\\mathit{l})\\rightarrow Zn^{2+}_{(aq)}+2Ag_{(s)}+2OH^-_{(aq)}}$\nGiven : $E^\\circ_{\\mathrm{Ag^+/Ag}}=0.80\\,\\mathrm{V}$, $E^\\circ_{\\mathrm{Zn^{2+}/Zn}}=-0.76\\,\\mathrm{V}$, $1\\,\\mathrm{F}=96500\\,\\mathrm{C\\,mol^{-1}}$\n$\\Delta_rG^\\circ$ for the above reaction is :","options":{"A":"$-301.080\\ \\mathrm{kJ\\,mol^{-1}}$","B":"$+310.080\\ \\mathrm{kJ\\,mol^{-1}}$","C":"$-326.070\\ \\mathrm{kJ\\,mol^{-1}}$","D":"$-375.060\\ \\mathrm{kJ\\,mol^{-1}}$"},"answer":"A","hint":"Use $\\Delta G^\\circ=-nFE^\\circ_\\mathrm{cell}$ with $n=2$.","explanation":"$E^\\circ_\\mathrm{cell}=0.80+0.76=1.56$ V; $\\Delta G^\\circ=-2\\times96500\\times1.56=-301080$ J $=-301.080$ kJ.","difficulty":2,"sources":[[2026,"R","56/2/1",1],[2026,"R","56/2/2",12],[2026,"R","56/2/3",2]]},{"id":"c0758","chapter":3,"type":"mcq","text":"Identify the correct statement :","options":{"A":"Molecularity of a reaction is an experimental quantity.","B":"For complex reactions molecularity has no meaning.","C":"Molecularity of a reaction can be zero or even a fraction.","D":"Molecularity more than three is very common in chemical reactions."},"answer":"B","hint":"Molecularity belongs to elementary steps only.","explanation":"Molecularity is theoretical, a whole number (1-3) and applies only to elementary reactions, so it has no meaning for complex reactions.","difficulty":1,"sources":[[2026,"R","56/2/1",2],[2026,"R","56/2/2",11],[2026,"R","56/2/3",1]]},{"id":"c0759","chapter":3,"type":"mcq","text":"The order for the given reaction is :\n$\\mathrm{A+2B\\rightarrow Products}$\nRate $=k[\\mathrm{A}]^{1/2}[\\mathrm{B}]^{1}$","options":{"A":"1.5","B":"1","C":"0.5","D":"2"},"answer":"A","hint":"Add the exponents of concentration terms.","explanation":"Order $=\\frac{1}{2}+1=1.5$.","difficulty":1,"sources":[[2026,"R","56/2/1",3],[2026,"R","56/2/2",10],[2026,"R","56/2/3",4]]},{"id":"c0760","chapter":4,"type":"mcq","text":"Electronic configuration of chromium is :","options":{"A":"$\\mathrm{[Ar]}\\,3d^4\\,4s^1$","B":"$\\mathrm{[Ar]}\\,3d^4\\,4s^2$","C":"$\\mathrm{[Ar]}\\,3d^5\\,4s^1$","D":"$\\mathrm{[Ar]}\\,3d^5\\,4s^2$"},"answer":"C","hint":"Half-filled d subshell gives extra stability.","explanation":"Cr ($Z=24$) is an exception: one 4s electron shifts to give the half-filled $3d^5\\,4s^1$.","difficulty":1,"sources":[[2026,"R","56/2/1",4],[2026,"R","56/2/2",9],[2026,"R","56/2/3",3]]},{"id":"c0761","chapter":5,"type":"mcq","text":"The correct IUPAC name of the complex $\\mathrm{[Pt(NH_3)_2Cl_2]}$ is :","options":{"A":"diamminedichloridoplatinum (IV)","B":"diamminedichloridoplatinum (II)","C":"dichloridodiammineplatinum (IV)","D":"dichloridodiammineplatinum (II)"},"answer":"B","hint":"Ligands are named alphabetically; find the Pt oxidation state.","explanation":"Ammine precedes chlorido alphabetically; $x+0+2(-1)=0$ gives Pt(II).","difficulty":2,"sources":[[2026,"R","56/2/1",5],[2026,"R","56/2/2",8],[2026,"R","56/2/3",6]]},{"id":"c0762","chapter":5,"type":"mcq","text":"Which of the following is heteroleptic complex ?","options":{"A":"$\\mathrm{[Co(NH_3)_6]^{3+}}$","B":"$\\mathrm{[Cr(NH_3)_6]^{3+}}$","C":"$\\mathrm{[Ni(H_2O)_6]^{2+}}$","D":"$\\mathrm{[Co(NH_3)_4Cl_2]^+}$"},"answer":"D","hint":"Heteroleptic means more than one kind of ligand.","explanation":"Only $\\mathrm{[Co(NH_3)_4Cl_2]^+}$ has two different ligands ($\\mathrm{NH_3}$ and $\\mathrm{Cl^-}$).","difficulty":1,"sources":[[2026,"R","56/2/1",6],[2026,"R","56/2/2",7],[2026,"R","56/2/3",5]]},{"id":"c0763","chapter":6,"type":"mcq","text":"Which of the following molecules is chiral in nature ?","options":{"A":"Propan-2-ol","B":"Butan-2-ol","C":"1-Bromobutane","D":"2-Bromopropane"},"answer":"B","hint":"Look for a carbon with four different groups.","explanation":"Butan-2-ol has C-2 bonded to H, OH, $\\mathrm{CH_3}$ and $\\mathrm{C_2H_5}$, so it is chiral.","difficulty":1,"sources":[[2026,"R","56/2/1",7],[2026,"R","56/2/2",6],[2026,"R","56/2/3",8]]},{"id":"c0764","chapter":7,"type":"mcq","text":"Identify the correct increasing order of boiling points of the given compounds :","options":{"A":"Propan-1-ol < butan-1-ol < butan-2-ol < pentan-1-ol","B":"Pentan-1-ol < butan-1-ol < butan-2-ol < Propan-1-ol","C":"Propan-1-ol < butan-2-ol < butan-1-ol < pentan-1-ol","D":"Butan-1-ol < Butan-2-ol < Propan-1-ol < Pentan-1-ol"},"answer":"C","hint":"Boiling point rises with chain length and falls with branching.","explanation":"Order: propan-1-ol (97 C) < butan-2-ol (99.5 C) < butan-1-ol (118 C) < pentan-1-ol (138 C).","difficulty":2,"sources":[[2026,"R","56/2/1",8],[2026,"R","56/2/2",5],[2026,"R","56/2/3",7]]},{"id":"c0765","chapter":9,"type":"mcq","text":"Identify the compound produced by the reduction of Ethanenitrile with Lithium aluminium hydride :","options":{"A":"Ethylamine","B":"Ethanal","C":"Propylamine","D":"Methylamine"},"answer":"A","hint":"LiAlH4 reduces $\\mathrm{-C\\equiv N}$ to a primary amine with the same carbon count.","explanation":"$\\mathrm{CH_3CN}\\xrightarrow{\\mathrm{LiAlH_4}}\\mathrm{CH_3CH_2NH_2}$, ethylamine.","difficulty":1,"sources":[[2026,"R","56/2/1",9],[2026,"R","56/2/2",4],[2026,"R","56/2/3",10]]},{"id":"c0766","chapter":10,"type":"mcq","text":"The base which is present in DNA but not in RNA is :","options":{"A":"Guanine","B":"Cytosine","C":"Thymine","D":"Adenine"},"answer":"C","hint":"RNA has uracil instead of one base.","explanation":"Thymine occurs in DNA; RNA contains uracil in its place.","difficulty":1,"sources":[[2026,"R","56/2/1",10],[2026,"R","56/2/2",3],[2026,"R","56/2/3",9]]},{"id":"c0767","chapter":10,"type":"mcq","text":"Proteins are polymers of $\\alpha$-amino acids which are joined to each other by :","options":{"A":"Covalent Bond","B":"Peptide Bond","C":"Glycosidic Bond","D":"Coordinate Bond"},"answer":"B","hint":"Link between -COOH and -NH2 of amino acids.","explanation":"Amino acids are linked by amide (peptide) bonds.","difficulty":1,"sources":[[2026,"R","56/2/1",11],[2026,"R","56/2/2",2],[2026,"R","56/2/3",12]]},{"id":"c0768","chapter":10,"type":"mcq","text":"Which of the following reactions is not explained by the open chain structure of glucose ?","options":{"A":"Glucose on prolonged heating with HI forms n-hexane.","B":"Glucose reacts with hydroxylamine to form an oxime.","C":"Glucose gets oxidized to gluconic acid on reaction with bromine water.","D":"Glucose exists in two different crystalline forms, alpha ($\\alpha$) and beta ($\\beta$)."},"answer":"D","hint":"Anomers arise from ring closure.","explanation":"$\\alpha$ and $\\beta$ forms (anomers) arise from the cyclic hemiacetal structure, not the open chain.","difficulty":1,"sources":[[2026,"R","56/2/1",12],[2026,"R","56/2/2",1],[2026,"R","56/2/3",11]]},{"id":"c0769","chapter":3,"type":"ar","text":"Assertion (A): The molecularity of the given reaction is 2\n$\\mathrm{2HI\\longrightarrow H_2+I_2}$\nReason (R): Two molecules of the reactants are involved in simultaneous collision between them.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Molecularity is the number of species colliding in an elementary step.","explanation":"Both true; two HI molecules collide simultaneously, which is exactly why molecularity is 2.","difficulty":1,"sources":[[2026,"R","56/2/1",13],[2026,"R","56/2/2",16],[2026,"R","56/2/3",14]]},{"id":"c0770","chapter":9,"type":"ar","text":"Assertion (A): Aromatic primary amines can be prepared by Gabriel Phthalimide synthesis.\nReason (R): Aryl halides do not undergo nucleophilic substitution with the anion formed by phthalimide.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Aryl halides are inert to SN2 by phthalimide anion.","explanation":"A is false because aryl halides cannot react with phthalimide anion; R is true.","difficulty":2,"sources":[[2026,"R","56/2/1",15],[2026,"R","56/2/2",14],[2026,"R","56/2/3",16]]},{"id":"c0771","chapter":10,"type":"ar","text":"Assertion (A): Glucose gets oxidized to six carbon gluconic acid on reaction with bromine water.\nReason (R): The carbonyl group is absent in the open chain structure of glucose.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Open chain glucose has an aldehyde group.","explanation":"A is true (CHO to COOH); R is false because the open chain has a carbonyl (aldehyde) group.","difficulty":1,"sources":[[2026,"R","56/2/1",16],[2026,"R","56/2/2",13],[2026,"R","56/2/3",15]]},{"id":"c0772","chapter":6,"type":"mcq","text":"Which of the following will be the least reactive towards nucleophilic substitution reaction ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"B","hint":"Aryl halides resist nucleophilic substitution.","explanation":"(A) benzyl chloride, (C) methyl chloride, (D) chlorocyclohexane are alkyl halides; (B) is an aryl halide with partial double bond character in C-Cl, so least reactive.","difficulty":2,"figure":"figures/c0772.png","sources":[[2026,"R","56/3/1",1]]},{"id":"c0773","chapter":7,"type":"mcq","text":"The intermediate formed during the slowest step involved in the dehydration of alcohol is :","options":{"A":"protonated alcohol","B":"carbanion","C":"free radical","D":"carbocation"},"answer":"D","hint":"The rate-determining step is loss of water from protonated alcohol.","explanation":"Protonated alcohol loses water slowly to form a carbocation, the rate-determining step.","difficulty":1,"sources":[[2026,"R","56/3/1",2]]},{"id":"c0774","chapter":5,"type":"mcq","text":"The oxidation number of Co in $\\mathrm{[Co(en)_3]_2(SO_4)_3}$ is :","options":{"A":"+3","B":"+2","C":"+4","D":"+6"},"answer":"A","hint":"en is neutral; balance charge with sulfate.","explanation":"Complex ion is $\\mathrm{[Co(en)_3]^{3+}}$ since $2x$ balances $3\\times(-2)$; en is neutral so Co is +3.","difficulty":1,"sources":[[2026,"R","56/3/1",3]]},{"id":"c0775","chapter":5,"type":"mcq","text":"According to Werner's theory, the primary valencies of the central metal atom :","options":{"A":"are satisfied by neutral molecules or negative ions.","B":"are equal to its coordination number.","C":"are satisfied by negative ions.","D":"are non-ionisable."},"answer":"C","hint":"Primary valency corresponds to oxidation state.","explanation":"Primary valencies are ionisable and satisfied only by negative ions; secondary valencies can be satisfied by neutral or negative ligands.","difficulty":1,"sources":[[2026,"R","56/3/1",4],[2026,"R","56/3/2",6],[2026,"R","56/3/3",1]]},{"id":"c0776","chapter":9,"type":"mcq","text":"Which of the following reagent is used to distinguish between $\\mathrm{(C_2H_5)_2NH}$ and $\\mathrm{(C_2H_5)_3N}$ ?","options":{"A":"$\\mathrm{CHCl_3+KOH}$","B":"$\\mathrm{C_6H_5SO_2Cl}$","C":"Conc. $\\mathrm{HCl+ZnCl_2}$","D":"$\\mathrm{NaOH+I_2}$"},"answer":"B","hint":"Hinsberg reagent distinguishes amine classes.","explanation":"Benzenesulfonyl chloride reacts with the secondary amine to give a sulfonamide but not with the tertiary amine.","difficulty":1,"sources":[[2026,"R","56/3/1",5]]},{"id":"c0777","chapter":9,"type":"mcq","text":"Among the following, which is the strongest base ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"B","hint":"Lone pair on N is not delocalised in benzylamine.","explanation":"In benzylamine the $\\mathrm{NH_2}$ is not attached to the ring, so lone pair is not delocalised; it is stronger than all the aromatic amines.","difficulty":2,"figure":"figures/c0777.png","sources":[[2026,"R","56/3/1",6]]},{"id":"c0778","chapter":4,"type":"mcq","text":"In aqueous solution, $\\mathrm{Cr_2O_7^{2-}}$ ion converts to which of the following in alkaline medium ?","options":{"A":"$\\mathrm{Cr^{3+}}$","B":"$\\mathrm{CrO_4^{2-}}$","C":"$\\mathrm{CrO}$","D":"$\\mathrm{CrO_3}$"},"answer":"B","hint":"Dichromate-chromate equilibrium depends on pH.","explanation":"$\\mathrm{Cr_2O_7^{2-}+2OH^-\\rightarrow 2CrO_4^{2-}+H_2O}$.","difficulty":1,"sources":[[2026,"R","56/3/1",7]]},{"id":"c0779","chapter":1,"type":"mcq","text":"The boiling point of an azeotropic mixture of water and ethanol is less than that of pure water and ethanol. The mixture shows :","options":{"A":"positive deviation from Raoult's Law.","B":"negative deviation from Raoult's Law.","C":"no deviation from Raoult's Law.","D":"that the solution is an ideal solution."},"answer":"A","hint":"Minimum boiling azeotrope implies high vapour pressure.","explanation":"Minimum boiling azeotropes arise from positive deviation (weaker interactions, higher vapour pressure).","difficulty":1,"sources":[[2026,"R","56/3/1",8]]},{"id":"c0780","chapter":1,"type":"mcq","text":"The mole fraction of a solute in 2.0 molal aqueous solution is :","options":{"A":"1.87","B":"0.347","C":"0.0347","D":"0.00347"},"answer":"C","hint":"2 molal means 2 mol solute per 1000 g (55.5 mol) of water.","explanation":"$\\chi=2/(2+55.5)=0.0348\\approx0.0347$.","difficulty":2,"sources":[[2026,"R","56/3/1",9],[2026,"R","56/3/2",1],[2026,"R","56/3/3",7]]},{"id":"c0781","chapter":2,"type":"mcq","text":"On electrolysis of very dilute aqueous solution of NaCl using platinum electrodes :","options":{"A":"$\\mathrm{H_2}$ gas is evolved at anode.","B":"Na is produced at cathode.","C":"$\\mathrm{O_2}$ gas is evolved at anode.","D":"$\\mathrm{H_2}$ gas is evolved at cathode."},"answer":"D","hint":"Compare discharge of water with Na+ and Cl-.","explanation":"At the cathode water is reduced to $\\mathrm{H_2}$ in preference to $\\mathrm{Na^+}$.","difficulty":2,"sources":[[2026,"R","56/3/1",10],[2026,"R","56/3/2",2],[2026,"R","56/3/3",5]]},{"id":"c0782","chapter":3,"type":"mcq","text":"For a reaction $\\mathrm{3A\\rightarrow 2B}$, the rate of reaction $+\\frac{d[\\mathrm{B}]}{dt}$ is equal to :","options":{"A":"$-\\frac{3}{2}\\frac{d[\\mathrm{A}]}{dt}$","B":"$-\\frac{2}{3}\\frac{d[\\mathrm{A}]}{dt}$","C":"$-\\frac{1}{3}\\frac{d[\\mathrm{A}]}{dt}$","D":"$+2\\frac{d[\\mathrm{A}]}{dt}$"},"answer":"B","hint":"Equate $-\\frac13 d[A]/dt$ with $\\frac12 d[B]/dt$.","explanation":"$\\frac{1}{2}\\frac{d[B]}{dt}=-\\frac{1}{3}\\frac{d[A]}{dt}$, so $\\frac{d[B]}{dt}=-\\frac{2}{3}\\frac{d[A]}{dt}$.","difficulty":2,"sources":[[2026,"R","56/3/1",11]]},{"id":"c0783","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives only glucose ?","options":{"A":"Sucrose","B":"Galactose","C":"Lactose","D":"Maltose"},"answer":"D","hint":"Which disaccharide has two glucose units?","explanation":"Maltose gives two glucose units; sucrose gives glucose and fructose, lactose gives glucose and galactose, galactose is a monosaccharide.","difficulty":1,"sources":[[2026,"R","56/3/1",12]]},{"id":"c0784","chapter":4,"type":"ar","text":"Assertion (A): Separation of Zr and Hf is difficult.\nReason (R): Because Zr and Hf lie in the same group of the periodic table.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Think of lanthanoid contraction.","explanation":"Per official key A is true and R false; separation is hard because of near-identical radii (lanthanoid contraction), not merely same group.","difficulty":2,"note":"Official answer C; R is literally true but the real reason is lanthanoid contraction.","sources":[[2026,"R","56/3/1",13]]},{"id":"c0785","chapter":7,"type":"ar","text":"Assertion (A): Phenol is less acidic than 4-methylphenol.\nReason (R): The presence of an electron releasing group in phenol makes it less acidic.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Electron releasing groups destabilise the phenoxide ion.","explanation":"A is false: 4-methylphenol is less acidic than phenol; R is true as an electron releasing group lowers acidity.","difficulty":2,"sources":[[2026,"R","56/3/1",14]]},{"id":"c0786","chapter":9,"type":"ar","text":"Assertion (A): Aromatic primary amines cannot be prepared by Gabriel phthalimide synthesis.\nReason (R): Gabriel phthalimide synthesis is used for the preparation of primary aliphatic amines.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Why does the aryl halide fail in Gabriel synthesis?","explanation":"Both true, but R only states usage; the actual reason is that aryl halides do not undergo SN by phthalimide anion.","difficulty":2,"note":"Official answer B.","sources":[[2026,"R","56/3/1",15]]},{"id":"c0787","chapter":3,"type":"ar","text":"Assertion (A): Order of reaction is applicable to elementary as well as complex reactions.\nReason (R): Order of a reaction is an experimental quantity.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Order is determined experimentally for any reaction.","explanation":"Both true; order applies to all reactions, but being experimental does not explain why it applies to both.","difficulty":2,"sources":[[2026,"R","56/3/1",16]]},{"id":"c0788","chapter":6,"type":"mcq","text":"Which of the following, compounds is most reactive towards nucleophilic substitution reaction with aqueous NaOH ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"D","hint":"Electron-withdrawing groups at o/p activate aryl halides.","explanation":"In (D) the o- and p-nitro groups stabilise the Meisenheimer intermediate, making it most reactive.","difficulty":2,"figure":"figures/c0788.png","sources":[[2026,"R","56/3/2",3]]},{"id":"c0789","chapter":7,"type":"mcq","text":"The dehydration of $1^\\circ$, $2^\\circ$ and $3^\\circ$ alcohols follows the order :","options":{"A":"$2^\\circ>1^\\circ>3^\\circ$","B":"$3^\\circ>2^\\circ>1^\\circ$","C":"$1^\\circ>2^\\circ>3^\\circ$","D":"$1^\\circ>3^\\circ>2^\\circ$"},"answer":"B","hint":"Order follows carbocation stability.","explanation":"Dehydration goes through carbocations, so $3^\\circ>2^\\circ>1^\\circ$.","difficulty":1,"sources":[[2026,"R","56/3/2",4]]},{"id":"c0790","chapter":5,"type":"mcq","text":"The oxidation number of Co in $\\mathrm{[Co(NH_3)_5(ONO)]SO_4}$ is :","options":{"A":"+3","B":"+2","C":"+4","D":"+6"},"answer":"A","hint":"Add ligand charges and balance with sulfate.","explanation":"$\\mathrm{SO_4^{2-}}$ outside, so complex is +2; $x+0-1=+2$ gives $x=+3$.","difficulty":1,"sources":[[2026,"R","56/3/2",5]]},{"id":"c0791","chapter":9,"type":"mcq","text":"Which reagent is used to distinguish between $\\mathrm{C_2H_5NH_2}$ and $\\mathrm{(C_2H_5)_2NH}$ ?","options":{"A":"$\\mathrm{KMnO_4}$","B":"$\\mathrm{CHCl_3+KOH}$ (ethanolic)","C":"$\\mathrm{NaOH+I_2}$","D":"Neutral $\\mathrm{FeCl_3}$"},"answer":"B","hint":"Carbylamine test is specific to primary amines.","explanation":"Primary amine gives foul-smelling isocyanide with $\\mathrm{CHCl_3+KOH}$; secondary does not.","difficulty":1,"sources":[[2026,"R","56/3/2",7]]},{"id":"c0792","chapter":9,"type":"mcq","text":"Among the following, which one has the lowest value of $\\mathrm{p}K_b$ ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"A","hint":"Lowest $\\mathrm{p}K_b$ means strongest base.","explanation":"Benzylamine (A) is an aliphatic-type amine with undelocalised lone pair and is the strongest base, hence lowest $\\mathrm{p}K_b$.","difficulty":2,"figure":"figures/c0792.png","sources":[[2026,"R","56/3/2",8]]},{"id":"c0793","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives only glucose ?","options":{"A":"Starch","B":"Sucrose","C":"Lactose","D":"Galactose"},"answer":"A","hint":"Which one is a polymer of glucose?","explanation":"Starch is a polymer of $\\alpha$-glucose and hydrolyses to glucose only.","difficulty":1,"sources":[[2026,"R","56/3/2",11]]},{"id":"c0794","chapter":3,"type":"mcq","text":"For the reaction $\\mathrm{2A\\rightarrow 3B}$, the rate of reaction $+\\frac{d[\\mathrm{B}]}{dt}$ is equal to :","options":{"A":"$-\\frac{3}{2}\\frac{d[\\mathrm{A}]}{dt}$","B":"$-\\frac{2}{3}\\frac{d[\\mathrm{A}]}{dt}$","C":"$-\\frac{1}{2}\\frac{d[\\mathrm{A}]}{dt}$","D":"$+3\\frac{d[\\mathrm{A}]}{dt}$"},"answer":"A","hint":"Equate $-\\frac12 d[A]/dt$ with $\\frac13 d[B]/dt$.","explanation":"$\\frac{1}{3}\\frac{d[B]}{dt}=-\\frac{1}{2}\\frac{d[A]}{dt}$, so $\\frac{d[B]}{dt}=-\\frac{3}{2}\\frac{d[A]}{dt}$.","difficulty":2,"sources":[[2026,"R","56/3/2",12]]},{"id":"c0795","chapter":4,"type":"ar","text":"Assertion (A): Separation of Zr and Hf is difficult.\nReason (R): Zr and Hf have almost identical atomic and ionic radii due to lanthanoid contraction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Lanthanoid contraction makes Zr and Hf alike.","explanation":"Both true; near-identical radii give similar properties, making separation difficult.","difficulty":1,"sources":[[2026,"R","56/3/2",13]]},{"id":"c0796","chapter":9,"type":"ar","text":"Assertion (A): Aromatic primary amines can easily be prepared by Gabriel phthalimide synthesis.\nReason (R): Gabriel phthalimide synthesis is used to prepare only aliphatic primary amines.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Aryl halides do not undergo nucleophilic substitution easily with phthalimide anion.","explanation":"A is false because aryl halides resist nucleophilic substitution; R is true.","difficulty":1,"sources":[[2026,"R","56/3/2",15]]},{"id":"c0797","chapter":3,"type":"ar","text":"Assertion (A): Order of reaction is not applicable for elementary reaction but applicable for complex reaction.\nReason (R): Order of reaction is an experimental quantity.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Think about which terms apply to elementary versus complex reactions.","explanation":"A is false (order can be defined for any reaction, molecularity applies only to elementary steps); R is true.","difficulty":2,"sources":[[2026,"R","56/3/2",16]]},{"id":"c0798","chapter":7,"type":"mcq","text":"Which of the following product is formed when salicylic acid is treated with $\\mathrm{(CH_3CO)_2O}$ in the presence of acid ?","options":{"A":"Structure (A)","B":"Structure (B)","C":"Structure (C)","D":"Structure (D)"},"answer":"D","hint":"This is the preparation of aspirin: which group gets acetylated?","explanation":"The phenolic OH is acetylated to OCOCH3 while COOH stays, giving acetylsalicylic acid.","difficulty":1,"figure":"figures/c0798.png","sources":[[2026,"R","56/3/3",3]]},{"id":"c0799","chapter":9,"type":"mcq","text":"Which reagent is used to distinguish between primary, secondary and tertiary amines ?","options":{"A":"$\\mathrm{C_6H_5SO_2Cl}$","B":"$\\mathrm{C_6H_5COCl}$","C":"$\\mathrm{CHCl_3}$ + ethanolic KOH","D":"$\\mathrm{NaOH + I_2}$"},"answer":"A","hint":"Hinsberg's reagent.","explanation":"Benzenesulphonyl chloride gives alkali-soluble product with 1°, insoluble with 2°, and no reaction with 3° amines.","difficulty":1,"sources":[[2026,"R","56/3/3",4]]},{"id":"c0800","chapter":9,"type":"mcq","text":"The correct order of decreasing basic strength in aqueous solution of the following is :","options":{"A":"$\\mathrm{(C_2H_5)_3N > C_2H_5NH_2 > (C_2H_5)_2NH}$","B":"$\\mathrm{(C_2H_5)_2NH > C_2H_5NH_2 > (C_2H_5)_3N}$","C":"$\\mathrm{C_2H_5NH_2 > (C_2H_5)_2NH > (C_2H_5)_3N}$","D":"$\\mathrm{(C_2H_5)_2NH > (C_2H_5)_3N > C_2H_5NH_2}$"},"answer":"D","hint":"Combine inductive effect with solvation of the ammonium ion in water.","explanation":"For ethyl amines in water the order is secondary > tertiary > primary.","difficulty":2,"sources":[[2026,"R","56/3/3",6]]},{"id":"c0801","chapter":4,"type":"mcq","text":"Which of the following transition metals shows +1 and +2 oxidation states ?","options":{"A":"Mn","B":"Zn","C":"Cu","D":"Sc"},"answer":"C","hint":"Think of Cu+ and Cu2+.","explanation":"Cu shows +1 and +2; Mn has many, Zn only +2, Sc only +3.","difficulty":1,"sources":[[2026,"R","56/3/3",8]]},{"id":"c0802","chapter":10,"type":"mcq","text":"On hydrolysis, which of the following carbohydrates gives only $\\beta$-glucose ?","options":{"A":"Starch","B":"Sucrose","C":"Maltose","D":"Cellulose"},"answer":"D","hint":"Consider the glycosidic linkage type in each polymer.","explanation":"Cellulose is made of β-D-glucose units joined by β-1,4 links; starch and maltose give α-glucose.","difficulty":1,"sources":[[2026,"R","56/3/3",9]]},{"id":"c0803","chapter":6,"type":"mcq","text":"Consider the following compounds :\nChlorobenzene (I), 2,4,6-trinitrochlorobenzene (II),\n2,4-dinitrochlorobenzene (III), 4-nitrochlorobenzene (IV)\nThe correct order of increasing ease of nucleophilic substitution reactions of these compounds is :","options":{"A":"I < IV < III < II","B":"I < III < IV < II","C":"II < III < IV < I","D":"IV < III < II < I"},"answer":"A","hint":"More electron-withdrawing groups at o/p positions favour nucleophilic substitution.","explanation":"Ease increases with number of o/p nitro groups: I < IV < III < II.","difficulty":2,"sources":[[2026,"R","56/3/3",10]]},{"id":"c0804","chapter":3,"type":"mcq","text":"The half-life periods of decomposition of $\\mathrm{NH_3}$ for different initial pressures are given below :\n$p$ (torr): 704, 75, 34.5\n$t_{1/2}$ (min): 80, 80, 80\nThe order of the reaction is :","options":{"A":"zero order","B":"first order","C":"0.5","D":"second order"},"answer":"B","hint":"Check how half-life depends on initial concentration.","explanation":"Half-life is independent of initial pressure, so the reaction is first order.","difficulty":1,"sources":[[2026,"R","56/3/3",11]]},{"id":"c0805","chapter":1,"type":"mcq","text":"1 mole of liquid A and 2 moles of liquid B make a solution having a total vapour pressure 40 torr. The vapour pressure of pure A and pure B are 30 torr and 45 torr respectively. The above solution :","options":{"A":"is an ideal solution.","B":"shows negative deviation from Raoult's Law.","C":"shows positive deviation from Raoult's Law.","D":"is a maximum boiling azeotrope."},"answer":"A","hint":"Calculate the Raoult's law vapour pressure and compare.","explanation":"$P = \\tfrac13(30)+\\tfrac23(45)=40$ torr equals the observed value, so the solution is ideal.","difficulty":2,"sources":[[2026,"R","56/3/3",12]]},{"id":"c0806","chapter":9,"type":"ar","text":"Assertion (A): Monobromination of aniline can be conveniently done by protecting the amino group by acetylation.\nReason (R): Acetylation increases the activation effect of the amino group.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Does acetylation make the nitrogen lone pair more or less available?","explanation":"A is true; R is false since acetylation decreases the activating effect, preventing polybromination.","difficulty":2,"sources":[[2026,"R","56/3/3",15]]},{"id":"c0807","chapter":6,"type":"mcq","text":"Oxidation of chloroform by air in the presence of sunlight produces a poisonous gas known as :","options":{"A":"Mustard gas","B":"Tear gas","C":"Chlorine gas","D":"Phosgene gas"},"answer":"D","hint":"Chloroform is stored in dark bottles for this reason.","explanation":"$\\mathrm{CHCl_3}$ is oxidised to carbonyl chloride, phosgene.","difficulty":1,"sources":[[2026,"R","56/4/1",1]]},{"id":"c0808","chapter":7,"type":"mcq","text":"Lucas reagent produces cloudiness immediately with :","options":{"A":"2-methyl-1-propanol","B":"Butan-2-ol","C":"2-methyl-2-propanol","D":"Butan-1-ol"},"answer":"C","hint":"Reactivity with Lucas reagent follows 3° > 2° > 1°.","explanation":"Tertiary alcohol 2-methyl-2-propanol gives immediate turbidity.","difficulty":1,"sources":[[2026,"R","56/4/1",2]]},{"id":"c0809","chapter":5,"type":"mcq","text":"Which of the following d-orbitals experience more repulsion in the crystal field splitting of octahedral complex ?","options":{"A":"$d_{xy}, d_{yz}, d_{xz}$","B":"$d_{x^2-y^2}, d_{z^2}$","C":"$d_{xy}, d_{x^2-y^2}$","D":"$d_{xz}, d_{z^2}$"},"answer":"B","hint":"Ligands approach along the axes.","explanation":"The $e_g$ orbitals point along the axes toward ligands and are raised in energy.","difficulty":1,"sources":[[2026,"R","56/4/1",3],[2026,"R","56/4/3",4]]},{"id":"c0810","chapter":5,"type":"mcq","text":"The chelating ligand used for the treatment of lead poisoning is :","options":{"A":"Ethane-1,2-diamine","B":"Oxalate ion","C":"Dimethylglyoxime","D":"EDTA"},"answer":"D","hint":"A hexadentate ligand is used in chelation therapy.","explanation":"EDTA forms stable soluble complexes with lead which are excreted.","difficulty":1,"sources":[[2026,"R","56/4/1",4]]},{"id":"c0811","chapter":4,"type":"mcq","text":"Manganate ion is paramagnetic due to the presence of :","options":{"A":"one unpaired electron","B":"two unpaired electrons","C":"three unpaired electrons","D":"fully paired electrons"},"answer":"A","hint":"Find the oxidation state of Mn in manganate.","explanation":"$\\mathrm{MnO_4^{2-}}$ has Mn(VI), $3d^1$, so one unpaired electron.","difficulty":1,"sources":[[2026,"R","56/4/1",5]]},{"id":"c0812","chapter":9,"type":"mcq","text":"The correct order of decreasing basicities of $\\mathrm{C_2H_5NH_2}$, $\\mathrm{(C_2H_5)_2NH}$ and $\\mathrm{(C_2H_5)_3N}$ in aqueous solution is :","options":{"A":"$\\mathrm{(C_2H_5)_3N > (C_2H_5)_2NH > C_2H_5NH_2}$","B":"$\\mathrm{(C_2H_5)_2NH > C_2H_5NH_2 > (C_2H_5)_3N}$","C":"$\\mathrm{C_2H_5NH_2 > (C_2H_5)_2NH > (C_2H_5)_3N}$","D":"$\\mathrm{(C_2H_5)_2NH > (C_2H_5)_3N > C_2H_5NH_2}$"},"answer":"D","hint":"Combine inductive effect with solvation of the ammonium ion.","explanation":"In water the order for ethylamines is secondary > tertiary > primary.","difficulty":2,"sources":[[2026,"R","56/4/1",6]]},{"id":"c0813","chapter":1,"type":"mcq","text":"The boiling point of one molal NaCl solution, assuming NaCl to be completely dissociated in water is : ($K_b$ for water = $0.52\\ \\mathrm{K\\,kg\\,mol^{-1}}$)","options":{"A":"100.52°C","B":"101.04°C","C":"100.04°C","D":"101.52°C"},"answer":"B","hint":"$\\Delta T_b = i K_b m$ with $i = 2$.","explanation":"$\\Delta T_b = 2\\times0.52\\times1 = 1.04$ K, so boiling point is 101.04°C.","difficulty":1,"sources":[[2026,"R","56/4/1",7],[2026,"R","56/4/2",8],[2026,"R","56/4/3",6]]},{"id":"c0814","chapter":1,"type":"mcq","text":"When a liquid and its vapour are at equilibrium and the pressure is suddenly decreased :","options":{"A":"vapour pressure of the solution increases","B":"heating occurs","C":"cooling occurs","D":"equilibrium remains unaffected"},"answer":"C","hint":"Which direction does the equilibrium shift, and is vaporisation endothermic?","explanation":"Lower pressure favours evaporation, which absorbs heat, so cooling occurs.","difficulty":2,"sources":[[2026,"R","56/4/1",8],[2026,"R","56/4/2",7],[2026,"R","56/4/3",9]]},{"id":"c0815","chapter":2,"type":"mcq","text":"Consider the following cell at 298 K :\n$\\mathrm{Mg(s)\\,|\\,Mg^{2+}(1.0\\ M)\\,||\\,Cu^{2+}(1.0\\ M)\\,|\\,Cu(s)}$\nHow can we increase the emf of the cell using the same substances ?","options":{"A":"By decreasing only the $\\mathrm{[Mg^{2+}]}$ to 0.1 M","B":"By decreasing only the $\\mathrm{[Cu^{2+}]}$ to 0.1 M","C":"By increasing both $\\mathrm{[Mg^{2+}]}$ and $\\mathrm{[Cu^{2+}]}$ to 2.0 M","D":"By increasing only the $\\mathrm{[Mg^{2+}]}$ to 2.0 M"},"answer":"A","hint":"Use the Nernst equation with $Q=[\\mathrm{Mg^{2+}}]/[\\mathrm{Cu^{2+}}]$.","explanation":"$E=E^\\circ-\\frac{0.059}{2}\\log\\frac{[Mg^{2+}]}{[Cu^{2+}]}$; emf rises when $[Mg^{2+}]$ decreases.","difficulty":2,"sources":[[2026,"R","56/4/1",9],[2026,"R","56/4/2",10],[2026,"R","56/4/3",8]]},{"id":"c0816","chapter":3,"type":"mcq","text":"The rate of a first order reaction is $5.6\\times10^{-4}\\ \\mathrm{mol\\,L^{-1}\\,s^{-1}}$, when the concentration of reactant is $0.2\\ \\mathrm{mol\\,L^{-1}}$. The rate constant 'k' is :","options":{"A":"$5.6\\times10^{-3}\\ \\mathrm{s^{-1}}$","B":"$2.8\\times10^{-4}\\ \\mathrm{s^{-1}}$","C":"$2.8\\times10^{-5}\\ \\mathrm{s^{-1}}$","D":"$2.8\\times10^{-3}\\ \\mathrm{s^{-1}}$"},"answer":"D","hint":"Rate = k[A] for first order.","explanation":"$k = 5.6\\times10^{-4}/0.2 = 2.8\\times10^{-3}\\ \\mathrm{s^{-1}}$.","difficulty":1,"sources":[[2026,"R","56/4/1",10],[2026,"R","56/4/2",9],[2026,"R","56/4/3",11]]},{"id":"c0817","chapter":10,"type":"mcq","text":"Nucleic acids are polymers of :","options":{"A":"amino acids","B":"nucleosides","C":"nucleotides","D":"pentose sugar"},"answer":"C","hint":"Monomer includes sugar, base and phosphate.","explanation":"Nucleic acids are long chains of nucleotides joined by phosphodiester bonds.","difficulty":1,"sources":[[2026,"R","56/4/1",11]]},{"id":"c0818","chapter":9,"type":"mcq","text":"In the reaction of NaOBr with amide, the carbonyl carbon is lost as :","options":{"A":"$\\mathrm{HCO_3^-}$","B":"$\\mathrm{CO_3^{2-}}$","C":"$\\mathrm{CO_2}$","D":"CO"},"answer":"B","hint":"Hofmann bromamide degradation occurs in aqueous alkali.","explanation":"The isocyanate is hydrolysed and CO2 is absorbed by NaOH, giving carbonate.","difficulty":1,"sources":[[2026,"R","56/4/1",12]]},{"id":"c0819","chapter":7,"type":"ar","text":"Assertion (A): Alcohols act as Bronsted bases as well as Bronsted acids.\nReason (R): It is due to the presence of unshared electron pairs on oxygen atom and presence of polar O – H bond.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Acid behaviour needs a polar O-H, base behaviour needs a lone pair.","explanation":"Both true; polar O-H gives acidity and lone pairs give basicity, so R explains A.","difficulty":1,"sources":[[2026,"R","56/4/1",13]]},{"id":"c0820","chapter":3,"type":"ar","text":"Assertion (A): For complex reaction, order of reaction is given by the slowest step.\nReason (R): Order of a reaction is an experimental quantity.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Rate-determining step versus how order is determined.","explanation":"Both true, but the experimental nature of order does not explain why the slowest step governs it.","difficulty":2,"sources":[[2026,"R","56/4/1",15]]},{"id":"c0821","chapter":4,"type":"ar","text":"Assertion (A): $E^\\circ_{\\mathrm{Sc^{3+}/Sc^{2+}}}$ has low value.\nReason (R): Because of the stability of $\\mathrm{Sc^{3+}}$ ion which has a noble gas configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Consider the electronic configuration of Sc3+.","explanation":"Sc3+ is $3d^0$ noble-gas-like and very stable, so reduction to Sc2+ is unfavourable; R explains A.","difficulty":2,"sources":[[2026,"R","56/4/1",16]]},{"id":"c0822","chapter":4,"type":"mcq","text":"Which property of transition metals enables them to form alloys ?","options":{"A":"High ionization enthalpy","B":"Similar atomic radii","C":"Catalytic property","D":"Complex formation"},"answer":"B","hint":"Think of atoms substituting for one another in the lattice.","explanation":"Similar atomic radii allow one metal to replace another in the crystal lattice, forming alloys.","difficulty":1,"sources":[[2026,"R","56/4/2",1]]},{"id":"c0823","chapter":5,"type":"mcq","text":"Which of the following d-orbitals experience more repulsion in the crystal field splitting of tetrahedral complex ?","options":{"A":"$d_{x^2-y^2}, d_{z^2}$","B":"$d_{x^2-y^2}, d_{xy}$","C":"$d_{xy}, d_{yz}, d_{z^2}$","D":"$d_{xy}, d_{yz}, d_{xz}$"},"answer":"D","hint":"Tetrahedral splitting is the reverse of octahedral.","explanation":"In tetrahedral fields the $t_2$ set ($d_{xy}, d_{yz}, d_{xz}$) is higher in energy.","difficulty":1,"sources":[[2026,"R","56/4/2",2]]},{"id":"c0824","chapter":6,"type":"mcq","text":"The position of $-$Br in the compound (structure shown) can be classified as :","options":{"A":"Vinylic","B":"Allylic","C":"Benzylic","D":"Aryl"},"answer":"B","hint":"Locate the carbon bearing Br relative to the C=C bond.","explanation":"Br is on an sp3 carbon next to the C=C of the side chain, which is allylic (not directly on the ring).","difficulty":1,"figure":"figures/c0824.png","sources":[[2026,"R","56/4/2",3]]},{"id":"c0825","chapter":7,"type":"mcq","text":"Williamson synthesis is an example of :","options":{"A":"Nucleophilic addition reaction","B":"Electrophilic substitution reaction","C":"Nucleophilic substitution reaction","D":"Electrophilic addition reaction"},"answer":"C","hint":"Alkoxide reacts with alkyl halide.","explanation":"Alkoxide ion displaces halide in an $S_N2$ reaction.","difficulty":1,"sources":[[2026,"R","56/4/2",4]]},{"id":"c0826","chapter":5,"type":"mcq","text":"Number of possible stereoisomers for the complex $\\mathrm{[Co(en)_2Cl_2]Cl}$ will be :","options":{"A":"3","B":"4","C":"2","D":"1"},"answer":"A","hint":"Count geometrical isomers and any optical isomers.","explanation":"Trans is achiral (1), cis is chiral (2 enantiomers), total 3.","difficulty":2,"sources":[[2026,"R","56/4/2",5]]},{"id":"c0827","chapter":9,"type":"mcq","text":"The correct order of decreasing basic strength of $\\mathrm{CH_3-NH_2}$, $\\mathrm{(CH_3)_2NH}$ and $\\mathrm{(CH_3)_3N}$ in aqueous solution is :","options":{"A":"$\\mathrm{(CH_3)_3N > (CH_3)_2NH > CH_3-NH_2}$","B":"$\\mathrm{CH_3-NH_2 > (CH_3)_2NH > (CH_3)_3N}$","C":"$\\mathrm{(CH_3)_2NH > CH_3-NH_2 > (CH_3)_3N}$","D":"$\\mathrm{(CH_3)_2NH > (CH_3)_3N > CH_3-NH_2}$"},"answer":"C","hint":"Methylamines differ from ethylamines in the aqueous order.","explanation":"For methyl amines the aqueous order is secondary > primary > tertiary.","difficulty":2,"sources":[[2026,"R","56/4/2",6]]},{"id":"c0828","chapter":9,"type":"mcq","text":"Which of the following reagent is used to convert benzene diazonium chloride to benzene ?","options":{"A":"$\\mathrm{H_2O}$","B":"$\\mathrm{LiAlH_4}$","C":"$\\mathrm{C_2H_5OH}$","D":"CuCN"},"answer":"C","hint":"Diazo group is replaced by hydrogen using a reducing agent.","explanation":"Ethanol (or hypophosphorous acid) reduces the diazonium salt to benzene with loss of N2.","difficulty":1,"sources":[[2026,"R","56/4/2",11]]},{"id":"c0829","chapter":10,"type":"mcq","text":"Which of the following is a water-soluble vitamin ?","options":{"A":"Vitamin K","B":"Vitamin A","C":"Vitamin B","D":"Vitamin D"},"answer":"C","hint":"Fat-soluble vitamins are A, D, E, K.","explanation":"Vitamin B group is water-soluble.","difficulty":1,"sources":[[2026,"R","56/4/2",12]]},{"id":"c0830","chapter":7,"type":"ar","text":"Assertion (A): Alcohols act as Bronsted bases as well as Bronsted acids.\nReason (R): Alcohols react as both nucleophiles and electrophiles.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Does nucleophile/electrophile behaviour explain proton donation/acceptance?","explanation":"Both statements are true, but R describes a different type of behaviour and does not explain A.","difficulty":2,"sources":[[2026,"R","56/4/2",13]]},{"id":"c0831","chapter":3,"type":"ar","text":"Assertion (A): For complex reaction, order of reaction is given by the fast step.\nReason (R): Order of reaction is determined experimentally.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which step controls the rate of a complex reaction?","explanation":"A is false (the slowest step governs); R is true.","difficulty":2,"sources":[[2026,"R","56/4/2",15]]},{"id":"c0832","chapter":4,"type":"ar","text":"Assertion (A): $E^\\circ_{\\mathrm{Cu^{2+}/Cu}}$ has positive value (+ 0.34 V).\nReason (R): It is due to low $\\Delta_{hyd}H^\\circ$ and high $\\Delta_aH^\\circ$.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"E° depends on atomisation, ionisation and hydration enthalpies.","explanation":"Cu has high atomisation enthalpy and its hydration enthalpy cannot compensate ionisation, giving positive E°; R explains A.","difficulty":2,"sources":[[2026,"R","56/4/2",16]]},{"id":"c0833","chapter":6,"type":"mcq","text":"Which of the following is not correct for $S_N1$ reaction ?","options":{"A":"Follows first order kinetics","B":"Favoured by polar protic solvents","C":"Proceeds through the formation of carbocation","D":"Results in inversion of configuration"},"answer":"D","hint":"Planar carbocation intermediate is attacked from both sides.","explanation":"$S_N1$ gives racemisation, not pure inversion (that is $S_N2$).","difficulty":1,"sources":[[2026,"R","56/4/3",1]]},{"id":"c0834","chapter":7,"type":"mcq","text":"Dehydration of tertiary alcohols with Cu at 573 K gives :","options":{"A":"Ketones","B":"Alkenes","C":"Aldehydes","D":"Carboxylic acid"},"answer":"B","hint":"Tertiary alcohols cannot be dehydrogenated.","explanation":"Tertiary alcohols lose water over hot copper to give alkenes.","difficulty":1,"sources":[[2026,"R","56/4/3",2]]},{"id":"c0835","chapter":4,"type":"mcq","text":"Which of the following transition metals shows +1 and +2 oxidation states ?","options":{"A":"Zn","B":"Cu","C":"Fe","D":"Cr"},"answer":"B","hint":"Think of Cu+ and Cu2+.","explanation":"Cu shows +1 and +2; Zn only +2, Fe and Cr show +2/+3 or more.","difficulty":1,"sources":[[2026,"R","56/4/3",5]]},{"id":"c0836","chapter":9,"type":"mcq","text":"The correct order of decreasing order of $\\mathrm{p}K_b$ values is :","options":{"A":"$\\mathrm{C_6H_5NH_2 > C_6H_5NHCH_3 > C_2H_5NH_2}$","B":"$\\mathrm{C_2H_5NH_2 > C_6H_5NH_2 > C_6H_5NHCH_3}$","C":"$\\mathrm{C_6H_5NH_2 > C_2H_5NH_2 > C_6H_5NHCH_3}$","D":"$\\mathrm{C_6H_5NHCH_3 > C_6H_5NH_2 > C_2H_5NH_2}$"},"answer":"A","hint":"Higher pKb means weaker base; aliphatic amines are stronger than aromatic.","explanation":"Ethylamine is strongest (lowest pKb); N-methylaniline is slightly stronger than aniline, so pKb order is aniline > N-methylaniline > ethylamine.","difficulty":2,"sources":[[2026,"R","56/4/3",7]]},{"id":"c0837","chapter":10,"type":"mcq","text":"Each polypeptide in a protein has amino acids linked with each other in a specific sequence and it is this sequence of amino acids that is said to be :","options":{"A":"primary structure of proteins","B":"secondary structure of proteins","C":"tertiary structure of proteins","D":"quaternary structure of proteins"},"answer":"A","hint":"Sequence of residues is the lowest level of organisation.","explanation":"The amino-acid sequence defines the primary structure.","difficulty":1,"sources":[[2026,"R","56/4/3",10]]},{"id":"c0838","chapter":9,"type":"mcq","text":"Benzene diazonium chloride on reaction with phenol in weakly basic medium gives :","options":{"A":"Benzene","B":"Anisole","C":"p-hydroxyazobenzene","D":"Benzophenone"},"answer":"C","hint":"Azo coupling at the para position of phenoxide.","explanation":"Coupling gives the azo dye p-hydroxyazobenzene.","difficulty":1,"sources":[[2026,"R","56/4/3",12]]},{"id":"c0839","chapter":9,"type":"ar","text":"Assertion (A): Diazonium salts of aromatic amines are less stable than those of aliphatic amines.\nReason (R): Diazonium salts of aromatic amines undergo resonance.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"D","hint":"Which diazonium salts are stable at 0-5 °C?","explanation":"A is false (aromatic ones are more stable because of resonance); R is true.","difficulty":2,"sources":[[2026,"R","56/4/3",14]]},{"id":"c0840","chapter":3,"type":"ar","text":"Assertion (A): For complex reaction, order of reaction is given by the slowest step.\nReason (R): Order of reaction is not applicable for the complex reaction.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Order is defined experimentally for any reaction.","explanation":"A is true (rate-determining step); R is false as order is applicable to complex reactions.","difficulty":2,"sources":[[2026,"R","56/4/3",15]]},{"id":"c0841","chapter":4,"type":"ar","text":"Assertion (A): $E^\\circ_{\\mathrm{Mn^{2+}/Mn}}$ value is highly negative.\nReason (R): Because $\\mathrm{Mn^{2+}}$ is highly stable due to half-filled $3d^5$ configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Consider the stability of Mn2+.","explanation":"Half-filled $3d^5$ makes $\\mathrm{Mn^{2+}}$ stable, so $E^\\circ$ is very negative; R explains A.","difficulty":2,"sources":[[2026,"R","56/4/3",16]]},{"id":"c0842","chapter":8,"type":"mcq","text":"Which of the reactions is used in the conversion of a ketone into hydrocarbon ?","options":{"A":"Reimer-Tiemann reaction","B":"Wolff-Kishner reduction","C":"Aldol condensation","D":"Stephen reaction"},"answer":"B","hint":"Carbonyl group is reduced to CH2.","explanation":"Wolff-Kishner (or Clemmensen) reduction converts C=O to CH2.","difficulty":1,"sources":[[2026,"R","56/5/1",1],[2026,"R","56/5/2",6],[2026,"R","56/5/3",3]]},{"id":"c0843","chapter":9,"type":"mcq","text":"Which of the following reagents are used to prepare primary amines by Hoffmann bromamide degradation reaction ?\n(i) $\\mathrm{R-CO-NH_2}$\n(ii) NaOH\n(iii) $\\mathrm{Br_2}$\n(iv) $\\mathrm{CHCl_3}$","options":{"A":"(i), (ii) and (iv)","B":"(i) and (iii)","C":"(i), (ii) and (iii)","D":"(i), (iii) and (iv)"},"answer":"C","hint":"Recall the reagents of Hofmann bromamide degradation.","explanation":"Amide with $\\mathrm{Br_2}$ and NaOH gives the amine with one carbon less; $\\mathrm{CHCl_3}$ is for the carbylamine reaction.","difficulty":1,"sources":[[2026,"R","56/5/1",2],[2026,"R","56/5/2",1],[2026,"R","56/5/3",4]]},{"id":"c0844","chapter":9,"type":"mcq","text":"The major product of carbylamine reaction is :","options":{"A":"Carboxylic acid","B":"Aldehyde","C":"Cyanide","D":"Isocyanide"},"answer":"D","hint":"Primary amine + chloroform + alkali.","explanation":"Carbylamine reaction gives foul-smelling isocyanide (carbylamine).","difficulty":1,"sources":[[2026,"R","56/5/1",3],[2026,"R","56/5/2",5],[2026,"R","56/5/3",1]]},{"id":"c0845","chapter":4,"type":"mcq","text":"Actinoids show larger number of oxidation states :","options":{"A":"because they are radioactive in nature","B":"because they have large atomic numbers","C":"because they have large atomic masses","D":"due to comparable energies of 5f, 6d and 7s orbitals"},"answer":"D","hint":"Think of which electrons are available for bonding.","explanation":"Comparable energies of 5f, 6d and 7s allow electrons from all three to participate.","difficulty":1,"sources":[[2026,"R","56/5/1",4],[2026,"R","56/5/2",3],[2026,"R","56/5/3",6]]},{"id":"c0846","chapter":6,"type":"mcq","text":"Consider the following reaction and identify A and B :\n$\\mathrm{CH_3Cl + NaI \\xrightarrow{dry\\ acetone} A + B}$","options":{"A":"A = $\\mathrm{CH_3I}$, B = NaCl","B":"A = $\\mathrm{CH_3OH}$, B = NaCl","C":"A = $\\mathrm{CH_3CHO}$, B = NaCl","D":"A = $\\mathrm{C_2H_6}$, B = $\\mathrm{CH_3I}$"},"answer":"A","hint":"Halogen exchange driven by insolubility of NaCl in acetone.","explanation":"Finkelstein reaction gives $\\mathrm{CH_3I}$ and NaCl.","difficulty":1,"sources":[[2026,"R","56/5/1",5],[2026,"R","56/5/2",4],[2026,"R","56/5/3",2]]},{"id":"c0847","chapter":9,"type":"mcq","text":"The correct formula of Hinsberg's reagent is :","options":{"A":"$\\mathrm{C_6H_5COCl}$","B":"$\\mathrm{C_6H_5SO_2Cl}$","C":"$\\mathrm{C_6H_5CONHCH_3}$","D":"$\\mathrm{C_6H_5CH_2NH_2}$"},"answer":"B","hint":"It is a sulphonyl chloride.","explanation":"Hinsberg's reagent is benzenesulphonyl chloride.","difficulty":1,"sources":[[2026,"R","56/5/1",6],[2026,"R","56/5/2",2],[2026,"R","56/5/3",5]]},{"id":"c0848","chapter":3,"type":"mcq","text":"Half-life ($t_{1/2}$) of a first order reaction is 1386 s. The value of rate constant is :","options":{"A":"$0.5\\times10^{4}\\ \\mathrm{s^{-1}}$","B":"$5.0\\times10^{-4}\\ \\mathrm{s^{-1}}$","C":"$0.5\\times10^{-5}\\ \\mathrm{s^{-1}}$","D":"$0.5\\times10^{-2}\\ \\mathrm{s^{-1}}$"},"answer":"B","hint":"Use $k = 0.693/t_{1/2}$.","explanation":"$k = 0.693/1386 = 5.0\\times10^{-4}\\ \\mathrm{s^{-1}}$.","difficulty":1,"sources":[[2026,"R","56/5/1",7],[2026,"R","56/5/2",8],[2026,"R","56/5/3",11]]},{"id":"c0849","chapter":5,"type":"mcq","text":"Which of the following ligands forms a chelate complex ?","options":{"A":"Ammonia","B":"Water","C":"$\\mathrm{NO_2^-}$","D":"Oxalate ion"},"answer":"D","hint":"A chelating ligand must be polydentate.","explanation":"Oxalate is bidentate and forms a ring with the metal; the others are monodentate.","difficulty":1,"sources":[[2026,"R","56/5/1",8],[2026,"R","56/5/2",7],[2026,"R","56/5/3",12]]},{"id":"c0850","chapter":7,"type":"mcq","text":"Primary, secondary and tertiary alcohols can be distinguished by :","options":{"A":"Lucas test","B":"Fehling's test","C":"Tollens' test","D":"Hinsberg's test"},"answer":"A","hint":"Rates of turbidity formation differ with alcohol class.","explanation":"Lucas reagent gives turbidity immediately (3°), in about 5 min (2°), and not at room temperature (1°).","difficulty":1,"sources":[[2026,"R","56/5/1",9],[2026,"R","56/5/2",12],[2026,"R","56/5/3",7]]},{"id":"c0851","chapter":9,"type":"mcq","text":"Consider the following compounds :\n$\\mathrm{C_2H_5NH_2}$, $\\mathrm{(C_2H_5)_2NH}$, $\\mathrm{C_6H_5CH_2NH_2}$, $\\mathrm{NH_3}$, $\\mathrm{C_6H_5NH_2}$\nThe correct increasing order of the above compounds on the basis of their basic strength is :","options":{"A":"$\\mathrm{C_6H_5NH_2 < NH_3 < C_6H_5CH_2NH_2 < C_2H_5NH_2 < (C_2H_5)_2NH}$","B":"$\\mathrm{NH_3 < C_6H_5NH_2 < C_6H_5CH_2NH_2 < C_2H_5NH_2 < (C_2H_5)_2NH}$","C":"$\\mathrm{C_6H_5CH_2NH_2 < (C_2H_5)_2NH < NH_3 < C_6H_5NH_2 < C_2H_5NH_2}$","D":"$\\mathrm{C_2H_5NH_2 < C_6H_5NH_2 < NH_3 < C_6H_5CH_2NH_2 < (C_2H_5)_2NH}$"},"answer":"A","hint":"Aryl amines are weakest; alkyl groups raise basicity.","explanation":"Aniline is weaker than NH3; benzylamine is slightly stronger than NH3 but weaker than ethylamine, and diethylamine is strongest.","difficulty":2,"sources":[[2026,"R","56/5/1",10],[2026,"R","56/5/2",11],[2026,"R","56/5/3",8]]},{"id":"c0852","chapter":10,"type":"mcq","text":"Identify the polysaccharide among the following :","options":{"A":"Fructose","B":"Maltose","C":"Glucose","D":"Cellulose"},"answer":"D","hint":"Polysaccharides yield many monosaccharide units on hydrolysis.","explanation":"Cellulose is a polymer of glucose; the others are mono- or disaccharides.","difficulty":1,"sources":[[2026,"R","56/5/1",11],[2026,"R","56/5/2",10],[2026,"R","56/5/3",9]]},{"id":"c0853","chapter":10,"type":"mcq","text":"The polypeptide chain in a protein has amino acids linked with each other in a specific sequence. This specific sequence of amino acids is called :","options":{"A":"Primary structure of protein","B":"Secondary structure of protein","C":"Tertiary structure of protein","D":"Quaternary structure of protein"},"answer":"A","hint":"Sequence of residues is the first level of protein structure.","explanation":"The amino-acid sequence is the primary structure.","difficulty":1,"sources":[[2026,"R","56/5/1",12],[2026,"R","56/5/2",9],[2026,"R","56/5/3",10]]},{"id":"c0854","chapter":10,"type":"ar","text":"Assertion (A): D (+) – Glucose is dextrorotatory in nature.\nReason (R): (+) represents dextrorotatory nature and D represents the configuration.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Meaning of the D and (+) labels.","explanation":"A is true; (+) denotes dextrorotation and D denotes configuration, which explains the name.","difficulty":1,"sources":[[2026,"R","56/5/1",13],[2026,"R","56/5/2",14],[2026,"R","56/5/3",15]]},{"id":"c0855","chapter":4,"type":"ar","text":"Assertion (A): Highest oxidation state of Mn is +7 in first series of transition elements.\nReason (R): Transition metals exhibit variable oxidation states.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"B","hint":"Does a general property explain a specific maximum?","explanation":"Both true, but variable oxidation states do not explain why Mn reaches +7 (all 3d and 4s electrons used).","difficulty":2,"sources":[[2026,"R","56/5/1",14],[2026,"R","56/5/2",15],[2026,"R","56/5/3",16]]},{"id":"c0856","chapter":7,"type":"ar","text":"Assertion (A): p-nitrophenol is more acidic than phenol.\nReason (R): Nitro group is an electron-withdrawing group, it stabilises phenoxide ion by dispersal of negative charge.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"A","hint":"Stability of the conjugate base decides acidity.","explanation":"Both true; –NO2 stabilises the p-nitrophenoxide ion, so R explains A.","difficulty":1,"sources":[[2026,"R","56/5/1",15],[2026,"R","56/5/2",16],[2026,"R","56/5/3",13]]},{"id":"c0857","chapter":8,"type":"ar","text":"Assertion (A): All aliphatic aldehydes give a positive Fehling's test.\nReason (R): Aliphatic aldehydes are reduced by Fehling's reagent.","options":{"A":"Both Assertion (A) and Reason (R) are true and Reason (R) is the correct explanation of the Assertion (A).","B":"Both Assertion (A) and Reason (R) are true, but Reason (R) is not the correct explanation of the Assertion (A).","C":"Assertion (A) is true, but Reason (R) is false.","D":"Assertion (A) is false, but Reason (R) is true."},"answer":"C","hint":"Is the aldehyde oxidised or reduced by Fehling's reagent?","explanation":"A is true; R is false because aldehydes are oxidised (Fehling's reagent is reduced).","difficulty":2,"sources":[[2026,"R","56/5/1",16],[2026,"R","56/5/2",13],[2026,"R","56/5/3",14]]}]};
